if (!window.CHAPTER_DATA) window.CHAPTER_DATA = {};
window.CHAPTER_DATA[1] = "<section class=\"chapter-section\" id=\"c12b-ch1\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#059669;\">1</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#059669;\">CBSE Class 12 Biology &bull; Chapter 1</div>\n      <h2>Sexual Reproduction in Flowering Plants</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 18 Verbatim Questions with Official CBSE Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"display:flex; justify-content:center; margin:24px 0;\">\n    <svg viewBox=\"0 0 760 220\" style=\"width:100%; max-width:760px; height:auto; background:#f8fafc; border:1px solid #e2e8f0; border-radius:12px; box-shadow:0 2px 8px rgba(0,0,0,0.04);\">\n      <!-- Title -->\n      <text x=\"380\" y=\"24\" text-anchor=\"middle\" font-family=\"system-ui, sans-serif\" font-size=\"14\" font-weight=\"700\" fill=\"#1e293b\">Anatomy of Anatropous Ovule & 7-Celled, 8-Nucleate Embryo Sac</text>\n      \n      <!-- Ovule schematic -->\n      <ellipse cx=\"170\" cy=\"120\" rx=\"60\" ry=\"75\" fill=\"#dcfce7\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <ellipse cx=\"170\" cy=\"120\" rx=\"42\" ry=\"55\" fill=\"#f0fdf4\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n\n      <!-- Embryo sac inside nucellus -->\n      <ellipse cx=\"170\" cy=\"120\" rx=\"25\" ry=\"38\" fill=\"#ffffff\" stroke=\"#10b981\" stroke-width=\"2\"/>\n\n      <!-- Chalazal end (top) Antipodals -->\n      <circle cx=\"162\" cy=\"95\" r=\"4\" fill=\"#059669\"/><circle cx=\"170\" cy=\"92\" r=\"4\" fill=\"#059669\"/><circle cx=\"178\" cy=\"95\" r=\"4\" fill=\"#059669\"/>\n      <text x=\"170\" y=\"82\" text-anchor=\"middle\" font-family=\"system-ui, sans-serif\" font-size=\"10\" font-weight=\"700\" fill=\"#059669\">Antipodals (3)</text>\n\n      <!-- Central cell with 2 polar nuclei -->\n      <circle cx=\"167\" cy=\"118\" r=\"3.5\" fill=\"#2563eb\"/><circle cx=\"173\" cy=\"118\" r=\"3.5\" fill=\"#2563eb\"/>\n      <text x=\"215\" y=\"122\" font-family=\"system-ui, sans-serif\" font-size=\"10\" font-weight=\"600\" fill=\"#2563eb\">Polar nuclei (n+n)</text>\n\n      <!-- Micropylar end (bottom) Egg apparatus -->\n      <circle cx=\"170\" cy=\"145\" r=\"5\" fill=\"#dc2626\"/>\n      <circle cx=\"162\" cy=\"142\" r=\"4\" fill=\"#ea580c\"/><circle cx=\"178\" cy=\"142\" r=\"4\" fill=\"#ea580c\"/>\n      <text x=\"170\" y=\"162\" text-anchor=\"middle\" font-family=\"system-ui, sans-serif\" font-size=\"10\" font-weight=\"700\" fill=\"#dc2626\">Egg Cell &amp; Synergids</text>\n\n      <!-- Micropyle pore -->\n      <path d=\"M 160 195 L 170 175 L 180 195\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <text x=\"170\" y=\"210\" text-anchor=\"middle\" font-family=\"system-ui, sans-serif\" font-size=\"11\" font-weight=\"700\" fill=\"#64748b\">Micropyle</text>\n\n      <!-- Key Concept Summary -->\n      <text x=\"360\" y=\"55\" font-family=\"system-ui, sans-serif\" font-size=\"12\" font-weight=\"700\" fill=\"#1e293b\">Core Principles &amp; Reproductive Events:</text>\n      <text x=\"360\" y=\"80\" font-family=\"system-ui, sans-serif\" font-size=\"12\" fill=\"#475569\">• Microsporogenesis: PMC ($2n$) $\\xrightarrow{\\text{Meiosis}}$ Microspore Tetrad ($n$) $\\to$ Pollen Grains</text>\n      <text x=\"360\" y=\"105\" font-family=\"system-ui, sans-serif\" font-size=\"12\" fill=\"#475569\">• Megasporogenesis: MMC ($2n$) $\\xrightarrow{\\text{Meiosis}}$ 4 Megaspores $\\to$ 1 Functional ($n$)</text>\n      <text x=\"360\" y=\"130\" font-family=\"system-ui, sans-serif\" font-size=\"12\" fill=\"#475569\">• Monosporic Development: Functional megaspore undergoes 3 free-nuclear mitoses</text>\n      <text x=\"360\" y=\"155\" font-family=\"system-ui, sans-serif\" font-size=\"12\" fill=\"#475569\">• Mature Embryo Sac: 7-celled, 8-nucleate (3 antipodals + 1 central + 2 synergids + 1 egg)</text>\n      <text x=\"360\" y=\"180\" font-family=\"system-ui, sans-serif\" font-size=\"12\" fill=\"#475569\">• Double Fertilisation: Syngamy (Egg + Sperm $\\to$ Zygote $2n$) &amp; Triple Fusion (PEN $3n$)</text>\n      <text x=\"360\" y=\"205\" font-family=\"system-ui, sans-serif\" font-size=\"12\" fill=\"#475569\">• Post-fertilisation: Ovule $\\to$ Seed; Ovary $\\to$ Fruit; Endosperm nourishes embryo</text>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\" style=\"font-size:0.88rem; font-weight:700; color:#334155; margin-bottom:16px; padding:8px 14px; background:#ecfdf5; border-radius:8px; border-left:4px solid #059669;\">Exercises 1.1 to 1.18</div>\n\n  <div class=\"questions-container\">\n    \n  <!-- c12b-ch1-q1 (Exercise 1.1) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q1')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.1</span><br>\n        Name the parts of an angiosperm flower in which development of male and female gametophyte take place.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Male Gametophyte Development:</strong><br>\n    The development of the male gametophyte (pollen grain) takes place inside the <strong>microsporangia (pollen sacs)</strong> of the <strong>anther</strong> (part of the stamen / androecium).</p>\n\n    <p><strong>2. Female Gametophyte Development:</strong><br>\n    The development of the female gametophyte (embryo sac) takes place inside the <strong>nucellus of the ovule (megasporangium)</strong>, located within the <strong>ovary</strong> of the pistil / carpel (gynoecium).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of anther / microsporangium for male gametophyte</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of ovule nucellus / ovary for female gametophyte</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q2 (Exercise 1.2) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q2')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.2</span><br>\n        Differentiate between microsporogenesis and megasporogenesis. Which type of cell division occurs during these events? Name the structures formed at the end of these two events.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Comparison Table:</strong></p>\n    <table style=\"width:100%; border-collapse:collapse; margin:12px 0;\">\n      <thead>\n        <tr style=\"background:#f1f5f9; text-align:left;\">\n          <th style=\"padding:8px; border:1px solid #cbd5e1;\">Feature</th>\n          <th style=\"padding:8px; border:1px solid #cbd5e1;\">Microsporogenesis</th>\n          <th style=\"padding:8px; border:1px solid #cbd5e1;\">Megasporogenesis</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td style=\"padding:8px; border:1px solid #cbd5e1;\"><strong>Definition</strong></td>\n          <td style=\"padding:8px; border:1px solid #cbd5e1;\">Formation of haploid microspores from diploid pollen mother cell (PMC).</td>\n          <td style=\"padding:8px; border:1px solid #cbd5e1;\">Formation of haploid megaspores from diploid megaspore mother cell (MMC).</td>\n        </tr>\n        <tr>\n          <td style=\"padding:8px; border:1px solid #cbd5e1;\"><strong>Site of Occurrence</strong></td>\n          <td style=\"padding:8px; border:1px solid #cbd5e1;\">Inside the microsporangium (pollen sac) of anther.</td>\n          <td style=\"padding:8px; border:1px solid #cbd5e1;\">Inside the nucellus of the ovule (megasporangium).</td>\n        </tr>\n        <tr>\n          <td style=\"padding:8px; border:1px solid #cbd5e1;\"><strong>Fate of Products</strong></td>\n          <td style=\"padding:8px; border:1px solid #cbd5e1;\">All four microspores of the tetrad are functional and develop into pollen grains.</td>\n          <td style=\"padding:8px; border:1px solid #cbd5e1;\">Usually only one megaspore (chalazal) remains functional; the other three degenerate.</td>\n        </tr>\n      </tbody>\n    </table>\n\n    <p><strong>2. Type of Cell Division:</strong><br>\n    <strong>Meiotic division (Meiosis / reductional division)</strong> occurs during both microsporogenesis and megasporogenesis.</p>\n\n    <p><strong>3. Structures Formed:</strong><br>\n    • At the end of microsporogenesis: <strong>Haploid microspores</strong> (arranged in a microspore tetrad), which separate and develop into mature <strong>pollen grains</strong>.<br>\n    • At the end of megasporogenesis: A <strong>linear tetrad of four haploid megaspores</strong>, of which one functional megaspore develops into the mature <strong>embryo sac (female gametophyte)</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Two clear points of difference between the processes</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Meiotic cell division</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Structures formed: microspores/pollen grains & megaspores/embryo sac</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q3 (Exercise 1.3) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q3')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.3</span><br>\n        Arrange the following terms in the correct developmental sequence:<br>\n    Pollen grain, sporogenous tissue, microspore tetrad, pollen mother cell, male gametes.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Developmental Sequence:</strong></p>\n    <div style=\"padding:12px; background:#ecfdf5; border:1px solid #a7f3d0; border-radius:8px; font-weight:700; color:#065f46; margin:12px 0;\">\n      Sporogenous tissue &nbsp;→&nbsp; Pollen mother cell (PMC) &nbsp;→&nbsp; Microspore tetrad &nbsp;→&nbsp; Pollen grain &nbsp;→&nbsp; Male gametes\n    </div>\n    <p><strong>Biological Rationale:</strong><br>\n    1. <strong>Sporogenous tissue</strong> fills the centre of each microsporangium in a young anther.<br>\n    2. Cells of sporogenous tissue differentiate into diploid <strong>pollen mother cells (PMCs)</strong>.<br>\n    3. Each PMC undergoes meiosis to produce a cluster of four haploid microspores, the <strong>microspore tetrad</strong>.<br>\n    4. As the anther matures and dehydrates, microspores dissociate into spherical <strong>pollen grains</strong>.<br>\n    5. The generative cell of the pollen grain divides mitotically to give rise to two <strong>male gametes</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate chronological sequence of all five stages</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Brief biological rationale for cell transitions</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q4 (Exercise 1.4) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q4')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.4</span><br>\n        With a neat, labelled diagram, describe the parts of a typical angiosperm ovule (anatropous ovule).\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Main Parts of an Anatropous Ovule:</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Funicle (Funiculus):</strong> The stalk by which the ovule is attached to the placenta of the ovary wall.</li>\n      <li><strong>Hilum:</strong> The junction point where the body of the ovule fuses with the funicle.</li>\n      <li><strong>Integuments:</strong> One or two protective multi-layered envelopes surrounding the nucellus, leaving a small pore at the apex.</li>\n      <li><strong>Micropyle:</strong> A narrow apical pore where the integuments do not fuse, serving as the entry passage for the pollen tube during fertilisation.</li>\n      <li><strong>Chalaza:</strong> The basal swollen region of the ovule opposite the micropyle, representing the origin of integuments.</li>\n      <li><strong>Nucellus:</strong> The central mass of parenchymatous nutritive cells enclosed within the integuments, providing nourishment to the developing embryo sac.</li>\n      <li><strong>Embryo Sac (Female Gametophyte):</strong> The 7-celled, 8-nucleate haploid structure embedded within the nucellus containing the egg apparatus, polar nuclei, and antipodals.</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Labelled description of Funicle, Hilum, Integuments, Micropyle</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Description of Chalaza, Nucellus, and Embryo Sac</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q5 (Exercise 1.5) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q5')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.5</span><br>\n        What is meant by monosporic development of female gametophyte?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Monosporic Development:</strong><br>\n    • During megasporogenesis, the diploid megaspore mother cell (MMC) undergoes meiosis to produce a linear tetrad of four haploid megaspores.<br>\n    • In the vast majority of angiosperms (Polygonum type), <strong>three megaspores situated at the micropylar end degenerate</strong> and get absorbed.<br>\n    • Only <strong>one single megaspore (situated at the chalazal end)</strong> remains functional and enlarges.<br>\n    • This single functional megaspore undergoes three sequential mitotic nuclear divisions to form the entire 7-celled, 8-nucleate female gametophyte (embryo sac).<br>\n    Because the entire embryo sac develops from <strong>one single functional megaspore</strong>, this method of embryo sac formation is designated as <strong>monosporic development</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of degeneration of 3 micropylar megaspores</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Development of entire embryo sac from single chalazal megaspore</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q6 (Exercise 1.6) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q6')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.6</span><br>\n        With a neat diagram explain the 7-celled, 8-nucleate nature of the female gametophyte (embryo sac) in angiosperms.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Development & Organization of Embryo Sac:</strong><br>\n    The nucleus of the functional megaspore divides mitotically into two nuclei which move to opposite poles, forming a 2-nucleate embryo sac. Two further sequential mitotic divisions result in 4 nuclei at each pole (total 8 nuclei). These divisions are strictly <strong>free-nuclear</strong> (cell wall formation does not occur immediately).</p>\n\n    <p><strong>Cellular Organization (7 Cells, 8 Nuclei):</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Egg Apparatus (3 Cells at Micropylar End):</strong> Consists of one central <strong>egg cell</strong> (female gamete) flanked by two <strong>synergids</strong>. Synergids possess characteristic cellular finger-like thickenings called the <strong>filiform apparatus</strong>, which guide the entry of the pollen tube.</li>\n      <li><strong>Antipodal Cells (3 Cells at Chalazal End):</strong> Three vegetative cells situated at the chalazal pole, involved in absorbing nutrition from the nucellus before degenerating.</li>\n      <li><strong>Central Cell (1 Large Cell):</strong> The largest cell occupying the center, containing <strong>two polar nuclei</strong> which fuse prior to fertilisation to form a diploid secondary nucleus ($2n$).</li>\n    </ol>\n    <p>Thus, while there are 8 nuclei in total, the two central polar nuclei reside within a single shared central cell, rendering the mature embryo sac <strong>7-celled and 8-nucleate</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Description of Egg apparatus (1 egg + 2 synergids with filiform apparatus)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Description of 3 antipodals and 1 large central cell with 2 polar nuclei</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of free-nuclear mitoses leading to 7-celled, 8-nucleate state</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q7 (Exercise 1.7) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q7')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.7</span><br>\n        What are chasmogamous flowers? Can cross-pollination occur in cleistogamous flowers? Give reasons.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Chasmogamous Flowers:</strong><br>\n    Chasmogamous flowers are open flowers with exposed anthers and stigmas, similar to flowers of typical angiosperms, permitting both cross-pollination (xenogamy) and self-pollination.</p>\n\n    <p><strong>2. Can Cross-Pollination Occur in Cleistogamous Flowers?</strong><br>\n    <strong>No, cross-pollination can never occur in cleistogamous flowers.</strong></p>\n\n    <p><strong>Reasons:</strong><br>\n    • Cleistogamous flowers remain permanently closed and <strong>never open at all</strong>, even at maturity (e.g. <em>Viola</em>, <em>Oxalis</em>, <em>Commelina</em>).<br>\n    • The anthers and stigma lie in close physical proximity inside the closed bud.<br>\n    • When the anthers dehisce, pollen grains inevitably fall directly onto the receptive stigma of the same flower.<br>\n    • Because the floral envelope remains sealed, external cross-pollen carried by wind, water, or insects is physically blocked from reaching the stigma, ensuring <strong>obligate autogamy</strong> and assured seed-set even in the complete absence of pollinators.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of chasmogamous flowers</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clear negative answer for cleistogamous flowers</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Physiological & structural reasons (never opening, sealed envelope, obligate autogamy)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q8 (Exercise 1.8) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q8')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.8</span><br>\n        Mention two strategies evolved by flowers to prevent self-pollination (outbreeding devices).\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Outbreeding Devices in Angiosperms (Any two):</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Dichogamy (Non-synchronisation of Pollen Release and Stigma Receptivity):</strong><br>\n      Pollen is released before the stigma becomes receptive (<strong>Protandry</strong>, e.g. Sunflower, Salvia), or the stigma matures and becomes receptive long before pollen is shed (<strong>Protogyny</strong>, e.g. <em>Aristolochia</em>, <em>Mirabilis</em>), preventing autogamy.</li>\n\n      <li><strong>Heterostyly (Spatial Separation of Anthers and Stigma):</strong><br>\n      Anthers and stigma are placed at different heights and spatial positions (e.g. <em>Primula</em>) so that pollen grains cannot physically land on the stigma of the same flower.</li>\n\n      <li><strong>Self-Incompatibility (Genetic Mechanism):</strong><br>\n      A genetic mechanism that prevents self-pollen (from the same flower or other flowers of the same plant) from fertilising the ovules by inhibiting pollen germination or pollen tube growth in the pistil (e.g. Tobacco, Potato).</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">First outbreeding device explained with botanical mechanism</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Second outbreeding device explained with botanical mechanism</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q9 (Exercise 1.9) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q9')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.9</span><br>\n        What is self-incompatibility? Why does self-pollination not lead to seed formation in self-incompatible species?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Definition of Self-Incompatibility:</strong><br>\n    Self-incompatibility is a genetically controlled pre-zygotic reproductive barrier in hermaphroditic plants that prevents self-pollen from fertilising ovules of the same flower or other flowers of the same individual plant.</p>\n\n    <p><strong>2. Why Self-Pollination Fails to Produce Seeds:</strong><br>\n    • It is governed by multi-allelic <strong>$S$-genes</strong> ($S_1, S_2, S_3, \\dots$).<br>\n    • When a pollen grain carries an $S$-allele that matches either of the $S$-alleles present in the diploid tissue of the pistil (stigma and style), a biochemical recognition-rejection reaction is triggered.<br>\n    • This incompatibility response blocks <strong>pollen germination on the stigma</strong> or causes <strong>callose plugging / bursting of the pollen tube</strong> in the transmission tissue of the style.<br>\n    • Consequently, male gametes never reach the embryo sac, fertilisation fails to occur, and no seeds are formed.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of self-incompatibility</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Biochemical/genetic mechanism (pollen tube inhibition by matching $S$-alleles)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q10 (Exercise 1.10) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q10')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.10</span><br>\n        What is bagging technique? How is it useful in a plant breeding programme?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Bagging Technique:</strong><br>\n    Bagging is an artificial hybridisation technique wherein emasculated (or female) flowers are covered with a protective perforated bag made of butter paper or parchment paper before their stigmas become receptive.</p>\n\n    <p><strong>2. Utility in Plant Breeding Programmes:</strong><br>\n    • <strong>Prevents Unwanted Contamination:</strong> It protects the receptive stigma from contamination by undesirable, airborne foreign pollen grains or insect vectors.<br>\n    • <strong>Controlled Cross-Pollination:</strong> When the stigma attains receptivity, the bag is temporarily opened, mature viable pollen grains collected from the chosen superior male parent are dusted onto the stigma, and the flower is promptly rebagged until fruits mature.<br>\n    • This guarantees that seeds produced possess the desired combination of agronomically superior parental traits (high yield, disease resistance).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of bagging with butter paper</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Significance in preventing contamination and ensuring controlled hybridisation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q11 (Exercise 1.11) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q11')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.11</span><br>\n        What is triple fusion? Where and how does it take place? Name the nuclei involved in triple fusion.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. What is Triple Fusion?</strong><br>\n    Triple fusion is the unique fusion of three haploid nuclei: one haploid male gamete ($n$) fusing with the two haploid polar nuclei (or diploid secondary nucleus, $2n$) in the central cell of the embryo sac to form the triploid <strong>Primary Endosperm Nucleus (PEN, $3n$)</strong>.</p>\n\n    <p><strong>2. Where and How it Takes Place:</strong><br>\n    • <strong>Location:</strong> Inside the <strong>central cell</strong> of the female gametophyte (embryo sac) within the ovule.<br>\n    • <strong>Process:</strong> The pollen tube enters one of the synergids through the filiform apparatus and discharges both male gametes into the cytoplasm of the synergid. While one male gamete moves towards the egg cell for syngamy, the second male gamete migrates into the central cell and fuses with the two polar nuclei.</p>\n\n    <p><strong>3. Nuclei Involved:</strong><br>\n    Three distinct nuclei are involved:\n    1. One haploid nucleus of the second <strong>male gamete</strong> ($n$).<br>\n    2. Two haploid <strong>polar nuclei</strong> ($n + n$) of the central cell.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of triple fusion and formation of triploid PEN ($3n$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Location in central cell and mechanism via second male gamete</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Specific naming of three participating nuclei</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q12 (Exercise 1.12) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q12')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.12</span><br>\n        Why do you think the zygote is dormant for some time in a fertilised ovule?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Biological Significance of Zygotic Dormancy:</strong><br>\n    • In angiosperms, the diploid zygote undergoes a period of rest and does not begin cell division immediately after syngamy.<br>\n    • <strong>Endosperm Development Precedes Embryo Development:</strong> The zygote remains dormant until a sufficient amount of nutritive <strong>endosperm tissue</strong> has been formed by the rapid divisions of the primary endosperm cell (PEC).<br>\n    • <strong>Adaptation for Survival:</strong> This is an evolutionary survival adaptation to ensure that an assured nutritional supply is readily available to support the energetic and metabolic demands of the developing embryo, preventing premature embryonic starvation or abortion.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Fact that endosperm development precedes embryo development</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evolutionary adaptation to guarantee nutritional supply</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q13 (Exercise 1.13) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q13')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.13</span><br>\n        Differentiate between:<br>\n    <strong>(a)</strong> hypocotyl and epicotyl;<br>\n    <strong>(b)</strong> coleoptile and coleorhiza;<br>\n    <strong>(c)</strong> integument and testa;<br>\n    <strong>(d)</strong> perisperm and pericarp.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>(a) Hypocotyl vs Epicotyl:</strong><br>\n    • <strong>Hypocotyl:</strong> The cylindrical portion of the embryonal axis below the level of cotyledons that terminates at its lower end in the radicle / root tip.<br>\n    • <strong>Epicotyl:</strong> The portion of the embryonal axis above the level of cotyledons that terminates in the plumule / shoot apex.</p>\n\n    <p><strong>(b) Coleoptile vs Coleorhiza:</strong><br>\n    • <strong>Coleoptile:</strong> A conical protective foliar sheath enclosing the plumule and epicotyl in monocot seeds (grasses), emerging above ground.<br>\n    • <strong>Coleorhiza:</strong> An undifferentiated protective sheath enclosing the radicle and root cap in monocot seeds, remaining underground.</p>\n\n    <p><strong>(c) Integument vs Testa:</strong><br>\n    • <strong>Integument:</strong> The pre-fertilisation protective covering layers of an ovule (living diploid maternal tissue).<br>\n    • <strong>Testa:</strong> The post-fertilisation, dehydrated, tough outer protective seed coat derived specifically from the outer integument.</p>\n\n    <p><strong>(d) Perisperm vs Pericarp:</strong><br>\n    • <strong>Perisperm:</strong> The persistent, non-consumed residual nucellus present in certain seeds such as Black Pepper and Beet.<br>\n    • <strong>Pericarp:</strong> The protective wall of the fruit developed directly from the wall of the ovary after fertilisation.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate differentiation for (a) Hypocotyl vs Epicotyl</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate differentiation for (b) Coleoptile vs Coleorhiza</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate differentiation for (c) Integument vs Testa</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate differentiation for (d) Perisperm vs Pericarp</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q14 (Exercise 1.14) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q14')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.14</span><br>\n        Why is apple called a false fruit? Which part(s) of the flower forms the fruit?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Why Apple is a False Fruit (Pseudocarp):</strong><br>\n    • In botanical terms, a <strong>true fruit</strong> develops exclusively from the mature, fertilised ovary of a flower without the participation of any other floral whorl.<br>\n    • In an apple, the edible fleshy part does not develop from the ovary wall. Instead, the <strong>thalamus (receptacle)</strong> enlarges and becomes fleshy, surrounding the central core that contains the true ovary and seeds.<br>\n    • Because non-ovarian floral tissue (the thalamus) forms the bulk of the fruit, apple is classified as a <strong>false fruit (thalamic fruit / pseudocarp)</strong> (along with strawberry and cashew).</p>\n\n    <p><strong>2. Parts Forming the Fruit:</strong><br>\n    • In a true fruit: The <strong>ovary wall</strong> forms the pericarp (epicarp, mesocarp, endocarp).<br>\n    • In an apple: The enlarged fleshy <strong>thalamus</strong> forms the edible flesh, while the central papery core is derived from the <strong>ovary</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of false fruit due to thalamus contribution</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of thalamus as edible part and ovary as core</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q15 (Exercise 1.15) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q15')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.15</span><br>\n        What is meant by emasculation? When and why does a plant breeder employ this technique?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Definition of Emasculation:</strong><br>\n    Emasculation is the surgical removal of anthers from a bisexual flower bud using a pair of sterile forceps before the anthers dehisce.</p>\n\n    <p><strong>2. When is it Employed?</strong><br>\n    It is performed during the early <strong>bud stage</strong>, well before the anthers mature and release pollen grains, and before the stigma attains receptivity.</p>\n\n    <p><strong>3. Why is it Employed by Plant Breeders?</strong><br>\n    • In bisexual flowers, self-pollination (autogamy) occurs naturally upon anther dehiscence.<br>\n    • Emasculation prevents self-pollination, ensuring that the flower can be pollinated exclusively with desired pollen grains collected from a selected superior male parent.<br>\n    (Note: If the female parent bears unisexual pistillate flowers, emasculation is not required).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition and timing (bud stage before dehiscence)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Purpose in preventing autogamy during controlled hybridisation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q16 (Exercise 1.16) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q16\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q16')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.16</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.16</span><br>\n        If one can induce parthenocarpy through the application of growth substances, which fruits would you select to induce parthenocarpy and why?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Selected Fruits for Induced Parthenocarpy:</strong><br>\n    Parthenocarpy (production of seedless fruits without fertilisation) would be induced in fruits where seeds are commercially undesirable, annoying, or unpalatable, such as:<br>\n    • <strong>Watermelon, Grapes, Oranges, Lemon, Guava, Tomato, Papaya, and Banana.</strong></p>\n\n    <p><strong>2. Justification (Why):</strong><br>\n    • In these fruits, seeds reduce consumer palatability, processing ease, and commercial market value. Seedlessness enhances edible pulp volume and juice extraction efficiency.<br>\n    • Conversely, parthenocarpy would <strong>never</strong> be induced in crops where the <em>seed itself is the economic product</em> (e.g. wheat, rice, maize, pulses, almonds, walnuts, mustard), as parthenocarpy would yield sterile, seedless empty shells, destroying the harvest.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Selection of pulpy/juicy fruits (Watermelon, Grapes, Oranges)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification: Enhanced palatability vs disaster if applied to grain/seed crops</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q17 (Exercise 1.17) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q17\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q17')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.17</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.17</span><br>\n        Explain the role of tapetum in the formation of pollen-grain wall.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Role of Tapetum in Pollen Wall Synthesis:</strong><br>\n    The tapetum is the innermost nourishing cell layer of the microsporangial wall, characterised by dense cytoplasm and polyploid/multinucleate cells.</p>\n\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Secretion of Sporopollenin Precursors:</strong> Tapetal cells produce <em>Ubisch bodies</em> (pro-orbicules) that secrete <strong>sporopollenin</strong>, the most biologically resistant organic polymer known, forming the sculptural, indestructible outer wall layer called the <strong>exine</strong>.</li>\n      <li><strong>Pollenkitt Synthesis:</strong> In insect-pollinated (entomophilous) plants, the tapetum synthesises and deposits a sticky, oily, carotenoid-rich coat called <strong>pollenkitt</strong> on the pollen surface, aiding adhesion to insect bodies and offering UV protection.</li>\n      <li><strong>Enzyme & Protein Secretion:</strong> It secretes the enzyme <em>callase</em> to dissolve the callose wall of microspore tetrads, liberating individual microspores, and synthesises physiological <strong>compatibility proteins</strong> housed in exine cavities for pollen-stigma recognition.</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Secretion of sporopollenin forming the exine layer</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Synthesis of pollenkitt for insect pollination</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Secretion of callase and compatibility recognition proteins</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch1-q18 (Exercise 1.18) -->\n  <div class=\"q-card\" id=\"c12b-ch1-q18\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch1-q18')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 1.18</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 1.18</span><br>\n        What is apomixis and what is its importance in agriculture?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Definition of Apomixis:</strong><br>\n    Apomixis is a form of asexual reproduction that <strong>mimics sexual reproduction</strong> by producing seeds without fertilisation (syngamy) and without meiosis (e.g. in species of <em>Asteraceae</em> and grasses).<br>\n    The embryos develop directly from diploid nucellar cells (adventive embryony) or from an unreduced diploid egg cell.</p>\n\n    <p><strong>2. Importance in Modern Agriculture:</strong><br>\n    • <strong>Fixation of Hybrid Vigour:</strong> Hybrid seeds offer tremendously increased crop productivity, but hybrid vigour segregates and is lost in subsequent generations if farmers save and replant seeds derived from sexual reproduction, forcing farmers to buy costly hybrid seeds every single year.<br>\n    • <strong>Elimination of Annual Hybrid Seed Costs:</strong> If hybrid crops are genetically engineered with apomictic traits, the seeds collected by farmers will breed completely true-to-type without genetic segregation of characters.<br>\n    • Farmers can reuse their own harvest seeds indefinitely year after year, revolutionising agricultural economics and global food security.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition of apomixis as asexual reproduction mimicking sexual reproduction</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Agricultural significance in preserving hybrid vigour and reducing seed costs</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"display:flex; justify-content:space-between; align-items:center; margin-top:36px; padding-top:20px; border-top:1px solid #e2e8f0;\">\n    <a href=\"../ncert-solutions-class-12-biology.html\" class=\"ch-nav-btn prev\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; text-decoration:none; color:#334155;\">← Class 12 Biology Hub</a>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(2)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#059669; color:white; font-weight:700; cursor:pointer;\">Next: Ch 2 (Human Reproduction) →</button>\n  </div>\n</section>";
window.CHAPTER_DATA[2] = "<section class=\"chapter-section\" id=\"c12b-ch2\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#059669;\">2</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#059669;\">CBSE Class 12 Biology &bull; Chapter 2</div>\n      <h2>Human Reproduction</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 21 Verbatim Questions with Official CBSE Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"display:flex; justify-content:center; margin:24px 0;\">\n    <svg viewBox=\"0 0 760 220\" style=\"width:100%; max-width:760px; height:auto; background:#f8fafc; border:1px solid #e2e8f0; border-radius:12px; box-shadow:0 2px 8px rgba(0,0,0,0.04);\">\n      <!-- Title -->\n      <text x=\"380\" y=\"24\" text-anchor=\"middle\" font-family=\"system-ui, sans-serif\" font-size=\"14\" font-weight=\"700\" fill=\"#1e293b\">Spermatogenesis, Oogenesis &amp; Menstrual Cycle Hormone Dynamics</text>\n      \n      <!-- Sperm Anatomy (Left) -->\n      <path d=\"M 60 110 C 60 95, 90 95, 100 110 C 90 125, 60 125, 60 110 Z\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <path d=\"M 60 110 C 60 102, 75 102, 80 110 C 75 118, 60 118, 60 110 Z\" fill=\"#10b981\"/>\n      <text x=\"70\" y=\"106\" font-family=\"system-ui, sans-serif\" font-size=\"8\" font-weight=\"800\" fill=\"#ffffff\">Acrosome</text>\n\n      <rect x=\"100\" y=\"104\" width=\"25\" height=\"12\" rx=\"3\" fill=\"#3b82f6\"/>\n      <text x=\"112\" y=\"113\" text-anchor=\"middle\" font-family=\"system-ui, sans-serif\" font-size=\"8\" font-weight=\"700\" fill=\"#ffffff\">Mitoch.</text>\n\n      <!-- Tail -->\n      <path d=\"M 125 110 Q 150 100, 180 110 T 230 110\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <text x=\"110\" y=\"135\" font-family=\"system-ui, sans-serif\" font-size=\"10\" font-weight=\"700\" fill=\"#059669\">Human Sperm (Head, Middle Piece, Tail)</text>\n\n      <!-- Menstrual Cycle Phases & Hormones (Right) -->\n      <rect x=\"330\" y=\"55\" width=\"400\" height=\"145\" rx=\"8\" fill=\"#ffffff\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"345\" y=\"75\" font-family=\"system-ui, sans-serif\" font-size=\"11\" font-weight=\"800\" fill=\"#1e293b\">Menstrual Cycle Phases (28 Days Standard):</text>\n      \n      <text x=\"345\" y=\"98\" font-family=\"system-ui, sans-serif\" font-size=\"10\" fill=\"#475569\">1. Menstrual Phase (Days 1–5): Endometrial breakdown, low progesterone</text>\n      <text x=\"345\" y=\"118\" font-family=\"system-ui, sans-serif\" font-size=\"10\" fill=\"#475569\">2. Follicular / Proliferative (Days 6–13): FSH stimulates follicles, Estrogen rises</text>\n      <text x=\"345\" y=\"138\" font-family=\"system-ui, sans-serif\" font-size=\"10\" fill=\"#dc2626\" font-weight=\"700\">3. Ovulatory Phase (Day 14): LH Surge triggers release of secondary oocyte</text>\n      <text x=\"345\" y=\"158\" font-family=\"system-ui, sans-serif\" font-size=\"10\" fill=\"#475569\">4. Luteal / Secretory (Days 15–28): Corpus luteum secretes high Progesterone</text>\n      \n      <text x=\"345\" y=\"185\" font-family=\"system-ui, sans-serif\" font-size=\"10\" font-weight=\"700\" fill=\"#059669\">• Fertilisation site: Ampullary-isthmic junction of Fallopian tube</text>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\" style=\"font-size:0.88rem; font-weight:700; color:#334155; margin-bottom:16px; padding:8px 14px; background:#ecfdf5; border-radius:8px; border-left:4px solid #059669;\">Exercises 2.1 to 2.21</div>\n\n  <div class=\"questions-container\">\n    \n  <!-- c12b-ch2-q1 (Exercise 2.1) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q1')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.1</span><br>\n        Fill in the blanks:<br>\n    <strong>(a)</strong> Humans reproduce .......... (asexually/sexually)<br>\n    <strong>(b)</strong> Humans are .......... (oviparous, viviparous, ovoviviparous)<br>\n    <strong>(c)</strong> Fertilisation is .......... in humans (external/internal)<br>\n    <strong>(d)</strong> Male and female gametes are .......... (diploid/haploid)<br>\n    <strong>(e)</strong> Zygote is .......... (diploid/haploid)<br>\n    <strong>(f)</strong> The process of release of ovum from a mature follicle is called ..........<br>\n    <strong>(g)</strong> Ovulation is induced by a hormone called ..........<br>\n    <strong>(h)</strong> The fusion of male and female gametes is called ..........<br>\n    <strong>(i)</strong> Fertilisation takes place in ..........<br>\n    <strong>(j)</strong> Zygote divides to form .......... which is implanted in uterus.<br>\n    <strong>(k)</strong> The structure which provides vascular connection between fetus and uterus is called ..........\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Answers:</strong></p>\n    <ol type=\"a\" style=\"line-height:1.8; font-weight:600;\">\n      <li><strong>sexually</strong></li>\n      <li><strong>viviparous</strong></li>\n      <li><strong>internal</strong></li>\n      <li><strong>haploid</strong></li>\n      <li><strong>diploid</strong></li>\n      <li><strong>ovulation</strong></li>\n      <li><strong>LH (Luteinising Hormone)</strong></li>\n      <li><strong>fertilisation (or syngamy)</strong></li>\n      <li><strong>ampullary-isthmic junction (or ampulla of fallopian tube)</strong></li>\n      <li><strong>blastocyst</strong></li>\n      <li><strong>placenta</strong></li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">All 11 blanks correctly answered with exact physiological terminology</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q2 (Exercise 2.2) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q2')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.2</span><br>\n        Draw a labelled diagram of the male reproductive system. Describe the pathway of sperm transport.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Major Components of Male Reproductive System:</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Primary Sex Organs:</strong> Pair of <strong>testes</strong> lodged in the extra-abdominal <strong>scrotum</strong>, maintaining a temperature $2-2.5^\\circ\\text{C}$ lower than core body temperature for spermatogenesis.</li>\n      <li><strong>Accessory Ducts:</strong> Rete testis &rarr; Vasa efferentia &rarr; Epididymis &rarr; Vas deferens &rarr; Ejaculatory duct &rarr; Urethra.</li>\n      <li><strong>Accessory Glands:</strong> Paired <strong>seminal vesicles</strong>, single <strong>prostate gland</strong>, and paired <strong>bulbourethral (Cowper's) glands</strong>.</li>\n      <li><strong>External Genitalia:</strong> Penis with specialised erectile tissue facilitating insemination.</li>\n    </ol>\n    <p><strong>Pathway of Sperm Transport:</strong><br>\n    Seminiferous tubules &rarr; Rete testis &rarr; Vasa efferentia &rarr; Epididymis (maturation &amp; storage) &rarr; Vas deferens &rarr; Joins duct of seminal vesicle to form Ejaculatory duct &rarr; Urethra &rarr; Urethral meatus.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Anatomical parts: Testes, Epididymis, Vas deferens, Glands, Urethra</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate chronological sequence of sperm pathway</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q3 (Exercise 2.3) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q3')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.3</span><br>\n        Draw a labelled diagram of the female reproductive system. Describe its primary functional components.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Key Functional Components of Female Reproductive System:</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Ovaries:</strong> Primary female sex organs producing the female gamete (ovum) and steroid hormones (estrogen and progesterone).</li>\n      <li><strong>Fallopian Tubes (Oviducts):</strong> Each $10-12 \\text{ cm}$ long, comprising three parts:\n        <ul>\n          <li><em>Infundibulum:</em> Funnel-shaped opening with finger-like <strong>fimbriae</strong> to collect ovum after ovulation.</li>\n          <li><em>Ampulla:</em> Wider curvature where fertilisation normally occurs.</li>\n          <li><em>Isthmus:</em> Narrow terminal lumen joining the uterus.</li>\n        </ul>\n      </li>\n      <li><strong>Uterus (Womb):</strong> Inverted pear-shaped organ with three wall layers: outer thin <em>perimetrium</em>, middle thick smooth muscular <em>myometrium</em> (responsible for labour contractions), and inner glandular vascular <em>endometrium</em> (undergoes cyclic changes during menstruation).</li>\n      <li><strong>Cervix and Vagina:</strong> The cervical canal along with vagina forms the <strong>birth canal</strong>.</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Anatomy: Ovaries, Oviduct parts (fimbriae, ampulla, isthmus)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Uterine layers (endometrium, myometrium, perimetrium) and birth canal</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q4 (Exercise 2.4) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q4')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.4</span><br>\n        Write two major functions each of testis and ovary.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Two Major Functions of Testis:</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Spermatogenesis:</strong> Production of viable haploid male gametes (spermatozoa) by spermatogenic cells within the seminiferous tubules.</li>\n      <li><strong>Endocrine Function:</strong> Interstitial cells of Leydig synthesise and secrete male sex hormones (<strong>androgens</strong>, principally <strong>testosterone</strong>), which stimulate spermatogenesis and maintain male secondary sexual characteristics.</li>\n    </ol>\n\n    <p><strong>Two Major Functions of Ovary:</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Oogenesis:</strong> Formation and periodic release of the mature female gamete (secondary oocyte / ovum).</li>\n      <li><strong>Endocrine Function:</strong> Secretion of female steroid sex hormones:\n        <ul>\n          <li><strong>Estrogen:</strong> Secreted by developing ovarian follicles, regulating female secondary sexual traits and endometrial repair.</li>\n          <li><strong>Progesterone:</strong> Secreted by the <em>corpus luteum</em> to prepare and maintain the endometrium for embryo implantation and pregnancy.</li>\n        </ul>\n      </li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Two distinct functions of testis (gametogenic and androgenic)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Two distinct functions of ovary (oogenic and hormonal: estrogen/progesterone)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q5 (Exercise 2.5) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q5')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.5</span><br>\n        Describe the microscopic structure of a seminiferous tubule.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Microscopic Structure of Seminiferous Tubule:</strong><br>\n    Each testicular lobule contains 1 to 3 highly coiled seminiferous tubules lined internally by a specialised germinal epithelium containing two types of cells:</p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Male Germ Cells (Spermatogonia):</strong> Diploid stem cells that undergo meiotic divisions to successively produce primary spermatocytes, secondary spermatocytes, spermatids, and finally mature spermatozoa.</li>\n      <li><strong>Sertoli Cells (Nurse Cells):</strong> Large, elongated pyramid-shaped somatic cells that provide physical support, nutritional nourishment, and chemical factors to developing spermatogenic cells. They also secrete androgen-binding protein (ABP) and inhibin, and form the blood-testis barrier.</li>\n      <li><strong>Interstitial Space:</strong> The connective tissue regions outside the seminiferous tubules contain small blood vessels and clusters of polyhedral <strong>Leydig cells (interstitial cells)</strong>, which synthesise and secrete androgens (testosterone) under LH stimulation, along with immunocompetent cells.</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Description of germinal epithelium and Spermatogonia</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Structure and functions of Sertoli (nurse) cells</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Interstitial space and Leydig cells synthesizing testosterone</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q6 (Exercise 2.6) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q6')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.6</span><br>\n        What is spermatogenesis? Briefly describe the process of spermatogenesis with a schematic representation.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Definition:</strong><br>\n    Spermatogenesis is the biological process of formation of mature, motile haploid spermatozoa from diploid immature male germ cells (spermatogonia) within the seminiferous tubules of testes, initiating at puberty.</p>\n\n    <p><strong>2. Stages of Spermatogenesis:</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Multiplication Phase:</strong> Spermatogonia ($2n = 46$) situated on the inner wall of seminiferous tubules multiply by repeated mitosis.</li>\n      <li><strong>Growth Phase:</strong> Some spermatogonia enlarge to form diploid <strong>primary spermatocytes ($2n$)</strong>.</li>\n      <li><strong>Maturation Phase (Meiosis):</strong>\n        <ul>\n          <li>Each primary spermatocyte undergoes <em>Meiosis I (reductional division)</em> to form two equal haploid <strong>secondary spermatocytes ($n = 23$)</strong>.</li>\n          <li>Secondary spermatocytes undergo <em>Meiosis II (equational division)</em> to produce four equal haploid <strong>spermatids ($n = 23$)</strong>.</li>\n        </ul>\n      </li>\n      <li><strong>Spermiogenesis:</strong> The non-motile, spherical spermatids are transformed into specialised, motile, flagellated <strong>spermatozoa (sperms)</strong>.</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition of spermatogenesis</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sequential phases (Multiplication, Growth, Meiosis I & II)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ploidy levels ($2n \to n$) and transformation of spermatids</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q7 (Exercise 2.7) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q7')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.7</span><br>\n        Name the hormones involved in regulation of spermatogenesis and explain their physiological roles.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Hormonal Regulation of Spermatogenesis:</strong><br>\n    Spermatogenesis is initiated at puberty due to the significant increase in the secretion of <strong>GnRH (Gonadotropin Releasing Hormone)</strong> from the hypothalamus.</p>\n\n    <ol style=\"line-height:1.8;\">\n      <li><strong>GnRH:</strong> Acts on the anterior pituitary gland and stimulates the secretion of two gonadotropins: LH and FSH.</li>\n      <li><strong>LH (Luteinising Hormone / ICSH):</strong> Acts directly on the <strong>Leydig cells</strong> and stimulates them to synthesise and secrete <strong>androgens (testosterone)</strong>. Testosterone in turn triggers and maintains spermatogenesis.</li>\n      <li><strong>FSH (Follicle Stimulating Hormone):</strong> Acts on <strong>Sertoli cells</strong> and stimulates secretion of <em>Androgen Binding Protein (ABP)</em> (which concentrates testosterone in seminiferous tubules) and factors essential for <strong>spermiogenesis</strong>.</li>\n      <li><strong>Inhibin:</strong> Secreted by Sertoli cells, exerts negative feedback on anterior pituitary to suppress excess FSH release when sperm count is high.</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Hypothalamic GnRH triggering pituitary gonadotropins</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of LH acting on Leydig cells for testosterone</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of FSH acting on Sertoli cells and inhibin feedback</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q8 (Exercise 2.8) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q8')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.8</span><br>\n        Define spermiogenesis and spermiation.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Spermiogenesis:</strong><br>\n    The physiological and morphological transformation of non-motile, round, haploid <strong>spermatids into mature, motile spermatozoa (sperms)</strong>. During this process, the Golgi complex condenses into the acrosome, the nucleus condenses, mitochondria spiral around the axial filament in the middle piece, and a long flagellar tail is formed.</p>\n\n    <p><strong>2. Spermiation:</strong><br>\n    The final detachment and <strong>release of fully formed mature spermatozoa from the Sertoli cells</strong> into the central lumen of the seminiferous tubule.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition of spermiogenesis (spermatid to spermatozoon)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition of spermiation (release from Sertoli cells into lumen)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q9 (Exercise 2.9) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q9')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.9</span><br>\n        Draw a labelled diagram of human sperm. Describe the structure and function of each region.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Structural Regions of Human Spermatozoon:</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Head:</strong> Contains an elongated haploid nucleus ($n = 23$) carrying paternal genetic material. Its anterior two-thirds is capped by the <strong>acrosome</strong>, a lysosome-derived vesicle filled with proteolytic hydrolytic enzymes (hyaluronidase, corona penetrating enzyme, acrosin) essential for penetrating the outer coats of the ovum.</li>\n      <li><strong>Neck:</strong> Very short segment containing a <em>proximal centriole</em> (initiates cleavage divisions in the fertilised egg) and a <em>distal centriole</em> (gives rise to the axial filament of the tail).</li>\n      <li><strong>Middle Piece:</strong> Contains numerous densely packed mitochondria spiralling around the axial filament (<em>nebenkern</em>), providing metabolic energy (ATP) to power the tail for sperm motility.</li>\n      <li><strong>Tail:</strong> A long flagellum surrounded by a plasma membrane, executing vigorous undulating lashing movements that propel the sperm through the female reproductive tract towards the ampulla.</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Head and acrosome enzymes with genetic role</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Middle piece and mitochondria providing energy for motility</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Neck centrioles and tail flagellum mechanism</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q10 (Exercise 2.10) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q10')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.10</span><br>\n        What are the major components of seminal plasma?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Components of Seminal Plasma:</strong><br>\n    Seminal plasma is the collective alkaline fluid secretion contributed by the male accessory glands (seminal vesicles $\\sim 60-70\\%$, prostate gland $\\sim 20-30\\%$, and bulbourethral glands $\\sim 5\\%$):</p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Fructose:</strong> Unique monosaccharide secreted by seminal vesicles serving as the primary energetic nutrient for sperm motility (also used as forensic marker for rape confirmation).</li>\n      <li><strong>Calcium Ions ($Ca^{2+}$) and Enzymes:</strong> Required for sperm motility and activation.</li>\n      <li><strong>Prostaglandins:</strong> Stimulate reverse peristaltic contractions in the female reproductive tract to help propel sperms towards the fallopian tubes.</li>\n      <li><strong>Alkaline Buffers / Bicarbonates:</strong> Neutralise the acidic vaginal environment ($\text{pH } 3.5 - 4.0$), safeguarding sperm survival.</li>\n      <li><strong>Mucus:</strong> Secreted by bulbourethral glands, facilitating lubrication of the penis.</li>\n      <li><strong>Clotting Enzymes &amp; Fibrinolysin:</strong> Help in coagulation and subsequent liquefaction of semen.</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Fructose as specific energy source</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calcium, prostaglandins and buffering components</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Lubricating mucus from bulbourethral glands</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q11 (Exercise 2.11) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q11')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.11</span><br>\n        What are the major functions of male accessory ducts and glands?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Functions of Male Accessory Ducts (Rete testis, Vasa efferentia, Epididymis, Vas deferens):</strong><br>\n    • <strong>Transport:</strong> Conduct spermatozoa from seminiferous tubules to the outside through the urethra.<br>\n    • <strong>Maturation &amp; Storage:</strong> The <em>epididymis</em> serves as the physiological site for temporary storage where spermatozoa undergo biochemical maturation, acquire functional motility, and fertilising capacity.</p>\n\n    <p><strong>2. Functions of Male Accessory Glands:</strong><br>\n    • <strong>Seminal Vesicles:</strong> Secrete nutrient-rich alkaline fluid containing fructose, prostaglandins, and clotting proteins to nourish and activate sperms.<br>\n    • <strong>Prostate Gland:</strong> Secretes a milky, slightly alkaline fluid containing citric acid, enzymes, and calcium that enhances motility.<br>\n    • <strong>Bulbourethral (Cowper's) Glands:</strong> Secrete clear, alkaline mucus prior to ejaculation to lubricate the glans penis and neutralise traces of acidic urine in the urethra.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Functions of ducts (transport, storage, epididymal maturation)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Specific functions of Seminal vesicles, Prostate, and Bulbourethral glands</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q12 (Exercise 2.12) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q12')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.12</span><br>\n        What is oogenesis? Give a brief account of oogenesis.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Definition:</strong><br>\n    Oogenesis is the biological process of formation of a mature haploid female gamete (ovum) within the ovary. Unlike spermatogenesis, it initiates during embryonic development.</p>\n\n    <p><strong>2. Stages of Oogenesis:</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Prenatal Phase (Fetal Life):</strong> A couple of million gamete mother cells (<strong>oogonia, $2n$</strong>) are formed in each fetal ovary; no more are formed after birth. Oogonia enter <em>Prophase-I of Meiosis-I</em> and get temporarily arrested as <strong>primary oocytes ($2n$)</strong>.</li>\n      <li><strong>Follicular Atresia:</strong> From birth to puberty, a large number of primary follicles degenerate, leaving only $60,000 - 80,000$ in each ovary at puberty.</li>\n      <li><strong>First Meiotic Division (At Puberty):</strong> Prior to ovulation, the primary oocyte completes its unequal Meiosis-I, producing a large haploid <strong>secondary oocyte ($n$)</strong> and a tiny <strong>first polar body ($n$)</strong>.</li>\n      <li><strong>Second Meiotic Division (At Fertilisation):</strong> The secondary oocyte is arrested at <em>Metaphase-II</em> and ovulated. Meiosis-II is completed only upon sperm entry (fertilisation), producing a mature <strong>ovum (ootid, $n$)</strong> and a <strong>second polar body ($n$)</strong>.</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition and embryonic initiation of oogenesis</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Primary oocyte arrest at Prophase-I and follicular atresia</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Unequal division yielding secondary oocyte ($n$) and polar body completion upon sperm entry</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q13 (Exercise 2.13) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q13')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.13</span><br>\n        Draw a labelled diagram of a section through human ovary showing different stages of follicular development.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Sequential Stages Visible in Ovarian Section:</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Primary Follicle:</strong> Primary oocyte enclosed by a single layer of granulosa cells.</li>\n      <li><strong>Secondary Follicle:</strong> More granulosa layers surrounded by a connective tissue <em>theca</em>.</li>\n      <li><strong>Tertiary Follicle:</strong> Characterised by an inner fluid-filled cavity called the <strong>antrum</strong>, with theca differentiated into <em>theca interna</em> (vascular, estrogen-secreting) and <em>theca externa</em>.</li>\n      <li><strong>Mature Graafian Follicle:</strong> Large follicle bulging at ovarian surface, containing secondary oocyte surrounded by the <em>zona pellucida</em> and <em>corona radiata</em>.</li>\n      <li><strong>Ovulation:</strong> Rupture of Graafian follicle releasing the secondary oocyte into peritoneal cavity.</li>\n      <li><strong>Corpus Luteum:</strong> Remnants of ruptured follicle luteinised into an endocrine body secreting progesterone.</li>\n      <li><strong>Corpus Albicans:</strong> Degenerated white fibrous scar of corpus luteum when pregnancy fails.</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Primary, secondary, and tertiary follicle with antrum</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Graafian follicle rupture (ovulation)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Corpus luteum and corpus albicans formation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q14 (Exercise 2.14) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q14')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.14</span><br>\n        Describe the structure of a mature Graafian follicle with a neat labelled diagram.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Structure of Mature Graafian Follicle:</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Theca Layers:</strong> Outer protective fibrous <em>theca externa</em> and inner cellular, highly vascular <em>theca interna</em> that actively secretes estrogen.</li>\n      <li><strong>Membrana Granulosa:</strong> Stratified layer of follicle/granulosa cells lining the follicle wall.</li>\n      <li><strong>Antrum:</strong> A large, crescent-shaped, central cavity filled with viscous fluid (<em>liquor folliculi</em>).</li>\n      <li><strong>Cumulus Oophorus (Germ Hill):</strong> A stalk of granulosa cells anchoring the oocyte to the follicle wall.</li>\n      <li><strong>Secondary Oocyte:</strong> Centrally situated haploid cell arrested at Metaphase-II.</li>\n      <li><strong>Zona Pellucida:</strong> A non-cellular, translucent, glycoproteinaceous membrane directly enclosing the oocyte.</li>\n      <li><strong>Corona Radiata:</strong> Radially elongated granulosa cells adhering firmly to the exterior of the zona pellucida.</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Theca externa & theca interna descriptions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Antrum and liquor folliculi</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Secondary oocyte with zona pellucida and corona radiata</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q15 (Exercise 2.15) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q15')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.15</span><br>\n        Name the functions of the following:<br>\n    <strong>(a)</strong> Corpus luteum<br>\n    <strong>(b)</strong> Endometrium<br>\n    <strong>(c)</strong> Acrosome<br>\n    <strong>(d)</strong> Sperm tail<br>\n    <strong>(e)</strong> Fimbriae.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Functions:</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>(a) Corpus Luteum:</strong> Acts as a temporary endocrine gland that secretes large quantities of <strong>progesterone</strong> (and some estrogen and inhibin), essential for maintaining the thickened endometrium for implantation and sustaining pregnancy.</li>\n      <li><strong>(b) Endometrium:</strong> The innermost glandular vascular layer of the uterus that provides the physical site for <strong>blastocyst implantation</strong> and placenta formation; sheds periodically during menstruation if fertilisation does not occur.</li>\n      <li><strong>(c) Acrosome:</strong> Releases proteolytic sperm lysins (hyaluronidase, acrosin) to digest the corona radiata and zona pellucida of the ovum, enabling <strong>sperm penetration and fertilisation</strong>.</li>\n      <li><strong>(d) Sperm Tail:</strong> Performs vigorous whip-like undulating movements powered by ATP from the middle piece, providing <strong>motility</strong> for sperm transport through the female tract.</li>\n      <li><strong>(e) Fimbriae:</strong> Finger-like ciliated projections at the edges of the infundibulum that sweep across the ovary surface to <strong>capture the released ovum</strong> after ovulation and direct it into the fallopian tube.</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">One accurate, specific functional description for each part (1 Mark each)</span><span class=\"marking-marks\">5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q16 (Exercise 2.16) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q16\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q16')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.16</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.16</span><br>\n        Identify True/False statements. Correct each false statement:<br>\n    <strong>(a)</strong> Androgens are produced by Sertoli cells.<br>\n    <strong>(b)</strong> Spermatozoa get nutrition from Sertoli cells.<br>\n    <strong>(c)</strong> Leydig cells are found in ovary.<br>\n    <strong>(d)</strong> Leydig cells synthesise androgens.<br>\n    <strong>(e)</strong> Oogenesis takes place in corpus luteum.<br>\n    <strong>(f)</strong> Menstrual cycle ceases during pregnancy.<br>\n    <strong>(g)</strong> Presence or absence of hymen is not a reliable indicator of virginity or sexual experience.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Evaluations and Corrections:</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>(a) False.</strong> Androgens are produced by the <strong>Leydig cells (interstitial cells)</strong>, not Sertoli cells.</li>\n      <li><strong>(b) True.</strong> Sertoli cells act as nurse cells providing nourishment to developing spermatozoa.</li>\n      <li><strong>(c) False.</strong> Leydig cells are found in the <strong>testis</strong> (in interstitial spaces between seminiferous tubules), not ovary.</li>\n      <li><strong>(d) True.</strong> Leydig cells synthesise and secrete androgens (primarily testosterone).</li>\n      <li><strong>(e) False.</strong> Oogenesis takes place in the <strong>ovary (ovarian follicles)</strong>, not in the corpus luteum (which forms after ovulation).</li>\n      <li><strong>(f) True.</strong> High progesterone from corpus luteum and placenta suppresses gonadotropins (LH/FSH), halting menstrual cycles during pregnancy.</li>\n      <li><strong>(g) True.</strong> The hymen can be torn by physical exertion, horseback riding, cycling, or using tampons, or may persist even after coitus; hence it is not a reliable indicator of virginity.</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">All seven statements correctly identified with valid corrections for false statements (0.5 Mark each)</span><span class=\"marking-marks\">3.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q17 (Exercise 2.17) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q17\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q17')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.17</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.17</span><br>\n        What is the menstrual cycle? Which hormones regulate the menstrual cycle?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Definition:</strong><br>\n    The menstrual cycle is the rhythmic series of cyclic natural physiological changes occurring in the ovaries and the uterine endometrium of female primates (human, apes, monkeys) roughly every $28-29 \\text{ days}$, from menarche (puberty) to menopause, preparing the uterus for potential pregnancy.</p>\n\n    <p><strong>2. Hormones Regulating the Menstrual Cycle:</strong></p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Pituitary Gonadotropins:</strong>\n        <ul>\n          <li><strong>FSH (Follicle Stimulating Hormone):</strong> Stimulates development of primary ovarian follicles into mature Graafian follicles and stimulates estrogen secretion.</li>\n          <li><strong>LH (Luteinising Hormone):</strong> A rapid mid-cycle surge of LH (<strong>LH Surge</strong> on Day 14) induces the rupture of the Graafian follicle and release of the secondary oocyte (<strong>ovulation</strong>), and converts the ruptured follicle into the <em>corpus luteum</em>.</li>\n        </ul>\n      </li>\n      <li><strong>Ovarian Steroid Hormones:</strong>\n        <ul>\n          <li><strong>Estrogen:</strong> Secreted by growing follicles, promotes repair and proliferation of the uterine endometrium.</li>\n          <li><strong>Progesterone:</strong> Secreted in large amounts by the corpus luteum during the secretory phase, maintaining the vascularised endometrium essential for implantation.</li>\n        </ul>\n      </li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition and periodicity of menstrual cycle</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pituitary hormones: FSH (follicular growth) and LH surge (ovulation)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ovarian hormones: Estrogen (proliferation) and Progesterone (maintenance)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q18 (Exercise 2.18) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q18\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q18')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.18</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.18</span><br>\n        What is parturition? Which hormones are involved in the induction of parturition?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Definition:</strong><br>\n    Parturition (childbirth) is the biological process of vigorous uterine contractions resulting in the expulsion or delivery of the mature fetus from the uterus through the birth canal at the end of gestation.</p>\n\n    <p><strong>2. Neuroendocrine Mechanism &amp; Hormones Involved:</strong><br>\n    Parturition is triggered by a complex <strong>neuroendocrine mechanism</strong> initiated by the fully developed fetus and placenta, generating mild uterine contractions termed the <strong>foetal ejection reflex</strong>.</p>\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Oxytocin:</strong> The foetal ejection reflex triggers the release of <strong>oxytocin</strong> from the maternal posterior pituitary. Oxytocin acts on the uterine myometrium, causing stronger contractions, which in turn stimulates further oxytocin secretion (positive feedback loop) until the baby is expelled.</li>\n      <li><strong>Relaxin:</strong> Secreted by the ovary/placenta towards term to relax the pubic symphysis ligament and dilate the cervix.</li>\n      <li><strong>Estrogen and Progesterone:</strong> The estrogen-to-progesterone ratio increases, increasing oxytocin receptors on myometrial cells.</li>\n      <li><strong>Prostaglandins:</strong> Produced locally in the uterine wall, amplifying the intensity of contractions.</li>\n    </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition and foetal ejection reflex neuroendocrine mechanism</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Key role of oxytocin positive feedback and supporting hormones (relaxin, prostaglandins)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q19 (Exercise 2.19) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q19\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q19')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.19</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.19</span><br>\n        In our society women are often blamed for giving birth to daughters. Can you explain why this is scientifically completely incorrect?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Scientific Basis of Sex Determination in Humans:</strong><br>\n    Sex in human beings is determined by the chromosomal constitution of the fertilising sperm from the father, not the mother (XY sex-determination system).</p>\n\n    <ol style=\"line-height:1.8;\">\n      <li><strong>Female Homogamety:</strong> Females have two identical $X$ sex chromosomes ($44 + XX$). During oogenesis, all ova produced are genetically identical, each carrying an $X$ chromosome ($22 + X$). The mother is completely <strong>homogametic</strong>.</li>\n      <li><strong>Male Heterogamety:</strong> Males have two different sex chromosomes ($44 + XY$). During spermatogenesis, the father produces two equal types of sperms in a $50:50$ ratio:\n        <ul>\n          <li>$50\\%$ gynosperms carrying an $X$ chromosome ($22 + X$).</li>\n          <li>$50\\%$ androsperms carrying a $Y$ chromosome ($22 + Y$).</li>\n        </ul>\n      </li>\n      <li><strong>Fertilisation Outcome:</strong>\n        <ul>\n          <li>If an $X$-carrying sperm fertilises the ovum: $(22 + X) + (22 + X) = 44 + XX implies$ <strong>Female child (daughter)</strong>.</li>\n          <li>If a $Y$-carrying sperm fertilises the ovum: $(22 + Y) + (22 + X) = 44 + XY implies$ <strong>Male child (son)</strong>.</li>\n        </ul>\n      </li>\n    </ol>\n    <p><strong>Conclusion:</strong> The genetic sex of the baby depends strictly on whether an $X$ or $Y$ sperm from the father fertilises the ovum. Blaming the mother is scientifically unfounded and socially unjust.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of female homogamety ($XX$) producing only $X$ ova</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of male heterogamety ($XY$) producing $X$ and $Y$ sperms (50:50)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clear conclusion that paternal sperm determines gender</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q20 (Exercise 2.20) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q20\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q20')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.20</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.20</span><br>\n        How many eggs are released by a human ovary in a month? How many eggs do you think would have been released if the mother gave birth to identical twins? Are fraternal twins different?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Eggs Released in a Month:</strong><br>\n    Normally, only <strong>one single egg (secondary oocyte)</strong> is released by one of the ovaries during each menstrual cycle (roughly every 28 days), with the ovaries typically alternating each month.</p>\n\n    <p><strong>2. In Case of Identical (Monozygotic) Twins:</strong><br>\n    Only <strong>one egg</strong> was released. A single ovum is fertilised by a single sperm to form one diploid zygote. During early cleavage stages (blastocyst), the inner cell mass splits into two separate embryonic clusters, producing two genetically identical individuals of the same sex.</p>\n\n    <p><strong>3. Fraternal (Dizygotic) Twins:</strong><br>\n    <strong>Yes, fraternal twins are fundamentally different.</strong><br>\n    • They arise when <strong>two separate eggs</strong> are released simultaneously during the same cycle (hyperovulation) and fertilised by <strong>two different sperms</strong>.<br>\n    • They are no more genetically alike than ordinary siblings born at different times, and can be of the same sex or different sexes.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">One egg per month in normal human ovulation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Monozygotic twins: one egg fertilised by one sperm splitting</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Dizygotic twins: two eggs fertilised by two sperms</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch2-q21 (Exercise 2.21) -->\n  <div class=\"q-card\" id=\"c12b-ch2-q21\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch2-q21')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q 2.21</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercise 2.21</span><br>\n        How many eggs do you think were released by the ovary of a female dog which gave birth to 6 puppies?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Answer:</strong><br>\n    A female dog is a litter-bearing, multiparous animal. Assuming each puppy developed from a separate fertilised zygote (dizygotic/polyovulatory mechanism typical of canine litters):<br>\n    • <strong>At least 6 eggs (or slightly more)</strong> were released by the ovaries during the estrus cycle.<br>\n    • Each individual ovum was fertilised by a separate sperm to produce 6 viable embryos.<br>\n    (Note: If any pair among the puppies were identical monozygotic twins, the number of eggs released could theoretically be fewer, but in dogs, multiple births primarily result from multiple simultaneous ovulations).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">6 eggs released due to polyovulatory nature of dogs</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"display:flex; justify-content:space-between; align-items:center; margin-top:36px; padding-top:20px; border-top:1px solid #e2e8f0;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(1)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 1</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(3)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#059669; color:white; font-weight:700; cursor:pointer;\">Next: Ch 3 (Reproductive Health) →</button>\n  </div>\n</section>";
window.CHAPTER_DATA[3] = "<section class=\"chapter-section\" id=\"c12b-ch3\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#059669;\">3</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#059669;\">CBSE Class 12 Biology &bull; Chapter 3</div>\n      <h2>Reproductive Health</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 12 Verbatim Questions with Official CBSE Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n<div class=\"chem-card\" style=\"margin-bottom:24px; padding:20px; background:#f0fdf4; border:1px solid #bbf7d0; border-radius:12px;\">\n  <h4 style=\"margin:0 0 12px 0; color:#059669; font-size:1.05rem;\">🧬 Key Concept Map: Contraceptive Strategies & Assisted Reproductive Technologies (ART)</h4>\n  <svg viewBox=\"0 0 880 320\" style=\"width:100%; max-width:880px; height:auto; display:block; margin:0 auto; background:white; border-radius:8px; border:1px solid #d1fae5;\">\n    <!-- Flowchart / Concept Architecture -->\n    <!-- Natural Methods -->\n    <rect x=\"20\" y=\"20\" width=\"180\" height=\"90\" rx=\"8\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"110\" y=\"45\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Natural / Traditional</text>\n    <text x=\"110\" y=\"65\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Periodic Abstinence</text>\n    <text x=\"110\" y=\"80\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Coitus Interruptus</text>\n    <text x=\"110\" y=\"95\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Lactational Amenorrhea</text>\n\n    <!-- Barrier Methods -->\n    <rect x=\"230\" y=\"20\" width=\"190\" height=\"90\" rx=\"8\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"325\" y=\"45\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Barrier Methods</text>\n    <text x=\"325\" y=\"65\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Condoms (Nirodh - male/fem)</text>\n    <text x=\"325\" y=\"80\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Diaphragms & Cervical Caps</text>\n    <text x=\"325\" y=\"95\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Blocks STIs/STDs</text>\n\n    <!-- IUDs & Chemical -->\n    <rect x=\"450\" y=\"20\" width=\"200\" height=\"90\" rx=\"8\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"550\" y=\"45\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Intrauterine Devices (IUDs)</text>\n    <text x=\"550\" y=\"65\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Non-medicated (Lippes loop)</text>\n    <text x=\"550\" y=\"80\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Cu-releasing (CuT, Cu7, Multiload)</text>\n    <text x=\"550\" y=\"95\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Hormone-releasing (Progestasert, LNG-20)</text>\n\n    <!-- Surgical / Sterilization -->\n    <rect x=\"680\" y=\"20\" width=\"180\" height=\"90\" rx=\"8\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"770\" y=\"45\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Surgical / Permanent</text>\n    <text x=\"770\" y=\"65\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Vasectomy (Vas deferens tied)</text>\n    <text x=\"770\" y=\"82\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Tubectomy (Fallopian tubes tied)</text>\n    <text x=\"770\" y=\"97\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Terminal block to gamete transport</text>\n\n    <!-- Connector lines -->\n    <line x1=\"440\" y1=\"120\" x2=\"440\" y2=\"160\" stroke=\"#059669\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n    <text x=\"440\" y=\"150\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#059669\" text-anchor=\"middle\" background=\"white\">Assisted Reproductive Technologies (ART)</text>\n\n    <!-- In Vitro Fertilisation (IVF) -->\n    <rect x=\"80\" y=\"180\" width=\"220\" height=\"110\" rx=\"8\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <text x=\"190\" y=\"205\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">IVF - Test Tube Baby</text>\n    <text x=\"190\" y=\"225\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Fertilisation outside in lab</text>\n    <text x=\"190\" y=\"243\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; ZIFT: Zygote up to 8 blastomeres &rarr; Tube</text>\n    <text x=\"190\" y=\"261\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; IUT: Embryo &gt; 8 blastomeres &rarr; Uterus</text>\n    <text x=\"190\" y=\"278\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; ICSI: Direct sperm injection</text>\n\n    <!-- In Vivo Fertilisation / Transfer -->\n    <rect x=\"340\" y=\"180\" width=\"220\" height=\"110\" rx=\"8\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <text x=\"450\" y=\"205\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">In Vivo Fertilisation</text>\n    <text x=\"450\" y=\"228\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; GIFT: Gamete Intra-Fallopian</text>\n    <text x=\"450\" y=\"246\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">Transfer (Ovum collected from donor)</text>\n    <text x=\"450\" y=\"264\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; For females who cannot produce ova</text>\n    <text x=\"450\" y=\"280\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">but can provide internal environment</text>\n\n    <!-- Artificial Insemination (AI) -->\n    <rect x=\"600\" y=\"180\" width=\"220\" height=\"110\" rx=\"8\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <text x=\"710\" y=\"205\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Artificial Insemination (AI)</text>\n    <text x=\"710\" y=\"228\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Semen collected from husband/donor</text>\n    <text x=\"710\" y=\"246\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; IUI: Intra-Uterine Insemination</text>\n    <text x=\"710\" y=\"264\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">&bull; Indicated for low sperm count</text>\n    <text x=\"710\" y=\"280\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\" text-anchor=\"middle\">(oligospermia) or erectile dysfunction</text>\n  </svg>\n</div>\n\n  <div class=\"ex-div\" style=\"font-size:0.88rem; font-weight:700; color:#334155; margin-bottom:16px; padding:8px 14px; background:#ecfdf5; border-radius:8px; border-left:4px solid #059669;\">NCERT Exercises (12 Verbatim Questions)</div>\n\n  <div class=\"questions-container\">\n    \n  <!-- c12b-ch3-q1 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch3-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch3-q1')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What do you think is the significance of reproductive health in a society?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>According to the <strong>World Health Organization (WHO)</strong>, reproductive health signifies a total well-being in all aspects of reproduction, including <strong>physical, emotional, behavioural, and social aspects</strong>.</p>\n  <p>The significance of achieving reproductive health in a society includes:</p>\n  <ol>\n    <li><strong>Prevention of Sexually Transmitted Infections (STIs):</strong> Creating awareness about hygienic sexual practices and protective barrier methods prevents the spread of STIs such as HIV/AIDS, Gonorrhoea, Syphilis, and Hepatitis-B.</li>\n    <li><strong>Population Stabilisation & Planned Parenthood:</strong> Educating couples regarding small family norms, birth spacing, and accessible contraceptives prevents unwanted pregnancies and curbs explosive population growth.</li>\n    <li><strong>Maternal and Infant Healthcare:</strong> Ensuring pre-natal, natal, and post-natal care reduces Maternal Mortality Rate (MMR) and Infant Mortality Rate (IMR).</li>\n    <li><strong>Eradication of Social Evils & Myths:</strong> Combating female foeticide, teenage pregnancy, illegal abortions, and sex-related crimes through scientifically grounded sexual education and stringent enforcement of laws (such as PCPNDT Act).</li>\n    <li><strong>Healthy Future Generation:</strong> A reproductively healthy society consists of physically sound individuals with responsible, emotionally balanced relationships, reducing societal disease burden and healthcare stress.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">WHO definition of reproductive health (total well-being across physical, emotional, behavioural, social aspects)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Key societal benefits (prevention of STIs, lowering MMR and IMR, population control)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Eradication of myths, prevention of female foeticide, and fostering healthy future generations</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch3-q2 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch3-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch3-q2')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Suggest the aspects of reproductive health which need to be given special attention in the present scenario.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>In the present socio-demographic scenario, the following core aspects require targeted interventions:</p>\n  <ol>\n    <li><strong>Adolescent Sex Education:</strong> Introducing age-appropriate, scientifically validated sexual education in schools to dispel myths, address bodily changes during puberty, and promote responsible adolescent behaviour.</li>\n    <li><strong>Awareness of STIs and Safe Sex:</strong> Disseminating clear knowledge about transmission vectors of STIs/HIV and advocating the consistent use of barrier contraceptives (condoms).</li>\n    <li><strong>Curbing Population Explosion via Family Planning:</strong> Promoting reversible contraceptives, non-hormonal oral pills (like <em>Saheli</em>), and providing incentives for small family norms.</li>\n    <li><strong>Eradication of Female Foeticide:</strong> Enforcing strict statutory bans on amniocentesis for foetal sex determination and monitoring ultrasound clinics under the PCPNDT Act.</li>\n    <li><strong>Maternal & Child Health Care (MCH):</strong> Promoting institutional deliveries, nutritional support for pregnant and lactating mothers, and mandatory infant immunisation programmes.</li>\n    <li><strong>Detection & Management of Reproductive Cancers:</strong> Early screening infrastructure for cervical, breast, and prostate cancers.</li>\n    <li><strong>Infertility Counselling & Accessible ART:</strong> Providing psychological support and cost-effective Assisted Reproductive Technologies (IVF, ZIFT, ICSI) for infertile couples.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Adolescent sex education and STI prevention awareness</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Maternal and infant healthcare, family planning, and contraceptive accessibility</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Strict legal ban on sex determination (female foeticide) and infertility management</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch3-q3 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch3-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch3-q3')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Is sex education necessary in schools? Why?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Yes, sex education is absolutely necessary in schools.</strong></p>\n  <p><strong>Scientific and Societal Reasons:</strong></p>\n  <ol>\n    <li><strong>Dissemination of Accurate Information:</strong> Adolescents undergo rapid anatomical, hormonal, and psychological changes during puberty. School-based sex education provides authentic scientific information about secondary sexual characteristics and reproductive anatomy, preventing peer misinformation.</li>\n    <li><strong>Dispelling Myths and Misconceptions:</strong> It prevents adolescents from falling prey to taboos, cultural stigmas, anxiety, and unfounded guilt regarding masturbation, nocturnal emissions, and menstruation.</li>\n    <li><strong>Prevention of Sexually Transmitted Infections (STIs):</strong> Educates students on safe sexual practices, the risks of unprotected intercourse, and prevention of fatal infections such as HIV/AIDS, Hepatitis-B, and HPV.</li>\n    <li><strong>Avoidance of Teenage Pregnancies:</strong> Informs youngsters about the physical, emotional, and social consequences of early sexual encounters and unplanned teenage pregnancies.</li>\n    <li><strong>Awareness on Reproductive Rights & Abuse Prevention:</strong> Equips youth with knowledge on bodily autonomy, recognising sexual harassment/abuse (POCSO awareness), and developing mutual gender respect.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear affirmative stance (Yes) with rationale on puberty and reproductive anatomy</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Dispelling myths, preventing STIs (HIV/AIDS), and avoiding teenage pregnancy</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Promoting safe sexual practices, bodily autonomy, and gender respect</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch3-q4 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch3-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch3-q4')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Do you think that reproductive health in our country has improved in the past fifty years? If yes, mention some such areas of improvement.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Yes, the reproductive health in India has shown significant, quantifiable improvement over the past fifty years.</strong> India was among the first countries in the world to launch a nationwide <strong>Family Planning Programme</strong> in 1951, later expanded as the <strong>Reproductive and Child Health Care (RCH) Programme</strong>.</p>\n  <p><strong>Key Areas of Improvement:</strong></p>\n  <ul>\n    <li><strong>Decline in MMR and IMR:</strong> Enhanced antenatal, delivery, and postnatal medical facilities have led to a dramatic decrease in the Maternal Mortality Rate (MMR) and Infant Mortality Rate (IMR).</li>\n    <li><strong>Increase in Institutional Deliveries:</strong> Shift from unassisted home deliveries to hospital-based institutional deliveries conducted by trained healthcare professionals.</li>\n    <li><strong>Mass Immunisation Programmes:</strong> Universal childhood immunisation has successfully controlled life-threatening infant infections like polio, tetanus, and measles.</li>\n    <li><strong>Availability and Adoption of Modern Contraceptives:</strong> Widespread availability of diverse contraceptive choices, including non-steroidal once-a-week oral pills like <em>Saheli</em> (developed by CDRI, Lucknow), copper-releasing IUDs, and condoms.</li>\n    <li><strong>Better Diagnostic & Medical Facilities:</strong> Early diagnosis and clinical management of STIs, reproductive cancers, and ectopic pregnancies.</li>\n    <li><strong>Assisted Reproductive Technology (ART) Facilities:</strong> Establishment of specialized fertility clinics offering IVF, ZIFT, and ICSI to assist infertile couples.</li>\n    <li><strong>Legal Frameworks & Public Awareness:</strong> Enactment of laws raising legal age of marriage (18 for females, 21 for males) and the strict ban on prenatal sex determination.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmation (Yes) and reference to National Family Planning (1951) and RCH programmes</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Decline in MMR/IMR and rise in institutional deliveries & immunisation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Advancements in contraceptive access (Saheli, IUDs) and ART fertility centers</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch3-q5 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch3-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch3-q5')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What are the suggested reasons for population explosion?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>The dramatic escalation in world and national human population in recent decades (population explosion) is attributed to the following major factors:</p>\n  <ol>\n    <li><strong>Rapid Decline in Death Rate:</strong> Breakthroughs in modern medicine, antibiotic therapies, mass sanitation, and vector control have drastically reduced the crude death rate.</li>\n    <li><strong>Sharp Decrease in Maternal Mortality Rate (MMR):</strong> Safe institutional deliveries, sterile obstetric procedures, and improved emergency maternal care have prevented childbirth-related maternal deaths.</li>\n    <li><strong>Sharp Decrease in Infant Mortality Rate (IMR):</strong> Universal immunisation, neonatal intensive care units (NICUs), and better maternal nutrition have protected neonates and infants from infant mortality.</li>\n    <li><strong>Increase in Longevity / Life Expectancy:</strong> Improved standards of living, disease eradication, and famine control have raised the average human lifespan from ~32 years (in 1947) to over 70 years today.</li>\n    <li><strong>Large Proportion of Population in Reproductive Age:</strong> A demographic bulge with a vast cohort of young individuals entering reproductive maturity (15–45 years).</li>\n    <li><strong>Socio-Cultural Factors & Illiteracy:</strong> Persistence of traditional preference for male offspring, religious dogmas resisting family planning, and low literacy levels in rural belts.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Decline in crude death rate and increase in life expectancy due to medical advancements</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sharp drop in Maternal Mortality Rate (MMR) and Infant Mortality Rate (IMR)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">High percentage of population in reproductive age cohort and socio-cultural factors</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch3-q6 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch3-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch3-q6')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Is the use of contraceptives justified? Give reasons.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Yes, the use of contraceptives is completely justified, ethically sound, and medically necessary.</strong></p>\n  <p><strong>Key Reasons:</strong></p>\n  <ol>\n    <li><strong>Curbing Population Explosion:</strong> Exponential population growth strains finite natural resources, clean drinking water, agricultural land, healthcare infrastructure, and employment. Contraceptives assist in voluntary population stabilisation.</li>\n    <li><strong>Prevention of Unwanted Pregnancies:</strong> Contraception prevents unintended pregnancies resulting from casual sexual encounters, contraceptive failure, or non-consensual coitus, thereby avoiding high-risk, unhygienic clandestine abortions.</li>\n    <li><strong>Protection Against STIs and HIV:</strong> Barrier contraceptives such as male and female condoms act as impenetrable physical barriers, providing dual protection against both pregnancy and sexually transmitted infections (STIs/AIDS).</li>\n    <li><strong>Maternal Health and Child Spacing:</strong> Allows mothers adequate recovery time between successive child births, preventing maternal malnutrition, severe anaemia, and birth defects in off-spring.</li>\n    <li><strong>Empowerment of Women:</strong> Provides women reproductive autonomy over their bodies, career aspirations, and reproductive timeline.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear affirmative stand (Yes, justified)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Population control and preservation of socioeconomic resources</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Prevention of unwanted pregnancies and unsafe abortions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">STI/HIV prevention and safeguarding maternal-child health</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch3-q7 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch3-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch3-q7')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Removal of gonads cannot be considered as a contraceptive option. Why?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Removal of gonads (castration/gonadectomy — orchidectomy in males, oophorectomy in females) cannot be considered as a contraceptive option</strong> because of the following critical medical and physiological reasons:</p>\n  <ol>\n    <li><strong>Violation of Ideal Contraceptive Definition:</strong> An ideal contraceptive must be user-friendly, easily available, effective, <em>reversible</em>, and with <em>no or least side-effects</em> without interfering with sexual drive, desire, or performance. Gonadectomy is <strong>completely irreversible</strong>.</li>\n    <li><strong>Endocrine Function Cessation:</strong> Gonads are not merely gamete-producing organs; they are vital primary endocrine glands:\n      <ul>\n        <li><strong>Testes:</strong> Produce testosterone (androgens) which maintain male libido, secondary sexual characteristics, bone mineral density, and muscle mass.</li>\n        <li><strong>Ovaries:</strong> Produce oestrogen and progesterone which regulate the menstrual cycle, secondary sexual characteristics, cardiovascular health, and bone turnover.</li>\n      </ul>\n    </li>\n    <li><strong>Severe Physiological and Hormonal Consequences:</strong> Surgical removal causes immediate surgical menopause/andropause, resulting in severe osteoporosis, cardiovascular instability, vasomotor symptoms (hot flashes), loss of libido, depression, and metabolic collapse.</li>\n    <li><strong>Surgical Contraception Alternatives Exist:</strong> Effective, safe surgical options like <strong>vasectomy</strong> (cutting/ligation of vas deferens) and <strong>tubectomy</strong> (cutting/ligation of fallopian tubes) block gamete transport <em>without altering hormonal endocrine balance or sexual function</em>.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Contraceptive criteria violation: irreversible and destroys sexual drive/desire</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Complete loss of essential steroid hormones (testosterone / oestrogen & progesterone)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Severe clinical side-effects (osteoporosis, loss of libido) vs surgical sterilisation (vasectomy/tubectomy)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch3-q8 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch3-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch3-q8')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Amniocentesis for sex determination is banned in our country. Is this ban necessary? Comment.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Yes, the statutory ban on amniocentesis for foetal sex determination is absolutely necessary and justified.</strong></p>\n  <p><strong>1. Original Diagnostic Purpose of Amniocentesis:</strong></p>\n  <ul>\n    <li>Amniocentesis is a prenatal diagnostic procedure where a small amount of amniotic fluid containing fetal cells is withdrawn from the uterus using a hypodermic needle.</li>\n    <li>Its legitimate clinical purpose is to detect <strong>chromosomal abnormalities</strong> (e.g., Down's syndrome, Turner's syndrome, Klinefelter's syndrome), inborn metabolic disorders, and hereditary genetic defects (e.g., sickle-cell anaemia, haemophilia).</li>\n  </ul>\n  <p><strong>2. Rationale for Statutory Ban:</strong></p>\n  <ul>\n    <li><strong>Rampant Female Foeticide:</strong> Due to entrenched patriarchal mindsets and societal craving for male children, this diagnostic tool was widely misused to determine the sex of the unborn fetus. If identified as female, the pregnancy was terminated through illegal Medical Termination of Pregnancy (MTP).</li>\n    <li><strong>Severe Distorted Child Sex Ratio:</strong> Misuse led to an alarming crash in the juvenile sex ratio in several Indian states, causing severe demographic, social, and psychological imbalances.</li>\n    <li><strong>PCPNDT Act:</strong> To curb this menace, the Government of India enacted the <strong>Pre-Conception and Pre-Natal Diagnostic Techniques (PCPNDT) Act</strong>, legally criminalising the disclosure or testing of fetal sex while preserving its genetic diagnostic utility under strict medical regulation.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmative stand and definition of genuine diagnostic purpose (detecting chromosomal disorders like Down syndrome)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Gross misuse for female foeticide leading to skewed sex ratio</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Significance of statutory ban (PCPNDT Act) in protecting the female unborn child and demographic balance</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch3-q9 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch3-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch3-q9')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Suggest some methods to assist infertile couples to have children.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Infertile couples can be assisted to bear children through specialised healthcare medical techniques known collectively as <strong>Assisted Reproductive Technologies (ART)</strong>:</p>\n  <table style=\"width:100%; border-collapse:collapse; margin-top:12px; font-size:0.92rem;\">\n    <thead>\n      <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n        <th style=\"padding:8px 12px; color:#065f46;\">Method (Acronym)</th>\n        <th style=\"padding:8px 12px; color:#065f46;\">Full Form & Procedure</th>\n        <th style=\"padding:8px 12px; color:#065f46;\">Clinical Indication</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:8px 12px; font-weight:700;\">IVF-ET</td>\n        <td style=\"padding:8px 12px;\"><strong>In Vitro Fertilisation & Embryo Transfer:</strong> Ova from wife/donor and sperm from husband/donor are fertilised under simulated laboratory conditions, followed by embryo transfer.</td>\n        <td style=\"padding:8px 12px;\">Tubal blockage, severe pelvic adhesions, or unexplained infertility.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:8px 12px; font-weight:700;\">ZIFT</td>\n        <td style=\"padding:8px 12px;\"><strong>Zygote Intra-Fallopian Transfer:</strong> The zygote or early embryo up to 8 blastomeres is transferred directly into the fallopian tube.</td>\n        <td style=\"padding:8px 12px;\">Fertilisation outside body with patent, functional fallopian tubes.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:8px 12px; font-weight:700;\">IUT</td>\n        <td style=\"padding:8px 12px;\"><strong>Intra-Uterine Transfer:</strong> Embryos with more than 8 blastomeres are transferred into the uterine cavity.</td>\n        <td style=\"padding:8px 12px;\">For advanced stage embryos to achieve implantation.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:8px 12px; font-weight:700;\">GIFT</td>\n        <td style=\"padding:8px 12px;\"><strong>Gamete Intra-Fallopian Transfer:</strong> Transfer of an ovum collected from a donor female into the fallopian tube of another female.</td>\n        <td style=\"padding:8px 12px;\">Female unable to produce ova, but capable of providing suitable internal environment for fertilisation & gestation.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:8px 12px; font-weight:700;\">ICSI</td>\n        <td style=\"padding:8px 12px;\"><strong>Intra-Cytoplasmic Sperm Injection:</strong> A laboratory procedure in which a single sperm is directly injected into the cytoplasm of an ovum.</td>\n        <td style=\"padding:8px 12px;\">Extremely low sperm count (oligozoospermia), poor sperm motility, or defective sperm penetration.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:8px 12px; font-weight:700;\">AI / IUI</td>\n        <td style=\"padding:8px 12px;\"><strong>Artificial Insemination / Intra-Uterine Insemination:</strong> Semen collected from husband or a healthy donor is artificially introduced into the vagina or uterus of the female.</td>\n        <td style=\"padding:8px 12px;\">Male partner unable to inseminate or has very low sperm counts in ejaculates.</td>\n      </tr>\n    </tbody>\n  </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">IVF-ET and distinction between ZIFT (&le; 8 blastomeres to tube) and IUT (&gt; 8 blastomeres to uterus)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">GIFT (transfer of donor ovum to fallopian tube for in vivo fertilisation)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ICSI (micro-injection of single sperm into ovum) and AI / IUI (intrauterine insemination for male infertility)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch3-q10 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch3-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch3-q10')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What are the measures one has to take to prevent from contracting STDs?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Sexually Transmitted Diseases (STDs) / Sexually Transmitted Infections (STIs) can be effectively prevented by adhering to the following hygienic and behavioural guidelines:</p>\n  <ol>\n    <li><strong>Avoid Unprotected Sex with Unknown/Multiple Partners:</strong> Abstain from sexual intercourse with unknown persons or multiple sexual partners, as infection vectors are silent or asymptomatic in many individuals.</li>\n    <li><strong>Consistent Use of Condoms:</strong> Always use barrier contraceptives (male or female condoms) during coitus. Condoms provide physical separation, significantly minimising mucosal contact and fluid exchange.</li>\n    <li><strong>Avoid Sharing Needles & Syringes:</strong> Never share hypodermic needles or surgical/piercing equipment, which can transmit blood-borne STIs like HIV/AIDS and Hepatitis-B.</li>\n    <li><strong>Transfusion of Screened Blood:</strong> Ensure that blood and blood products are rigorously screened for HIV, Hepatitis-B, and Syphilis prior to any medical transfusion.</li>\n    <li><strong>Early Diagnosis and Treatment:</strong> In case of doubt or symptoms (such as burning during urination, unusual urethral/vaginal discharge, itching, pelvic pain, or genital sores/ulcers), consult a qualified medical professional immediately for early clinical diagnosis.</li>\n    <li><strong>Complete Course of Prescribed Medication:</strong> Complete the full regimen of prescribed antibiotic/antiviral therapy, and ensure simultaneous testing and treatment of the sexual partner to avoid reinfection.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Avoiding sexual contact with unknown/multiple partners</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Regular and consistent use of condoms during coitus</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Avoiding sharing needles and ensuring screened blood transfusions</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Early medical consultation for symptoms and completing treatment course for both partners</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch3-q11 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch3-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch3-q11')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        State True/False with explanation:\n  <br>(a) Abortions could happen spontaneously too.\n  <br>(b) Infertility is defined as the inability to produce a viable offspring and is always due to abnormalities/defects in the female partner.\n  <br>(c) Complete lactation helps in contraception.\n  <br>(d) Creating awareness about sex related aspects is an effective method to improve reproductive health of the people.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:12px;\">\n    <div style=\"padding:10px; background:#f8fafc; border-radius:6px; border-left:4px solid #10b981;\">\n      <strong>(a) Statement:</strong> \"Abortions could happen spontaneously too.\"<br>\n      <strong>Verdict: TRUE</strong><br>\n      <em>Explanation:</em> Spontaneous abortions (commonly called miscarriages) occur naturally due to chromosomal anomalies in the fetus, defective implantation, hormonal insufficiencies (such as low progesterone levels), maternal physiological infections, or anatomical uterine malformations.\n    </div>\n    <div style=\"padding:10px; background:#f8fafc; border-radius:6px; border-left:4px solid #ef4444;\">\n      <strong>(b) Statement:</strong> \"Infertility is defined as the inability to produce a viable offspring and is always due to abnormalities/defects in the female partner.\"<br>\n      <strong>Verdict: FALSE</strong><br>\n      <em>Explanation:</em> Infertility is the inability to conceive even after 1–2 years of unprotected coitus. It is <strong>not</strong> solely due to defects in the female. In over 40–50% of clinical cases, infertility stems from male factors such as azoospermia, oligospermia, asthenospermia (poor motility), or erectile dysfunction.\n    </div>\n    <div style=\"padding:10px; background:#f8fafc; border-radius:6px; border-left:4px solid #10b981;\">\n      <strong>(c) Statement:</strong> \"Complete lactation helps in contraception.\"<br>\n      <strong>Verdict: TRUE</strong><br>\n      <em>Explanation:</em> Known as <strong>Lactational Amenorrhea</strong>. Intense suckling by the infant stimulates elevated prolactin secretion, which suppresses hypothalamic GnRH release. Consequently, pituitary gonadotropins (LH and FSH) are suppressed, preventing ovarian follicular development and ovulation. It is effective up to a maximum period of six months postpartum.\n    </div>\n    <div style=\"padding:10px; background:#f8fafc; border-radius:6px; border-left:4px solid #10b981;\">\n      <strong>(d) Statement:</strong> \"Creating awareness about sex related aspects is an effective method to improve reproductive health of the people.\"<br>\n      <strong>Verdict: TRUE</strong><br>\n      <em>Explanation:</em> Awareness empowers individuals with scientific understanding of reproductive organs, contraception, sexually transmitted infections, prenatal care, safe sexual practices, and eradication of social stigmas.\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) True with valid explanation of spontaneous miscarriage/chromosomal issues</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) False with clear explanation that male factors (oligospermia, motility) contribute equally</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) True with explanation of lactational amenorrhea (prolactin suppressing GnRH/LH/FSH)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) True with explanation of empowering informed choices and reducing STIs</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch3-q12 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch3-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch3-q12')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Correct the following statements:\n  <br>(a) Surgical methods of contraception prevent gamete formation.\n  <br>(b) All sexually transmitted diseases are completely curable.\n  <br>(c) Oral pills are very popular contraceptives among the rural women.\n  <br>(d) In MTP, the foetus is removed after 20 weeks of pregnancy.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:12px;\">\n    <div style=\"padding:10px; background:#f8fafc; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(a) Incorrect:</strong> \"Surgical methods of contraception prevent gamete formation.\"<br>\n      <strong style=\"color:#059669;\">Corrected Statement:</strong> Surgical methods of contraception (vasectomy and tubectomy) <strong>prevent gamete transport</strong> (block gamete passage), thereby preventing fertilization; gamete formation (spermatogenesis and oogenesis) continues normally.\n    </div>\n    <div style=\"padding:10px; background:#f8fafc; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(b) Incorrect:</strong> \"All sexually transmitted diseases are completely curable.\"<br>\n      <strong style=\"color:#059669;\">Corrected Statement:</strong> Except for <strong>HIV infections, genital herpes, and hepatitis-B</strong>, which are incurable, other sexually transmitted infections are completely curable if detected early and treated properly.\n    </div>\n    <div style=\"padding:10px; background:#f8fafc; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(c) Incorrect:</strong> \"Oral pills are very popular contraceptives among the rural women.\"<br>\n      <strong style=\"color:#059669;\">Corrected Statement:</strong> Oral contraceptive pills are widely accepted and very popular contraceptives among <strong>urban and educated women</strong> (contraceptives with high compliance like Saheli are increasingly introduced across demographics).\n    </div>\n    <div style=\"padding:10px; background:#f8fafc; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(d) Incorrect:</strong> \"In MTP, the foetus is removed after 20 weeks of pregnancy.\"<br>\n      <strong style=\"color:#059669;\">Corrected Statement:</strong> Medical Termination of Pregnancy (MTP) is considered safe only <strong>up to the first trimester (up to 12 weeks of pregnancy)</strong>; abortions performed in the second trimester (up to 20–24 weeks under specific legal provisions) are significantly riskier for the mother.\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Corrected to: surgical methods block gamete transport, not gamete formation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Corrected to: HIV, genital herpes, and hepatitis-B are not completely curable</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Corrected to: oral pills are very popular among urban/educated women</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Corrected to: MTP is safe during the first trimester (up to 12 weeks of pregnancy)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"display:flex; justify-content:space-between; align-items:center; margin-top:36px; padding-top:20px; border-top:1px solid #e2e8f0;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(2)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 2</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(4)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#059669; color:white; font-weight:700; cursor:pointer;\">Next: Ch 4 (Principles of Inheritance and Variation) →</button>\n  </div>\n</section>";
window.CHAPTER_DATA[4] = "<section class=\"chapter-section\" id=\"c12b-ch4\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#059669;\">4</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#059669;\">CBSE Class 12 Biology &bull; Chapter 4</div>\n      <h2>Principles of Inheritance and Variation</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 16 Verbatim Questions with Official CBSE Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n<div class=\"chem-card\" style=\"margin-bottom:24px; padding:20px; background:#f0fdf4; border:1px solid #bbf7d0; border-radius:12px;\">\n  <h4 style=\"margin:0 0 12px 0; color:#059669; font-size:1.05rem;\">🧬 Core Genetics Map: Mendelian Principles vs Morgan's Linkage & Sex Determination</h4>\n  <svg viewBox=\"0 0 880 300\" style=\"width:100%; max-width:880px; height:auto; display:block; margin:0 auto; background:white; border-radius:8px; border:1px solid #d1fae5;\">\n    <!-- Mendel's Laws Card -->\n    <rect x=\"20\" y=\"20\" width=\"260\" height=\"260\" rx=\"10\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"150\" y=\"48\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Mendelian Postulates</text>\n    <line x1=\"35\" y1=\"58\" x2=\"265\" y2=\"58\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <text x=\"35\" y=\"80\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#047857\">1. Law of Dominance:</text>\n    <text x=\"35\" y=\"98\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Factors occur in pairs</text>\n    <text x=\"35\" y=\"114\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; One allele masks another in F1</text>\n    <text x=\"35\" y=\"138\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#047857\">2. Law of Segregation:</text>\n    <text x=\"35\" y=\"156\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Purity of gametes (no blending)</text>\n    <text x=\"35\" y=\"172\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Alleles separate during meiosis</text>\n    <text x=\"35\" y=\"196\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#047857\">3. Independent Assortment:</text>\n    <text x=\"35\" y=\"214\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Dihybrid ratio: 9 : 3 : 3 : 1</text>\n    <text x=\"35\" y=\"230\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Valid only for unlinked genes</text>\n    <text x=\"35\" y=\"250\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#059669\">&bull; Test Cross Ratio: 1 : 1 (Monohybrid)</text>\n\n    <!-- Morgan Linkage Card -->\n    <rect x=\"310\" y=\"20\" width=\"260\" height=\"260\" rx=\"10\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <text x=\"440\" y=\"48\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Morgan & Chromosomal Theory</text>\n    <line x1=\"325\" y1=\"58\" x2=\"555\" y2=\"58\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n    <text x=\"325\" y=\"80\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#1d4ed8\">Sutton & Boveri (1902):</text>\n    <text x=\"325\" y=\"98\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Parallelism: Chromosomes & genes</text>\n    <text x=\"325\" y=\"122\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#1d4ed8\">T.H. Morgan (Drosophila):</text>\n    <text x=\"325\" y=\"140\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Discovered Sex-linkage & Recombination</text>\n    <text x=\"325\" y=\"158\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Tight Linkage: 98.7% Parental (y-w)</text>\n    <text x=\"325\" y=\"176\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Loose Linkage: 62.8% Parental (w-m)</text>\n    <text x=\"325\" y=\"200\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#1d4ed8\">Alfred Sturtevant:</text>\n    <text x=\"325\" y=\"218\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Genetic Mapping (1% recombination</text>\n    <text x=\"325\" y=\"234\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">  = 1 map unit or 1 centiMorgan)</text>\n\n    <!-- Genetic Disorders Card -->\n    <rect x=\"600\" y=\"20\" width=\"260\" height=\"260\" rx=\"10\" fill=\"#fef2f2\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n    <text x=\"730\" y=\"48\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">Genetic Disorders</text>\n    <line x1=\"615\" y1=\"58\" x2=\"845\" y2=\"58\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n    <text x=\"615\" y=\"80\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#b91c1c\">Mendelian Disorders:</text>\n    <text x=\"615\" y=\"98\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Haemophilia (X-linked recessive)</text>\n    <text x=\"615\" y=\"114\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Sickle-Cell (Autosomal recessive, GAG&rarr;GUG)</text>\n    <text x=\"615\" y=\"130\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Phenylketonuria (PAH gene, Chr 12)</text>\n    <text x=\"615\" y=\"146\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Thalassemia (Globin chain synthesis defect)</text>\n    <text x=\"615\" y=\"170\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#b91c1c\">Chromosomal Aneuploidy:</text>\n    <text x=\"615\" y=\"188\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Down's Syndrome: Trisomy 21 (2n + 1 = 47)</text>\n    <text x=\"615\" y=\"204\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Klinefelter's Syndrome: XXY (47, XXY)</text>\n    <text x=\"615\" y=\"220\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Turner's Syndrome: XO (45, XO)</text>\n    <text x=\"615\" y=\"244\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#991b1b\">Sex Determination: XX-XY, XX-XO, ZZ-ZW</text>\n  </svg>\n</div>\n\n  <div class=\"ex-div\" style=\"font-size:0.88rem; font-weight:700; color:#334155; margin-bottom:16px; padding:8px 14px; background:#ecfdf5; border-radius:8px; border-left:4px solid #059669;\">NCERT Exercises (16 Verbatim Questions)</div>\n\n  <div class=\"questions-container\">\n    \n  <!-- c12b-ch4-q1 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q1')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Mention the advantages of selecting pea plant for experiment by Mendel.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Gregor Johann Mendel selected the garden pea (<em>Pisum sativum</em>) for his landmark hybridisation experiments due to several distinct morphological, reproductive, and practical advantages:</p>\n  <ol>\n    <li><strong>Well-Defined Contrasting Traits:</strong> Pea plants exhibit conspicuous, easily identifiable contrasting characters (e.g., tall vs dwarf, yellow vs green seeds, round vs wrinkled seeds, purple vs white flowers).</li>\n    <li><strong>Naturally Self-Pollinating with Cleistogamous Tendency:</strong> The pea flower has a papilionaceous corolla (keel petals enclose the stamens and stigma), ensuring natural self-pollination and enabling the continuous generation of pure-breeding true lines.</li>\n    <li><strong>Feasibility of Easy Artificial Hybridisation (Cross-Pollination):</strong> Manual cross-pollination can be conveniently carried out by <em>emasculation</em> (removal of anthers before dehiscence) followed by controlled dusting of desired pollen and <em>bagging</em>.</li>\n    <li><strong>Short Life Cycle and Annual Habit:</strong> Peas complete their entire life cycle within 3–4 months, enabling Mendel to follow several successive generations within a few years.</li>\n    <li><strong>High Fecundity (Abundant Progeny):</strong> A single plant produces numerous seeds in each pod, providing large sample sizes that permit statistical validity and reliable mathematical probability ratios.</li>\n    <li><strong>Ease of Cultivation:</strong> Pea plants require simple cultivation conditions and small garden plots.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Presence of distinct, easily observable contrasting characters</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Natural self-pollination (pure lines) and ease of artificial cross-pollination (emasculation/bagging)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Short life cycle (annual) and large number of offspring per plant for statistical analysis</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q2 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q2')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Differentiate between the following:\n  <br>(a) Dominance and Recessive\n  <br>(b) Homozygous and Heterozygous\n  <br>(c) Monohybrid and Dihybrid\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:16px;\">\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(a) Dominance vs Recessive</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.9rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:6px 10px; width:50%;\">Dominant Character / Allele</th>\n          <th style=\"padding:6px 10px; width:50%;\">Recessive Character / Allele</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Expresses its phenotypic effect both in homozygous (TT) and heterozygous (Tt) conditions.</td>\n          <td style=\"padding:6px 10px;\">Expresses its phenotypic effect only in the homozygous condition (tt); suppressed in heterozygote.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:6px 10px;\">Produces a fully functional normal enzyme or structural protein.</td>\n          <td style=\"padding:6px 10px;\">Usually produces a non-functional enzyme, defective protein, or no enzyme at all.</td>\n        </tr>\n      </table>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(b) Homozygous vs Heterozygous</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.9rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:6px 10px; width:50%;\">Homozygous Individual / Genotype</th>\n          <th style=\"padding:6px 10px; width:50%;\">Heterozygous Individual / Genotype</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Possesses two identical alleles at a given locus (e.g., TT or tt).</td>\n          <td style=\"padding:6px 10px;\">Possesses two dissimilar/different alleles at a given locus (e.g., Tt).</td>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Produces only one type of gamete (100% T or 100% t).</td>\n          <td style=\"padding:6px 10px;\">Produces two different types of gametes in equal proportion (50% T and 50% t).</td>\n        </tr>\n        <tr>\n          <td style=\"padding:6px 10px;\">Breeds true upon selfing (pure breeding line).</td>\n          <td style=\"padding:6px 10px;\">Segregates into varied phenotypes upon selfing.</td>\n        </tr>\n      </table>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(c) Monohybrid vs Dihybrid Cross</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.9rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:6px 10px; width:50%;\">Monohybrid Cross</th>\n          <th style=\"padding:6px 10px; width:50%;\">Dihybrid Cross</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">A cross involving the study of the inheritance of a single pair of contrasting characters (e.g., Plant Height).</td>\n          <td style=\"padding:6px 10px;\">A cross involving the simultaneous study of the inheritance of two pairs of contrasting characters (e.g., Seed Shape and Seed Colour).</td>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">F2 Phenotypic ratio = <strong>3 : 1</strong><br>F2 Genotypic ratio = <strong>1 : 2 : 1</strong></td>\n          <td style=\"padding:6px 10px;\">F2 Phenotypic ratio = <strong>9 : 3 : 3 : 1</strong><br>F2 Genotypic ratio = <strong>(1:2:1) &times; (1:2:1) [9 genotypes]</strong></td>\n        </tr>\n        <tr>\n          <td style=\"padding:6px 10px;\">Monohybrid Test cross ratio = <strong>1 : 1</strong></td>\n          <td style=\"padding:6px 10px;\">Dihybrid Test cross ratio = <strong>1 : 1 : 1 : 1</strong></td>\n        </tr>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Clear differentiation between Dominance & Recessive with molecular basis/homozygous-heterozygous expression</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Differentiation between Homozygous & Heterozygous (allelic constitution and gamete production)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Differentiation between Monohybrid & Dihybrid cross (number of gene pairs & classic F2 ratios)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q3 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q3')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        A diploid organism is heterozygous for 4 loci, how many types of gametes can be produced?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Formula and Calculation:</strong></p>\n  <p>The number of genetically distinct gametes produced by an individual with independently assorting heterozygous gene loci is given by the formula:</p>\n  <div style=\"background:#f8fafc; padding:12px; border-left:4px solid #059669; font-weight:700; margin:10px 0;\">\n    Number of gamete types = 2<sup>n</sup>\n  </div>\n  <p>Where <strong>n</strong> represents the number of heterozygous loci.</p>\n  <ul>\n    <li>Given: Diploid organism is heterozygous for 4 loci, so <strong>n = 4</strong>.</li>\n    <li>Representative Genotype: <em>AaBbCcDd</em></li>\n    <li>Calculation:\n      <br>Number of gametes = 2<sup>4</sup> = 2 &times; 2 &times; 2 &times; 2 = <strong>16 types of gametes</strong>.</li>\n  </ul>\n  <p><strong>Conclusion:</strong> The organism can produce <strong>16 genetically distinct types of gametes</strong> (each with a probability of 1/16).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct formula stated: Number of gametes = 2^n, where n is number of heterozygous loci</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution with n = 4 leading to correct answer: 2^4 = 16 types of gametes</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q4 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q4')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Explain the Law of Dominance using a monohybrid cross.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Statement of Mendel's Law of Dominance:</strong></p>\n  <ol>\n    <li>Characters are controlled by discrete physical units called <strong>factors</strong> (now called genes).</li>\n    <li>Factors occur in pairs in diploid organisms.</li>\n    <li>In a dissimilar pair of factors (heterozygous condition), one member of the pair dominates (<strong>dominant factor</strong>) and expresses itself phenotypically, while the other member is masked/suppressed (<strong>recessive factor</strong>).</li>\n  </ol>\n  <p><strong>Demonstration Using Monohybrid Cross (Stem Height in <em>Pisum sativum</em>):</strong></p>\n  <ul>\n    <li><strong>Parents (P):</strong> Pure-breeding Tall (TT) &times; Pure-breeding Dwarf (tt)</li>\n    <li><strong>Gametes:</strong> All 'T' from tall parent; all 't' from dwarf parent.</li>\n    <li><strong>F1 Generation:</strong> All offspring are heterozygous <strong>Tt</strong>. Phenotypically, <strong>100% of the F1 plants are Tall</strong>. Despite carrying the allele for dwarfness ('t'), only the tall phenotype ('T') is expressed. This proves that 'T' is dominant over 't'.</li>\n    <li><strong>F2 Generation (Selfing F1 &times; F1, Tt &times; Tt):</strong>\n      <table style=\"width:240px; border-collapse:collapse; margin:10px 0; text-align:center;\">\n        <tr style=\"background:#ecfdf5; border:1px solid #10b981;\">\n          <th style=\"padding:6px; border:1px solid #10b981;\">Gametes</th>\n          <th style=\"padding:6px; border:1px solid #10b981;\">T (&frac12;)</th>\n          <th style=\"padding:6px; border:1px solid #10b981;\">t (&frac12;)</th>\n        </tr>\n        <tr>\n          <th style=\"padding:6px; background:#ecfdf5; border:1px solid #10b981;\">T (&frac12;)</th>\n          <td style=\"padding:6px; border:1px solid #cbd5e1; font-weight:700;\">TT (Tall)</td>\n          <td style=\"padding:6px; border:1px solid #cbd5e1; font-weight:700;\">Tt (Tall)</td>\n        </tr>\n        <tr>\n          <th style=\"padding:6px; background:#ecfdf5; border:1px solid #10b981;\">t (&frac12;)</th>\n          <td style=\"padding:6px; border:1px solid #cbd5e1; font-weight:700;\">Tt (Tall)</td>\n          <td style=\"padding:6px; border:1px solid #cbd5e1; font-weight:700;\">tt (Dwarf)</td>\n        </tr>\n      </table>\n      <p>In the F2 generation, the masked recessive trait reappears in the homozygous state (tt).<br>\n      <strong>Phenotypic Ratio:</strong> 3 Tall : 1 Dwarf (3 : 1)<br>\n      <strong>Genotypic Ratio:</strong> 1 TT : 2 Tt : 1 tt (1 : 2 : 1)</p>\n    </li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Three postulates of Law of Dominance (factors in pairs, discrete units, dominant masks recessive)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">P and F1 cross schematic (TT x tt -> 100% Tt tall) explaining dominant expression</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">F2 Punnett square with 3:1 phenotypic and 1:2:1 genotypic ratios</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q5 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q5')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Define and design a test-cross.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition:</strong></p>\n  <p>A <strong>test cross</strong> is a cross between an individual showing a dominant phenotype (whose genotype is unknown, i.e., whether homozygous dominant or heterozygous) and the <strong>homozygous recessive parent</strong>.</p>\n  <p><strong>Purpose of Test Cross:</strong> To determine the unknown genotype of the dominant parent.</p>\n\n  <p><strong>Design of Test Cross for Flower Colour in Pea (Violet vs White):</strong></p>\n  <p>Dominant flower colour is Violet (alleles: W), recessive is White (ww). An individual plant with violet flowers may have genotype <strong>WW</strong> (homozygous) or <strong>Ww</strong> (heterozygous).</p>\n  \n  <div style=\"display:flex; flex-wrap:wrap; gap:16px; margin-top:10px;\">\n    <div style=\"flex:1; min-width:260px; background:#f8fafc; padding:12px; border-radius:8px; border:1px solid #cbd5e1;\">\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">Case 1: If Unknown Plant is Homozygous (WW)</h5>\n      <p style=\"font-size:0.88rem; margin:0 0 6px 0;\">Cross: <strong>WW &times; ww</strong></p>\n      <table style=\"width:100%; border-collapse:collapse; text-align:center; font-size:0.88rem;\">\n        <tr style=\"background:#ecfdf5;\"><th style=\"border:1px solid #10b981; padding:4px;\">&times;</th><th style=\"border:1px solid #10b981; padding:4px;\">W</th><th style=\"border:1px solid #10b981; padding:4px;\">W</th></tr>\n        <tr><th style=\"border:1px solid #10b981; padding:4px; background:#ecfdf5;\">w</th><td style=\"border:1px solid #cbd5e1; padding:4px;\">Ww (Violet)</td><td style=\"border:1px solid #cbd5e1; padding:4px;\">Ww (Violet)</td></tr>\n        <tr><th style=\"border:1px solid #10b981; padding:4px; background:#ecfdf5;\">w</th><td style=\"border:1px solid #cbd5e1; padding:4px;\">Ww (Violet)</td><td style=\"border:1px solid #cbd5e1; padding:4px;\">Ww (Violet)</td></tr>\n      </table>\n      <p style=\"font-size:0.85rem; font-weight:700; color:#065f46; margin:8px 0 0 0;\">Result: 100% Violet Flowers &rarr; Unknown parent is homozygous dominant (WW).</p>\n    </div>\n\n    <div style=\"flex:1; min-width:260px; background:#f8fafc; padding:12px; border-radius:8px; border:1px solid #cbd5e1;\">\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">Case 2: If Unknown Plant is Heterozygous (Ww)</h5>\n      <p style=\"font-size:0.88rem; margin:0 0 6px 0;\">Cross: <strong>Ww &times; ww</strong></p>\n      <table style=\"width:100%; border-collapse:collapse; text-align:center; font-size:0.88rem;\">\n        <tr style=\"background:#ecfdf5;\"><th style=\"border:1px solid #10b981; padding:4px;\">&times;</th><th style=\"border:1px solid #10b981; padding:4px;\">W</th><th style=\"border:1px solid #10b981; padding:4px;\">w</th></tr>\n        <tr><th style=\"border:1px solid #10b981; padding:4px; background:#ecfdf5;\">w</th><td style=\"border:1px solid #cbd5e1; padding:4px;\">Ww (Violet)</td><td style=\"border:1px solid #cbd5e1; padding:4px;\">ww (White)</td></tr>\n        <tr><th style=\"border:1px solid #10b981; padding:4px; background:#ecfdf5;\">w</th><td style=\"border:1px solid #cbd5e1; padding:4px;\">Ww (Violet)</td><td style=\"border:1px solid #cbd5e1; padding:4px;\">ww (White)</td></tr>\n      </table>\n      <p style=\"font-size:0.85rem; font-weight:700; color:#065f46; margin:8px 0 0 0;\">Result: 50% Violet : 50% White (1 : 1) &rarr; Unknown parent is heterozygous (Ww).</p>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Precise definition of test cross (cross of unknown dominant phenotype with homozygous recessive)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Designing Case 1 (WW x ww) yielding 100% dominant phenotype</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Designing Case 2 (Ww x ww) yielding 1 : 1 ratio confirming heterozygosity</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q6 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q6')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Using a Punnett Square, workout the distribution of phenotypic features in the first filial generation after a cross between a homozygous female and a heterozygous male for a single locus.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Let the single locus be denoted by gene allele <strong>'A'</strong> (dominant) and <strong>'a'</strong> (recessive).</p>\n  <p>The female is homozygous, which can be either <strong>Case I: Homozygous Dominant (AA)</strong> or <strong>Case II: Homozygous Recessive (aa)</strong>.</p>\n  <p>The male parent is heterozygous: <strong>Aa</strong>.</p>\n\n  <h5 style=\"color:#059669; margin:12px 0 6px 0;\">Case I: Homozygous Dominant Female (AA) &times; Heterozygous Male (Aa)</h5>\n  <ul>\n    <li>Female Gametes: 100% <strong>A</strong></li>\n    <li>Male Gametes: 50% <strong>A</strong>, 50% <strong>a</strong></li>\n  </ul>\n  <table style=\"width:280px; border-collapse:collapse; margin:8px 0; text-align:center;\">\n    <tr style=\"background:#ecfdf5; border:1px solid #10b981;\">\n      <th style=\"padding:6px; border:1px solid #10b981;\">&#9792; \\ &#9794;</th>\n      <th style=\"padding:6px; border:1px solid #10b981;\">A (&frac12;)</th>\n      <th style=\"padding:6px; border:1px solid #10b981;\">a (&frac12;)</th>\n    </tr>\n    <tr>\n      <th style=\"padding:6px; background:#ecfdf5; border:1px solid #10b981;\">A (1)</th>\n      <td style=\"padding:6px; border:1px solid #cbd5e1; font-weight:700;\">AA (Dominant)</td>\n      <td style=\"padding:6px; border:1px solid #cbd5e1; font-weight:700;\">Aa (Dominant)</td>\n    </tr>\n  </table>\n  <p><strong>F1 Phenotype:</strong> 100% show the <strong>Dominant Phenotype</strong> (Genotypes: 50% AA, 50% Aa).</p>\n\n  <h5 style=\"color:#059669; margin:12px 0 6px 0;\">Case II: Homozygous Recessive Female (aa) &times; Heterozygous Male (Aa) [Test Cross]</h5>\n  <ul>\n    <li>Female Gametes: 100% <strong>a</strong></li>\n    <li>Male Gametes: 50% <strong>A</strong>, 50% <strong>a</strong></li>\n  </ul>\n  <table style=\"width:280px; border-collapse:collapse; margin:8px 0; text-align:center;\">\n    <tr style=\"background:#ecfdf5; border:1px solid #10b981;\">\n      <th style=\"padding:6px; border:1px solid #10b981;\">&#9792; \\ &#9794;</th>\n      <th style=\"padding:6px; border:1px solid #10b981;\">A (&frac12;)</th>\n      <th style=\"padding:6px; border:1px solid #10b981;\">a (&frac12;)</th>\n    </tr>\n    <tr>\n      <th style=\"padding:6px; background:#ecfdf5; border:1px solid #10b981;\">a (1)</th>\n      <td style=\"padding:6px; border:1px solid #cbd5e1; font-weight:700;\">Aa (Dominant)</td>\n      <td style=\"padding:6px; border:1px solid #cbd5e1; font-weight:700;\">aa (Recessive)</td>\n    </tr>\n  </table>\n  <p><strong>F1 Phenotype:</strong> 50% Dominant : 50% Recessive (Ratio = <strong>1 : 1</strong>).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear representation of genotypes for parents (AA or aa female, Aa male)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Punnett square and outcome for Case I (AA x Aa -> 100% dominant phenotype)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Punnett square and outcome for Case II (aa x Aa -> 1:1 dominant:recessive phenotype)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q7 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q7')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        When a cross in made between tall plant with yellow seeds (TtYy) and tall plant with green seed (Ttyy), what proportions of phenotype in the offspring could be expected to be:\n  <br>(a) tall and green.\n  <br>(b) dwarf and green.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Parental Cross:</strong> Tall Yellow (<strong>TtYy</strong>) &times; Tall Green (<strong>Ttyy</strong>)</p>\n  <p><strong>1. Gametes Produced:</strong></p>\n  <ul>\n    <li>Parent 1 (TtYy): <strong>TY, Ty, tY, ty</strong> (4 types in equal frequency of &frac14;)</li>\n    <li>Parent 2 (Ttyy): <strong>Ty, ty</strong> (2 types in equal frequency of &frac12;)</li>\n  </ul>\n\n  <p><strong>2. Punnett Square (4 &times; 2 = 8 boxes):</strong></p>\n  <table style=\"width:100%; border-collapse:collapse; margin:10px 0; text-align:center; font-size:0.88rem;\">\n    <tr style=\"background:#ecfdf5; border:1px solid #10b981;\">\n      <th style=\"padding:6px; border:1px solid #10b981;\">Gametes</th>\n      <th style=\"padding:6px; border:1px solid #10b981;\">TY (&frac14;)</th>\n      <th style=\"padding:6px; border:1px solid #10b981;\">Ty (&frac14;)</th>\n      <th style=\"padding:6px; border:1px solid #10b981;\">tY (&frac14;)</th>\n      <th style=\"padding:6px; border:1px solid #10b981;\">ty (&frac14;)</th>\n    </tr>\n    <tr>\n      <th style=\"padding:6px; background:#ecfdf5; border:1px solid #10b981;\">Ty (&frac12;)</th>\n      <td style=\"padding:6px; border:1px solid #cbd5e1;\">TTYy<br><strong>(Tall, Yellow)</strong></td>\n      <td style=\"padding:6px; border:1px solid #cbd5e1;\">TTyy<br><strong>(Tall, Green)</strong></td>\n      <td style=\"padding:6px; border:1px solid #cbd5e1;\">TtYy<br><strong>(Tall, Yellow)</strong></td>\n      <td style=\"padding:6px; border:1px solid #cbd5e1;\">Ttyy<br><strong>(Tall, Green)</strong></td>\n    </tr>\n    <tr>\n      <th style=\"padding:6px; background:#ecfdf5; border:1px solid #10b981;\">ty (&frac12;)</th>\n      <td style=\"padding:6px; border:1px solid #cbd5e1;\">TtYy<br><strong>(Tall, Yellow)</strong></td>\n      <td style=\"padding:6px; border:1px solid #cbd5e1;\">Ttyy<br><strong>(Tall, Green)</strong></td>\n      <td style=\"padding:6px; border:1px solid #cbd5e1;\">ttYy<br><strong>(Dwarf, Yellow)</strong></td>\n      <td style=\"padding:6px; border:1px solid #cbd5e1;\">ttyy<br><strong>(Dwarf, Green)</strong></td>\n    </tr>\n  </table>\n\n  <p><strong>Phenotypic Analysis (Out of 8 total combinations):</strong></p>\n  <ul>\n    <li>Tall, Yellow: TTYy (1) + TtYy (2) = 3/8</li>\n    <li><strong>Tall, Green:</strong> TTyy (1) + Ttyy (2) = <strong>3/8 (37.5%)</strong></li>\n    <li>Dwarf, Yellow: ttYy (1) = 1/8</li>\n    <li><strong>Dwarf, Green:</strong> ttyy (1) = <strong>1/8 (12.5%)</strong></li>\n  </ul>\n  <p><strong>Final Answers:</strong></p>\n  <p><strong>(a) Proportion of Tall and Green:</strong> 3/8 or <strong>37.5%</strong><br>\n  <strong>(b) Proportion of Dwarf and Green:</strong> 1/8 or <strong>12.5%</strong></p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Determining correct gametes for TtYy (4) and Ttyy (2)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Punnett square showing all 8 offspring combinations accurately</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Tall & green = 3/8; (b) Dwarf & green = 1/8 with correct deduction</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q8 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q8')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Two heterozygous parents are crossed. If the two loci are linked what would be the distribution of phenotypic features in F1 generation for a dihybrid cross?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>When two heterozygous parents (genotype: <em>AaBb</em>) are crossed and the two gene loci are <strong>linked</strong> (located on the same homologous chromosome pair):</p>\n  <ol>\n    <li><strong>Absence of Independent Assortment:</strong> The genes do not assort independently. The classical Mendelian dihybrid F2 ratio of <strong>9 : 3 : 3 : 1 will NOT be obtained</strong>.</li>\n    <li><strong>Case 1: Complete Linkage (No crossing over):</strong>\n      <ul>\n        <li>If genes are in cis-coupling phase (<em>AB / ab</em>), gametes formed are only parental types: <em>AB</em> (50%) and <em>ab</em> (50%).</li>\n        <li>Offspring produced upon crossing two heterozygous parents (<em>AB/ab &times; AB/ab</em>):\n          <br>Genotypes: 1 <em>AB/AB</em> : 2 <em>AB/ab</em> : 1 <em>ab/ab</em>\n          <br>Phenotypes: <strong>3 Parental Dominant (A_B_) : 1 Parental Double Recessive (aabb)</strong> (Ratio = <strong>3 : 1</strong>).\n        </li>\n        <li>Non-parental (recombinant) phenotypes are <strong>0%</strong>.</li>\n      </ul>\n    </li>\n    <li><strong>Case 2: Incomplete Linkage (Crossing over occurs):</strong>\n      <ul>\n        <li>Parental phenotypes appear in a <strong>significantly higher proportion (&gt; 50%)</strong> than expected by independent assortment.</li>\n        <li>Recombinant (non-parental) phenotypes appear in a <strong>lower frequency (&lt; 50%)</strong>, directly proportional to the physical distance between the linked loci on the chromosome.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation that linked genes violate independent assortment and deviate from 9:3:3:1</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Complete linkage outcome: strictly parental phenotypes in 3:1 ratio (no recombinants)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Incomplete linkage outcome: parental phenotypes predominate (>50%) over recombinant types (<50%)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q9 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q9')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Briefly mention the contribution of T.H. Morgan in genetics.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Thomas Hunt Morgan</strong> (awarded the Nobel Prize in Physiology or Medicine in 1933) is regarded as the <strong>Father of Experimental Genetics</strong>. His major contributions include:</p>\n  <ol>\n    <li><strong>Selection of <em>Drosophila melanogaster</em> (Fruit Fly) as Model Organism:</strong> Established fruit flies for genetic research due to their short 2-week life cycle, ease of synthetic medium culture, high progeny count, clear morphological sexual dimorphism, and easily visible hereditary variations under low-power microscopes.</li>\n    <li><strong>Experimental Verification of Chromosomal Theory:</strong> Provided conclusive experimental proof for the Sutton-Boveri Chromosomal Theory of Inheritance.</li>\n    <li><strong>Discovery of Sex-Linkage:</strong> Discovered X-linked inheritance in Drosophila (e.g., white-eye mutation discovered in males and tracing criss-cross inheritance).</li>\n    <li><strong>Discovery of Linkage and Recombination:</strong> Demonstrated that genes located on the same chromosome do not assort independently, coining the term <strong>linkage</strong> to describe the physical association of genes on a chromosome, and <strong>recombination</strong> to describe generation of non-parental gene combinations due to crossing over.</li>\n    <li><strong>Foundation of Chromosome Mapping:</strong> His student, <strong>Alfred Sturtevant</strong>, utilized Morgan's recombination frequencies as a measure of genetic distance to construct the first genetic linkage maps.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Experimental proof of Chromosomal Theory of Inheritance using Drosophila melanogaster</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Discovery of sex-linked inheritance (white-eye mutation in fruit fly)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formulation of concepts of Linkage and Recombination and laying groundwork for genetic mapping</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q10 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q10')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What is pedigree analysis? Suggest how such an analysis, can be useful.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition of Pedigree Analysis:</strong></p>\n  <p><strong>Pedigree analysis</strong> is the systematic study and analysis of the inheritance of a specific trait, disease, or abnormality across multiple successive generations of a human family, represented in the form of a standardised genealogical family tree diagram.</p>\n\n  <p><strong>Utility and Clinical Applications:</strong></p>\n  <ol>\n    <li><strong>Overcomes Limitations of Human Experimental Genetics:</strong> Controlled experimental breeding and hybridisation crosses are unethical and impossible in humans; furthermore, human families have small numbers of progeny. Pedigree charts allow geneticists to trace family history retrospectively.</li>\n    <li><strong>Identification of Inheritance Patterns:</strong> Determines whether an inherited trait is:\n      <ul>\n        <li><strong>Autosomal dominant</strong> (e.g., Myotonic dystrophy)</li>\n        <li><strong>Autosomal recessive</strong> (e.g., Sickle-cell anaemia, Cystic fibrosis)</li>\n        <li><strong>Sex-linked (X-linked) recessive</strong> (e.g., Haemophilia, Red-green colour blindness)</li>\n      </ul>\n    </li>\n    <li><strong>Genetic Counselling & Carrier Detection:</strong> Enables genetic counsellors to determine carrier status (heterozygous carriers) among prospective parents and assess the statistical probability/risk of conceiving an affected child.</li>\n    <li><strong>Prenatal Decision Making:</strong> Guides informed decisions on prenatal amniocentesis, IVF with preimplantation genetic diagnosis (PGD), or family planning.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear definition of pedigree analysis (charting inheritance of traits across generations)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Overcoming limitations of human breeding experiments and identifying inheritance patterns (autosomal vs sex-linked, dominant vs recessive)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Application in genetic counselling, carrier detection, and assessing risk of congenital anomalies</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q11 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q11')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        How is sex determined in human beings?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Sex determination in human beings is based on the <strong>XX-XY chromosomal mechanism</strong>, characterized by <strong>male heterogamety</strong>.</p>\n  <ol>\n    <li><strong>Karyotypic Constitution:</strong>\n      <ul>\n        <li>Human somatic cells contain 23 pairs (46 chromosomes): <strong>22 pairs of autosomes</strong> and <strong>1 pair of sex chromosomes (allosomes)</strong>.</li>\n        <li><strong>Females (Homogametic):</strong> Possess two identical X chromosomes (<strong>44 + XX</strong>). All ova produced during oogenesis carry an X chromosome (<strong>22 + X</strong>).</li>\n        <li><strong>Males (Heterogametic):</strong> Possess one X and one significantly smaller Y chromosome (<strong>44 + XY</strong>). During spermatogenesis, males produce two distinct types of sperms in equal 50:50 proportion:\n          <ul>\n            <li>50% Gynomperms carrying <strong>22 + X</strong></li>\n            <li>50% Androsperms carrying <strong>22 + Y</strong></li>\n          </ul>\n        </li>\n      </ul>\n    </li>\n    <li><strong>Fertilisation & Sex Outcome:</strong>\n      <ul>\n        <li>If an ovum (22 + X) is fertilised by an X-bearing sperm (22 + X), the resulting zygote is <strong>44 + XX</strong>, which develops into a <strong>Female child</strong>.</li>\n        <li>If an ovum (22 + X) is fertilised by a Y-bearing sperm (22 + Y), the resulting zygote is <strong>44 + XY</strong>, which develops into a <strong>Male child</strong> (due to presence of SRY gene on Y chromosome).</li>\n      </ul>\n    </li>\n    <li><strong>Statistical Probability:</strong> Since X-bearing and Y-bearing sperms are produced in equal numbers, there is an exact <strong>50% (1 : 1) probability</strong> of having either a boy or a girl in each pregnancy.</li>\n    <li><strong>Biological Fact:</strong> It is biologically the <strong>father's sperm</strong> that determines the sex of the child, not the mother.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Chromosomal constitution: Female (44+XX, homogametic) and Male (44+XY, heterogametic)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sperm types (50% X and 50% Y) and fertilization outcomes (XX female, XY male)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Equal 50% statistical probability and establishing that father determines the sex of the child</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q12 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q12')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        A child has blood group O. If the father has blood group A and mother blood group B, work out the genotypes of the parents and the possible genotypes of the other offsprings.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Determination of Parental Genotypes:</strong></p>\n  <ul>\n    <li>The child has blood group <strong>O</strong>. The genotype of blood group O is homozygous recessive: <strong>i i</strong>.</li>\n    <li>The child receives one allele 'i' from the father and one allele 'i' from the mother.</li>\n    <li>The father has blood group <strong>A</strong>. Therefore, the father must be heterozygous carrying the recessive allele: <strong>I<sup>A</sup>i</strong>.</li>\n    <li>The mother has blood group <strong>B</strong>. Therefore, the mother must also be heterozygous carrying the recessive allele: <strong>I<sup>B</sup>i</strong>.</li>\n  </ul>\n\n  <p><strong>2. Genetic Cross & Punnett Square:</strong></p>\n  <p>Cross: Father (<strong>I<sup>A</sup>i</strong>) &times; Mother (<strong>I<sup>B</sup>i</strong>)</p>\n  <table style=\"width:300px; border-collapse:collapse; margin:10px 0; text-align:center;\">\n    <tr style=\"background:#ecfdf5; border:1px solid #10b981;\">\n      <th style=\"padding:6px; border:1px solid #10b981;\">&#9794; \\ &#9792;</th>\n      <th style=\"padding:6px; border:1px solid #10b981;\">I<sup>B</sup> (&frac12;)</th>\n      <th style=\"padding:6px; border:1px solid #10b981;\">i (&frac12;)</th>\n    </tr>\n    <tr>\n      <th style=\"padding:6px; background:#ecfdf5; border:1px solid #10b981;\">I<sup>A</sup> (&frac12;)</th>\n      <td style=\"padding:6px; border:1px solid #cbd5e1;\"><strong>I<sup>A</sup>I<sup>B</sup></strong><br>(Blood Group AB)</td>\n      <td style=\"padding:6px; border:1px solid #cbd5e1;\"><strong>I<sup>A</sup>i</strong><br>(Blood Group A)</td>\n    </tr>\n    <tr>\n      <th style=\"padding:6px; background:#ecfdf5; border:1px solid #10b981;\">i (&frac12;)</th>\n      <td style=\"padding:6px; border:1px solid #cbd5e1;\"><strong>I<sup>B</sup>i</strong><br>(Blood Group B)</td>\n      <td style=\"padding:6px; border:1px solid #cbd5e1;\"><strong>i i</strong><br>(Blood Group O - given)</td>\n    </tr>\n  </table>\n\n  <p><strong>3. Possible Genotypes and Phenotypes of Other Offspring:</strong></p>\n  <ol>\n    <li>Genotype <strong>I<sup>A</sup>I<sup>B</sup></strong> &rarr; Phenotype: <strong>Blood Group AB</strong> (Probability: 25%)</li>\n    <li>Genotype <strong>I<sup>A</sup>i</strong> &rarr; Phenotype: <strong>Blood Group A</strong> (Probability: 25%)</li>\n    <li>Genotype <strong>I<sup>B</sup>i</strong> &rarr; Phenotype: <strong>Blood Group B</strong> (Probability: 25%)</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Deducing child genotype (ii) and heterozygous parental genotypes (I^A i and I^B i)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Punnett square showing all four allelic combinations</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct listing of possible genotypes (I^A I^B, I^A i, I^B i) and phenotypes (AB, A, B) of other offspring</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q13 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q13')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Explain the following terms with one example each:\n  <br>(a) Co-dominance\n  <br>(b) Incomplete dominance\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:16px;\">\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(a) Co-dominance</h5>\n      <p><strong>Definition:</strong> Co-dominance is a phenomenon in which both alleles of a gene in a heterozygote express themselves equally and simultaneously in the phenotype. There is no dominant-recessive relationship, nor is there any blending of characters.</p>\n      <p><strong>Example: ABO Blood Grouping in Humans:</strong></p>\n      <ul>\n        <li>The gene <em>I</em> controls ABO blood groups and has three alleles: <em>I<sup>A</sup>, I<sup>B</sup></em>, and <em>i</em>.</li>\n        <li>Alleles <em>I<sup>A</sup></em> and <em>I<sup>B</sup></em> produce slightly different forms of surface sugar polymers on erythrocytes.</li>\n        <li>When both <em>I<sup>A</sup></em> and <em>I<sup>B</sup></em> are present together in an individual (genotype <strong>I<sup>A</sup>I<sup>B</sup></strong>), both alleles express their respective sugars fully. As a consequence, the red blood cells have both A and B types of sugars, resulting in <strong>Blood Group AB</strong>.</li>\n      </ul>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(b) Incomplete Dominance</h5>\n      <p><strong>Definition:</strong> Incomplete dominance is an inheritance pattern in which neither allele of a gene is completely dominant over the other. The heterozygous F1 hybrid exhibits an intermediate, blending phenotype between the two homozygous parental phenotypes.</p>\n      <p><strong>Example: Flower Colour in Snapdragon (<em>Antirrhinum majus</em>) or 4 O'clock Plant (<em>Mirabilis jalapa</em>):</strong></p>\n      <ul>\n        <li>A true-breeding red-flowered plant (<strong>RR</strong>) crossed with a true-breeding white-flowered plant (<strong>rr</strong>).</li>\n        <li>The F1 hybrid (<strong>Rr</strong>) produces <strong>Pink flowers</strong> (intermediate between red and white).</li>\n        <li>Selfing of F1 (Rr &times; Rr) produces F2 progeny with:\n          <br><strong>Phenotypic ratio:</strong> 1 Red : 2 Pink : 1 White (<strong>1 : 2 : 1</strong>)\n          <br><strong>Genotypic ratio:</strong> 1 RR : 2 Rr : 1 rr (<strong>1 : 2 : 1</strong>)\n        </li>\n        <li>Here, both phenotypic and genotypic ratios are identical (1:2:1), demonstrating that the recessive allele 'r' is not altered and segregates cleanly in F2.</li>\n      </ul>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Co-dominance definition and ABO blood group AB (I^A I^B) explanation</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Incomplete dominance definition and Snapdragon/Mirabilis flower colour (RR red x rr white -> Rr pink) with 1:2:1 ratio</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q14 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q14')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What is point mutation? Give one example.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition:</strong></p>\n  <p>A <strong>point mutation</strong> is a gene mutation that arises due to a change, substitution, insertion, or deletion of a <strong>single base pair</strong> in the DNA sequence of a gene.</p>\n\n  <p><strong>Classic Example: Sickle-Cell Anaemia:</strong></p>\n  <ol>\n    <li>Sickle-cell anaemia is an autosomal recessive genetic disease caused by a point mutation (base substitution) in the gene coding for the &beta;-globin chain of haemoglobin located on chromosome 11.</li>\n    <li>At the <strong>6th codon</strong> of the &beta;-globin gene, a transversion mutation converts the normal codon <strong>GAG to GUG</strong> (thymine substituted by adenine in the coding strand).</li>\n    <li>This results in the substitution of <strong>Glutamic acid (Glu) by Valine (Val)</strong> at the sixth position of the &beta;-globin polypeptide chain:\n      <div style=\"background:#f8fafc; padding:8px 12px; margin:8px 0; border-left:4px solid #059669; font-family:monospace;\">\n        Normal HbA gene: GAG (mRNA) &rarr; Glutamic Acid (Polar, hydrophilic)<br>\n        Sickle HbS gene: GUG (mRNA) &rarr; Valine (Non-polar, hydrophobic)\n      </div>\n    </li>\n    <li>Under low oxygen tension, the mutant haemoglobin (HbS) undergoes polymerisation, changing the shape of the erythrocyte from a flexible biconcave disc to an elongated, rigid <strong>sickle-like structure</strong>, leading to microvascular occlusion and haemolytic anaemia.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition of point mutation (change/substitution of a single base pair in DNA)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Detailed example: Sickle-cell anaemia (GAG to GUG transversion at 6th codon of beta-globin replacing glutamic acid with valine)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q15 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q15')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Who had proposed the chromosomal theory of the inheritance?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>The <strong>Chromosomal Theory of Inheritance</strong> was proposed independently in 1902 by:</p>\n  <div style=\"background:#f0fdf4; padding:12px; border:1px solid #86efac; border-radius:8px; margin:10px 0; font-size:1.05rem; font-weight:700; color:#065f46;\">\n    Walter Sutton and Theodor Boveri (1902)\n  </div>\n  <p><strong>Core Concept:</strong></p>\n  <ul>\n    <li>They noticed that the behaviour of chromosomes during meiosis (gamete formation) was parallel to the behaviour of Mendelian factors (genes).</li>\n    <li>They united chromosomal segregation during anaphase I & II with Mendelian principles and concluded that genes are linear physical entities carried upon chromosomes.</li>\n    <li><em>Note:</em> Experimental verification of this theory was subsequently provided by <strong>Thomas Hunt Morgan</strong> and his colleagues using <em>Drosophila melanogaster</em>.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Walter Sutton and Theodor Boveri (1902)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch4-q16 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch4-q16\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch4-q16')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q16</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Mention any two autosomal genetic disorders with their symptoms.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Two well-known autosomal genetic disorders are:</p>\n  \n  <div style=\"display:flex; flex-direction:column; gap:14px; margin-top:10px;\">\n    <!-- Disorder 1 -->\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">1. Down's Syndrome (Autosomal Aneuploidy / Trisomy 21)</h5>\n      <p style=\"margin:0 0 6px 0;\"><strong>Genetic Basis:</strong> Presence of an additional copy of chromosome number 21 (karyotype: <strong>47, +21</strong>) due to non-disjunction of chromosomes during gametogenesis. First described by Langdon Down in 1866.</p>\n      <p style=\"margin:0; font-weight:700; color:#334155;\">Key Clinical Symptoms:</p>\n      <ul style=\"margin:4px 0 0 0;\">\n        <li>Short stature with small round head.</li>\n        <li>Furrowed tongue and partially open mouth.</li>\n        <li>Broad palm with characteristic single transverse palmar crease (Simian crease).</li>\n        <li>Physical, psychomotor, and mental development is retarded.</li>\n      </ul>\n    </div>\n\n    <!-- Disorder 2 -->\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">2. Phenylketonuria (PKU) (Autosomal Recessive Inborn Error of Metabolism)</h5>\n      <p style=\"margin:0 0 6px 0;\"><strong>Genetic Basis:</strong> Mutation in the gene coding for the hepatic enzyme <strong>phenylalanine hydroxylase</strong> located on chromosome 12.</p>\n      <p style=\"margin:0; font-weight:700; color:#334155;\">Key Clinical Symptoms:</p>\n      <ul style=\"margin:4px 0 0 0;\">\n        <li>Inability to convert amino acid phenylalanine into tyrosine, causing accumulation of phenylalanine and its conversion to phenylpyruvic acid.</li>\n        <li>Accumulation of these neurotoxic derivatives in brain leads to <strong>severe mental retardation</strong>.</li>\n        <li>Excretion of phenyl derivatives in urine due to poor kidney tubular reabsorption.</li>\n        <li>Hypopigmentation of hair and skin.</li>\n      </ul>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Disorder 1: Down syndrome (Trisomy 21) with genetic basis and symptoms (furrowed tongue, short stature, simian crease, mental retardation)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Disorder 2: Phenylketonuria / Sickle cell anaemia with genetic basis and symptoms (mental retardation, hypopigmentation / anaemia, RBC sickling)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"display:flex; justify-content:space-between; align-items:center; margin-top:36px; padding-top:20px; border-top:1px solid #e2e8f0;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(3)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 3</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(5)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#059669; color:white; font-weight:700; cursor:pointer;\">Next: Ch 5 (Molecular Basis of Inheritance) →</button>\n  </div>\n</section>";
window.CHAPTER_DATA[5] = "<section class=\"chapter-section\" id=\"c12b-ch5\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#059669;\">5</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#059669;\">CBSE Class 12 Biology &bull; Chapter 5</div>\n      <h2>Molecular Basis of Inheritance</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 14 Verbatim Questions with Official CBSE Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n<div class=\"chem-card\" style=\"margin-bottom:24px; padding:20px; background:#f0fdf4; border:1px solid #bbf7d0; border-radius:12px;\">\n  <h4 style=\"margin:0 0 12px 0; color:#059669; font-size:1.05rem;\">🧬 Molecular Architecture: Central Dogma, Lac Operon & DNA Fingerprinting</h4>\n  <svg viewBox=\"0 0 880 300\" style=\"width:100%; max-width:880px; height:auto; display:block; margin:0 auto; background:white; border-radius:8px; border:1px solid #d1fae5;\">\n    <!-- Central Dogma -->\n    <rect x=\"20\" y=\"20\" width=\"270\" height=\"260\" rx=\"10\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"155\" y=\"48\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Central Dogma (Crick, 1958)</text>\n    <line x1=\"35\" y1=\"58\" x2=\"275\" y2=\"58\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    \n    <rect x=\"40\" y=\"80\" width=\"70\" height=\"35\" rx=\"6\" fill=\"#10b981\"/>\n    <text x=\"75\" y=\"102\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"white\" text-anchor=\"middle\">DNA</text>\n\n    <!-- Arrow Replication -->\n    <path d=\"M 60 80 C 40 50, 90 50, 85 75\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\" marker-end=\"url(#arrow)\"/>\n    <text x=\"75\" y=\"55\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#047857\" text-anchor=\"middle\">Replication</text>\n\n    <line x1=\"110\" y1=\"97\" x2=\"155\" y2=\"97\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <polygon points=\"155,93 163,97 155,101\" fill=\"#059669\"/>\n    <text x=\"135\" y=\"90\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#065f46\" text-anchor=\"middle\">Transcription</text>\n\n    <rect x=\"165\" y=\"80\" width=\"70\" height=\"35\" rx=\"6\" fill=\"#3b82f6\"/>\n    <text x=\"200\" y=\"102\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"white\" text-anchor=\"middle\">mRNA</text>\n\n    <line x1=\"200\" y1=\"115\" x2=\"200\" y2=\"155\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <polygon points=\"196,155 200,163 204,155\" fill=\"#3b82f6\"/>\n    <text x=\"238\" y=\"140\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#1e40af\" text-anchor=\"middle\">Translation</text>\n\n    <rect x=\"155\" y=\"165\" width=\"90\" height=\"35\" rx=\"6\" fill=\"#f59e0b\"/>\n    <text x=\"200\" y=\"187\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"white\" text-anchor=\"middle\">PROTEIN</text>\n\n    <text x=\"40\" y=\"230\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Reverse Transcription (Teminism):</text>\n    <text x=\"40\" y=\"248\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">  RNA &rarr; cDNA (in Retroviruses)</text>\n    <text x=\"40\" y=\"266\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#059669\">&bull; Chargaff Rule: [A]=[T], [G]=[C]</text>\n\n    <!-- Lac Operon Card -->\n    <rect x=\"310\" y=\"20\" width=\"270\" height=\"260\" rx=\"10\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <text x=\"445\" y=\"48\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Lac Operon (Jacob & Monod)</text>\n    <line x1=\"325\" y1=\"58\" x2=\"565\" y2=\"58\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n\n    <!-- Gene segments -->\n    <g transform=\"translate(325, 75)\">\n      <rect x=\"0\" y=\"0\" width=\"35\" height=\"30\" fill=\"#cbd5e1\" stroke=\"#64748b\"/>\n      <text x=\"17\" y=\"20\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#1e293b\" text-anchor=\"middle\">p</text>\n      <rect x=\"35\" y=\"0\" width=\"35\" height=\"30\" fill=\"#fecaca\" stroke=\"#dc2626\"/>\n      <text x=\"52\" y=\"20\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">i</text>\n      <rect x=\"70\" y=\"0\" width=\"35\" height=\"30\" fill=\"#cbd5e1\" stroke=\"#64748b\"/>\n      <text x=\"87\" y=\"20\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#1e293b\" text-anchor=\"middle\">p</text>\n      <rect x=\"105\" y=\"0\" width=\"35\" height=\"30\" fill=\"#fed7aa\" stroke=\"#ea580c\"/>\n      <text x=\"122\" y=\"20\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#9a3412\" text-anchor=\"middle\">o</text>\n      <rect x=\"140\" y=\"0\" width=\"33\" height=\"30\" fill=\"#bbf7d0\" stroke=\"#16a34a\"/>\n      <text x=\"156\" y=\"20\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#166534\" text-anchor=\"middle\">z</text>\n      <rect x=\"173\" y=\"0\" width=\"33\" height=\"30\" fill=\"#bfdbfe\" stroke=\"#2563eb\"/>\n      <text x=\"189\" y=\"20\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">y</text>\n      <rect x=\"206\" y=\"0\" width=\"34\" height=\"30\" fill=\"#e9d5ff\" stroke=\"#9333ea\"/>\n      <text x=\"223\" y=\"20\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#6b21a8\" text-anchor=\"middle\">a</text>\n    </g>\n\n    <text x=\"325\" y=\"130\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#1e40af\">Structural Genes & Products:</text>\n    <text x=\"325\" y=\"148\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; <strong>z</strong> &rarr; &beta;-galactosidase (lactose &rarr; glu+gal)</text>\n    <text x=\"325\" y=\"165\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; <strong>y</strong> &rarr; &beta;-galactoside permease (entry)</text>\n    <text x=\"325\" y=\"182\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; <strong>a</strong> &rarr; &beta;-galactoside transacetylase</text>\n    <text x=\"325\" y=\"205\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#b91c1c\">Regulation State:</text>\n    <text x=\"325\" y=\"223\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; (-) Lactose: Repressor binds Operator (OFF)</text>\n    <text x=\"325\" y=\"240\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; (+) Lactose/Allolactose: Inducer inactivates</text>\n    <text x=\"325\" y=\"256\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">  repressor &rarr; Operon turns ON</text>\n\n    <!-- Genetic Code & HGP Card -->\n    <rect x=\"600\" y=\"20\" width=\"260\" height=\"260\" rx=\"10\" fill=\"#fef2f2\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n    <text x=\"730\" y=\"48\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">Key Molecular Landmarks</text>\n    <line x1=\"615\" y1=\"58\" x2=\"845\" y2=\"58\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n    <text x=\"615\" y=\"80\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#b91c1c\">Genetic Code Features:</text>\n    <text x=\"615\" y=\"98\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Triplet (61 codons amino acids, 3 STOP)</text>\n    <text x=\"615\" y=\"114\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Degenerate, Unambiguous & Universal</text>\n    <text x=\"615\" y=\"130\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Initiator: AUG (Methionine)</text>\n    <text x=\"615\" y=\"152\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#b91c1c\">DNA Fingerprinting (Alec Jeffreys):</text>\n    <text x=\"615\" y=\"170\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; VNTRs (Variable Number Tandem Repeats)</text>\n    <text x=\"615\" y=\"186\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Minisatellites (0.1 to 20 kb)</text>\n    <text x=\"615\" y=\"202\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Southern Blotting + Radio-labelled probe</text>\n    <text x=\"615\" y=\"225\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#b91c1c\">Human Genome Project (HGP):</text>\n    <text x=\"615\" y=\"242\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; 3.1647 billion bp, ~30,000 genes</text>\n    <text x=\"615\" y=\"258\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Chromosome 1 has highest (2,968 genes)</text>\n  </svg>\n</div>\n\n  <div class=\"ex-div\" style=\"font-size:0.88rem; font-weight:700; color:#334155; margin-bottom:16px; padding:8px 14px; background:#ecfdf5; border-radius:8px; border-left:4px solid #059669;\">NCERT Exercises (14 Verbatim Questions)</div>\n\n  <div class=\"questions-container\">\n    \n  <!-- c12b-ch5-q1 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch5-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch5-q1')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Group the following as nitrogenous bases and nucleosides:\nAdenine, Cytidine, Thymine, Guanosine, Uracil and Cytosine.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>In nucleic acids, a <strong>nitrogenous base</strong> is a heterocyclic nitrogen-containing aromatic compound (purine or pyrimidine). A <strong>nucleoside</strong> is formed when a nitrogenous base is covalently linked to a pentose sugar (ribose or 2'-deoxyribose) through an <em>N-glycosidic bond</em>.</p>\n  \n  <div style=\"display:flex; flex-wrap:wrap; gap:16px; margin-top:12px;\">\n    <div style=\"flex:1; min-width:240px; background:#ecfdf5; padding:14px; border-radius:8px; border:1px solid #10b981;\">\n      <h5 style=\"color:#065f46; margin:0 0 8px 0; font-size:1rem;\">1. Nitrogenous Bases</h5>\n      <p style=\"font-size:0.85rem; color:#475569; margin:0 0 8px 0;\">Heterocyclic aromatic bases without sugar linkage:</p>\n      <ul style=\"margin:0; padding-left:20px; font-weight:700; color:#065f46;\">\n        <li>Adenine (Purine)</li>\n        <li>Thymine (Pyrimidine - in DNA)</li>\n        <li>Uracil (Pyrimidine - in RNA)</li>\n        <li>Cytosine (Pyrimidine)</li>\n      </ul>\n    </div>\n\n    <div style=\"flex:1; min-width:240px; background:#eff6ff; padding:14px; border-radius:8px; border:1px solid #3b82f6;\">\n      <h5 style=\"color:#1e40af; margin:0 0 8px 0; font-size:1rem;\">2. Nucleosides</h5>\n      <p style=\"font-size:0.85rem; color:#475569; margin:0 0 8px 0;\">Base + Pentose Sugar (via N-glycosidic linkage):</p>\n      <ul style=\"margin:0; padding-left:20px; font-weight:700; color:#1e40af;\">\n        <li>Cytidine (Cytosine + Ribose / Deoxyribose)</li>\n        <li>Guanosine (Guanine + Ribose / Deoxyribose)</li>\n      </ul>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct grouping of nitrogenous bases: Adenine, Thymine, Uracil, Cytosine</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct grouping of nucleosides: Cytidine, Guanosine</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch5-q2 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch5-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch5-q2')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        If a double stranded DNA has 20 per cent of cytosine, calculate the per cent of adenine in the DNA.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Application of Chargaff's Equimolar Rules:</strong></p>\n  <p>Erwin Chargaff demonstrated that in any double-stranded DNA (dsDNA):</p>\n  <ol>\n    <li>The total purine content is always equal to total pyrimidine content: <strong>[A + G] = [T + C]</strong>.</li>\n    <li>Adenine pairs exclusively with Thymine by two hydrogen bonds: <strong>% A = % T</strong>.</li>\n    <li>Guanine pairs exclusively with Cytosine by three hydrogen bonds: <strong>% G = % C</strong>.</li>\n  </ol>\n\n  <p><strong>Step-by-Step Calculation:</strong></p>\n  <ul>\n    <li>Given: Cytosine (C) = <strong>20%</strong></li>\n    <li>Since % G = % C, therefore: Guanine (G) = <strong>20%</strong></li>\n    <li>Total percentage of (G + C) = 20% + 20% = <strong>40%</strong></li>\n    <li>Total percentage of (A + T) = 100% - 40% = <strong>60%</strong></li>\n    <li>Since % A = % T, therefore:\n      <div style=\"background:#f8fafc; padding:10px 14px; border-left:4px solid #059669; font-weight:700; margin:8px 0; font-size:1.05rem;\">\n        % Adenine (A) = 60% / 2 = 30%\n      </div>\n    </li>\n  </ul>\n  <p><strong>Conclusion:</strong> The percentage of Adenine in this double-stranded DNA is <strong>30%</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Statement of Chargaff's rule: %G = %C and %A = %T; %A + %T + %G + %C = 100%</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation showing %G = 20%, %(A+T) = 60%, arriving at %Adenine = 30%</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch5-q3 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch5-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch5-q3')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        If the sequence of one strand of DNA is written as follows:\n  <br><strong>5' -ATGCATGCATGCATGCATGCATGCATGC-3'</strong>\n  <br>Write down the sequence of complementary strand in 5' &rarr; 3' direction.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Rule of Complementary Base Pairing & Antiparallel Polarity:</strong></p>\n  <ol>\n    <li>DNA strands are <strong>antiparallel</strong> (if one strand is 5' &rarr; 3', the complementary strand is 3' &rarr; 5').</li>\n    <li>Base-pairing rules state that Adenine (A) pairs with Thymine (T) and Guanine (G) pairs with Cytosine (C).</li>\n  </ol>\n\n  <p><strong>Step 1: Write the complementary strand in the 3' &rarr; 5' direction:</strong></p>\n  <div style=\"background:#f8fafc; padding:10px 14px; border-radius:6px; font-family:monospace; margin:8px 0;\">\n    Given strand:&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;5' -ATGCATGCATGCATGCATGCATGCATGC- 3'<br>\n    Complementary (3' &rarr; 5'): 3' -TACGTACGTACGTACGTACGTACGTACG- 5'\n  </div>\n\n  <p><strong>Step 2: Invert the complementary strand into the requested 5' &rarr; 3' direction:</strong></p>\n  <div style=\"background:#ecfdf5; padding:12px 14px; border-left:4px solid #059669; font-family:monospace; font-weight:700; margin:8px 0; font-size:1rem; color:#065f46;\">\n    5' -GCATGCATGCATGCATGCATGCATGCAT- 3'\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Applying Watson-Crick base pairing rules (A-T and G-C) to find 3'->5' complement</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correctly writing the inverted sequence in the requested 5' -> 3' polarity</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch5-q4 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch5-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch5-q4')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        If the sequence of the coding strand in a transcription unit is written as follows:\n  <br><strong>5' -ATGCATGCATGCATGCATGCATGCATGC-3'</strong>\n  <br>Write down the sequence of mRNA.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Transcription Polarity and mRNA Rule:</strong></p>\n  <ul>\n    <li>In a transcription unit, the <strong>template strand</strong> (3' &rarr; 5') is transcribed into mRNA.</li>\n    <li>The <strong>coding strand</strong> (5' &rarr; 3') is <em>not</em> transcribed, but by scientific convention, the sequence of mRNA is <strong>identical to the coding strand</strong>, with only one chemical difference: <strong>Thymine (T) in DNA is replaced by Uracil (U) in RNA</strong>.</li>\n    <li>The polarity of both the coding strand and the resulting mRNA is 5' &rarr; 3'.</li>\n  </ul>\n\n  <p><strong>Deduction:</strong></p>\n  <div style=\"background:#f8fafc; padding:10px 14px; border-radius:6px; font-family:monospace; margin:8px 0;\">\n    Coding strand (DNA):&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;5' -ATGCATGCATGCATGCATGCATGCATGC- 3'<br>\n    Template strand (DNA):&nbsp;&nbsp;&nbsp;3' -TACGTACGTACGTACGTACGTACGTACG- 5'<br>\n    mRNA transcribed:&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;5' -AUGCAUGCAUGCAUGCAUGCAUGCAUGC- 3'\n  </div>\n\n  <div style=\"background:#ecfdf5; padding:12px 14px; border-left:4px solid #059669; font-family:monospace; font-weight:700; margin:8px 0; font-size:1rem; color:#065f46;\">\n    Sequence of mRNA: 5' -AUGCAUGCAUGCAUGCAUGCAUGCAUGC- 3'\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation that mRNA sequence is identical to coding strand except T is replaced by U</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate mRNA sequence written with 5' to 3' polarity</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch5-q5 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch5-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch5-q5')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Which property of DNA double helix led Watson and Crick to hypothesise semi-conservative mode of DNA replication? Explain.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>The Core Property:</strong></p>\n  <p>The property of <strong>complementary base pairing</strong> between the two antiparallel polynucleotide strands led James Watson and Francis Crick (1953) to immediately propose the semi-conservative mode of replication.</p>\n\n  <p><strong>Explanation:</strong></p>\n  <ol>\n    <li>Watson and Crick famously noted in their 1953 Nature paper: <em>\"It has not escaped our notice that the specific pairing we have postulated immediately suggests a possible copying mechanism for the genetic material.\"</em></li>\n    <li>Due to strict complementary base pairing (Adenine specifically pairing with Thymine via 2 H-bonds, and Guanine specifically pairing with Cytosine via 3 H-bonds), the sequence of bases in one strand automatically and precisely dictates the sequence of bases in the opposite strand.</li>\n    <li>During replication:\n      <ul>\n        <li>The hydrogen bonds holding the two parental strands together uncoil and separate.</li>\n        <li>Each separated parental strand acts as a <strong>template</strong> for the synthesis of a new complementary strand.</li>\n        <li>Substrate deoxyribonucleoside triphosphates (dNTPs) align opposite the template according to base pairing rules and are joined by DNA polymerase.</li>\n      </ul>\n    </li>\n    <li>Upon completion of replication, each daughter DNA duplex contains <strong>one conserved parental strand</strong> and <strong>one newly synthesised strand</strong>. Hence, the replication process is termed <strong>semi-conservative</strong> (experimentally verified later by Meselson and Stahl in 1958).</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of the property: Complementary base pairing between the two strands</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of uncoiling and each strand serving as a template for synthesis of a new partner</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Daughter molecule having one parental strand and one newly synthesised strand (semi-conservative)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch5-q6 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch5-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch5-q6')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Depending upon the chemical nature of the template (DNA or RNA) and the nature of synthesized products (DNA or RNA), contemplate the types of nucleic acid polymerases.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Nucleic acid polymerases are classified strictly according to the substrate template they read and the type of macromolecule they synthesise:</p>\n  \n  <table style=\"width:100%; border-collapse:collapse; margin-top:12px; font-size:0.9rem;\">\n    <thead>\n      <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n        <th style=\"padding:8px 10px; color:#065f46;\">Polymerase Class</th>\n        <th style=\"padding:8px 10px; color:#065f46;\">Template Used</th>\n        <th style=\"padding:8px 10px; color:#065f46;\">Product Synthesised</th>\n        <th style=\"padding:8px 10px; color:#065f46;\">Biological Example & Role</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:8px 10px; font-weight:700;\">1. DNA-dependent DNA Polymerase</td>\n        <td style=\"padding:8px 10px;\">DNA (deoxypolynucleotide)</td>\n        <td style=\"padding:8px 10px;\">DNA</td>\n        <td style=\"padding:8px 10px;\"><strong>DNA Polymerase I, II, III (e.g. in <em>E. coli</em>):</strong> Catalyses semiconservative DNA replication.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:8px 10px; font-weight:700;\">2. DNA-dependent RNA Polymerase</td>\n        <td style=\"padding:8px 10px;\">DNA</td>\n        <td style=\"padding:8px 10px;\">RNA</td>\n        <td style=\"padding:8px 10px;\"><strong>RNA Polymerase:</strong> Catalyses transcription (mRNA, tRNA, rRNA synthesis) in prokaryotes & eukaryotes.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:8px 10px; font-weight:700;\">3. RNA-dependent DNA Polymerase (Reverse Transcriptase)</td>\n        <td style=\"padding:8px 10px;\">RNA</td>\n        <td style=\"padding:8px 10px;\">DNA (cDNA)</td>\n        <td style=\"padding:8px 10px;\"><strong>Reverse Transcriptase:</strong> Present in retroviruses (e.g., HIV) to convert viral genomic RNA into cDNA.</td>\n      </tr>\n      <tr style=\"background:#f8fafc;\">\n        <td style=\"padding:8px 10px; font-weight:700;\">4. RNA-dependent RNA Polymerase (RNA Replicase)</td>\n        <td style=\"padding:8px 10px;\">RNA</td>\n        <td style=\"padding:8px 10px;\">RNA</td>\n        <td style=\"padding:8px 10px;\"><strong>RNA Replicase:</strong> Used by RNA viruses (e.g., Poliovirus, TMV, Influenza) to replicate their RNA genomes.</td>\n      </tr>\n    </tbody>\n  </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">DNA-dependent DNA polymerase (DNA template -> DNA product) with role in replication</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">DNA-dependent RNA polymerase (DNA template -> RNA product) with role in transcription</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">RNA-dependent DNA polymerase (Reverse Transcriptase) and RNA-dependent RNA polymerase (RNA Replicase)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch5-q7 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch5-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch5-q7')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        How did Hershey and Chase differentiate between DNA and protein in their experiment while proving that DNA is the genetic material?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Alfred Hershey and Martha Chase (1952) worked with <strong>bacteriophage T2</strong> that infects <em>Escherichia coli</em> to provide unequivocal proof that DNA is the genetic material.</p>\n  \n  <p><strong>Chemical Differentiation Strategy Using Radioisotopes:</strong></p>\n  <ul>\n    <li><strong>Radioactive Phosphorus (<sup>32</sup>P) for DNA:</strong> DNA contains phosphorus as an integral constituent of its sugar-phosphate backbone, but contains <em>no sulphur</em>. Bacteriophages grown in a medium containing radioactive <strong><sup>32</sup>P</strong> incorporated radioactivity exclusively into their <strong>DNA</strong>.</li>\n    <li><strong>Radioactive Sulphur (<sup>35</sup>S) for Protein:</strong> Proteins contain sulphur in amino acids (cysteine and methionine), but contain <em>no phosphorus</em>. Bacteriophages grown in a medium containing radioactive <strong><sup>35</sup>S</strong> incorporated radioactivity exclusively into their <strong>protein capsid coats</strong>.</li>\n  </ul>\n\n  <p><strong>Experimental Protocol & Results:</strong></p>\n  <ol>\n    <li><strong>Infection:</strong> Both batches of labeled phages were allowed to attach to separate cultures of <em>E. coli</em>.</li>\n    <li><strong>Blending:</strong> The bacterial cultures were agitated in a kitchen blender to dislodge the empty viral coats (ghosts) from the surface of the bacterial cells.</li>\n    <li><strong>Centrifugation:</strong> The viral ghosts (lighter supernatant) were separated from the heavier bacterial cells (pellet).</li>\n    <li><strong>Observation:</strong>\n      <ul>\n        <li>Bacteria infected with <sup>32</sup>P-labeled phages showed <strong>radioactivity in the cell pellet</strong>, and subsequent progeny phages were radioactive.</li>\n        <li>Bacteria infected with <sup>35</sup>S-labeled phages showed <strong>radioactivity in the supernatant</strong>; no radioactivity was detected in the bacterial cell pellet.</li>\n      </ul>\n    </li>\n  </ol>\n  <p><strong>Conclusion:</strong> This decisively proved that <strong>DNA (and not protein) enters the bacteria from the virus</strong>, confirming that DNA is the hereditary genetic material.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Radioactive labelling strategy: 32P labels DNA (contains phosphorus, no sulfur); 35S labels protein coat (contains sulfur, no phosphorus)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Three-step methodology: Infection, Blending, and Centrifugation</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Experimental result: 32P in pellet (inside bacteria) and 35S in supernatant proving DNA is the genetic material</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch5-q8 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch5-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch5-q8')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Differentiate between the followings:\n  <br>(a) Repetitive DNA and Satellite DNA\n  <br>(b) mRNA and tRNA\n  <br>(c) Template strand and Coding strand\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:16px;\">\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(a) Repetitive DNA vs Satellite DNA</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.9rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:6px 10px; width:50%;\">Repetitive DNA</th>\n          <th style=\"padding:6px 10px; width:50%;\">Satellite DNA</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Broad category of DNA sequences that are repeated many times (from hundreds to millions of times) in the genome.</td>\n          <td style=\"padding:6px 10px;\">A specific sub-fraction of repetitive DNA that separates as distinct minor peaks during CsCl density gradient centrifugation.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:6px 10px;\">Can be interspersed or tandem; includes transposons, retrotransposons, and satellite sequences.</td>\n          <td style=\"padding:6px 10px;\">Highly tandemly repeated non-coding sequences (micro-satellites, mini-satellites/VNTRs) showing high polymorphism.</td>\n        </tr>\n      </table>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(b) mRNA vs tRNA</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.9rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:6px 10px; width:50%;\">mRNA (Messenger RNA)</th>\n          <th style=\"padding:6px 10px; width:50%;\">tRNA (Transfer / Adapter RNA)</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Linear, single-stranded molecule without secondary base-paired loops; accounts for ~5% of cellular RNA.</td>\n          <td style=\"padding:6px 10px;\">Clover-leaf shaped 2D (inverted L-shaped 3D) molecule with folded hydrogen-bonded arms; accounts for ~15% of cellular RNA.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:6px 10px;\">Carries genetic information in triplet <strong>codons</strong> from DNA to ribosomes for polypeptide synthesis.</td>\n          <td style=\"padding:6px 10px;\">Acts as an adapter molecule: reads mRNA codons via its <strong>anticodon loop</strong> and carries the cognate amino acid at its 3'-CCA end.</td>\n        </tr>\n      </table>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(c) Template Strand vs Coding Strand</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.9rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:6px 10px; width:50%;\">Template Strand (Antisense Strand)</th>\n          <th style=\"padding:6px 10px; width:50%;\">Coding Strand (Sense Strand)</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Has <strong>3' &rarr; 5' polarity</strong>.</td>\n          <td style=\"padding:6px 10px;\">Has <strong>5' &rarr; 3' polarity</strong>.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:6px 10px;\">Actively transcribed by RNA polymerase; base sequence is complementary to the synthesised mRNA.</td>\n          <td style=\"padding:6px 10px;\">Not transcribed into mRNA; its sequence is identical to the synthesised mRNA (with T instead of U).</td>\n        </tr>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Clear differentiation between Repetitive DNA and Satellite DNA (CsCl density gradient peaks/VNTRs)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Differentiation between mRNA and tRNA (structure and biological function as template vs adapter)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Differentiation between Template strand (3'->5', transcribed) and Coding strand (5'->3', reference)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch5-q9 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch5-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch5-q9')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        List two essential roles of ribosome during translation.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>During protein synthesis (translation), the ribosome acts as a complex cellular macromolecular machine performing the following two essential roles:</p>\n  <ol>\n    <li><strong>Structural Platform & Positioning of mRNA and Aminoacyl-tRNAs:</strong>\n      <ul>\n        <li>The smaller ribosomal subunit binds to the mRNA transcript, ensuring proper reading-frame alignment at the initiation codon (AUG).</li>\n        <li>The larger ribosomal subunit contains two functional binding sites (<strong>A site</strong> for aminoacyl-tRNA and <strong>P site</strong> for peptidyl-tRNA), positioning adjacent aminoacyl-tRNAs close enough for peptide bond formation.</li>\n      </ul>\n    </li>\n    <li><strong>Enzymatic Catalysis (Peptidyl Transferase Activity):</strong>\n      <ul>\n        <li>The ribosome acts as a <strong>ribozyme</strong>. In prokaryotes, the <strong>23S rRNA</strong> of the larger ribosomal subunit catalyses the formation of peptide bonds between the amino group of the incoming amino acid at the A site and the carboxyl group of the growing peptidyl chain at the P site.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Providing structural framework/binding sites (A, P, E sites) and reading mRNA codons</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Acting as a catalyst/ribozyme (23S rRNA peptidyl transferase) for peptide bond synthesis</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch5-q10 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch5-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch5-q10')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        In the medium where E. coli was growing, lactose was added, which induced the lac operon. Then, why does lac operon shut down some time after addition of lactose in the medium?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>The shut-down of the <em>lac</em> operon occurs through an intrinsic biochemical feedback loop:</p>\n  <ol>\n    <li><strong>Induction Phase:</strong> When lactose (allolactose) is added to the growth medium, it binds to the active repressor protein synthesised by the regulatory <em>i</em> gene. This alters the repressor's allosteric conformation, preventing it from binding to the operator region.</li>\n    <li><strong>Transcription of Structural Genes:</strong> RNA polymerase accesses the promoter and transcribes the polycistronic mRNA, translating into:\n      <ul>\n        <li><strong>&beta;-galactosidase (<em>z</em> gene):</strong> Hydrolyses lactose into glucose and galactose.</li>\n        <li><strong>Permease (<em>y</em> gene):</strong> Increases cell membrane permeability to &beta;-galactosides.</li>\n        <li><strong>Transacetylase (<em>a</em> gene):</strong> Transfers an acetyl group to &beta;-galactosides.</li>\n      </ul>\n    </li>\n    <li><strong>Metabolic Depletion of Inducer:</strong> As &beta;-galactosidase hydrolyses lactose, the intracellular concentration of lactose/allolactose declines steadily until all of it is metabolised into glucose and galactose.</li>\n    <li><strong>Repressor Reactivation and Shut-Down:</strong> In the absence of lactose/inducer, the newly synthesized repressor protein remains free and in its active conformation. It binds tightly once again to the <strong>operator gene (<em>o</em>)</strong>, physically blocking RNA polymerase from transcribing the structural genes. Consequently, the <em>lac</em> operon is switched <strong>OFF</strong>.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Action of beta-galactosidase hydrolysing lactose into glucose and galactose</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Gradual depletion of all lactose (inducer) molecules from the medium/bacterial cell</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Free repressor binds back to operator, blocking RNA polymerase and turning operon OFF</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch5-q11 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch5-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch5-q11')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Explain (in one or two lines) the function of the followings:\n  <br>(a) Promoter\n  <br>(b) tRNA\n  <br>(c) Exons\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:12px;\">\n    <div style=\"background:#f8fafc; padding:10px 14px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(a) Promoter:</strong><br>\n      A DNA sequence located towards the 5'-end (upstream) of the structural gene that provides the specific binding site for RNA polymerase and determines which DNA strand serves as the template for transcription.\n    </div>\n    <div style=\"background:#f8fafc; padding:10px 14px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(b) tRNA (Transfer RNA):</strong><br>\n      Acts as an adapter molecule that reads the genetic code on mRNA through its complementary anticodon triplet and transfers the corresponding cognate amino acid to the growing polypeptide chain during translation.\n    </div>\n    <div style=\"background:#f8fafc; padding:10px 14px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(c) Exons:</strong><br>\n      The coding/expressed coding nucleotide sequences in eukaryotic split genes that appear in mature, spliced functional RNA and are translated into the final polypeptide sequence.\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Promoter: Binding site for RNA polymerase initiating transcription</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) tRNA: Adapter molecule matching anticodon to mRNA codon and delivering amino acid</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Exons: Coding/expressed regions retained in mature mRNA after splicing</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch5-q12 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch5-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch5-q12')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Why is the Human Genome Project called a mega project?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>The <strong>Human Genome Project (HGP)</strong>, initiated in 1990 and completed in 2003, is termed a \"Mega Project\" because of its unprecedented scale, budget, data volume, and international logistical collaboration:</p>\n  <ol>\n    <li><strong>Enormous Scale and Target Size:</strong> The human haploid genome comprises approximately <strong>3 &times; 10<sup>9</sup> base pairs (3 billion bp)</strong>. Sequencing every individual nucleotide across all 24 chromosomes (22 autosomes + X + Y) was a monumental biological undertaking.</li>\n    <li><strong>Colossal Financial Cost:</strong> The projected cost of sequencing was roughly <strong>US $3 per base pair</strong>, making the total estimated budget of the project nearly <strong>US $9 billion</strong>.</li>\n    <li><strong>Immense Data Volume & Storage Requirements:</strong> If the sequence was printed in books containing 1,000 pages each, with 1,000 letters per page, sequencing one human cell would require <strong>3,300 books</strong>! This necessitated the development of novel computer algorithms, high-speed computational databases, and bioinformatics tools for storage, retrieval, and analysis.</li>\n    <li><strong>Massive Global Collaboration:</strong> Coordinated by the US Department of Energy (DOE) and the National Institutes of Health (NIH), with key participation from the Wellcome Trust (UK), Japan, France, Germany, China, and thousands of international scientists over a 13-year timeline.</li>\n    <li><strong>Associated Ethical, Legal, and Social Issues (ELSI):</strong> Required dedicated funding to address the societal, legal, and privacy implications of human genomic data.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Scale: Sequencing 3 x 10^9 base pairs across the human haploid genome</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Huge estimated financial cost (~$9 billion at $3 per base pair)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Data volume (3300 books of 1000 pages each) spurring bioinformatics and global multi-country collaboration</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch5-q13 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch5-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch5-q13')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What is DNA fingerprinting? Mention its application.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition:</strong></p>\n  <p><strong>DNA fingerprinting</strong> (DNA profiling), developed by <strong>Sir Alec Jeffreys</strong> in 1984, is a molecular diagnostic technique used to identify individuals based on unique variations and patterns in their DNA sequence, specifically targeting <strong>Variable Number of Tandem Repeats (VNTRs)</strong> in satellite DNA.</p>\n\n  <p><strong>Underlying Scientific Principle:</strong></p>\n  <ul>\n    <li>99.9% of DNA sequence is identical among all human beings. Individual uniqueness resides in 0.1% polymorphic non-coding DNA.</li>\n    <li>VNTRs (minisatellites) exhibit a very high degree of inheritable <strong>DNA polymorphism</strong>. The size and repeat number of VNTRs vary from person to person (ranging from 0.1 to 20 kb), yielding a unique banding pattern upon Southern blot hybridisation with a radio-labelled VNTR probe (except in monozygotic identical twins).</li>\n  </ul>\n\n  <p><strong>Major Practical Applications:</strong></p>\n  <ol>\n    <li><strong>Forensic Criminology:</strong> Identifying suspects or victims in criminal investigations (homicides, rapes, burglaries) by matching DNA extracted from trace biological evidence (blood drops, semen stains, hair roots, saliva).</li>\n    <li><strong>Paternity and Maternity Dispute Resolution:</strong> Solving disputed lineage or custody cases, as an individual's VNTR bands are strictly inherited from biological parents (50% from mother, 50% from father).</li>\n    <li><strong>Immigration Verification:</strong> Scientifically verifying biological kinship claims for immigration authorities.</li>\n    <li><strong>Pedigree and Wildlife Conservation:</strong> Monitoring genetic diversity and parentage in captive breeding programmes of endangered species.</li>\n    <li><strong>Evolutionary and Anthropological Studies:</strong> Tracing prehistoric human migrations and population genetics.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of DNA fingerprinting (Alec Jeffreys) and basis in VNTR polymorphism</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Forensic criminology and crime-scene individual identification application</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Paternity dispute resolution and pedigree/biodiversity conservation applications</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch5-q14 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch5-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch5-q14')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Briefly describe the following:\n  <br>(a) Transcription\n  <br>(b) Polymorphism\n  <br>(c) Translation\n  <br>(d) Bioinformatics\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:14px;\">\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">(a) Transcription</h5>\n      <p style=\"margin:0;\">The enzymatic process of copying genetic information from the template strand of DNA into a complementary single-stranded RNA molecule (mRNA), catalyzed by <strong>DNA-dependent RNA polymerase</strong>. It proceeds in three distinct phases: <em>initiation</em> (at promoter via &sigma;-factor), <em>elongation</em>, and <em>termination</em> (via &rho;-factor). In eukaryotes, primary transcripts (hnRNA) undergo post-transcriptional processing: 5'-capping, 3'-polyadenylation (tailing), and splicing to remove introns.</p>\n    </div>\n\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">(b) Polymorphism (DNA Polymorphism)</h5>\n      <p style=\"margin:0;\">Heritable genetic variation occurring at a frequency greater than 0.01 (1%) in a human population. It arises due to mutations that accumulate over generations in non-coding DNA sequences. DNA polymorphism ranges from single nucleotide polymorphisms (SNPs) to variable numbers of tandem repeats (VNTRs), and forms the scientific foundation for genetic linkage mapping and DNA fingerprinting.</p>\n    </div>\n\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">(c) Translation</h5>\n      <p style=\"margin:0;\">The cellular process wherein the sequence of nucleotide triplets (codons) in mRNA is decoded to synthesize a specific sequence of amino acids in a polypeptide chain. It requires ribosomes, aminoacyl-tRNAs, GTP, and initiation/elongation factors, proceeding through amino acid activation, charging of tRNA, initiation at AUG codon, peptide chain elongation (peptidyl transferase), and termination at stop codons (UAA, UAG, UGA).</p>\n    </div>\n\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">(d) Bioinformatics</h5>\n      <p style=\"margin:0;\">An interdisciplinary branch of science that combines computer science, mathematics, statistics, and molecular biology to acquire, store, organise, analyse, and model biological data, especially massive macromolecular datasets generated by high-throughput DNA sequencing (e.g., Human Genome Project).</p>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Transcription: DNA to RNA copying catalyzed by RNA polymerase with initiation, elongation, termination</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Polymorphism: Heritable variation (>1% frequency) in non-coding DNA forming basis of DNA fingerprinting</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Translation: Decoding mRNA triplets into polypeptide chains at the ribosome</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Bioinformatics: Computational and statistical analysis of massive genomic and biological datasets</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"display:flex; justify-content:space-between; align-items:center; margin-top:36px; padding-top:20px; border-top:1px solid #e2e8f0;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(4)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 4</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(6)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#059669; color:white; font-weight:700; cursor:pointer;\">Next: Ch 6 (Evolution) →</button>\n  </div>\n</section>";
window.CHAPTER_DATA[6] = "<section class=\"chapter-section\" id=\"c12b-ch6\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#059669;\">6</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#059669;\">CBSE Class 12 Biology &bull; Chapter 6</div>\n      <h2>Evolution</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 10 Verbatim Questions with Official CBSE Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n<div class=\"chem-card\" style=\"margin-bottom:24px; padding:20px; background:#f0fdf4; border:1px solid #bbf7d0; border-radius:12px;\">\n  <h4 style=\"margin:0 0 12px 0; color:#059669; font-size:1.05rem;\">🧬 Evolutionary Biology: Adaptive Radiation, Natural Selection & Human Phylogeny</h4>\n  <svg viewBox=\"0 0 880 300\" style=\"width:100%; max-width:880px; height:auto; display:block; margin:0 auto; background:white; border-radius:8px; border:1px solid #d1fae5;\">\n    <!-- Darwin's Finches / Adaptive Radiation -->\n    <rect x=\"20\" y=\"20\" width=\"260\" height=\"260\" rx=\"10\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"150\" y=\"48\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Adaptive Radiation</text>\n    <line x1=\"35\" y1=\"58\" x2=\"265\" y2=\"58\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <circle cx=\"150\" cy=\"120\" r=\"32\" fill=\"#10b981\"/>\n    <text x=\"150\" y=\"118\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"white\" text-anchor=\"middle\">Common</text>\n    <text x=\"150\" y=\"130\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"white\" text-anchor=\"middle\">Ancestor</text>\n\n    <!-- Radiation arrows -->\n    <line x1=\"150\" y1=\"88\" x2=\"150\" y2=\"68\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <text x=\"150\" y=\"66\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#065f46\" text-anchor=\"middle\">Insectivorous Finch</text>\n\n    <line x1=\"178\" y1=\"105\" x2=\"225\" y2=\"90\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <text x=\"240\" y=\"88\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#065f46\" text-anchor=\"start\">Cactus Finch</text>\n\n    <line x1=\"178\" y1=\"135\" x2=\"225\" y2=\"150\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <text x=\"240\" y=\"155\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#065f46\" text-anchor=\"start\">Seed-eating Finch</text>\n\n    <line x1=\"122\" y1=\"135\" x2=\"70\" y2=\"150\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <text x=\"65\" y=\"155\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#065f46\" text-anchor=\"end\">Vegetarian Tree Finch</text>\n\n    <text x=\"35\" y=\"195\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#047857\">Key Examples:</text>\n    <text x=\"35\" y=\"213\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Darwin's Finches (Galapagos Is.)</text>\n    <text x=\"35\" y=\"231\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Australian Marsupials</text>\n    <text x=\"35\" y=\"249\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Convergent Evolution: Placental mammals</text>\n\n    <!-- Natural Selection Modes -->\n    <rect x=\"310\" y=\"20\" width=\"260\" height=\"260\" rx=\"10\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <text x=\"440\" y=\"48\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Modes of Natural Selection</text>\n    <line x1=\"325\" y1=\"58\" x2=\"555\" y2=\"58\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n\n    <!-- Curves -->\n    <g transform=\"translate(325, 70)\">\n      <path d=\"M 10 50 Q 40 5, 70 50\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2.5\"/>\n      <text x=\"40\" y=\"65\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#166534\" text-anchor=\"middle\">1. Stabilising</text>\n      <text x=\"40\" y=\"78\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#475569\" text-anchor=\"middle\">(Mean favoured)</text>\n\n      <path d=\"M 90 50 Q 135 10, 150 50\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"2.5\"/>\n      <text x=\"120\" y=\"65\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">2. Directional</text>\n      <text x=\"120\" y=\"78\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#475569\" text-anchor=\"middle\">(One extreme)</text>\n\n      <path d=\"M 170 45 Q 185 10, 195 40 Q 210 10, 225 45\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"2.5\"/>\n      <text x=\"200\" y=\"65\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">3. Disruptive</text>\n      <text x=\"200\" y=\"78\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#475569\" text-anchor=\"middle\">(Two extremes)</text>\n    </g>\n\n    <text x=\"325\" y=\"175\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#1e40af\">Hardy-Weinberg Principle:</text>\n    <text x=\"325\" y=\"195\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; p + q = 1 and p&sup2; + 2pq + q&sup2; = 1</text>\n    <text x=\"325\" y=\"213\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Factors disrupting equilibrium:</text>\n    <text x=\"335\" y=\"229\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#475569\">Gene flow, Genetic drift (Founder effect),</text>\n    <text x=\"335\" y=\"244\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#475569\">Mutation, Recombination & Selection</text>\n\n    <!-- Human Evolution Stages -->\n    <rect x=\"600\" y=\"20\" width=\"260\" height=\"260\" rx=\"10\" fill=\"#fef2f2\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n    <text x=\"730\" y=\"48\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">Chronology of Human Evolution</text>\n    <line x1=\"615\" y1=\"58\" x2=\"845\" y2=\"58\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n\n    <text x=\"615\" y=\"78\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\"><strong>15 mya:</strong> Dryopithecus & Ramapithecus</text>\n    <text x=\"615\" y=\"96\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\"><strong>3-4 mya:</strong> Australopithecines (walked upright)</text>\n    <text x=\"615\" y=\"114\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\"><strong>2 mya:</strong> <em>Homo habilis</em> (Tool maker)</text>\n    <text x=\"630\" y=\"130\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#047857\">&bull; Brain capacity: 650 - 800 cc (did not eat meat)</text>\n\n    <text x=\"615\" y=\"152\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\"><strong>1.5 mya:</strong> <em>Homo erectus</em> (Java Man)</text>\n    <text x=\"630\" y=\"168\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#047857\">&bull; Brain capacity: 900 cc (ate meat)</text>\n\n    <text x=\"615\" y=\"190\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\"><strong>100,000-40,000 ya:</strong> Neanderthal Man</text>\n    <text x=\"630\" y=\"206\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#047857\">&bull; Brain capacity: 1,400 cc (buried dead)</text>\n\n    <text x=\"615\" y=\"228\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\"><strong>75,000-10,000 ya:</strong> <em>Homo sapiens</em></text>\n    <text x=\"630\" y=\"244\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#047857\">&bull; Modern human (brain ~1,450 cc, agriculture)</text>\n  </svg>\n</div>\n\n  <div class=\"ex-div\" style=\"font-size:0.88rem; font-weight:700; color:#334155; margin-bottom:16px; padding:8px 14px; background:#ecfdf5; border-radius:8px; border-left:4px solid #059669;\">NCERT Exercises (10 Verbatim Questions)</div>\n\n  <div class=\"questions-container\">\n    \n  <!-- c12b-ch6-q1 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch6-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch6-q1')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Explain antibiotic resistance observed in bacteria in light of Darwinian selection theory.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>The emergence of antibiotic resistance in bacterial colonies is a classic modern demonstration of <strong>natural selection in action (anthropogenic selection)</strong>:</p>\n  <ol>\n    <li><strong>Pre-existing Genetic Variation:</strong> In any large bacterial population, spontaneous gene mutations occur at a low background frequency. A microscopic fraction of individual bacteria fortuitously possess pre-existing mutant alleles that confer resistance to a specific antibiotic (e.g., enzyme breaking down penicillin or altered cell-wall permeability).</li>\n    <li><strong>Environmental Selection Pressure:</strong> When the bacterial colony is exposed to an antibiotic, it creates a powerful selective environmental pressure.\n      <ul>\n        <li>Sensitive, non-resistant bacteria lack protective mutations and are killed off in large numbers.</li>\n        <li>The pre-existing resistant mutant bacteria survive the lethal antibiotic exposure.</li>\n      </ul>\n    </li>\n    <li><strong>Differential Reproduction (Survival of the Fittest):</strong> The surviving resistant individuals now have access to unhindered space and nutrients. They rapidly reproduce by binary fission and pass on the resistance genes to their progeny (and horizontally to other bacteria via R-plasmids).</li>\n    <li><strong>Population Shift:</strong> Over successive generations, the proportion of antibiotic-resistant bacteria increases exponentially until the entire bacterial population becomes resistant.</li>\n  </ol>\n  <p><strong>Conclusion:</strong> Antibiotic resistance did not evolve <em>de novo</em> in response to the drug (Lamarckian need); rather, natural selection simply selected pre-existing resistant variants that possessed greater fitness under the altered environmental condition.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Pre-existing genetic variation (spontaneous mutations before antibiotic exposure)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Application of antibiotic as a selective agent eliminating non-resistant bacteria</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Differential survival and reproduction of resistant mutants leading to population shift</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch6-q2 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch6-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch6-q2')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Find out from newspapers and popular science articles any new fossil discoveries or controversies about evolution.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Fossil discoveries and paleontological controversies continuously refine the tree of life:</p>\n  <ol>\n    <li><strong>Recent Landmark Fossil Discoveries:</strong>\n      <ul>\n        <li><strong><em>Homo naledi</em> (Rising Star Cave, South Africa):</strong> Primitive hominin fossils discovered by Lee Berger with a brain size resembling <em>Australopithecus</em> (450–550 cc) but exhibiting modern human-like wrist, hand, and foot bones, and evidence of intentional mortuary disposal of dead bodies.</li>\n        <li><strong>Denisovans (Denisova Cave, Siberia):</strong> High-resolution DNA extracted from a finger bone and teeth revealed a distinct archaic human sister group that interbred with both Neanderthals and ancestors of modern Melanesians and Indigenous Australians.</li>\n        <li><strong>Feathered Non-Avian Dinosaurs (Liaoning, China):</strong> Fossils such as <em>Microraptor gui</em> and <em>Anchiornis</em> possessing asymmetrical aerodynamic flight feathers, confirming the dinosaurian origin of birds.</li>\n      </ul>\n    </li>\n    <li><strong>Major Scientific Controversies in Evolutionary Biology:</strong>\n      <ul>\n        <li><strong>Gradualism vs Punctuated Equilibrium:</strong> Debate between Darwin's model of slow, uniform phyletic gradualism versus Stephen Jay Gould and Niles Eldredge's model of long periods of stasis interrupted by rapid bursts of speciation.</li>\n        <li><strong>Neanderthal-Modern Human Interbreeding:</strong> Whether archaic hominins were completely displaced (Out of Africa model) or underwent significant genetic admixture with migrating <em>Homo sapiens</em> (confirmed by genomic evidence: 1–2% Neanderthal DNA in non-African populations).</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Mention of significant recent hominin or vertebrate fossil discoveries (e.g., Homo naledi / Denisovans / feathered dinosaurs)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Discussion of prominent evolutionary debates (Punctuated Equilibrium vs Phyletic Gradualism or Neanderthal admixture)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch6-q3 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch6-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch6-q3')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Attempt giving a clear definition of the term species.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Biological Species Concept (Ernst Mayr, 1942):</strong></p>\n  <div style=\"background:#f0fdf4; padding:12px 16px; border:1px solid #86efac; border-radius:8px; margin:10px 0; font-size:1.02rem; color:#065f46;\">\n    A <strong>species</strong> is a group of naturally occurring, interbreeding or potentially interbreeding natural populations that are <strong>reproductively isolated</strong> from other such groups, share a common gene pool, and produce <strong>viable, fertile offspring</strong>.\n  </div>\n\n  <p><strong>Key Essential Criteria of a Biological Species:</strong></p>\n  <ol>\n    <li><strong>Interbreeding:</strong> Members within the group can freely mate and exchange genes under natural conditions.</li>\n    <li><strong>Production of Fertile Progeny:</strong> The offspring resulting from mating must be viable and capable of reproducing themselves (e.g., a cross between horse and donkey produces a sterile Mule; hence horse and donkey are distinct biological species).</li>\n    <li><strong>Reproductive Isolation:</strong> Intrinsic biological isolating mechanisms (pre-zygotic or post-zygotic barriers like behavioural, mechanical, seasonal, or genetic incompatibility) prevent gene flow between different species.</li>\n    <li><strong>Common Gene Pool & Evolutionary Ancestry:</strong> Members share common karyotypic and morphological homologies derived from a recent common ancestor.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Ernst Mayr biological species definition: naturally interbreeding populations producing fertile offspring</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Criteria of reproductive isolation and shared common gene pool</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch6-q4 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch6-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch6-q4')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Try to trace the various components of human evolution (hint: brain size and function, skeletal structure, dietary preference, etc.)\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Human evolution traces the anatomical and behavioural transition from arboreal primates to bipedal, tool-making, culturally sophisticated modern humans:</p>\n  \n  <table style=\"width:100%; border-collapse:collapse; margin-top:10px; font-size:0.88rem;\">\n    <thead>\n      <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n        <th style=\"padding:6px 10px; color:#065f46;\">Stage & Geological Age</th>\n        <th style=\"padding:6px 10px; color:#065f46;\">Cranial Capacity (Brain Size)</th>\n        <th style=\"padding:6px 10px; color:#065f46;\">Skeletal & Locomotor Structure</th>\n        <th style=\"padding:6px 10px; color:#065f46;\">Dietary Habits & Key Traits</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\"><strong>1. Dryopithecus & Ramapithecus</strong><br>(~15 mya)</td>\n        <td style=\"padding:6px 10px;\">Ape-sized small brain (~350–400 cc)</td>\n        <td style=\"padding:6px 10px;\">Hairy, walked like gorillas/chimpanzees; Ramapithecus was more man-like with semi-erect posture.</td>\n        <td style=\"padding:6px 10px;\">Herbivorous, ate nuts, leaves, and tough vegetation.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\"><strong>2. Australopithecines</strong><br>(~3–4 mya, East Africa)</td>\n        <td style=\"padding:6px 10px;\">~450–500 cc</td>\n        <td style=\"padding:6px 10px;\">Full bipedal locomotion, erect posture, lumbar curve, height &lt; 4 feet.</td>\n        <td style=\"padding:6px 10px;\">Essentially ate fruits, hunted with stone weapons.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\"><strong>3. <em>Homo habilis</em></strong><br>(Handy Man, ~2 mya)</td>\n        <td style=\"padding:6px 10px;\"><strong>650–800 cc</strong></td>\n        <td style=\"padding:6px 10px;\">First human-like hominid; opposable thumb adapted for making stone tools.</td>\n        <td style=\"padding:6px 10px;\">Did <strong>not</strong> eat meat (largely vegetarian).</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\"><strong>4. <em>Homo erectus</em></strong><br>(Java Man, ~1.5 mya)</td>\n        <td style=\"padding:6px 10px;\"><strong>~900 cc</strong></td>\n        <td style=\"padding:6px 10px;\">Fully upright posture, robust skeleton, prominent supraorbital brow ridges.</td>\n        <td style=\"padding:6px 10px;\">Probably <strong>ate meat</strong>; first to harness and use fire for warmth and cooking.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\"><strong>5. Neanderthal Man</strong><br>(100,000–40,000 ya)</td>\n        <td style=\"padding:6px 10px;\"><strong>~1,400 cc</strong></td>\n        <td style=\"padding:6px 10px;\">Short, muscular, heavily built body adapted for harsh Ice Age cold.</td>\n        <td style=\"padding:6px 10px;\">Carnivorous hunters; used animal hides to protect bodies and <strong>buried their dead</strong> with rituals.</td>\n      </tr>\n      <tr style=\"background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\"><strong>6. <em>Homo sapiens</em></strong><br>(Modern Man, 75,000–10,000 ya)</td>\n        <td style=\"padding:6px 10px;\"><strong>~1,350–1,500 cc</strong></td>\n        <td style=\"padding:6px 10px;\">High forehead, distinct chin, reduced jaw, slender gracile skeleton.</td>\n        <td style=\"padding:6px 10px;\">Omnivorous; developed prehistoric cave art (18,000 ya), agriculture, and settled civilizations (10,000 ya).</td>\n      </tr>\n    </tbody>\n  </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Tracing chronological stages: Australopithecus, Homo habilis, Homo erectus, Neanderthal, Homo sapiens</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Brain size progression (450 -> 650-800 -> 900 -> 1400 -> 1450 cc)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Skeletal modifications (bipedalism, upright posture, precision grip)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Dietary transitions (fruit eating -> meat eating) and cultural advances (fire, tools, burial, cave art)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch6-q5 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch6-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch6-q5')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Find out through internet and popular science articles whether animals other than man have self-consciousness.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Self-consciousness</strong> is the cognitive capacity of an organism to recognise itself as an individual separate from the environment and other individuals.</p>\n  <ol>\n    <li><strong>The Mirror Self-Recognition (MSR) Test:</strong>\n      <ul>\n        <li>Devised by Gordon Gallup Jr. in 1970. An odourless dye or mark is placed on a part of the animal's body that it can only see when looking in a mirror.</li>\n        <li>If the animal touches or investigates the mark on its own body (rather than attacking the mirror image as a conspecific intruder), it demonstrates mirror self-recognition and bodily self-awareness.</li>\n      </ul>\n    </li>\n    <li><strong>Animals Demonstrating Self-Consciousness:</strong>\n      <ul>\n        <li><strong>Great Apes:</strong> Chimpanzees, Bonobos, and Orangutans consistently pass the mirror test and demonstrate self-directed grooming.</li>\n        <li><strong>Cetaceans (Marine Mammals):</strong> Bottlenose Dolphins and Killer Whales (Orcas) inspect marks on their bodies in underwater mirrors and possess complex social pods and vocal dialects.</li>\n        <li><strong>Asian Elephants:</strong> Exhibit self-recognition in giant mirrors, show empathy, grieve their dead, and display metacognition.</li>\n        <li><strong>Corvids (Birds):</strong> Eurasian Magpies are the only non-mammals verified to pass the mirror self-recognition test.</li>\n      </ul>\n    </li>\n  </ol>\n  <p><strong>Conclusion:</strong> While humans possess the most sophisticated, symbolic, and metacognitive self-consciousness, rudimentary to advanced self-consciousness is scientifically proven in several non-human mammals and birds.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of self-consciousness and explanation of Mirror Self-Recognition (MSR) test</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing proven animal examples: Chimpanzees, Dolphins, Elephants, and Eurasian Magpies</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch6-q6 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch6-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch6-q6')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        List 10 modern-day animals and using the internet resources link it to a corresponding ancient fossil. Name both.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>The genealogical relationship between modern animals and their ancient fossil ancestors provides conclusive palaeontological proof of common descent:</p>\n  \n  <table style=\"width:100%; border-collapse:collapse; margin-top:10px; font-size:0.88rem;\">\n    <thead>\n      <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n        <th style=\"padding:6px 10px; color:#065f46;\">#</th>\n        <th style=\"padding:6px 10px; color:#065f46;\">Modern-Day Animal</th>\n        <th style=\"padding:6px 10px; color:#065f46;\">Ancient Fossil Ancestor</th>\n        <th style=\"padding:6px 10px; color:#065f46;\">Key Evolutionary Transition Feature</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\">1</td>\n        <td style=\"padding:6px 10px;\"><strong>Horse</strong> (<em>Equus</em>)</td>\n        <td style=\"padding:6px 10px;\"><em>Eohippus</em> (Hyracotherium)</td>\n        <td style=\"padding:6px 10px;\">Fox-sized, 4 toes on forelimb &rarr; single central hooved digit in modern horse.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\">2</td>\n        <td style=\"padding:6px 10px;\"><strong>Birds</strong> (Aves)</td>\n        <td style=\"padding:6px 10px;\"><em>Archaeopteryx lithographica</em></td>\n        <td style=\"padding:6px 10px;\">Connecting link between reptiles and birds (toothed beak, clawed wings, feathered tail).</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\">3</td>\n        <td style=\"padding:6px 10px;\"><strong>Whale</strong> (Cetacea)</td>\n        <td style=\"padding:6px 10px;\"><em>Pakicetus</em> / <em>Basilosaurus</em></td>\n        <td style=\"padding:6px 10px;\">Four-legged terrestrial artiodactyl &rarr; fully aquatic streamlined whale with vestigial pelvic bones.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\">4</td>\n        <td style=\"padding:6px 10px;\"><strong>Elephant</strong> (<em>Elephas</em>)</td>\n        <td style=\"padding:6px 10px;\"><em>Moeritherium</em> / <em>Mammuthus</em></td>\n        <td style=\"padding:6px 10px;\">Tapir-like animal &rarr; elongated proboscis (trunk) and enlarged second upper incisors (tusks).</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\">5</td>\n        <td style=\"padding:6px 10px;\"><strong>Modern Man</strong> (<em>Homo sapiens</em>)</td>\n        <td style=\"padding:6px 10px;\"><em>Australopithecus afarensis</em> (\"Lucy\")</td>\n        <td style=\"padding:6px 10px;\">Arboreal climber &rarr; upright obligate biped with expanding brain case.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\">6</td>\n        <td style=\"padding:6px 10px;\"><strong>Camel</strong> (<em>Camelus</em>)</td>\n        <td style=\"padding:6px 10px;\"><em>Protylopus</em></td>\n        <td style=\"padding:6px 10px;\">Rabbit-sized Eocene desert dweller with un-fused foot bones.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\">7</td>\n        <td style=\"padding:6px 10px;\"><strong>Amphibians</strong> (Frogs/Salamanders)</td>\n        <td style=\"padding:6px 10px;\"><em>Ichthyostega</em> / <em>Tiktaalik</em></td>\n        <td style=\"padding:6px 10px;\">Transition between lobe-finned fish (Sarcopterygii) and earliest 4-limbed tetrapods.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\">8</td>\n        <td style=\"padding:6px 10px;\"><strong>Mammals</strong></td>\n        <td style=\"padding:6px 10px;\"><em>Morganucodon</em> / Therapsids</td>\n        <td style=\"padding:6px 10px;\">Synapsid mammal-like reptiles evolving hair, heterodont dentition, and middle ear ossicles.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\">9</td>\n        <td style=\"padding:6px 10px;\"><strong>Giraffe</strong> (<em>Giraffa</em>)</td>\n        <td style=\"padding:6px 10px;\"><em>Sivatherium</em> / <em>Samotherium</em></td>\n        <td style=\"padding:6px 10px;\">Short-necked deer-like ungulate evolving elongated cervical vertebrae.</td>\n      </tr>\n      <tr style=\"background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\">10</td>\n        <td style=\"padding:6px 10px;\"><strong>Turtle</strong> (Testudines)</td>\n        <td style=\"padding:6px 10px;\"><em>Odontochelys</em> / <em>Proganochelys</em></td>\n        <td style=\"padding:6px 10px;\">Ancient toothed reptile with plastron (belly shell) before the evolution of the full dorsal carapace.</td>\n      </tr>\n    </tbody>\n  </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurately pairing modern animals with ancient fossil ancestors (Horse-Eohippus, Birds-Archaeopteryx, Whale-Pakicetus, etc.)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Describing key morphological transition traits for the lineage pairs</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch6-q7 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch6-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch6-q7')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Practise drawing various animals and plants.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>CBSE Pedagogical Guidelines for Biological Drawings:</strong></p>\n  <p>Morphological and anatomical drawings in evolutionary biology provide visual comprehension of homologous structures, analogous adaptations, and vestigial remnants.</p>\n  <ul>\n    <li><strong>Homologous Anatomical Structures:</strong>\n      <ul>\n        <li><strong>Forelimb bones of Mammals:</strong> Draw the comparative skeletal framework of Man, Cheetah, Whale (flipper), and Bat (wing) highlighting the common structural pattern of <em>Humerus, Radius, Ulna, Carpals, Metacarpals, and Phalanges</em>, illustrating <strong>divergent evolution</strong>.</li>\n        <li><strong>Plant Homologies:</strong> Bougainvillea thorns (stem adaptation) and Cucurbita tendrils (stem adaptation) arising from the axillary bud position.</li>\n      </ul>\n    </li>\n    <li><strong>Analogous Structures:</strong>\n      <ul>\n        <li>Wings of butterfly (membranous fold of chitin with no skeleton) and wings of bird (feathers supported by bony limb bones), illustrating <strong>convergent evolution</strong>.</li>\n        <li>Eye of octopus and eye of mammal; flippers of penguins and flippers of dolphins; sweet potato (root tuber) and potato (stem tuber).</li>\n      </ul>\n    </li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Homologous structures (mammalian forelimbs / Bougainvillea thorn & Cucurbita tendril)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Analogous structures (wings of insect & bird / eye of octopus & mammal)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch6-q8 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch6-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch6-q8')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Describe one example of adaptive radiation.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition:</strong></p>\n  <p><strong>Adaptive radiation</strong> is the evolutionary process in which an ancestral stock radiates outward from a common point of origin into different geographical niches or habitats, diversifying into multiple morphologically distinct species adapted to specific ecological roles.</p>\n\n  <p><strong>Classic Example: Darwin's Finches of the Galapagos Islands:</strong></p>\n  <ol>\n    <li>Charles Darwin observed an extraordinary variety of small black birds on the isolated Galapagos archipelago.</li>\n    <li><strong>Common Origin:</strong> All the diverse finch species evolved on the island itself from an original seed-eating ancestral bird that had drifted from the South American mainland.</li>\n    <li><strong>Radiative Specialisation:</strong> In the absence of mainland competitors, the birds radiated into diverse ecological niches on different islands:\n      <ul>\n        <li><strong>Vegetarian tree finches:</strong> Developed short, stout parrot-like beaks for consuming buds and leaves.</li>\n        <li><strong>Insectivorous tree finches:</strong> Developed sharp, curved grasping beaks for plucking insects from bark crevices.</li>\n        <li><strong>Woodpecker finches:</strong> Learned to hold cactus spines in their beaks to probe tree holes for grubs (tool use).</li>\n        <li><strong>Cactus ground finches:</strong> Developed long, decurved beaks for opening cactus flowers and fruits.</li>\n        <li><strong>Large, medium, and small ground finches:</strong> Developed heavily crushed crushing beaks of various sizes specialised for cracking tough seeds.</li>\n      </ul>\n    </li>\n    <li><strong>Conclusion:</strong> From one original seed-eating ancestor, natural selection favoured diverse beak adaptations matching different feeding niches, exemplifying <em>adaptive radiation</em>.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Precise definition of adaptive radiation (evolution of different species starting from a point and radiating to other habitats)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Detailed example: Darwin's Finches in Galapagos archipelago with common seed-eating ancestor</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Morphological differentiation in beaks matching distinct ecological/feeding niches (insectivorous, cactus, seed-eating)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch6-q9 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch6-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch6-q9')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Can we call human evolution as adaptive radiation?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>No, human evolution is NOT considered a typical example of adaptive radiation.</strong></p>\n  <p><strong>Scientific Justification:</strong></p>\n  <ol>\n    <li><strong>Definition of Adaptive Radiation:</strong> Adaptive radiation requires a single ancestral lineage to diverge and split simultaneously into multiple diverse, coexisting species that radiate outward into different ecological habitats and dietary niches (e.g., Darwin's finches or Australian marsupials).</li>\n    <li><strong>Human Evolution is Primarily Anagenesis (Linear Chronological Progression):</strong>\n      <ul>\n        <li>The evolutionary trajectory from <em>Ramapithecus &rarr; Australopithecus &rarr; Homo habilis &rarr; Homo erectus &rarr; Homo sapiens</em> is largely anagenetic (chronological progressive succession of successive hominid species over time), with one species replacing another rather than radiating into multiple distinct ecological niches.</li>\n      </ul>\n    </li>\n    <li><strong>Single Extant Species:</strong> Today, there is only <strong>one single extant human species</strong> across the entire planet: <em>Homo sapiens</em>. Humans did not undergo morphological diversification into separate species to occupy diverse habitats; instead, humans adapted through <strong>cultural, technological, and intellectual tools</strong> (fire, clothing, shelter, agriculture).</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear negative answer (No, not an example of adaptive radiation)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Contrast between adaptive radiation (branching into many co-existing ecological species) vs human evolution (linear anagenesis/succession)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Only one extant species (Homo sapiens) adapted culturally and technologically across all habitats</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch6-q10 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch6-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch6-q10')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Using various resources such as your school Library or the internet and discussions with your teacher, trace the evolutionary stages of any one animal say horse.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>The evolutionary pedigree of the horse (family <strong>Equidae</strong>) represents one of the most complete and extensively documented fossil records in vertebrate palaeontology, spanning roughly 55 million years across the Cenozoic era:</p>\n\n  <table style=\"width:100%; border-collapse:collapse; margin-top:10px; font-size:0.88rem;\">\n    <thead>\n      <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n        <th style=\"padding:6px 10px; color:#065f46;\">Stage / Genus</th>\n        <th style=\"padding:6px 10px; color:#065f46;\">Geological Epoch</th>\n        <th style=\"padding:6px 10px; color:#065f46;\">Body Height</th>\n        <th style=\"padding:6px 10px; color:#065f46;\">Digit (Foot) Morphology & Dentition</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\"><strong>1. <em>Eohippus</em></strong><br>(Hyracotherium / Dawn Horse)</td>\n        <td style=\"padding:6px 10px;\">Eocene (~55 mya)</td>\n        <td style=\"padding:6px 10px;\">~30 cm (size of fox/hare)</td>\n        <td style=\"padding:6px 10px;\">Forelimbs with <strong>4 functional digits</strong>, hindlimbs with 3 digits. Low-crowned (brachydont) teeth for browsing soft leaves.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\"><strong>2. <em>Mesohippus</em></strong><br>(Intermediate Horse)</td>\n        <td style=\"padding:6px 10px;\">Oligocene (~35 mya)</td>\n        <td style=\"padding:6px 10px;\">~60 cm (size of sheep)</td>\n        <td style=\"padding:6px 10px;\">3 digits on both fore and hind feet; middle digit (digit III) enlarged bearing most body weight.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\"><strong>3. <em>Merychippus</em></strong><br>(Ruminating Horse)</td>\n        <td style=\"padding:6px 10px;\">Miocene (~20 mya)</td>\n        <td style=\"padding:6px 10px;\">~100 cm</td>\n        <td style=\"padding:6px 10px;\">3 digits on all feet, but side digits reduced to non-touching splints; middle toe bears entire body weight. High-crowned (hypsodont) teeth with cement for grazing silica-rich grass.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\"><strong>4. <em>Pliohippus</em></strong><br>(First One-Toed Horse)</td>\n        <td style=\"padding:6px 10px;\">Pliocene (~5 mya)</td>\n        <td style=\"padding:6px 10px;\">~120 cm</td>\n        <td style=\"padding:6px 10px;\"><strong>Monodactyl:</strong> Single central toe (digit III) terminating in a hoof; lateral digits reduced to inner splint bones. Fast runner.</td>\n      </tr>\n      <tr style=\"background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\"><strong>5. <em>Equus</em></strong><br>(Modern Horse)</td>\n        <td style=\"padding:6px 10px;\">Pleistocene to Present</td>\n        <td style=\"padding:6px 10px;\">~150–160 cm</td>\n        <td style=\"padding:6px 10px;\">Single large hooved toe on each foot adapted for galloping on open grasslands. Complex folded enamel ridges on molars for grinding abrasive grasses.</td>\n      </tr>\n    </tbody>\n  </table>\n\n  <p><strong>Summary of Major Evolutionary Trends in Horse Evolution:</strong></p>\n  <ol>\n    <li>Steady progressive increase in overall body size and limb length.</li>\n    <li>Reduction in digit number from 4/3 to a single functional hooved digit (monodactyly).</li>\n    <li>Elongation of head, neck, and cannon bones.</li>\n    <li>Shift from browsing low-crowned teeth to grazing high-crowned (hypsodont) teeth with complex enamel folding.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Listing 5 chronological stages: Eohippus -> Mesohippus -> Merychippus -> Pliohippus -> Equus</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Morphological shifts in digits (reduction from 4/3 toes to single central hooved digit)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Dental transition (brachydont browsing teeth to hypsodont grazing teeth) and size increase</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"display:flex; justify-content:space-between; align-items:center; margin-top:36px; padding-top:20px; border-top:1px solid #e2e8f0;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(5)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 5</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(7)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#059669; color:white; font-weight:700; cursor:pointer;\">Next: Ch 7 (Human Health and Disease) →</button>\n  </div>\n</section>";
window.CHAPTER_DATA[7] = "<section class=\"chapter-section\" id=\"c12b-ch7\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#059669;\">7</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#059669;\">CBSE Class 12 Biology &bull; Chapter 7</div>\n      <h2>Human Health and Disease</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 17 Verbatim Questions with Official CBSE Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n<div class=\"chem-card\" style=\"margin-bottom:24px; padding:20px; background:#f0fdf4; border:1px solid #bbf7d0; border-radius:12px;\">\n  <h4 style=\"margin:0 0 12px 0; color:#059669; font-size:1.05rem;\">🧬 Immunology & Oncology Map: Antibody Architecture, HIV Pathogenesis & Cell Transformation</h4>\n  <svg viewBox=\"0 0 880 300\" style=\"width:100%; max-width:880px; height:auto; display:block; margin:0 auto; background:white; border-radius:8px; border:1px solid #d1fae5;\">\n    <!-- Antibody Structure (H2L2) -->\n    <rect x=\"20\" y=\"20\" width=\"270\" height=\"260\" rx=\"10\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"155\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Antibody Molecule (H2L2)</text>\n    <line x1=\"35\" y1=\"56\" x2=\"275\" y2=\"56\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n\n    <!-- Y-shape diagram -->\n    <!-- Heavy Chains (green) -->\n    <path d=\"M 140 230 L 140 140 L 95 80\" fill=\"none\" stroke=\"#059669\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n    <path d=\"M 170 230 L 170 140 L 215 80\" fill=\"none\" stroke=\"#059669\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n    <!-- Light Chains (blue) -->\n    <path d=\"M 75 140 L 75 80\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n    <path d=\"M 235 140 L 235 80\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n\n    <!-- Disulfide bonds (red lines) -->\n    <line x1=\"140\" y1=\"160\" x2=\"170\" y2=\"160\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n    <line x1=\"140\" y1=\"175\" x2=\"170\" y2=\"175\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n    <line x1=\"110\" y1=\"100\" x2=\"80\" y2=\"100\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n    <line x1=\"200\" y1=\"100\" x2=\"230\" y2=\"100\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n\n    <!-- Labels -->\n    <text x=\"85\" y=\"70\" font-family=\"sans-serif\" font-size=\"9\" font-weight=\"bold\" fill=\"#dc2626\" text-anchor=\"middle\">Antigen-binding site</text>\n    <text x=\"225\" y=\"70\" font-family=\"sans-serif\" font-size=\"9\" font-weight=\"bold\" fill=\"#dc2626\" text-anchor=\"middle\">Antigen-binding site</text>\n    <text x=\"155\" y=\"250\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#047857\" text-anchor=\"middle\">Constant Region (Fc)</text>\n    <text x=\"40\" y=\"268\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">2 Heavy (H) + 2 Light (L) Chains</text>\n\n    <!-- Retrovirus / HIV Life Cycle -->\n    <rect x=\"310\" y=\"20\" width=\"270\" height=\"260\" rx=\"10\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <text x=\"445\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">HIV Pathogenesis in Helper T Cells</text>\n    <line x1=\"325\" y1=\"56\" x2=\"565\" y2=\"56\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n\n    <circle cx=\"360\" cy=\"85\" r=\"18\" fill=\"#fecaca\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n    <text x=\"360\" y=\"89\" font-family=\"sans-serif\" font-size=\"9\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">HIV</text>\n    <line x1=\"378\" y1=\"85\" x2=\"415\" y2=\"85\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n    <text x=\"430\" y=\"88\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#1e40af\">Attaches to CD4 receptor</text>\n\n    <text x=\"325\" y=\"125\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">1. Viral RNA enters host macrophage/T<sub>H</sub> cell</text>\n    <text x=\"325\" y=\"145\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">2. <strong>Reverse Transcriptase:</strong> Viral RNA &rarr; DNA</text>\n    <text x=\"325\" y=\"165\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">3. <strong>Integrase:</strong> Viral DNA integrates in host genome</text>\n    <text x=\"325\" y=\"185\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">4. Host produces new viral particles (HIV Factory)</text>\n    <text x=\"325\" y=\"205\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#dc2626\">5. Lysis of <strong>T<sub>H</sub> (CD4<sup>+</sup>) lymphocytes</strong></text>\n    <text x=\"325\" y=\"225\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">6. Progressive collapse of Cell-Mediated Immunity</text>\n    <text x=\"325\" y=\"250\" font-family=\"sans-serif\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#991b1b\">ELISA (Screening) &bull; Western Blot (Confirm)</text>\n\n    <!-- Normal vs Cancerous Cells -->\n    <rect x=\"600\" y=\"20\" width=\"260\" height=\"260\" rx=\"10\" fill=\"#fef2f2\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n    <text x=\"730\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">Cancer Biology & Immunity</text>\n    <line x1=\"615\" y1=\"56\" x2=\"845\" y2=\"56\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n\n    <text x=\"615\" y=\"78\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#b91c1c\">Hallmarks of Cancer Cells:</text>\n    <text x=\"615\" y=\"96\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Loss of <strong>Contact Inhibition</strong></text>\n    <text x=\"615\" y=\"114\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Uncontrolled mitotic proliferation (Tumour)</text>\n    <text x=\"615\" y=\"132\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; <strong>Metastasis:</strong> Malignant cells invade distant</text>\n    <text x=\"625\" y=\"148\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#475569\">sites via blood and lymphatics</text>\n    \n    <text x=\"615\" y=\"172\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#b91c1c\">Immune System Divisions:</text>\n    <text x=\"615\" y=\"190\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; <strong>Innate:</strong> Physical, physiological, cellular,</text>\n    <text x=\"625\" y=\"206\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#475569\">and cytokine barriers (Interferons)</text>\n    <text x=\"615\" y=\"224\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; <strong>Acquired:</strong> Humoral (B-cells/Antibodies)</text>\n    <text x=\"625\" y=\"240\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#475569\">and Cell-Mediated (T-cells &bull; Graft rejection)</text>\n    <text x=\"615\" y=\"260\" font-family=\"sans-serif\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#047857\">Primary: Bone Marrow & Thymus</text>\n  </svg>\n</div>\n\n  <div class=\"ex-div\" style=\"font-size:0.88rem; font-weight:700; color:#334155; margin-bottom:16px; padding:8px 14px; background:#ecfdf5; border-radius:8px; border-left:4px solid #059669;\">NCERT Exercises (17 Verbatim Questions)</div>\n\n  <div class=\"questions-container\">\n    \n  <!-- c12b-ch7-q1 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q1')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What are the various public health measures, which you would suggest as safeguard against infectious diseases?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Public health measures are preventative interventions aimed at breaking transmission vectors, eradicating reservoirs, and providing population-wide immunity:</p>\n  <ol>\n    <li><strong>Maintenance of Personal & Public Hygiene:</strong>\n      <ul>\n        <li>Keeping the physical body clean, bathing daily, and consuming clean drinking water, uncontaminated food, fruits, and vegetables.</li>\n        <li>Proper sanitary disposal of human excreta, domestic sewage, and chemical wastes; regular cleaning and periodic disinfection of municipal water storage reservoirs, overhead tanks, and swimming pools.</li>\n      </ul>\n    </li>\n    <li><strong>Control and Elimination of Disease Vectors:</strong>\n      <ul>\n        <li>Preventing stagnancy of water in residential drains, coolers, tires, and pots to eliminate breeding of mosquito vectors (<em>Anopheles, Culex, Aedes</em>).</li>\n        <li>Introducing larvivorous fish like <strong><em>Gambusia</em></strong> in ornamental ponds and water bodies to devour mosquito larvae biologically.</li>\n        <li>Spraying insecticides like DDT/malathion in drainage swamps, spraying oil film over ditches, and using wire mesh/screens on doors and windows.</li>\n      </ul>\n    </li>\n    <li><strong>Universal Immunisation & Vaccination Programmes:</strong> Mass inoculation campaigns using childhood vaccines (e.g., BCG, Polio drops, DPT, MMR, Hepatitis-B) to build herd immunity.</li>\n    <li><strong>Quarantine and Isolation:</strong> Prompt clinical isolation of infected individuals suffering from highly contagious airborne or contact diseases (e.g., Pneumonia, Tuberculosis, Chickenpox) to prevent community outbreaks.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Personal and public hygiene measures (clean drinking water, proper sewage/excreta disposal)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Vector control methods (eradicating stagnant water, Gambusia fish, mosquito netting, insecticide sprays)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Universal vaccination programmes and quarantine/isolation protocols for contagious infections</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q2 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q2')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        In which way has the study of biology helped us to control infectious diseases?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>The advancements in modern biological disciplines (microbiology, immunology, pathology, biochemistry, and recombinant DNA technology) have revolutionized our capability to manage, control, and eradicate infectious diseases:</p>\n  <ol>\n    <li><strong>Discovery of Microbial Etiology & Life Cycles:</strong> Identifying causative pathogens (bacteria, viruses, protozoans, fungi, helminths) and elucidating their vectors and life cycles allowed the formulation of targeted prophylactic measures (e.g., breaking the vector cycle of the malaria parasite).</li>\n    <li><strong>Immunology & Vaccine Development:</strong> Understanding the principles of humoral and cell-mediated immunological memory enabled the development of life-saving vaccines. This resulted in the total global eradication of <strong>Smallpox</strong> and near-complete elimination of <strong>Polio, Tetanus, and Diphtheria</strong>.</li>\n    <li><strong>Discovery of Antibiotics & Antimicrobial Drugs:</strong> Fleming's discovery of Penicillin and subsequent discovery of wide-spectrum antibiotics, antifungals, and synthetic antimalarials (chloroquine, artemisinin) transformed formerly fatal bacterial infections into easily treatable conditions.</li>\n    <li><strong>Recombinant DNA Technology:</strong> Genetic engineering enabled the scalable, ultra-pure production of safe vaccines (e.g., Recombinant Hepatitis-B vaccine produced from transgenic yeast <em>Saccharomyces cerevisiae</em>).</li>\n    <li><strong>Advanced Molecular Diagnostics:</strong> Techniques like <strong>ELISA</strong> and <strong>PCR (Polymerase Chain Reaction)</strong> allow early, ultra-sensitive detection of pathogens (e.g., HIV, Hepatitis) even before overt clinical symptoms appear.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Elucidation of pathogen life cycles, vectors, and transmission dynamics</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Development of vaccines enabling eradication of smallpox and control of polio/diphtheria</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Discovery and manufacture of antibiotics and therapeutic drugs</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Recombinant DNA biotechnology (yeast-derived Hep-B vaccine) and molecular diagnostics (ELISA/PCR)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q3 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q3')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        How does the transmission of each of the following diseases take place?\n  <br>(a) Amoebiasis\n  <br>(b) Malaria\n  <br>(c) Ascariasis\n  <br>(d) Pneumonia\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:12px;\">\n    <div style=\"background:#f8fafc; padding:10px 14px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(a) Amoebiasis (Amoebic Dysentery):</strong><br>\n      Caused by the protozoan parasite <em>Entamoeba histolytica</em>. Transmitted via the <strong>faecal-oral route</strong>. Houseflies (<em>Musca domestica</em>) act as mechanical carriers, transferring mature tetranucleate cysts from the faeces of infected individuals to drinking water and food items, which are subsequently ingested.\n    </div>\n    <div style=\"background:#f8fafc; padding:10px 14px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(b) Malaria:</strong><br>\n      Caused by protozoans of the genus <em>Plasmodium</em> (<em>P. vivax, P. malariae, P. falciparum</em>). Transmitted biologically through the bite of an infected <strong>female <em>Anopheles</em> mosquito</strong>, which injects infectious motile <strong>sporozoites</strong> along with its salivary secretions into the human bloodstream during a blood meal.\n    </div>\n    <div style=\"background:#f8fafc; padding:10px 14px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(c) Ascariasis:</strong><br>\n      Caused by the common intestinal roundworm endoparasite <em>Ascaris lumbricoides</em>. The microscopic embryonated eggs of the parasite are excreted in the faeces of infected persons, contaminating soil, groundwater, and growing vegetables/fruits. A healthy person acquires infection through ingestion of <strong>contaminated water, unwashed vegetables, or unhygienic dirty fingers</strong>.\n    </div>\n    <div style=\"background:#f8fafc; padding:10px 14px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(d) Pneumonia:</strong><br>\n      Caused by bacteria such as <em>Streptococcus pneumoniae</em> and <em>Haemophilus influenzae</em>. Transmitted via <strong>airborne droplet / aerosol inhalation</strong> released by an infected person during coughing or sneezing, or through indirect contact by sharing contaminated utensils, glasses, or handkerchiefs.\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Amoebiasis: Faecal-oral route via houseflies (mechanical carriers) contaminating food/water with cysts</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Malaria: Bite of infected female Anopheles mosquito injecting sporozoites</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Ascariasis: Ingestion of water/fruits/vegetables contaminated with excreted eggs of Ascaris</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Pneumonia: Inhaling droplets/aerosols released by infected person or sharing utensils</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q4 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q4')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What measure would you take to prevent water-borne diseases?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Water-borne diseases (e.g., Cholera, Typhoid, Amoebiasis, Hepatitis-A, and Ascariasis) can be comprehensively prevented through the following sanitary interventions:</p>\n  <ol>\n    <li><strong>Safe and Potable Drinking Water Supply:</strong> Ensuring that drinking water is sourced from clean, protected aquifers, subjected to municipal coagulation, sand filtration, and chemical <strong>chlorination / ozonation</strong> to destroy enteric pathogens.</li>\n    <li><strong>Household Water Treatment:</strong> <strong>Boiling drinking water</strong> vigorously for 10–15 minutes (which kills heat-sensitive vegetative bacteria, amoebic cysts, and viruses) or using certified domestic ultraviolet (UV) and Reverse Osmosis (RO) water purifiers.</li>\n    <li><strong>Proper Sewage & Faecal Disposal:</strong> Eliminating open defecation through the construction of hygienic sanitary latrines, septic tanks, and modern underground municipal sewage treatment plants (STPs) to prevent subterranean sewage leakage into drinking water mains.</li>\n    <li><strong>Periodic Disinfection of Reservoirs:</strong> Regular de-silting, cleaning, and chemical disinfection of overhead municipal tanks, wells, and domestic storage cisterns using potassium permanganate or bleaching powder.</li>\n    <li><strong>Food Hygiene and Fly Control:</strong> Keeping cooked food and drinking water covered at all times to prevent mechanical contamination by common filth flies.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Safe potable water supply through municipal chlorination, boiling, or UV/RO filtration</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Elimination of open defecation and preventing sewage contamination of drinking pipelines</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Regular chemical disinfection of water reservoirs/wells and covering food items from flies</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q5 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q5')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Discuss with your teacher what does 'a suitable gene' means, in the context of DNA vaccines.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>In the context of modern third-generation <strong>DNA vaccines (genetic vaccines)</strong>, the term <strong>\"a suitable gene\"</strong> refers to a specific, carefully characterized, and engineered segment of DNA (cloned into an expression plasmid) that satisfies the following criteria:</p>\n  <ol>\n    <li><strong>Codes for a Dominant Immunogenic Antigen:</strong> It contains the exact coding nucleotide sequence that directs host cells to synthesize a major outer surface protein or antigenic capsid peptide of the target pathogen (e.g., the gene encoding the Spike glycoprotein of SARS-CoV-2 or the envelope surface antigen HBsAg of Hepatitis-B virus).</li>\n    <li><strong>Elicits Protective Immune Response:</strong> When expressed inside the host cell, the translated antigenic protein is processed and presented on the cell surface via MHC Class I and MHC Class II molecules, stimulating both:\n      <ul>\n        <li><strong>Humoral Immunity:</strong> Triggering B-lymphocytes to produce neutralising antibodies.</li>\n        <li><strong>Cell-Mediated Immunity (CMI):</strong> Activating Cytotoxic CD8<sup>+</sup> T cells and Memory T cells.</li>\n      </ul>\n    </li>\n    <li><strong>Completely Non-Pathogenic & Safe:</strong> The gene chosen must strictly code for an immunogenic structural subunit and <strong>must NOT code for any virulent toxin, pathogenic replication enzyme, or oncogenic factor</strong>. Thus, the vaccine cannot cause actual disease or revert to virulence.</li>\n    <li><strong>Optimal Expression Architecture:</strong> The gene is paired with a strong eukaryotic promoter (e.g., CMV promoter) and polyadenylation signal ensuring robust transcription and translation within human cells.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition: Specific gene coding for a major immunogenic surface antigen of the pathogen</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Capacity to induce dual protective immunity (neutralising antibodies via B-cells and CMI via T-cells)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Total safety: Gene devoid of virulence, toxins, or ability to produce active disease</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q6 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q6')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Name the primary and secondary lymphoid organs.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Lymphoid organs are the specialised anatomical organs where the origin, maturation, and proliferation of lymphocytes occur. They are divided into two categories:</p>\n  \n  <div style=\"display:flex; flex-wrap:wrap; gap:16px; margin-top:12px;\">\n    <div style=\"flex:1; min-width:250px; background:#ecfdf5; padding:14px; border-radius:8px; border:1px solid #10b981;\">\n      <h5 style=\"color:#065f46; margin:0 0 8px 0; font-size:1rem;\">1. Primary Lymphoid Organs</h5>\n      <p style=\"font-size:0.85rem; color:#475569; margin:0 0 8px 0;\">Sites where immature lymphocytes differentiate and mature into antigen-sensitive lymphocytes:</p>\n      <ul style=\"margin:0; padding-left:20px; font-weight:700; color:#065f46;\">\n        <li>Bone Marrow (Site of origin of all blood cells and maturation site of B-lymphocytes)</li>\n        <li>Thymus (Lobular organ located near heart, site of maturation of T-lymphocytes)</li>\n      </ul>\n    </div>\n\n    <div style=\"flex:1; min-width:250px; background:#eff6ff; padding:14px; border-radius:8px; border:1px solid #3b82f6;\">\n      <h5 style=\"color:#1e40af; margin:0 0 8px 0; font-size:1rem;\">2. Secondary Lymphoid Organs</h5>\n      <p style=\"font-size:0.85rem; color:#475569; margin:0 0 8px 0;\">Sites where mature lymphocytes interact with antigens and proliferate into effector cells:</p>\n      <ul style=\"margin:0; padding-left:20px; font-weight:700; color:#1e40af;\">\n        <li>Spleen (Large bean-shaped organ, filter of blood)</li>\n        <li>Lymph Nodes (Trap tissue fluid antigens)</li>\n        <li>Tonsils</li>\n        <li>Peyer's Patches of the Small Intestine</li>\n        <li>Appendix</li>\n        <li>MALT (Mucosa-Associated Lymphoid Tissue - ~50% of lymphoid tissue)</li>\n      </ul>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Primary lymphoid organs: Bone marrow and Thymus (maturation of B and T lymphocytes)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Secondary lymphoid organs: Spleen, Lymph nodes, Tonsils, Peyer's patches, MALT</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q7 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q7')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        The following are some well-known abbreviations, which have been used in this chapter. Expand each one to its full form:\n  <br>(a) MALT\n  <br>(b) CMI\n  <br>(c) AIDS\n  <br>(d) NACO\n  <br>(e) HIV\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:10px;\">\n    <div style=\"background:#f8fafc; padding:8px 12px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(a) MALT:</strong> <strong>M</strong>ucosa-<strong>A</strong>ssociated <strong>L</strong>ymphoid <strong>T</strong>issue (constitutes ~50% of total human lymphoid tissue).\n    </div>\n    <div style=\"background:#f8fafc; padding:8px 12px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(b) CMI:</strong> <strong>C</strong>ell-<strong>M</strong>ediated <strong>I</strong>mmunity (mediated by T-lymphocytes; responsible for graft rejection).\n    </div>\n    <div style=\"background:#f8fafc; padding:8px 12px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(c) AIDS:</strong> <strong>A</strong>cquired <strong>I</strong>mmuno<strong>d</strong>eficiency <strong>S</strong>yndrome.\n    </div>\n    <div style=\"background:#f8fafc; padding:8px 12px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(d) NACO:</strong> <strong>N</strong>ational <strong>A</strong>IDS <strong>C</strong>ontrol <strong>O</strong>rganisation.\n    </div>\n    <div style=\"background:#f8fafc; padding:8px 12px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(e) HIV:</strong> <strong>H</strong>uman <strong>I</strong>mmunodeficiency <strong>V</strong>irus.\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) MALT: Mucosa-Associated Lymphoid Tissue</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) CMI: Cell-Mediated Immunity</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) AIDS: Acquired Immunodeficiency Syndrome</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) NACO: National AIDS Control Organisation</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) HIV: Human Immunodeficiency Virus</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q8 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q8')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Differentiate the following and give examples of each:\n  <br>(a) Innate and acquired immunity\n  <br>(b) Active and passive immunity\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:16px;\">\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(a) Innate Immunity vs Acquired Immunity</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.9rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:6px 10px; width:50%;\">Innate Immunity</th>\n          <th style=\"padding:6px 10px; width:50%;\">Acquired (Adaptive) Immunity</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Inborn, non-specific defence present from the time of birth.</td>\n          <td style=\"padding:6px 10px;\">Pathogen-specific defence acquired during an individual's lifetime after exposure to foreign antigens.</td>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Lacks immunological memory; responds with equal intensity upon repeated exposures.</td>\n          <td style=\"padding:6px 10px;\">Characterised by long-lasting <strong>immunological memory</strong>; mounts rapid, heightened anamnestic response upon re-exposure.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:6px 10px;\"><strong>Examples:</strong> Physical barrier (Skin, mucus), Physiological (HCl in stomach, Lysozyme in tears), Cellular (PMNL neutrophils, Macrophages), Cytokine (Interferons).</td>\n          <td style=\"padding:6px 10px;\"><strong>Examples:</strong> Antibodies produced against measles infection; immunity developed after vaccination with Polio or BCG vaccine.</td>\n        </tr>\n      </table>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(b) Active Immunity vs Passive Immunity</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.9rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:6px 10px; width:50%;\">Active Immunity</th>\n          <th style=\"padding:6px 10px; width:50%;\">Passive Immunity</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Developed when the host's own immune system is challenged by living or dead microbes/antigens to synthesize antibodies.</td>\n          <td style=\"padding:6px 10px;\">Conferred by introducing ready-made preformed antibodies directly into the recipient's body from an external donor.</td>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Slow in onset, takes time to develop full response, but provides long-lasting immunological protection.</td>\n          <td style=\"padding:6px 10px;\">Provides immediate, fast-acting emergency protection, but is temporary and does not generate immunological memory.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:6px 10px;\"><strong>Examples:</strong> Recovery from natural chickenpox infection; active immunisation with MMR or Polio vaccines.</td>\n          <td style=\"padding:6px 10px;\"><strong>Examples:</strong> Secretory <strong>IgA</strong> received by neonate through mother's colostrum; maternal <strong>IgG</strong> crossing placenta; Anti-tetanus serum (ATS); Anti-venom for snakebite.</td>\n        </tr>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Innate vs Acquired: Inborn/non-specific vs pathogen-specific/memory based with valid examples</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Active vs Passive: Host synthesising own antibodies vs ready-made preformed antibodies with valid examples (colostrum IgA / Anti-venom)</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q9 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q9')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Draw a well-labelled diagram of an antibody molecule.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Structural Description of an Antibody Molecule:</strong></p>\n  <ul>\n    <li>An antibody (immunoglobulin, Ig) is a Y-shaped glycoprotein represented as <strong>H<sub>2</sub>L<sub>2</sub></strong>.</li>\n    <li>It consists of <strong>four polypeptide chains</strong>:\n      <ul>\n        <li>Two identical long <strong>Heavy (H) chains</strong> (~440 amino acids each, ~50 kDa).</li>\n        <li>Two identical short <strong>Light (L) chains</strong> (~220 amino acids each, ~25 kDa).</li>\n      </ul>\n    </li>\n    <li>The four chains are held together in a Y-configuration by covalent <strong>inter-chain disulphide (-S-S-) bonds</strong> and non-covalent interactions.</li>\n    <li><strong>Variable Region (Fab fragment):</strong> The N-terminal tips of both heavy and light chains form the <strong>Antigen-Binding Site (Paratope)</strong>, highly specific to a particular antigen epitope (lock-and-key fit). Each antibody molecule has <strong>two antigen-binding sites</strong> (bivalent).</li>\n    <li><strong>Constant Region (Fc fragment):</strong> The C-terminal stem region mediates effector biological functions (complement activation, binding to macrophage Fc receptors).</li>\n  </ul>\n  <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border:1px solid #cbd5e1; text-align:center; margin-top:10px;\">\n    <p style=\"margin:0; font-weight:700; color:#065f46;\">Labels required in standard CBSE diagram:</p>\n    <p style=\"margin:4px 0 0 0; font-size:0.88rem; color:#334155;\">Antigen-binding site &bull; Light Chain &bull; Heavy Chain &bull; Disulphide Bonds (-S-S-) &bull; Variable Region (V<sub>H</sub>, V<sub>L</sub>) &bull; Constant Region (C<sub>H</sub>, C<sub>L</sub>) &bull; C-terminus &bull; N-terminus</p>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Four polypeptide chains correctly depicted as H2L2 (2 heavy, 2 light chains)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct placement of inter-chain disulphide bonds (-S-S-)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate labelling: Antigen-binding site, Variable regions, Constant regions, Light and Heavy chains</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q10 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q10')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What are the various routes by which transmission of human immunodeficiency virus takes place?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Human Immunodeficiency Virus (HIV), the causative lentivirus of AIDS, is transmitted exclusively through specific parenteral body fluid exchanges:</p>\n  <ol>\n    <li><strong>Unprotected Sexual Intercourse:</strong> Sexual contact (vaginal, anal, or oral) with an HIV-infected partner without consistent barrier contraception (condom), allowing mucosal fluid transmission.</li>\n    <li><strong>Transfusion of Contaminated Blood & Blood Products:</strong> Transfusion of unscreened blood or infusing clotting factor concentrates from infected donors.</li>\n    <li><strong>Sharing of Contaminated Needles & Syringes:</strong> Inoculation via unsterilized hypodermic needles, particularly among intravenous (IV) drug abusers sharing injection paraphernalia.</li>\n    <li><strong>Perinatal / Vertical Transmission from Mother to Child:</strong> Transmission from an infected mother to her fetus across the placenta during pregnancy, during parturition (childbirth), or post-natally through breastfeeding.</li>\n    <li><strong>Accidental Occupational Exposure:</strong> Needlestick injuries or mucosal splashes encountered by healthcare personnel handling infected blood specimens.</li>\n  </ol>\n  <p><em>Important Note:</em> HIV is <strong>NOT</strong> transmitted through casual non-sexual contact, shaking hands, hugging, sharing meals, sharing toilets, coughing, or mosquito bites.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Unprotected sexual contact with infected individual</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Transfusion of contaminated blood and blood products</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sharing infected hypodermic needles (intravenous drug abusers)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Transplacental / perinatal transmission from infected mother to child (and note on no casual spread)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q11 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q11')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What is the mechanism by which the AIDS virus causes deficiency of immune system of the infected person?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>HIV progressively dismantles the host's immune system through targeted replication inside helper T-lymphocytes:</p>\n  <ol>\n    <li><strong>Viral Entry:</strong> HIV enters the host body and binds specifically via its envelope glycoprotein <strong>gp120</strong> to the <strong>CD4 receptors</strong> and chemokine co-receptors (CCR5/CXCR4) present on the surface of <strong>macrophages and Helper T-lymphocytes (T<sub>H</sub> cells)</strong>.</li>\n    <li><strong>Macrophage as HIV Factory:</strong>\n      <ul>\n        <li>Upon entering the macrophage, the viral single-stranded genomic RNA is reverse-transcribed into viral double-stranded DNA by the viral enzyme <strong>Reverse Transcriptase</strong>.</li>\n        <li>The viral DNA enters the host nucleus and incorporates into the host chromosome via the viral enzyme <strong>Integrase</strong>.</li>\n        <li>The infected macrophage continuously transcribes and sheds new viral progeny, acting as an <strong>HIV factory</strong> without immediately undergoing lysis.</li>\n      </ul>\n    </li>\n    <li><strong>Attack on Helper T-Lymphocytes (T<sub>H</sub> Cells):</strong> Simultaneously, HIV enters Helper T-cells (CD4<sup>+</sup> cells), replicates vigorously, and causes massive cellular lysis, releasing thousands of daughter virions that attack uninfected helper T-cells in the bloodstream and lymphoid organs.</li>\n    <li><strong>Progressive Depletion of CD4<sup>+</sup> T Cells:</strong> The number of helper T-cells steadily drops from normal levels (900–1200 cells/mm<sup>3</sup>) to below <strong>200 cells/mm<sup>3</sup></strong>.</li>\n    <li><strong>Immune Collapse & Opportunistic Infections:</strong> Because Helper T-cells are essential for orchestrating both humoral (B-cell activation) and cell-mediated immunity, their depletion renders the patient severely immunocompromised. The individual becomes vulnerable to fatal opportunistic infections by pathogens that are normally benign (e.g., <em>Mycobacterium tuberculosis</em>, Cytomegalovirus, fungi like <em>Candida</em>, and the protozoan <em>Toxoplasma gondii</em>).</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Binding to CD4 receptors on macrophages and T_H lymphocytes</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reverse transcriptase synthesizing viral DNA and integration into host genome (HIV factory in macrophages)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Lysis of T_H lymphocytes causing continuous decline in CD4 count (<200 cells/mm^3)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Inability to coordinate humoral/cell-mediated immunity leading to fatal opportunistic infections (Mycobacterium, Toxoplasma)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q12 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q12')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        How is a cancerous cell different from a normal cell?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Cancer cells exhibit profound morphological, physiological, and genetic deviations from normal somatic cells:</p>\n  \n  <table style=\"width:100%; border-collapse:collapse; margin-top:10px; font-size:0.88rem;\">\n    <thead>\n      <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n        <th style=\"padding:6px 10px; color:#065f46; width:25%;\">Feature</th>\n        <th style=\"padding:6px 10px; color:#065f46; width:38%;\">Normal Cell</th>\n        <th style=\"padding:6px 10px; color:#065f46; width:37%;\">Cancerous Cell</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px; font-weight:700;\">1. Contact Inhibition</td>\n        <td style=\"padding:6px 10px;\">Shows <strong>contact inhibition</strong>: physical contact with neighbouring cells halts cell division when a monolayer is formed.</td>\n        <td style=\"padding:6px 10px;\"><strong>Lacks contact inhibition</strong>: cells continue dividing uncontrollably, piling on top of each other to form neoplastic masses (tumours).</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px; font-weight:700;\">2. Cell Proliferation & Lifespan</td>\n        <td style=\"padding:6px 10px;\">Division is strictly regulated by cell cycle checkpoints; undergoes programmed cell death (apoptosis) after a finite number of divisions (Hayflick limit).</td>\n        <td style=\"padding:6px 10px;\">Undergoes unconstrained, autonomous, indefinite division (immortalization due to persistent telomerase expression); evades apoptosis.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px; font-weight:700;\">3. Differentiation</td>\n        <td style=\"padding:6px 10px;\">Highly specialized and structurally differentiated to perform specific tissue functions.</td>\n        <td style=\"padding:6px 10px;\">Undifferentiated or poorly differentiated (anaplasia); loses tissue-specific structural architecture.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px; font-weight:700;\">4. Metastasis & Invasiveness</td>\n        <td style=\"padding:6px 10px;\">Adheres securely to extracellular matrix; does not invade neighbouring tissues or migrate.</td>\n        <td style=\"padding:6px 10px;\">Exhibits <strong>metastasis</strong>: breaks loose from primary tumour, enters bloodstream/lymph, and seeds secondary tumours at distant body sites.</td>\n      </tr>\n      <tr>\n        <td style=\"padding:6px 10px; font-weight:700;\">5. Angiogenesis</td>\n        <td style=\"padding:6px 10px;\">Normal, physiological microvasculature.</td>\n        <td style=\"padding:6px 10px;\">Secretes tumour angiogenic factors (e.g., VEGF) inducing rapid neo-vascularisation to hijack host nutrients.</td>\n      </tr>\n    </tbody>\n  </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Loss of contact inhibition in cancer cells vs normal cells</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Uncontrolled cell division, evading apoptosis and immortality (telomerase)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Metastasis, loss of differentiation, and neo-angiogenesis</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q13 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q13')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Explain what is meant by metastasis.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition:</strong></p>\n  <p><strong>Metastasis</strong> is the pathological process by which malignant cancer cells slough off from the primary tumour, intravasate into circulatory vessels (blood or lymphatic channels), travel to distant anatomical sites in the body, extravasate into normal tissues, and establish secondary tumours.</p>\n\n  <p><strong>Significance & Mechanism:</strong></p>\n  <ol>\n    <li>Metastasis is the <strong>most dreaded and dangerous characteristic property of malignant neoplasms</strong>, distinguishing malignant tumours from benign tumours (which remain localized encapsulated masses).</li>\n    <li><strong>Stepwise Metastatic Cascade:</strong>\n      <ul>\n        <li><strong>Local Infiltration:</strong> Cancer cells secrete matrix metalloproteinases (MMPs) to digest the extracellular basement membrane.</li>\n        <li><strong>Intravasation:</strong> Cells penetrate into capillary blood vessels or lymphatics.</li>\n        <li><strong>Transport & Evasion:</strong> Cells survive hemodynamic shear stress and evade immune surveillance in circulation.</li>\n        <li><strong>Extravasation & Colonisation:</strong> Cells arrest in microvessels of distant vital organs (lungs, liver, bones, brain), extravasate into parenchyma, and proliferate rapidly into aggressive secondary tumours.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition of metastasis: migration of malignant cells to distant sites via blood/lymph forming secondary tumours</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification as the most feared property of malignant tumours vs benign tumours</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q14 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q14')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        List the harmful effects of smoking.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Tobacco smoke contains over 4,000 toxic chemical compounds, including at least 60 known human carcinogens, nicotine, and carbon monoxide. The major deleterious health consequences include:</p>\n  <ol>\n    <li><strong>Cardiovascular Hazards:</strong>\n      <ul>\n        <li><strong>Nicotine:</strong> An alkaloid that stimulates the adrenal medulla to release adrenaline and noradrenaline into circulation, causing tachycardia (rapid heart rate) and acute elevation of blood pressure (hypertension).</li>\n        <li><strong>Carbon Monoxide (CO):</strong> Binds to haemoglobin with 200-fold higher affinity than oxygen, forming carboxyhaemoglobin (CO-Hb). This significantly reduces the oxygen-carrying capacity of blood, leading to tissue hypoxia and arteriosclerosis.</li>\n      </ul>\n    </li>\n    <li><strong>Cancers:</strong> Strongly linked to malignant cancers of the <strong>lungs, urinary bladder, throat, oral cavity, larynx, and esophagus</strong>.</li>\n    <li><strong>Respiratory Pathologies:</strong>\n      <ul>\n        <li><strong>Emphysema:</strong> Chronic inhalation destroys alveolar septa, severely reducing the respiratory surface area available for gas exchange.</li>\n        <li><strong>Chronic Bronchitis:</strong> Paralyses respiratory ciliated epithelium and causes chronic hypersecretion of mucus, persistent coughing, and airway obstruction.</li>\n      </ul>\n    </li>\n    <li><strong>Gastric Ulcers:</strong> Tobacco increases gastric hydrochloric acid secretion, increasing incidence of peptic and duodenal ulcers.</li>\n    <li><strong>Pregnancy Complications:</strong> Smoking during pregnancy restricts fetal oxygenation, causing intrauterine growth retardation (IUGR), low birth weight, and spontaneous miscarriage.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Nicotine stimulating adrenaline (hypertension, tachycardia) and CO reducing oxygen-carrying capacity</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Carcinogenic effects: Cancers of lungs, urinary bladder, larynx, and oral cavity</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Respiratory destruction (Emphysema and chronic bronchitis) and fetal hazards</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q15 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q15')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Do you think that friends can influence one to take alcohol/drugs? If yes, how may one protect himself/herself from such an influence?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Yes, peer influence is one of the most decisive initiating triggers for drug and alcohol experimentation among adolescents.</strong> During adolescence, youngsters crave peer acceptance, fear social exclusion, and are particularly vulnerable to peer pressure.</p>\n  \n  <p><strong>Measures to Protect Oneself from Negative Peer Influence:</strong></p>\n  <ol>\n    <li><strong>Learn to Say \"NO\" Assertively:</strong> Cultivate clear personal boundaries and assertively refuse offers of alcohol, cigarettes, or drugs without guilt or hesitation (e.g., firmly stating <em>\"No, I don't consume alcohol/drugs\"</em>).</li>\n    <li><strong>Choose Healthy Friendships:</strong> Distance oneself from peer groups that glorify substance abuse or indulge in illicit activities; actively surround oneself with peers who share constructive academic, athletic, and creative interests.</li>\n    <li><strong>Avoid Undue Peer Pressure:</strong> Do not compromise personal moral values, physical health, or future ambitions simply to \"fit in\" or appear mature and rebellious.</li>\n    <li><strong>Seek Counsel from Parents and Mentors:</strong> Share personal conflicts, peer dilemmas, or anxieties openly with parents, teachers, or elder siblings, seeking their guidance.</li>\n    <li><strong>Channel Energy into Positive Pursuits:</strong> Direct physical energy and intellectual curiosity into sports, yoga, music, reading, martial arts, or community service.</li>\n    <li><strong>Seek Professional Psychological Support:</strong> If unable to cope with peer pressure or experiencing chronic anxiety/depression, seek help from school counsellors or clinical psychologists.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmative stand on peer pressure as a primary initiating factor during adolescence</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Specific protective strategies: Assertive refusal (Saying \"NO\") and avoiding undue peer pressure</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Seeking parental guidance, choosing positive friend circles, and engaging in sports/hobbies</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q16 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q16\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q16')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q16</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Why is that once a person starts taking alcohol or drugs, it is difficult to get rid of this habit? Discuss it with your teacher.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>The biological and psychological difficulty in breaking free from substance abuse stems from two interrelated neurological phenomena: <strong>Addiction (Tolerance)</strong> and <strong>Dependence (Withdrawal Syndrome)</strong>:</p>\n  <ol>\n    <li><strong>Neurobiological Addiction & Reward Circuitry:</strong>\n      <ul>\n        <li>Drugs and alcohol stimulate the mesolimbic dopamine reward pathway in the brain, inducing intense feelings of euphoria and a temporary sense of well-being.</li>\n        <li>With repeated use, the brain's neuroreceptors undergo down-regulation; their <strong>tolerance level increases</strong>. Consequently, the user requires progressively higher and more frequent doses to experience the same initial high.</li>\n      </ul>\n    </li>\n    <li><strong>Physiological and Psychological Dependence:</strong>\n      <ul>\n        <li>The body adapts homeostatically to the constant presence of the chemical. The individual becomes completely dependent on the drug to function normally.</li>\n      </ul>\n    </li>\n    <li><strong>Severe Withdrawal Syndrome:</strong>\n      <ul>\n        <li>If regular intake of the drug or alcohol is abruptly discontinued, the individual experiences agonizing, clinically manifest <strong>withdrawal symptoms</strong>.</li>\n        <li>These include severe anxiety, trembling/tremors, profuse sweating, nausea, vomiting, insomnia, depression, and hallucinations (e.g., <em>delirium tremens</em> in alcohol withdrawal), which can be life-threatening.</li>\n        <li>To escape this unbearable psychological and physical distress, the individual relapses and consumes the drug again, perpetuating a vicious trap.</li>\n      </ul>\n    </li>\n    <li><strong>Compulsive Craving & Loss of Self-Control:</strong> The drug alters prefrontal cortical circuits responsible for decision making, judgment, and impulse control.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Addiction mechanisms: Dopamine reward pathway, receptor tolerance, requiring higher doses</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Concept of physiological dependence where body requires substance to function</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Agonizing withdrawal syndrome (tremors, sweating, nausea, anxiety) driving relapse</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch7-q17 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch7-q17\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch7-q17')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q17</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        In your view what motivates youngsters to take to alcohol or drugs and how can this be avoided?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Factors that Motivate Youngsters to Experiment with Alcohol or Drugs:</strong></p>\n  <ul>\n    <li><strong>Curiosity and Experimentation:</strong> Inherent adolescent desire to explore the unknown or experience a novel \"high\".</li>\n    <li><strong>Peer Pressure & Need to Belong:</strong> The pressure to fit into popular social cliques or project an image of \"coolness\" and adulthood.</li>\n    <li><strong>Escape from Stress and Academic Pressure:</strong> Inability to manage severe competition, high parental expectations, and academic stress.</li>\n    <li><strong>Unstable Family Environment:</strong> Broken homes, domestic abuse, lack of parental warmth, or parental substance abuse.</li>\n    <li><strong>Media Glamorisation:</strong> Depiction of smoking, drinking, and drug usage in movies, television series, and social media as symbols of glamour, freedom, and rebellion.</li>\n  </ul>\n\n  <p><strong>2. Preventative & Remedial Interventions:</strong></p>\n  <ol>\n    <li><strong>Avoid Undue Peer Pressure:</strong> Parents and teachers should not thrust unfair comparisons or unachievable expectations on adolescents; each child's individual pace, strengths, and personality must be respected.</li>\n    <li><strong>Education and Open Counselling:</strong> Imparting comprehensive awareness about the biological, physiological, and social hazards of drug abuse, teaching youngsters to face problems constructively.</li>\n    <li><strong>Seeking Help from Parents and Peers:</strong> Youngsters facing anxiety or distress should be encouraged to vent emotions freely with parents, teachers, and close friends rather than seeking solitary chemical solace.</li>\n    <li><strong>Looking for Danger Signs:</strong> Vigilant parents and teachers should look out for early behavioural warnings (sudden drop in grades, absenteeism, aggressive defiance, isolation, bloodshot eyes) and initiate early interventions.</li>\n    <li><strong>Seeking Professional Medical Help:</strong> Enrolling affected youth in specialised medical de-addiction and rehabilitation clinics for clinical detoxification and cognitive behavioural therapy.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Motivating factors: Curiosity, peer pressure, stress escape, family instability, media glamour</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Preventive solutions: Avoiding undue pressure, counselling, early identification of warning signs, professional de-addiction therapy</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"display:flex; justify-content:space-between; align-items:center; margin-top:36px; padding-top:20px; border-top:1px solid #e2e8f0;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(6)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 6</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(8)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#059669; color:white; font-weight:700; cursor:pointer;\">Next: Ch 8 (Microbes in Human Welfare) →</button>\n  </div>\n</section>";
window.CHAPTER_DATA[8] = "<section class=\"chapter-section\" id=\"c12b-ch8\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#059669;\">8</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#059669;\">CBSE Class 12 Biology &bull; Chapter 8</div>\n      <h2>Microbes in Human Welfare</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 15 Verbatim Questions with Official CBSE Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n<div class=\"chem-card\" style=\"margin-bottom:24px; padding:20px; background:#f0fdf4; border:1px solid #bbf7d0; border-radius:12px;\">\n  <h4 style=\"margin:0 0 12px 0; color:#059669; font-size:1.05rem;\">🧬 Microbial Applications Map: Sewage Treatment Plant (STP) & Biogas Production</h4>\n  <svg viewBox=\"0 0 880 300\" style=\"width:100%; max-width:880px; height:auto; display:block; margin:0 auto; background:white; border-radius:8px; border:1px solid #d1fae5;\">\n    <!-- STP Flowchart -->\n    <rect x=\"20\" y=\"20\" width=\"410\" height=\"260\" rx=\"10\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"225\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Sewage Treatment Plant (STP) Flowchart</text>\n    <line x1=\"35\" y1=\"56\" x2=\"415\" y2=\"56\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n\n    <!-- Primary Treatment -->\n    <rect x=\"35\" y=\"70\" width=\"165\" height=\"55\" rx=\"6\" fill=\"#f1f5f9\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n    <text x=\"117\" y=\"90\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#1e293b\" text-anchor=\"middle\">Primary Treatment</text>\n    <text x=\"117\" y=\"105\" font-family=\"sans-serif\" font-size=\"9.5\" fill=\"#475569\" text-anchor=\"middle\">&bull; Sequential Filtration</text>\n    <text x=\"117\" y=\"118\" font-family=\"sans-serif\" font-size=\"9.5\" fill=\"#475569\" text-anchor=\"middle\">&bull; Sedimentation (Primary Sludge)</text>\n\n    <!-- Arrow -->\n    <line x1=\"200\" y1=\"97\" x2=\"235\" y2=\"97\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <polygon points=\"235,93 243,97 235,101\" fill=\"#059669\"/>\n    <text x=\"218\" y=\"90\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#059669\" text-anchor=\"middle\">Effluent</text>\n\n    <!-- Secondary / Biological -->\n    <rect x=\"245\" y=\"70\" width=\"170\" height=\"55\" rx=\"6\" fill=\"#dcfce7\" stroke=\"#16a34a\" stroke-width=\"1.5\"/>\n    <text x=\"330\" y=\"90\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#166534\" text-anchor=\"middle\">Aeration Tank</text>\n    <text x=\"330\" y=\"105\" font-family=\"sans-serif\" font-size=\"9.5\" fill=\"#15803d\" text-anchor=\"middle\">&bull; Vigorous Agitation + Air</text>\n    <text x=\"330\" y=\"118\" font-family=\"sans-serif\" font-size=\"9.5\" fill=\"#15803d\" text-anchor=\"middle\">&bull; Flocs consume organic waste</text>\n\n    <line x1=\"330\" y1=\"125\" x2=\"330\" y2=\"150\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <polygon points=\"326,150 330,158 334,150\" fill=\"#059669\"/>\n    <text x=\"375\" y=\"142\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#059669\">BOD drastically drops</text>\n\n    <!-- Settling Tank -->\n    <rect x=\"245\" y=\"160\" width=\"170\" height=\"45\" rx=\"6\" fill=\"#e0e7ff\" stroke=\"#4f46e5\" stroke-width=\"1.5\"/>\n    <text x=\"330\" y=\"180\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#3730a3\" text-anchor=\"middle\">Settling Tank</text>\n    <text x=\"330\" y=\"195\" font-family=\"sans-serif\" font-size=\"9.5\" fill=\"#4338ca\" text-anchor=\"middle\">Flocs settle as <strong>Activated Sludge</strong></text>\n\n    <!-- Split arrow -->\n    <line x1=\"245\" y1=\"182\" x2=\"180\" y2=\"182\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n    <polygon points=\"180,178 172,182 180,186\" fill=\"#dc2626\"/>\n    <text x=\"210\" y=\"175\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#dc2626\">Major part</text>\n\n    <!-- Anaerobic Sludge Digester -->\n    <rect x=\"35\" y=\"160\" width=\"135\" height=\"55\" rx=\"6\" fill=\"#fee2e2\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n    <text x=\"102\" y=\"178\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">Anaerobic Digester</text>\n    <text x=\"102\" y=\"193\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#7f1d1d\" text-anchor=\"middle\">Methanogens produce</text>\n    <text x=\"102\" y=\"206\" font-family=\"sans-serif\" font-size=\"9\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">BIOGAS (CH4+CO2+H2S)</text>\n\n    <text x=\"35\" y=\"245\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; Treated water discharged safely into natural water bodies (rivers)</text>\n    <text x=\"35\" y=\"262\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#047857\">BOD test: Measure of organic pollution in water</text>\n\n    <!-- Biogas & Industrial Microbes Card -->\n    <rect x=\"450\" y=\"20\" width=\"410\" height=\"260\" rx=\"10\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <text x=\"655\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Microbes: Bioactive Molecules & Biogas</text>\n    <line x1=\"465\" y1=\"56\" x2=\"845\" y2=\"56\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n\n    <text x=\"465\" y=\"78\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#1e40af\">Industrial Bioactive Products:</text>\n    <text x=\"465\" y=\"96\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Cyclosporin A:</strong> <em>Trichoderma polysporum</em> (Immunosuppressive)</text>\n    <text x=\"465\" y=\"114\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Statins:</strong> <em>Monascus purpureus</em> (Lowers blood cholesterol)</text>\n    <text x=\"465\" y=\"132\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Streptokinase:</strong> <em>Streptococcus</em> (Clot buster for MI)</text>\n    <text x=\"465\" y=\"150\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Citric Acid:</strong> <em>Aspergillus niger</em> (Fungus)</text>\n    <text x=\"465\" y=\"168\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Lactic Acid:</strong> <em>Lactobacillus</em> (LAB in curd, Vit B12)</text>\n\n    <text x=\"465\" y=\"196\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#059669\">Biocontrol & Biofertilisers:</text>\n    <text x=\"465\" y=\"214\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong><em>Bacillus thuringiensis</em> (Bt):</strong> Lepidopteran caterpillar control</text>\n    <text x=\"465\" y=\"232\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Baculoviruses (NPV):</strong> Narrow spectrum, species-specific</text>\n    <text x=\"465\" y=\"250\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Mycorrhiza (<em>Glomus</em>):</strong> Absorbs phosphorus from soil</text>\n    <text x=\"465\" y=\"266\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Cyanobacteria:</strong> <em>Anabaena, Nostoc, Oscillatoria</em> (Paddy fields)</text>\n  </svg>\n</div>\n\n  <div class=\"ex-div\" style=\"font-size:0.88rem; font-weight:700; color:#334155; margin-bottom:16px; padding:8px 14px; background:#ecfdf5; border-radius:8px; border-left:4px solid #059669;\">NCERT Exercises (15 Verbatim Questions)</div>\n\n  <div class=\"questions-container\">\n    \n  <!-- c12b-ch8-q1 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q1')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Bacteria cannot be seen with the naked eyes, but these can be seen with the help of a microscope. If you have to carry a sample from your home to your biology laboratory to demonstrate the presence of microbes under a microscope, which sample would you carry and why?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Sample to Carry:</strong></p>\n  <p>The best and most accessible sample to carry is a fresh drop of <strong>Curd (Yoghurt)</strong> or buttermilk.</p>\n\n  <p><strong>Scientific Reasons:</strong></p>\n  <ol>\n    <li><strong>Vast Bacterial Density:</strong> A single drop of curd contains millions of living bacteria, primarily <strong>Lactic Acid Bacteria (LAB)</strong> such as <em>Lactobacillus acidophilus</em>.</li>\n    <li><strong>Ease of Demonstration:</strong> Preparing a temporary wet-mount slide or stained smear is straightforward:\n      <ul>\n        <li>Take a tiny loop of curd diluted in a drop of water on a clean glass slide.</li>\n        <li>Heat-fix gently and stain with methylene blue or crystal violet.</li>\n        <li>Under the high-power objective (40X or 100X oil immersion), distinct rod-shaped (bacilli) <em>Lactobacillus</em> cells can be clearly visualised individually and in chains.</li>\n      </ul>\n    </li>\n    <li><strong>Safety & Non-Pathogenicity:</strong> LAB are harmless, probiotic, food-grade microorganisms safe for student handling.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of curd/yoghurt as the ideal domestic sample</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Scientific rationale: Rich in Lactobacillus (LAB) and safe/easy to mount and stain under microscope</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q2 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q2')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Give examples to prove that microbes release gases during metabolism.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Microbes release gases (primarily <strong>CO<sub>2</sub>, CH<sub>4</sub>, and H<sub>2</sub></strong>) during anaerobic fermentation and cellular respiration, proven by the following examples:</p>\n  <ol>\n    <li><strong>Puffed-up Appearance of Dough (Dosa and Idli Batter):</strong>\n      <ul>\n        <li>The dough used for making idli and dosa puffs up and becomes aerated due to the production of <strong>carbon dioxide gas (CO<sub>2</sub>)</strong> through anaerobic fermentation by natural bacterial microflora (e.g., <em>Leuconostoc mesenteroides</em> and <em>Streptococcus faecalis</em>).</li>\n      </ul>\n    </li>\n    <li><strong>Leavening of Bread by Baker's Yeast:</strong>\n      <ul>\n        <li>In bread-making, <strong>Baker's Yeast (<em>Saccharomyces cerevisiae</em>)</strong> ferments dough sugars into ethanol and CO<sub>2</sub>. The trapped bubbles of escaping CO<sub>2</sub> gas cause the dough to rise and give baked bread its characteristic spongy, porous texture.</li>\n      </ul>\n    </li>\n    <li><strong>Large Holes in Swiss Cheese:</strong>\n      <ul>\n        <li>The characteristic large holes (\"eyes\") in Swiss cheese are created by the release of copious amounts of <strong>carbon dioxide (CO<sub>2</sub>)</strong> gas by the bacterium <strong><em>Propionibacterium freudenreichii / P. shermanii</em></strong> during propionic acid fermentation.</li>\n      </ul>\n    </li>\n    <li><strong>Biogas (Gobar Gas) Production:</strong>\n      <ul>\n        <li>Methanogenic bacteria (e.g., <strong><em>Methanobacterium</em></strong>) growing anaerobically on cellulosic livestock dung produce large volumes of inflammable biogas consisting of <strong>methane (CH<sub>4</sub>, 50–70%), CO<sub>2</sub> (30–40%), and H<sub>2</sub>S</strong>.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Puffed-up dough for idli/dosa due to CO2 released by fermenting bacteria</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Bread making: Sponginess due to CO2 released by Baker's yeast (Saccharomyces cerevisiae)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Swiss cheese holes (Propionibacterium shermanii) and Biogas production (Methanobacterium releasing CH4/CO2)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q3 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q3')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        In which food would you find lactic acid bacteria? Mention some of their useful applications.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Occurrence:</strong></p>\n  <p><strong>Lactic Acid Bacteria (LAB)</strong>, such as <em>Lactobacillus</em> and related species, are prominently found in <strong>Curd (Yoghurt), Buttermilk, and Fermented Milk Cheeses</strong>.</p>\n\n  <p><strong>Useful Applications of Lactic Acid Bacteria:</strong></p>\n  <ol>\n    <li><strong>Conversion of Milk into Curd:</strong>\n      <ul>\n        <li>A small amount of curd added to fresh lukewarm milk acts as an <strong>inoculum or starter</strong> containing millions of LAB.</li>\n        <li>At optimal incubation temperature (~37–40&deg;C), LAB multiply and produce lactic acid, which coagulates and partially digests milk proteins (casein), converting liquid milk into solid curd.</li>\n      </ul>\n    </li>\n    <li><strong>Enhancement of Nutritional Quality:</strong>\n      <ul>\n        <li>LAB fermentation dramatically enriches the nutritional value of curd by substantially increasing the concentration of <strong>Vitamin B<sub>12</sub></strong>.</li>\n      </ul>\n    </li>\n    <li><strong>Inhibition of Gut Pathogens:</strong>\n      <ul>\n        <li>In the human gastrointestinal tract, LAB act as protective <strong>probiotics</strong> by producing bacteriocins and maintaining an acidic luminal pH that checks and suppresses the growth of harmful disease-causing enteric pathogens.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Naming food source: Curd, buttermilk, and fermented dairy products</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conversion of milk to curd via lactic acid coagulation of casein</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Nutritional enrichment with Vitamin B12 and probiotic checking of gut pathogens</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q4 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q4')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Name some traditional Indian foods made of wheat, rice and Bengal gram (or their products) which involve use of microbes.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Traditional fermented Indian culinary items prepared through microbial action include:</p>\n  <ol>\n    <li><strong>Foods Made from Rice and Bengal Gram (Black Gram / Urad Dal):</strong>\n      <ul>\n        <li><strong>Idli:</strong> Steamed soft savory cakes prepared from a fermented mixture of soaked rice and black gram batter, fermented by bacteria like <em>Leuconostoc mesenteroides</em> and <em>Streptococcus faecalis</em>.</li>\n        <li><strong>Dosa:</strong> Crisp crepes prepared from the same fermented rice and black gram batter.</li>\n        <li><strong>Dhokla:</strong> A Gujarati delicacy made from a fermented batter of coarsely ground Bengal gram (chana dal) or chickpeas and rice, fermented by lactic bacteria.</li>\n        <li><strong>Vada:</strong> Savoury fried fritters made from soaked and lightly fermented Bengal gram / black gram paste.</li>\n      </ul>\n    </li>\n    <li><strong>Foods Made from Wheat:</strong>\n      <ul>\n        <li><strong>Bhatura & Naan:</strong> Traditional leavened flatbreads made from refined wheat flour (maida) mixed with curd, warm water, and yeast / bacterial starter, leavened by anaerobic CO<sub>2</sub> production.</li>\n        <li><strong>Bread:</strong> Leavened wheat loaf baked using Baker's yeast (<em>Saccharomyces cerevisiae</em>).</li>\n        <li><strong>Jalebi:</strong> Sweet spirals made from a fermented batter of refined wheat flour (maida) allowed to ferment overnight.</li>\n      </ul>\n    </li>\n    <li><strong>Traditional Drink (Bonus Mention):</strong>\n      <ul>\n        <li><strong>Toddy:</strong> A traditional refreshing South Indian beverage prepared by fermenting the sugary sap of palm trees with wild yeasts.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Rice and Bengal gram foods: Idli, Dosa, Dhokla, Vada with microbial role</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Wheat products: Bhatura, Naan, leavened bread, Jalebi batter</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reference to traditional fermented drink (Toddy) or specific fermenting microbes</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q5 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q5')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        In which way have microbes played a major role in controlling diseases caused by harmful bacteria?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Microorganisms have played a revolutionary role in controlling and curing bacterial diseases primarily through the discovery and industrial manufacturing of <strong>Antibiotics</strong>:</p>\n  <ol>\n    <li><strong>Production of Antibiotics:</strong>\n      <ul>\n        <li>Antibiotics are chemical substances produced by certain microorganisms that can kill or inhibit the growth of other disease-causing pathogenic microorganisms even at very low concentrations.</li>\n        <li><strong>Alexander Fleming's Discovery of Penicillin (1928):</strong> Discovered from the mold <em>Penicillium notatum</em>; its full therapeutic potential as an antibiotic was established by <strong>Ernest Chain and Howard Florey</strong> during World War II.</li>\n        <li>Other life-saving antibiotics discovered from actinomycetes/bacteria include:\n          <ul>\n            <li><strong>Streptomycin</strong> (from <em>Streptomyces griseus</em>) for tuberculosis.</li>\n            <li><strong>Tetracycline, Chloramphenicol, and Erythromycin</strong> for typhoid, pneumonia, and broad-spectrum bacterial infections.</li>\n          </ul>\n        </li>\n      </ul>\n    </li>\n    <li><strong>Production of Vaccines:</strong> Attenuated or killed bacterial strains (e.g., BCG for tuberculosis, cholera vaccine, and recombinant bacterial antigens) stimulate host antibody production and immunological memory.</li>\n    <li><strong>Competitive Exclusion via Probiotics:</strong> Beneficial bacteria (e.g., <em>Lactobacillus</em>) in the gut synthesize bacteriocins and maintain an acidic pH that competitively prevents colonisation by pathogens like <em>Salmonella</em> and <em>Shigella</em>.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Role of antibiotics as chemical substances produced by microbes killing pathogenic bacteria</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Historic examples: Penicillin (Penicillium notatum) and Streptomycin (Streptomyces griseus)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Impact on controlling fatal plagues, diphtheria, leprosy, and role of vaccines/probiotics</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q6 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q6')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Name any two species of fungus, which are used in the production of the antibiotics.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Two fungal species industrially utilized for the commercial production of antibiotics are:</p>\n  <ol>\n    <li><strong><em>Penicillium notatum</em> / <em>Penicillium chrysogenum</em>:</strong>\n      <ul>\n        <li>Used for the industrial production of <strong>Penicillin</strong> (a &beta;-lactam bactericidal antibiotic that inhibits bacterial peptidoglycan cell-wall synthesis).</li>\n      </ul>\n    </li>\n    <li><strong><em>Cephalosporium acremonium</em> (now known as <em>Acremonium chrysogenum</em>):</strong>\n      <ul>\n        <li>Used for the industrial production of <strong>Cephalosporins</strong> (a broad-spectrum class of &beta;-lactam antibiotics effective against both Gram-positive and Gram-negative bacteria).</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">1. Penicillium notatum / Penicillium chrysogenum producing Penicillin</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">2. Cephalosporium acremonium producing Cephalosporin</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q7 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q7')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What is sewage? In which way can sewage be harmful to us?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition of Sewage:</strong></p>\n  <p><strong>Sewage</strong> is the municipal wastewater generated in large quantities daily in human settlements, towns, and cities. It contains human excreta, domestic kitchen and bathroom discharge, wash waters, organic debris, and toxic street runoff.</p>\n\n  <p><strong>Harmful Effects of Untreated Sewage:</strong></p>\n  <ol>\n    <li><strong>Spread of Fatal Water-Borne Epidemics:</strong> Sewage contains dense populations of dangerous pathogenic bacteria, viruses, and parasites. Discharging raw sewage into rivers contaminates potable drinking supplies, triggering devastating epidemics of <strong>cholera, typhoid, hepatitis-A, dysentery, and polio</strong>.</li>\n    <li><strong>Eutrophication & Severe Oxygen Depletion (Fish Mortality):</strong> Raw sewage has an extremely high <strong>Biochemical Oxygen Demand (BOD)</strong>. Aerobic decomposition by saprophytic bacteria rapidly consumes all dissolved oxygen (DO) in receiving water bodies, suffocating fish and collapsing aquatic ecosystems.</li>\n    <li><strong>Bioaccumulation of Toxic Chemical Contaminants:</strong> Modern municipal sewage contains non-biodegradable detergents, heavy metals (lead, mercury, cadmium), microplastics, and pharmaceutical residues that bioaccumulate in aquatic food chains.</li>\n    <li><strong>Foul Odour and Environmental Degradation:</strong> Anaerobic putrefaction produces foul-smelling toxic gases like hydrogen sulphide (H<sub>2</sub>S) and methane, turning water bodies into toxic open cesspools.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of municipal sewage (wastewater containing human excreta, domestic waste, organic matter)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Water-borne disease epidemics (cholera, typhoid, hepatitis, dysentery)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">High BOD causing dissolved oxygen depletion, aquatic fish death, and toxic bioaccumulation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q8 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q8')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What is the key difference between primary and secondary sewage treatment?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Sewage treatment is carried out in two distinct successive stages:</p>\n  \n  <table style=\"width:100%; border-collapse:collapse; margin-top:10px; font-size:0.9rem;\">\n    <thead>\n      <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n        <th style=\"padding:6px 10px; color:#065f46; width:50%;\">Primary Treatment (Physical)</th>\n        <th style=\"padding:6px 10px; color:#065f46; width:50%;\">Secondary Treatment (Biological)</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\">A strictly <strong>physical process</strong> involving the mechanical removal of large and small particulate debris.</td>\n        <td style=\"padding:6px 10px;\">A <strong>biological process</strong> involving the metabolic action of aerobic and anaerobic microorganisms.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\">Accomplished by <strong>sequential filtration</strong> (removes floating trash) and <strong>sedimentation</strong> (removes grit, soil, and pebbles).</td>\n        <td style=\"padding:6px 10px;\">Accomplished in huge <strong>aeration tanks</strong> where vigorous air pumping stimulates growth of <strong>flocs</strong> (bacteria associated with fungal filaments).</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\">Produces <strong>primary sludge</strong> (solids that settle) and <strong>primary effluent</strong> (supernatant).</td>\n        <td style=\"padding:6px 10px;\">Produces <strong>activated sludge</strong> (settled microbial flocs) and biogas via anaerobic sludge digesters.</td>\n      </tr>\n      <tr>\n        <td style=\"padding:6px 10px;\">Does not alter the dissolved organic load; BOD remains extremely high.</td>\n        <td style=\"padding:6px 10px;\">Microbes digest dissolved organic matter, <strong>drastically reducing the Biochemical Oxygen Demand (BOD)</strong> by 90–95%.</td>\n      </tr>\n    </tbody>\n  </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Primary treatment: Physical removal of debris via sequential filtration and sedimentation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Secondary treatment: Biological digestion by aerobic microbial flocs in aeration tanks</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Outcome contrast: Primary separates coarse sludge vs Secondary drastically reduces BOD of effluent</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q9 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q9')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Do you think microbes can also be used as source of energy? If yes, how?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Yes, microbes are widely used as a renewable, decentralized source of clean energy.</strong></p>\n  <p><strong>Scientific Mechanism: Biogas (Gobar Gas) Generation:</strong></p>\n  <ol>\n    <li><strong>Role of Methanogens:</strong>\n      <ul>\n        <li>Certain anaerobic bacteria, collectively called <strong>methanogens</strong> (e.g., <strong><em>Methanobacterium</em></strong>), grow anaerobically on cellulosic materials such as cow dung (gobar), agricultural crop residues, and human excreta.</li>\n        <li>Methanogens are naturally present in the rumen (first stomach chamber) of cattle, aiding in cellulose breakdown; hence, cattle dung is exceptionally rich in these bacteria.</li>\n      </ul>\n    </li>\n    <li><strong>Operation of a Biogas Plant:</strong>\n      <ul>\n        <li>Cattle dung and water are mixed in a 1:1 ratio to form a slurry, fed into a concrete digester pit (10–15 feet deep).</li>\n        <li>Under strict anaerobic conditions, methanogens digest the slurry in three metabolic phases: <em>hydrolysis</em>, <em>acidogenesis</em>, and <em>methanogenesis</em>.</li>\n        <li>This produces <strong>Biogas</strong>, a gaseous mixture consisting of:\n          <ul>\n            <li><strong>Methane (CH<sub>4</sub>):</strong> 50–70% (primary combustible fuel)</li>\n            <li><strong>Carbon dioxide (CO<sub>2</sub>):</strong> 30–40%</li>\n            <li>Traces of H<sub>2</sub>, N<sub>2</sub>, and H<sub>2</sub>S</li>\n          </ul>\n        </li>\n      </ul>\n    </li>\n    <li><strong>Utility:</strong> Biogas is piped directly into rural households for <strong>smokeless cooking, domestic lighting, and running agricultural water pumps</strong>. The residual spent slurry serves as rich organic manure (biofertiliser).</li>\n    <li><strong>Microbial Biofuels (Bonus):</strong> Yeast (<em>Saccharomyces</em>) ferments molasses/corn starch into <strong>bioethanol</strong>, used as green biofuel blended with petrol.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear affirmation (Yes) and identification of Methanobacterium / methanogens</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Process of anaerobic digestion of cellulosic dung producing biogas (50-70% methane)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Practical utilisation for smokeless rural cooking/lighting and bioethanol production</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q10 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q10')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Microbes can be used to decrease the use of chemical fertilisers and pesticides. Explain how this can be accomplished.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Indiscriminate use of chemical fertilisers and synthetic pesticides degrades soil health, causes groundwater pollution, and leads to biomagnification. Microbes offer eco-friendly, biological alternatives:</p>\n\n  <p><strong>1. Microbes as Biofertilisers (Replacing Chemical NPK Fertilisers):</strong></p>\n  <ul>\n    <li><strong>Symbiotic Nitrogen Fixers:</strong> <strong><em>Rhizobium</em></strong> forms root nodules in leguminous crops, fixing atmospheric N<sub>2</sub> into organic forms readily absorbed by plants.</li>\n    <li><strong>Free-Living & Associative Nitrogen Fixers:</strong> <strong><em>Azotobacter</em></strong> and <strong><em>Azospirillum</em></strong> enrich soil nitrogen content in non-leguminous crops.</li>\n    <li><strong>Mycorrhizal Fungi:</strong> Fungi of the genus <strong><em>Glomus</em></strong> establish symbiotic mycorrhizal associations with plant roots. The fungal hyphae absorb <strong>phosphorus</strong> from soil and pass it to the plant, while conferring resistance to root pathogens and tolerance to drought.</li>\n    <li><strong>Cyanobacteria:</strong> Free-living or symbiotic autotrophs (e.g., <strong><em>Anabaena, Nostoc, Oscillatoria</em></strong>) fix nitrogen and add organic matter, acting as critical biofertilisers in paddy (rice) fields.</li>\n  </ul>\n\n  <p><strong>2. Microbes as Biocontrol Agents (Replacing Chemical Pesticides):</strong></p>\n  <ul>\n    <li><strong><em>Bacillus thuringiensis</em> (Bt):</strong> Spores of Bt produce insecticidal crystal (Cry) proteins. When sprayed on crops (e.g., brassicas and fruit trees), caterpillars ingest the spores. The protoxin dissolves in the alkaline insect gut, creating pores that kill the pest without harming birds, beneficial insects, or mammals.</li>\n    <li><strong><em>Trichoderma</em> Species:</strong> Free-living soil-dwelling fungi present in root ecosystems that act as potent biological control agents against diverse plant root fungal pathogens.</li>\n    <li><strong>Baculoviruses (Genus <em>Nucleopolyhedrovirus</em> - NPV):</strong> Pathogens that attack insects and other arthropods. They are excellent biological control agents because of their <strong>narrow-spectrum, species-specific insecticidal action</strong>, having zero negative impact on non-target insects, mammals, birds, or beneficial pollinators (ideal for Integrated Pest Management - IPM).</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Biofertilisers: Nitrogen fixers (Rhizobium, Azotobacter, Cyanobacteria) and phosphorus-absorbing Glomus mycorrhiza</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Biocontrol: Bacillus thuringiensis (Bt) for caterpillars and Trichoderma for soil root pathogens</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Baculoviruses (NPV) providing narrow-spectrum, species-specific IPM control</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q11 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q11')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Three water samples namely river water, untreated sewage water and secondary effluent discharged from a sewage treatment plant were subjected to BOD test. The samples were labelled A, B and C; but the laboratory attendant forgot to label which was which. The BOD values of the three samples A, B and C were recorded as 20 mg/L, 8 mg/L and 400 mg/L, respectively.\n  <br>Which sample of the water is most polluted? Can you assign the correct label to each assuming the river water is relatively clean?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Scientific Principle of the BOD Test:</strong></p>\n  <ul>\n    <li><strong>Biochemical Oxygen Demand (BOD)</strong> is the amount of oxygen required by aerobic microbes to oxidize all the biodegradable organic matter present in one liter of water.</li>\n    <li>There is a <strong>direct linear relationship between BOD and organic pollution</strong>: higher the organic waste load, greater is microbial respiration, higher is the BOD, and lower is the dissolved oxygen (DO).</li>\n  </ul>\n\n  <p><strong>1. Identification of the Most Polluted Water Sample:</strong></p>\n  <div style=\"background:#fef2f2; padding:10px 14px; border-left:4px solid #ef4444; margin:8px 0; font-weight:700; color:#991b1b;\">\n    Sample C is the most polluted water sample because it has the highest BOD value (400 mg/L).\n  </div>\n\n  <p><strong>2. Assigning Correct Labels to Samples A, B, and C:</strong></p>\n  <ul>\n    <li><strong>Sample C (BOD = 400 mg/L): Untreated Sewage Water</strong>\n      <br>Contains raw human excreta and highest dissolved/suspended organic matter; hence consumes maximum dissolved oxygen during microbial decomposition.</li>\n    <li><strong>Sample A (BOD = 20 mg/L): Secondary Effluent from STP</strong>\n      <br>Has undergone primary sedimentation and secondary biological digestion in aeration tanks; its BOD has been reduced by 90–95%, but still retains minor residual organic load.</li>\n    <li><strong>Sample B (BOD = 8 mg/L): Clean River Water</strong>\n      <br>Relatively clean, natural flowing surface water containing minimal organic contaminants and supporting healthy aquatic life; hence has the lowest BOD.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Sample C (400 mg/L) as the most polluted based on BOD principle</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct assignment of Sample C = Untreated sewage water</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct assignment of Sample A = Secondary effluent from STP (20 mg/L)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct assignment of Sample B = Relatively clean river water (8 mg/L)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q12 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q12')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Find out the name of the microbes from which Cyclosporin A (an immunosuppressive drug) and Statins (blood cholesterol lowering agents) are obtained.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>The producing microorganisms for these two clinically indispensable bioactive molecules are:</p>\n  \n  <div style=\"display:flex; flex-direction:column; gap:12px; margin-top:10px;\">\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">1. Cyclosporin A (Immunosuppressive Drug)</h5>\n      <p style=\"margin:0 0 4px 0;\"><strong>Producing Microbe:</strong> The filamentous fungus <strong><em>Trichoderma polysporum</em></strong>.</p>\n      <p style=\"margin:0; font-size:0.88rem; color:#475569;\"><strong>Clinical Utility:</strong> Used as an essential immunosuppressive agent in organ-transplant recipients to prevent graft rejection by suppressing T-lymphocyte activation.</p>\n    </div>\n\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">2. Statins (Blood Cholesterol-Lowering Agents)</h5>\n      <p style=\"margin:0 0 4px 0;\"><strong>Producing Microbe:</strong> The yeast <strong><em>Monascus purpureus</em></strong>.</p>\n      <p style=\"margin:0; font-size:0.88rem; color:#475569;\"><strong>Biochemical Mechanism:</strong> Statins act by competitively inhibiting <strong>HMG-CoA reductase</strong>, the rate-limiting enzyme responsible for de novo endogenous cholesterol biosynthesis in the liver.</p>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Cyclosporin A obtained from the fungus Trichoderma polysporum</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Statins obtained from the yeast Monascus purpureus (with competitive inhibition of cholesterol synthesis)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q13 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q13')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Find out the role of microbes in the following and discuss it with your teacher:\n  <br>(a) Single cell protein (SCP)\n  <br>(b) Soil\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:14px;\">\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">(a) Single Cell Protein (SCP)</h5>\n      <p style=\"margin:0;\">Microorganisms represent an alternate, protein-rich biomass for human food and animal feed to combat global malnutrition and food insecurity:</p>\n      <ul style=\"margin:6px 0 0 0;\">\n        <li><strong><em>Spirulina</em> (Cyanobacterium):</strong> Cultivated easily on potato processing wastewater, straw, molasses, or sewage. Rich in proteins, minerals, vitamins, essential fatty acids, and carbohydrates.</li>\n        <li><strong><em>Methylophilus methylotrophus</em> (Bacterium):</strong> Because of its rapid growth rate and high biomass productivity, 250 g of this micro-organism can produce an astounding <strong>25 tonnes of protein</strong> in 24 hours (compared to a 250 kg cow producing only ~200 g protein/day).</li>\n        <li><strong>Mushrooms (e.g., <em>Agaricus bisporus</em>):</strong> Edible basidiomycete fungi grown on agricultural compost.</li>\n      </ul>\n    </div>\n\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">(b) Soil</h5>\n      <p style=\"margin:0;\">Microbes form the foundation of pedogenesis, soil texture, fertility, and biochemical biogeochemical cycling:</p>\n      <ul style=\"margin:6px 0 0 0;\">\n        <li><strong>Decomposition & Humification:</strong> Saprophytic bacteria and fungi decompose leaf litter, dead animal carcasses, and cellulose into rich, dark amorphous <strong>humus</strong>, releasing immobilized N, P, K, and micro-nutrients back into the soil solution.</li>\n        <li><strong>Nitrogen Cycling:</strong> Biological nitrogen fixation by <em>Rhizobium</em>, nitrification by <em>Nitrosomonas</em> and <em>Nitrobacter</em>, and denitrification by <em>Pseudomonas</em> balance terrestrial nitrogen.</li>\n        <li><strong>Soil Aggregation:</strong> Fungal hyphae and bacterial exopolysaccharides bind fine mineral particles together, improving soil porosity, crumb structure, and water retention capacity.</li>\n      </ul>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Role in SCP: Microbes (Spirulina, Methylophilus methylotrophus) providing protein-rich biomass with rapid yield</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Role in Soil: Decomposition, humus formation, biogeochemical nutrient recycling, and improving soil aeration</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q14 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q14')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Arrange the following in the decreasing order (most important first) of their importance, for the welfare of human society. Give reasons for your answer:\n  <br>Biogas, Citric acid, Penicillin and Curd.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Arrangement in Decreasing Order of Importance for Human Welfare:</strong></p>\n  <div style=\"background:#ecfdf5; padding:12px 16px; border:1px solid #10b981; border-radius:8px; margin:10px 0; font-weight:700; color:#065f46; font-size:1.05rem; text-align:center;\">\n    1. Penicillin &gt; 2. Biogas &gt; 3. Curd &gt; 4. Citric Acid\n  </div>\n\n  <p><strong>Detailed Rationale for Hierarchy:</strong></p>\n  <ol>\n    <li><strong>1. Penicillin (Most Critical - Life Saving):</strong>\n      <br>Antibiotics like penicillin are indispensable for human survival. Before its discovery, minor bacterial wounds, pneumonia, and childbirth sepsis caused millions of deaths. It revolutionized medicine by treating life-threatening infectious diseases worldwide.</li>\n    <li><strong>2. Biogas (Ecological & Energy Security):</strong>\n      <br>Biogas provides a renewable, smokeless, clean fuel for rural households, addressing rural deforestation, energy poverty, and global warming while transforming foul cattle excreta into pathogen-free organic manure.</li>\n    <li><strong>3. Curd (Nutritional & Probiotic Health):</strong>\n      <br>A staple domestic dairy food item consumed daily across millions of households. It supplies high biological-value milk protein, synthesizes Vitamin B<sub>12</sub>, and acts as a gut probiotic checking harmful pathogen growth.</li>\n    <li><strong>4. Citric Acid (Industrial Food Additive):</strong>\n      <br>Produced by the mold <em>Aspergillus niger</em>. While widely used as an industrial acidifier, flavouring agent, and preservative in beverages and confectioneries, its societal importance is commercial rather than vital to life preservation.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct hierarchy: Penicillin > Biogas > Curd > Citric acid</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification for Penicillin (life-saving antibiotic) and Biogas (renewable energy/sanitation)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification for Curd (daily nutritional/probiotic food) and Citric acid (commercial food additive)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q15 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q15')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        How do biofertilisers enrich the fertility of the soil?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Biofertilisers</strong> are living cultures of beneficial microorganisms that enrich the nutrient quality and physical fertility of soil through biological pathways:</p>\n  <ol>\n    <li><strong>Biological Nitrogen Fixation (BNF):</strong>\n      <ul>\n        <li>Atmospheric nitrogen (N<sub>2</sub>) cannot be assimilated directly by plants. Biofertilisers possess the enzyme <strong>nitrogenase</strong> that reduces atmospheric N<sub>2</sub> into ammonia (NH<sub>3</sub>):\n          <ul>\n            <li><strong>Symbiotic bacteria:</strong> <em>Rhizobium</em> forms nodules in legumes, fixing up to 50–100 kg N/ha/year.</li>\n            <li><strong>Free-living bacteria:</strong> <em>Azotobacter</em> (aerobic) and <em>Clostridium</em> (anaerobic) enrich arable soil.</li>\n            <li><strong>Associative symbionts:</strong> <em>Azospirillum</em> colonises the rhizosphere of cereals (sorghum, maize).</li>\n          </ul>\n        </li>\n      </ul>\n    </li>\n    <li><strong>Phosphate Solubilisation & Uptake (Mycorrhiza):</strong>\n      <ul>\n        <li>Fungi of the genus <strong><em>Glomus</em></strong> form symbiotic endo-mycorrhizal associations with plant roots. Their extensive fungal mycelial network explores soil volumes far beyond root hairs to absorb <strong>insoluble phosphorus</strong> and deliver it to host plants.</li>\n        <li>Mycorrhizae also confer systemic resistance to root-borne pathogens, tolerance to salinity and drought, and increase overall plant vigor.</li>\n      </ul>\n    </li>\n    <li><strong>Enrichment via Cyanobacteria:</strong>\n      <ul>\n        <li>In wetland paddy (rice) agroecosystems, autotrophic <strong>cyanobacteria</strong> (e.g., <em>Anabaena, Nostoc, Aulosira, Oscillatoria</em>) fix nitrogen in specialised thick-walled cells called <strong>heterocysts</strong> and contribute substantial organic biomass, preventing soil erosion.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Nitrogen fixation: Nitrogenase converting atmospheric N2 to ammonia (Rhizobium, Azotobacter, Azospirillum)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Phosphate mobilization: Mycorrhizal fungi (Glomus) absorbing phosphorus and conferring drought/disease resistance</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Cyanobacteria (Anabaena, Nostoc) in paddy fields adding nitrogen and organic matter</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"display:flex; justify-content:space-between; align-items:center; margin-top:36px; padding-top:20px; border-top:1px solid #e2e8f0;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(7)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 7</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(9)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#059669; color:white; font-weight:700; cursor:pointer;\">Next: Ch 9 (Biotechnology: Principles and Processes) →</button>\n  </div>\n</section>";
window.CHAPTER_DATA[9] = "<section class=\"chapter-section\" id=\"c12b-ch9\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#059669;\">9</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#059669;\">CBSE Class 12 Biology &bull; Chapter 9</div>\n      <h2>Biotechnology: Principles and Processes</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 12 Verbatim Questions with Official CBSE Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n<div class=\"chem-card\" style=\"margin-bottom:24px; padding:20px; background:#f0fdf4; border:1px solid #bbf7d0; border-radius:12px;\">\n  <h4 style=\"margin:0 0 12px 0; color:#059669; font-size:1.05rem;\">🧬 Recombinant DNA Technology: pBR322 Vector Architecture & PCR Cycle</h4>\n  <svg viewBox=\"0 0 880 300\" style=\"width:100%; max-width:880px; height:auto; display:block; margin:0 auto; background:white; border-radius:8px; border:1px solid #d1fae5;\">\n    <!-- pBR322 Vector Map -->\n    <rect x=\"20\" y=\"20\" width=\"380\" height=\"260\" rx=\"10\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"210\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Cloning Vector pBR322 (4,361 bp)</text>\n    <line x1=\"35\" y1=\"56\" x2=\"385\" y2=\"56\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n\n    <!-- Circular Vector Graphic -->\n    <circle cx=\"210\" cy=\"155\" r=\"75\" fill=\"none\" stroke=\"#059669\" stroke-width=\"6\"/>\n    <!-- EcoRI / ClaI / HindIII top -->\n    <text x=\"210\" y=\"70\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#dc2626\" text-anchor=\"middle\">EcoRI &bull; ClaI &bull; HindIII</text>\n    <line x1=\"210\" y1=\"74\" x2=\"210\" y2=\"80\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n\n    <!-- ampR gene with PstI / PvuI -->\n    <path d=\"M 140 130 A 75 75 0 0 1 180 85\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"10\"/>\n    <text x=\"120\" y=\"110\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#1e40af\">amp<sup>R</sup></text>\n    <text x=\"85\" y=\"95\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#1e40af\">PstI, PvuI</text>\n\n    <!-- tetR gene with BamHI / SalI -->\n    <path d=\"M 240 85 A 75 75 0 0 1 280 130\" fill=\"none\" stroke=\"#d97706\" stroke-width=\"10\"/>\n    <text x=\"285\" y=\"110\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#b45309\">tet<sup>R</sup></text>\n    <text x=\"325\" y=\"95\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#b45309\">BamHI, SalI</text>\n\n    <!-- ori and rop bottom -->\n    <path d=\"M 150 195 A 75 75 0 0 1 185 228\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"10\"/>\n    <text x=\"135\" y=\"225\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#166534\">ori</text>\n\n    <path d=\"M 235 228 A 75 75 0 0 1 270 195\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"10\"/>\n    <text x=\"285\" y=\"225\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#5b21b6\">rop (PvuII)</text>\n\n    <text x=\"210\" y=\"155\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">pBR322</text>\n    <text x=\"210\" y=\"170\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#64748b\" text-anchor=\"middle\">Bolivar & Rodriguez</text>\n\n    <!-- PCR Cycle Card -->\n    <rect x=\"420\" y=\"20\" width=\"440\" height=\"260\" rx=\"10\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <text x=\"640\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Polymerase Chain Reaction (PCR) - Kary Mullis</text>\n    <line x1=\"435\" y1=\"56\" x2=\"845\" y2=\"56\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n\n    <!-- Step 1: Denaturation -->\n    <rect x=\"435\" y=\"70\" width=\"125\" height=\"55\" rx=\"6\" fill=\"#fee2e2\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n    <text x=\"497\" y=\"90\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">1. Denaturation</text>\n    <text x=\"497\" y=\"105\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#7f1d1d\" text-anchor=\"middle\">94 &ndash; 96 &deg;C</text>\n    <text x=\"497\" y=\"118\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#7f1d1d\" text-anchor=\"middle\">dsDNA melts to ssDNA</text>\n\n    <!-- Arrow -->\n    <line x1=\"560\" y1=\"97\" x2=\"575\" y2=\"97\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <polygon points=\"575,93 583,97 575,101\" fill=\"#3b82f6\"/>\n\n    <!-- Step 2: Annealing -->\n    <rect x=\"585\" y=\"70\" width=\"125\" height=\"55\" rx=\"6\" fill=\"#fef3c7\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n    <text x=\"647\" y=\"90\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#92400e\" text-anchor=\"middle\">2. Annealing</text>\n    <text x=\"647\" y=\"105\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#78350f\" text-anchor=\"middle\">50 &ndash; 60 &deg;C</text>\n    <text x=\"647\" y=\"118\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#78350f\" text-anchor=\"middle\">Primers bind 3' ends</text>\n\n    <!-- Arrow -->\n    <line x1=\"710\" y1=\"97\" x2=\"725\" y2=\"97\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <polygon points=\"725,93 733,97 725,101\" fill=\"#3b82f6\"/>\n\n    <!-- Step 3: Extension -->\n    <rect x=\"735\" y=\"70\" width=\"115\" height=\"55\" rx=\"6\" fill=\"#dcfce7\" stroke=\"#16a34a\" stroke-width=\"1.5\"/>\n    <text x=\"792\" y=\"90\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#166534\" text-anchor=\"middle\">3. Extension</text>\n    <text x=\"792\" y=\"105\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#15803d\" text-anchor=\"middle\">72 &deg;C</text>\n    <text x=\"792\" y=\"118\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#15803d\" text-anchor=\"middle\"><em>Taq</em> Polymerase</text>\n\n    <text x=\"435\" y=\"150\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#1e40af\">Key Reagents in PCR:</text>\n    <text x=\"435\" y=\"168\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; Target Template DNA &bull; Pair of synthetic oligonucleotide primers</text>\n    <text x=\"435\" y=\"184\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; Deoxynucleoside triphosphates (dNTPs: dATP, dCTP, dGTP, dTTP)</text>\n    <text x=\"435\" y=\"200\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Taq Polymerase</strong> isolated from thermophilic <em>Thermus aquaticus</em></text>\n    <text x=\"435\" y=\"218\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#047857\">Amplification: 30 cycles yield ~ 1 billion (&sim; 10<sup>9</sup>) DNA copies!</text>\n    <text x=\"435\" y=\"240\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#475569\">Agarose Gel: Ethidium bromide staining + UV light reveals bright orange bands</text>\n  </svg>\n</div>\n\n  <div class=\"ex-div\" style=\"font-size:0.88rem; font-weight:700; color:#334155; margin-bottom:16px; padding:8px 14px; background:#ecfdf5; border-radius:8px; border-left:4px solid #059669;\">NCERT Exercises (12 Verbatim Questions)</div>\n\n  <div class=\"questions-container\">\n    \n  <!-- c12b-ch9-q1 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch9-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch9-q1')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Can you list 10 recombinant proteins which are used for medical practice? Find out where they are used as therapeutics (use the internet).\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Recombinant DNA technology has enabled the high-purity production of therapeutic human proteins in transgenic host cells (e.g., bacteria, yeast, CHO cells):</p>\n  \n  <table style=\"width:100%; border-collapse:collapse; margin-top:10px; font-size:0.88rem;\">\n    <thead>\n      <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n        <th style=\"padding:6px 10px; color:#065f46;\">#</th>\n        <th style=\"padding:6px 10px; color:#065f46;\">Recombinant Therapeutic Protein</th>\n        <th style=\"padding:6px 10px; color:#065f46;\">Medical / Clinical Application</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\">1</td>\n        <td style=\"padding:6px 10px;\"><strong>Recombinant Human Insulin (Humulin)</strong></td>\n        <td style=\"padding:6px 10px;\">Treatment of Insulin-Dependent Type-1 Diabetes Mellitus.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\">2</td>\n        <td style=\"padding:6px 10px;\"><strong>Human Growth Hormone (hGH / Somatotropin)</strong></td>\n        <td style=\"padding:6px 10px;\">Treatment of pituitary dwarfism, growth failure, and Turner syndrome in children.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\">3</td>\n        <td style=\"padding:6px 10px;\"><strong>Erythropoietin (rhEPO)</strong></td>\n        <td style=\"padding:6px 10px;\">Treatment of severe anaemia associated with chronic renal failure and cancer chemotherapy.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\">4</td>\n        <td style=\"padding:6px 10px;\"><strong>Factor VIII (Anti-Haemophilic Factor)</strong></td>\n        <td style=\"padding:6px 10px;\">Treatment of Haemophilia A to restore blood clotting function.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\">5</td>\n        <td style=\"padding:6px 10px;\"><strong>Factor IX (Christmas Factor)</strong></td>\n        <td style=\"padding:6px 10px;\">Treatment of Haemophilia B.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\">6</td>\n        <td style=\"padding:6px 10px;\"><strong>Tissue Plasminogen Activator (t-PA)</strong></td>\n        <td style=\"padding:6px 10px;\">Emergency \"clot-buster\" thrombolytic drug for dissolving acute myocardial infarctions (heart attacks) and ischemic strokes.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\">7</td>\n        <td style=\"padding:6px 10px;\"><strong>Interferons (&alpha;, &beta;, &gamma;)</strong></td>\n        <td style=\"padding:6px 10px;\">Treatment of viral infections (Hepatitis B & C) and specific neoplasms (Kaposi's sarcoma, hairy cell leukaemia).</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\">8</td>\n        <td style=\"padding:6px 10px;\"><strong>Granulocyte-Colony Stimulating Factor (G-CSF)</strong></td>\n        <td style=\"padding:6px 10px;\">Treats severe neutropenia by stimulating neutrophil production following cancer chemotherapy or bone marrow transplants.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\">9</td>\n        <td style=\"padding:6px 10px;\"><strong>&alpha;-1-Antitrypsin</strong></td>\n        <td style=\"padding:6px 10px;\">Therapeutic replacement therapy for treating emphysema caused by congenital enzyme deficiency.</td>\n      </tr>\n      <tr style=\"background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\">10</td>\n        <td style=\"padding:6px 10px;\"><strong>Hepatitis B Surface Antigen (HBsAg)</strong></td>\n        <td style=\"padding:6px 10px;\">Subunit recombinant vaccine for active immunisation against Hepatitis-B virus infection.</td>\n      </tr>\n    </tbody>\n  </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Listing 10 recombinant proteins accurately (Insulin, hGH, Erythropoietin, Factor VIII, t-PA, etc.)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate therapeutic applications for each listed protein</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch9-q2 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch9-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch9-q2')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Make a chart (with diagrammatic representation) showing a restriction enzyme, the substrate DNA on which it acts, the site at which it cuts DNA and the product it produces.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Action of Restriction Endonuclease <em>EcoRI</em> (from <em>Escherichia coli</em> RY 13):</strong></p>\n  <p><em>EcoRI</em> inspects the length of DNA and recognises a specific 6 base-pair palindromic recognition sequence:</p>\n  \n  <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border:1px solid #cbd5e1; font-family:monospace; margin:10px 0;\">\n    <p style=\"margin:0 0 6px 0; font-weight:700; color:#065f46;\">1. Substrate DNA & Palindromic Recognition Site:</p>\n    5' &mdash;&mdash; G &darr; A &nbsp; A &nbsp; T &nbsp; T &nbsp; C &mdash;&mdash; 3'<br>\n    3' &mdash;&mdash; C &nbsp; T &nbsp; T &nbsp; A &nbsp; A &uarr; G &mdash;&mdash; 5'\n  </div>\n\n  <p><strong>2. Site of Cleavage:</strong></p>\n  <ul>\n    <li><em>EcoRI</em> cuts both strands of the double helix at the same specific point between <strong>G and A bases</strong>, just slightly away from the centre of the symmetry.</li>\n    <li>It cleaves the phosphodiester backbone between Guanine and Adenine on both complementary strands.</li>\n  </ul>\n\n  <div style=\"background:#ecfdf5; padding:12px; border-radius:8px; border-left:4px solid #059669; font-family:monospace; margin:10px 0;\">\n    <p style=\"margin:0 0 6px 0; font-weight:700; color:#065f46;\">3. Resulting Products (Staggered Sticky Ends):</p>\n    Strand 1:&nbsp;&nbsp;5' &mdash;&mdash; G&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;A &nbsp; A &nbsp; T &nbsp; T &nbsp; C &mdash;&mdash; 3'<br>\n    Strand 2:&nbsp;&nbsp;3' &mdash;&mdash; C &nbsp; T &nbsp; T &nbsp; A &nbsp; A&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;G &mdash;&mdash; 5'\n  </div>\n\n  <p><strong>Significance of Sticky Ends:</strong> The single-stranded overhanging overhangs are termed <strong>sticky ends</strong> because they readily form complementary hydrogen bonds with matching sticky ends cut by the same enzyme on vector DNA, facilitating covalent sealing by <strong>DNA ligase</strong> to produce recombinant DNA.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Naming EcoRI and writing correct palindromic recognition sequence (5'-GAATTC-3')</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Indicating cleavage site between G and A on both strands away from center</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Diagrammatic depiction of sticky overhanging ends (5'-AATT-3') and role in ligation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch9-q3 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch9-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch9-q3')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        From what you have learnt, can you tell whether enzymes are bigger or DNA is bigger in molecular size? How did you know?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>DNA is vastly bigger in molecular size, weight, and chain length than an enzyme.</strong></p>\n  <p><strong>Scientific Proof and Comparison:</strong></p>\n  <ol>\n    <li><strong>Chemical Constitution:</strong>\n      <ul>\n        <li><strong>Enzymes:</strong> Enzymes are proteins, which are linear polymers of amino acids. A typical catalytic enzyme (e.g., DNA polymerase or lysozyme) contains roughly 100 to a few thousand amino acids. The average molecular weight of an enzyme ranges between <strong>10,000 to a few hundred thousand Daltons (10<sup>4</sup> to 10<sup>6</sup> Da)</strong>.</li>\n        <li><strong>DNA:</strong> DNA is an enormous polynucleotide macromolecule. A single human chromosome consists of a continuous DNA duplex containing between <strong>50 million to 250 million base pairs</strong>. The molecular mass of a single chromosome DNA reaches <strong>billions of Daltons (10<sup>10</sup> to 10<sup>12</sup> Da)</strong>.</li>\n      </ul>\n    </li>\n    <li><strong>Genetic Relationship (Gene codes for Enzyme):</strong>\n      <ul>\n        <li>DNA carries the instructions to synthesize thousands of different proteins. A single gene on a DNA strand transcribes an mRNA that translates into one enzyme.</li>\n        <li>Since an enzyme is merely the translated expression of a minute fraction (one gene) of a vast genomic DNA macromolecule containing tens of thousands of genes, the master blueprint (DNA) is infinitely larger than any single protein product it specifies.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear statement: DNA is vastly bigger than an enzyme</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Comparison of molecular weights (DNA ~10^10-10^12 Da vs Enzyme ~10^4-10^6 Da)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Rationale that one DNA molecule encodes thousands of distinct protein/enzymes</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch9-q4 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch9-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch9-q4')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What would be the molar concentration of human DNA in a human cell? Consult your teacher.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Step-by-Step Biophysical Calculation:</strong></p>\n  <ol>\n    <li><strong>DNA Content per Human Diploid Cell:</strong>\n      <ul>\n        <li>A human somatic cell contains 46 chromosomes (23 pairs), corresponding to <strong>1 single diploid genomic DNA set (or 46 separate DNA molecules)</strong> per cell.</li>\n      </ul>\n    </li>\n    <li><strong>Volume of a Human Cell:</strong>\n      <ul>\n        <li>The average volume of a spherical mammalian cell (radius <em>r</em> &asymp; 10 &mu;m = 10<sup>-5</sup> m) is:\n          <br>Volume <em>V</em> = (4/3)&pi;r<sup>3</sup> &asymp; (4/3) &times; 3.14 &times; (10<sup>-5</sup>)<sup>3</sup> &asymp; <strong>4.19 &times; 10<sup>-15</sup> m<sup>3</sup> = 4.19 &times; 10<sup>-12</sup> Litres (or ~1–4 pL)</strong>.\n          <br>If considering nuclear volume specifically (radius ~3 &mu;m): <em>V<sub>nucleus</sub></em> &asymp; <strong>1.13 &times; 10<sup>-13</sup> Litres</strong>.\n        </li>\n      </ul>\n    </li>\n    <li><strong>Calculation of Molar Concentration (M = Moles / Volume):</strong>\n      <ul>\n        <li>Number of moles of diploid genome in 1 cell = 1 / Avogadro's Number:\n          <br>Moles = 1 / (6.023 &times; 10<sup>23</sup>) &asymp; <strong>1.66 &times; 10<sup>-24</sup> moles</strong>.</li>\n        <li>Molar Concentration in whole cell:\n          <br>M = (1.66 &times; 10<sup>-24</sup> moles) / (4.19 &times; 10<sup>-12</sup> L) &asymp; <strong>4 &times; 10<sup>-13</sup> M (0.4 picomolar)</strong>.</li>\n        <li>Alternatively, if calculated in terms of total individual <strong>base pairs</strong> (6.6 &times; 10<sup>9</sup> bp per diploid cell):\n          <br>Moles of base pairs = (6.6 &times; 10<sup>9</sup>) / (6.023 &times; 10<sup>23</sup>) &asymp; 1.1 &times; 10<sup>-14</sup> moles.\n          <br>Molar concentration of base pairs in cell &asymp; (1.1 &times; 10<sup>-14</sup>) / (4.19 &times; 10<sup>-12</sup> L) &asymp; <strong>2.6 &times; 10<sup>-3</sup> M = 2.6 mM (millimolar)</strong>.\n        </li>\n      </ul>\n    </li>\n  </ol>\n  <p><strong>Conclusion:</strong> The molar concentration of the diploid human genome is approximately <strong>0.4 pM</strong> (or in terms of nucleotide base pairs, roughly <strong>2.6 mM</strong>).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of moles per cell using Avogadro's number (1 / 6.023 x 10^23)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Estimation of cell/nuclear volume and deriving molarity (~0.4 pM for genome or ~2-3 mM for base pairs)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch9-q5 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch9-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch9-q5')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Do eukaryotic cells have restriction endonucleases? Justify your answer.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>No, eukaryotic cells naturally do NOT have restriction endonucleases.</strong></p>\n  <p><strong>Scientific Justification:</strong></p>\n  <ol>\n    <li><strong>Evolutionary Purpose in Prokaryotes:</strong>\n      <ul>\n        <li>Restriction endonucleases evolved exclusively in bacteria and archaea as a primitive, adaptive <strong>intracellular immune defense mechanism</strong> against bacteriophage (viral) infection.</li>\n        <li>Bacteria synthesize restriction enzymes to cleave incoming foreign viral DNA, while protecting their own genomic DNA from self-digestion through site-specific <strong>DNA methylases</strong> (the Restriction-Modification or R-M system).</li>\n      </ul>\n    </li>\n    <li><strong>Absence and Incompatibility in Eukaryotes:</strong>\n      <ul>\n        <li>Eukaryotic genomic DNA is organized inside a membrane-bound nucleus and intricately packaged with histone proteins into chromatin fibers.</li>\n        <li>Eukaryotic cells have evolved entirely different, sophisticated defense systems against viral and transposable element invaders, such as <strong>RNA interference (RNAi), APOBEC cytidine deaminases, and adaptive cell-mediated immunity</strong>.</li>\n        <li>If restriction endonucleases were present within a eukaryotic nucleus, they would cleave endogenous genomic DNA at every occurrence of their recognition sequence, leading to fatal chromosome fragmentation and cellular death.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definitive negative answer: No, eukaryotic cells lack restriction endonucleases</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Biological role of restriction enzymes as prokaryotic bacterial defense against bacteriophages</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification: Eukaryotes utilize alternative antiviral systems (RNAi, immune cells) and would suffer lethal auto-genomic digestion</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch9-q6 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch9-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch9-q6')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Besides better stirring and oxygen availability, what other advantages have stirred tank bioreactors over shake flasks?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>A <strong>stirred-tank bioreactor</strong> provides an engineered, automated, large-scale (100–1,000 litres) closed culture vessel with multiple decisive bioprocess engineering advantages over small laboratory shake flasks:</p>\n  <ol>\n    <li><strong>Continuous Real-Time Process Monitoring & Control:</strong>\n      <ul>\n        <li>Equipped with automated control systems to continuously monitor and maintain optimal physiological parameters:\n          <ul>\n            <li><strong>Temperature Control:</strong> Steam jacket / cooling coils maintain constant temperature despite metabolic heat generation.</li>\n            <li><strong>pH Automation:</strong> Automatic addition of acid or base to maintain strict pH setpoints.</li>\n            <li><strong>Dissolved Oxygen (DO) Sensors:</strong> Monitors oxygen saturation levels automatically.</li>\n          </ul>\n        </li>\n      </ul>\n    </li>\n    <li><strong>Efficient Foam Management:</strong> Includes an automated <strong>foam control / foam breaker system</strong> to prevent excessive foaming caused by aeration and protein denaturation, which overflows and plugs filters in shake flasks.</li>\n    <li><strong>Aseptic Sampling Ports:</strong> Equipped with sterile sampling ports that permit drawing small culture samples periodically to test optical density, cell viability, and product concentration without breaching sterility or interrupting the fermentation run.</li>\n    <li><strong>Continuous vs Batch Operation:</strong> Can be operated in fed-batch or continuous culture modes (chemostat), maintaining microorganisms in their physiologically active exponential / log phase for maximum biomass and product yield.</li>\n    <li><strong>Massive Scalability:</strong> Allows scaling biological processes from millilitre flask volumes to thousands of litres required for commercial pharmaceutical production.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Precise temperature, pH, and dissolved oxygen automation systems</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Foam control system and sterile sampling ports for real-time monitoring</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ability to run continuous/fed-batch culture and massive industrial scalability (100-1000 L)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch9-q7 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch9-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch9-q7')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Collect 5 examples of palindromic DNA sequences by consulting your teacher. Better try to create a palindromic sequence by following base-pair rules.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>A <strong>palindromic sequence</strong> in DNA is a sequence of base pairs that reads identical on both complementary strands when reading in the same direction (5' &rarr; 3' or 3' &rarr; 5').</p>\n  \n  <p><strong>5 Verified Examples of Restriction Enzyme Palindromes:</strong></p>\n  <div style=\"display:flex; flex-direction:column; gap:10px; margin-top:8px; font-family:monospace; font-size:0.9rem;\">\n    <div style=\"background:#f8fafc; padding:8px 12px; border-left:4px solid #059669; border-radius:4px;\">\n      <strong>1. <em>EcoRI</em> Recognition Palindrome (6 bp):</strong><br>\n      5' &mdash; G &darr; A &nbsp; A &nbsp; T &nbsp; T &nbsp; C &mdash; 3'<br>\n      3' &mdash; C &nbsp; T &nbsp; T &nbsp; A &nbsp; A &uarr; G &mdash; 5'\n    </div>\n    <div style=\"background:#f8fafc; padding:8px 12px; border-left:4px solid #059669; border-radius:4px;\">\n      <strong>2. <em>HindIII</em> Recognition Palindrome (6 bp):</strong><br>\n      5' &mdash; A &darr; A &nbsp; G &nbsp; C &nbsp; T &nbsp; T &mdash; 3'<br>\n      3' &mdash; T &nbsp; T &nbsp; C &nbsp; G &nbsp; A &uarr; A &mdash; 5'\n    </div>\n    <div style=\"background:#f8fafc; padding:8px 12px; border-left:4px solid #059669; border-radius:4px;\">\n      <strong>3. <em>BamHI</em> Recognition Palindrome (6 bp):</strong><br>\n      5' &mdash; G &darr; G &nbsp; A &nbsp; T &nbsp; C &nbsp; C &mdash; 3'<br>\n      3' &mdash; C &nbsp; C &nbsp; T &nbsp; A &nbsp; G &uarr; G &mdash; 5'\n    </div>\n    <div style=\"background:#f8fafc; padding:8px 12px; border-left:4px solid #059669; border-radius:4px;\">\n      <strong>4. <em>SmaI</em> Recognition Palindrome (Blunt cutter, 6 bp):</strong><br>\n      5' &mdash; C &nbsp; C &nbsp; C &darr; G &nbsp; G &nbsp; G &mdash; 3'<br>\n      3' &mdash; G &nbsp; G &nbsp; G &uarr; C &nbsp; C &nbsp; C &mdash; 5'\n    </div>\n    <div style=\"background:#f8fafc; padding:8px 12px; border-left:4px solid #059669; border-radius:4px;\">\n      <strong>5. <em>HaeIII</em> Recognition Palindrome (4 bp):</strong><br>\n      5' &mdash; G &nbsp; G &darr; C &nbsp; C &mdash; 3'<br>\n      3' &mdash; C &nbsp; C &uarr; G &nbsp; G &mdash; 5'\n    </div>\n  </div>\n\n  <p style=\"margin-top:12px;\"><strong>Rule for Designing Custom Palindromes:</strong></p>\n  <p>To create an 8-base-pair palindrome: Choose 4 bases at random for 5'-end (e.g., 5'-<strong>TCGA</strong>...). Write the inverted Watson-Crick complement for the next 4 bases (...<strong>TCGA</strong>-3').</p>\n  <div style=\"background:#ecfdf5; padding:8px 12px; border-left:4px solid #10b981; font-family:monospace; margin-top:4px;\">\n    Custom 8 bp Palindrome:<br>\n    5' &mdash; T &nbsp; C &nbsp; G &nbsp; A &nbsp; T &nbsp; C &nbsp; G &nbsp; A &mdash; 3' &nbsp;&rarr; Inverted: 5' &mdash; A &nbsp; G &nbsp; C &nbsp; T &nbsp; A &nbsp; G &nbsp; C &nbsp; T &mdash; 3'\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition of palindromic sequence in DNA</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing 5 correct biological palindromes with dual strand 5'->3' polarities</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Demonstrating custom creation using complementary base pairing rules</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch8-q8 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch8-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch8-q8')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Can you recall meiosis and indicate at what stage a recombinant DNA is made?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Biological Context:</strong></p>\n  <p>In natural sexual reproduction, recombinant DNA is formed during <strong>Meiosis I</strong>, specifically at the <strong>Pachytene stage of Prophase I</strong>.</p>\n\n  <p><strong>Detailed Meiotic Mechanism:</strong></p>\n  <ol>\n    <li>During the preceding Zygotene stage, homologous maternal and paternal chromosomes pair lengthwise to form bivalents (synaptonemal complex).</li>\n    <li>At the <strong>Pachytene stage</strong>, non-sister chromatids of homologous chromosomes undergo physical exchange of genetic segments called <strong>Crossing Over</strong>.</li>\n    <li>This process is an enzyme-mediated breakage and reciprocal reunion catalyzed by the multi-enzyme complex <strong>Recombinase</strong> (endonucleases and ligases).</li>\n    <li>The breaking, swapping, and re-joining of non-sister chromatid DNA strands creates brand new chimeric combinations of maternal and paternal alleles, producing natural <strong>recombinant DNA</strong> (visualised later at Diplotene as X-shaped chiasmata).</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Meiosis I -> Prophase I -> Pachytene stage</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of crossing over between non-sister chromatids mediated by recombinase enzyme</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch9-q9 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch9-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch9-q9')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Can you think and answer how a reporter enzyme can be used to monitor transformation of host cells by genetically engineered DNA?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>A <strong>reporter enzyme</strong> (encoded by a reporter gene) provides an easily assayable phenotypic signal (such as a colour change, fluorescence, or luminescence) that allows researchers to visually distinguish transformed recombinant host cells from non-recombinants without lethal selection:</p>\n  \n  <p><strong>Classic Example: &beta;-Galactosidase Reporter (Insertional Inactivation / Blue-White Screening):</strong></p>\n  <ol>\n    <li><strong>Vector Construction:</strong> The plasmid vector (e.g., pUC19) carries the reporter gene <strong><em>lacZ</em></strong>, which codes for the enzyme <strong>&beta;-galactosidase</strong>. The multiple cloning site (MCS) is engineered directly inside the coding sequence of <em>lacZ</em>.</li>\n    <li><strong>Non-Recombinant Vector (No foreign insert):</strong>\n      <ul>\n        <li>The <em>lacZ</em> gene remains intact and fully functional.</li>\n        <li>The translated active &beta;-galactosidase hydrolyses a chromogenic substrate (<strong>X-gal</strong>) present in the agar medium, producing a bright blue indole precipitate.</li>\n        <li>Result: Colonies appear <strong>Blue</strong>.</li>\n      </ul>\n    </li>\n    <li><strong>Recombinant Vector (Foreign gene successfully inserted):</strong>\n      <ul>\n        <li>Ligation of foreign DNA into the MCS causes <strong>insertional inactivation</strong> of the <em>lacZ</em> gene.</li>\n        <li>No functional &beta;-galactosidase is produced. The chromogenic substrate X-gal is not hydrolysed.</li>\n        <li>Result: Recombinant transformant colonies appear <strong>White</strong>.</li>\n      </ul>\n    </li>\n  </ol>\n  <p><strong>Conclusion:</strong> White colonies can be directly picked from the plate as confirmed recombinants, eliminating tedious replica plating.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of reporter enzyme: provides detectable phenotypic signal (colour/luminescence)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mechanism of insertional inactivation of reporter gene (e.g. lacZ encoding beta-galactosidase)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Differentiating outcomes on X-gal: Blue colonies (non-recombinants) vs White colonies (successful recombinants)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch9-q10 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch9-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch9-q10')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Describe briefly the following:\n  <br>(a) Origin of replication\n  <br>(b) Bioreactors\n  <br>(c) Downstream processing\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:14px;\">\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">(a) Origin of Replication (ori)</h5>\n      <p style=\"margin:0;\">A specific conserved nucleotide sequence in a DNA molecule or plasmid vector where replication is initiated. Any piece of foreign DNA linked to the <em>ori</em> sequence is replicated along with the host genome. The <em>ori</em> sequence also controls the <strong>copy number</strong> of the linked foreign gene; cloning into a vector whose <em>ori</em> supports high copy numbers ensures massive yield of the recombinant gene.</p>\n    </div>\n\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">(b) Bioreactors</h5>\n      <p style=\"margin:0;\">Large cylindrical vessels (100–1,000 litres) engineered to biologically convert raw substrate materials into specific recombinant proteins or bioactive products using living microbial, plant, or animal cells. They provide optimal growth parameters (temperature, pH, dissolved oxygen, nutrients, and vitamins) through automated agitation impellers, spargers, and monitoring probes.</p>\n    </div>\n\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">(c) Downstream Processing</h5>\n      <p style=\"margin:0;\">The collective series of post-fermentation separation, isolation, and purification processes that convert raw fermented culture broth into a finished, clinically safe, marketable commercial product. It involves cell disruption, centrifugation, membrane ultrafiltration, chromatography, formulation with preservatives, strict quality control testing, and clinical trials for pharmaceutical drugs.</p>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Origin of replication: Sequence initiating replication and controlling vector copy number</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Bioreactors: Large-scale vessels providing automated optimal growth conditions (pH, temp, aeration)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Downstream processing: Post-fermentation recovery, separation, purification, and quality control</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch9-q11 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch9-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch9-q11')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Explain briefly:\n  <br>(a) PCR\n  <br>(b) Restriction enzymes and DNA\n  <br>(c) Chitinase\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:14px;\">\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">(a) Polymerase Chain Reaction (PCR)</h5>\n      <p style=\"margin:0;\">An in vitro molecular technique invented by Kary Mullis (1983) to amplify a specific target segment of DNA into billions of copies in a matter of hours. It proceeds through repeated automated thermal cycles consisting of three steps: <strong>Denaturation</strong> of dsDNA at 94&deg;C, <strong>Annealing</strong> of oligonucleotide primers at 50–60&deg;C, and <strong>Extension</strong> at 72&deg;C catalyzed by a thermostable DNA polymerase (<strong><em>Taq</em> Polymerase</strong> isolated from <em>Thermus aquaticus</em>) using dNTP substrates.</p>\n    </div>\n\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">(b) Restriction Enzymes and DNA</h5>\n      <p style=\"margin:0;\">Bacterial enzymes acting as \"molecular scissors\" that recognize specific short palindromic base sequences (4–8 bp) in double-stranded DNA and hydrolyse the phosphodiester bonds at specific points on both strands. They generate either sticky overhanging ends (e.g., <em>EcoRI, HindIII</em>) or blunt ends (e.g., <em>SmaI</em>), allowing foreign genes and cloning vectors cut with the same enzyme to be seamlessly joined by DNA ligase.</p>\n    </div>\n\n    <div style=\"background:#f8fafc; padding:12px; border-radius:8px; border-left:4px solid #059669;\">\n      <h5 style=\"color:#059669; margin:0 0 4px 0;\">(c) Chitinase</h5>\n      <p style=\"margin:0;\">A hydrolytic enzyme used during DNA isolation to enzymatically digest the tough, rigid chitinaceous cell wall of fungal cells (e.g., yeast or mold), releasing the intact cellular contents and pure genomic DNA for recombinant DNA experiments.</p>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) PCR: In vitro DNA amplification via Denaturation, Annealing, and Taq polymerase Extension</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Restriction enzymes: Molecular scissors cutting palindromic sequences to yield sticky/blunt ends</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Chitinase: Hydrolytic enzyme digesting fungal chitin cell walls to release pure genomic DNA</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch9-q12 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch9-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch9-q12')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Discuss with your teacher and find out how to distinguish between:\n  <br>(a) Plasmid DNA and Chromosomal DNA\n  <br>(b) RNA and DNA\n  <br>(c) Exonuclease and Endonuclease\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:16px;\">\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(a) Plasmid DNA vs Chromosomal DNA</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.9rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:6px 10px; width:50%;\">Plasmid DNA</th>\n          <th style=\"padding:6px 10px; width:50%;\">Chromosomal DNA</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Extra-chromosomal, small, circular double-stranded DNA capable of autonomous replication.</td>\n          <td style=\"padding:6px 10px;\">Primary genomic, massive linear (eukaryotes) or large circular (prokaryotes) master DNA.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:6px 10px;\">Dispersion is dispensable for routine survival; carries accessory traits (e.g., antibiotic resistance). Extensively used as cloning vector.</td>\n          <td style=\"padding:6px 10px;\">Essential for basic metabolism, cell survival, growth, and reproduction.</td>\n        </tr>\n      </table>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(b) RNA vs DNA</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.9rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:6px 10px; width:50%;\">RNA (Ribonucleic Acid)</th>\n          <th style=\"padding:6px 10px; width:50%;\">DNA (Deoxyribonucleic Acid)</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Contains <strong>ribose sugar</strong> (possesses reactive 2'-OH group).</td>\n          <td style=\"padding:6px 10px;\">Contains <strong>2'-deoxyribose sugar</strong> (lacks reactive oxygen at 2' carbon).</td>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Contains the pyrimidine base <strong>Uracil (U)</strong>. Usually single-stranded and chemically labile.</td>\n          <td style=\"padding:6px 10px;\">Contains the pyrimidine base <strong>Thymine (5-methyl uracil)</strong>. Double-stranded and exceptionally stable.</td>\n        </tr>\n      </table>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(c) Exonuclease vs Endonuclease</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.9rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:6px 10px; width:50%;\">Exonuclease</th>\n          <th style=\"padding:6px 10px; width:50%;\">Endonuclease</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Cleaves nucleotides sequentially one-by-one from the terminal free <strong>ends</strong> (5'-end or 3'-end) of a DNA strand.</td>\n          <td style=\"padding:6px 10px;\">Cleaves internal phosphodiester bonds at <strong>specific positions within</strong> the DNA strand.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:6px 10px;\">Cannot generate internal fragments or specific sticky ends for molecular cloning.</td>\n          <td style=\"padding:6px 10px;\">Restriction endonucleases recognize specific palindromes and cut internally, serving as indispensable tools for creating recombinant DNA.</td>\n        </tr>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Plasmid vs Chromosomal DNA (extra-chromosomal autonomous vector vs master genomic blueprint)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) RNA vs DNA (ribose with 2'-OH & Uracil vs deoxyribose & Thymine)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Exonuclease vs Endonuclease (terminal cleavage vs internal cleavage at palindromic sites)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"display:flex; justify-content:space-between; align-items:center; margin-top:36px; padding-top:20px; border-top:1px solid #e2e8f0;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(8)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 8</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(10)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#059669; color:white; font-weight:700; cursor:pointer;\">Next: Ch 10 (Biotechnology and its Applications) →</button>\n  </div>\n</section>";
window.CHAPTER_DATA[10] = "<section class=\"chapter-section\" id=\"c12b-ch10\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#059669;\">10</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#059669;\">CBSE Class 12 Biology &bull; Chapter 10</div>\n      <h2>Biotechnology and its Applications</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 13 Verbatim Questions with Official CBSE Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n<div class=\"chem-card\" style=\"margin-bottom:24px; padding:20px; background:#f0fdf4; border:1px solid #bbf7d0; border-radius:12px;\">\n  <h4 style=\"margin:0 0 12px 0; color:#059669; font-size:1.05rem;\">🧬 Applications of Biotechnology: Eli Lilly Humulin Synthesis & RNAi Mechanism</h4>\n  <svg viewBox=\"0 0 880 300\" style=\"width:100%; max-width:880px; height:auto; display:block; margin:0 auto; background:white; border-radius:8px; border:1px solid #d1fae5;\">\n    <!-- Recombinant Insulin / Eli Lilly -->\n    <rect x=\"20\" y=\"20\" width=\"410\" height=\"260\" rx=\"10\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"225\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Humulin Production (Eli Lilly, 1983)</text>\n    <line x1=\"35\" y1=\"56\" x2=\"415\" y2=\"56\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n\n    <!-- Natural Proinsulin Structure -->\n    <rect x=\"35\" y=\"70\" width=\"165\" height=\"75\" rx=\"6\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n    <text x=\"117\" y=\"88\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#334155\" text-anchor=\"middle\">Mammalian Proinsulin</text>\n    <text x=\"45\" y=\"105\" font-family=\"sans-serif\" font-size=\"9.5\" fill=\"#2563eb\">&bull; Chain A (21 aa)</text>\n    <text x=\"45\" y=\"120\" font-family=\"sans-serif\" font-size=\"9.5\" fill=\"#16a34a\">&bull; Chain B (30 aa)</text>\n    <text x=\"45\" y=\"135\" font-family=\"sans-serif\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#dc2626\">&bull; C-peptide (Extra segment)</text>\n\n    <!-- Arrow -->\n    <line x1=\"205\" y1=\"107\" x2=\"235\" y2=\"107\" stroke=\"#059669\" stroke-width=\"2\"/>\n    <polygon points=\"235,103 243,107 235,111\" fill=\"#059669\"/>\n\n    <!-- Recombinant Route -->\n    <rect x=\"245\" y=\"70\" width=\"170\" height=\"75\" rx=\"6\" fill=\"#dcfce7\" stroke=\"#16a34a\" stroke-width=\"1.5\"/>\n    <text x=\"330\" y=\"88\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#166534\" text-anchor=\"middle\">Eli Lilly Synthetic Route</text>\n    <text x=\"255\" y=\"105\" font-family=\"sans-serif\" font-size=\"9.5\" fill=\"#334155\">&bull; Synthesized DNA for A & B</text>\n    <text x=\"255\" y=\"120\" font-family=\"sans-serif\" font-size=\"9.5\" fill=\"#334155\">&bull; Cloned in separate <em>E. coli</em></text>\n    <text x=\"255\" y=\"135\" font-family=\"sans-serif\" font-size=\"9.5\" fill=\"#334155\">&bull; Chains extracted & purified</text>\n\n    <!-- Disulfide linking -->\n    <rect x=\"100\" y=\"160\" width=\"250\" height=\"55\" rx=\"6\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n    <text x=\"225\" y=\"180\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Mature Active Human Insulin</text>\n    <text x=\"225\" y=\"198\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#1e40af\" text-anchor=\"middle\">Chain A & Chain B linked by <strong>Disulphide (-S-S-) Bonds</strong></text>\n\n    <text x=\"35\" y=\"240\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; Eliminated allergic reactions caused by bovine/porcine insulin</text>\n    <text x=\"35\" y=\"258\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#047857\">C-peptide is NOT present in mature active insulin</text>\n\n    <!-- RNAi & Gene Therapy Card -->\n    <rect x=\"450\" y=\"20\" width=\"410\" height=\"260\" rx=\"10\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <text x=\"655\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">RNA Interference (RNAi) & ADA Therapy</text>\n    <line x1=\"465\" y1=\"56\" x2=\"845\" y2=\"56\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n\n    <text x=\"465\" y=\"78\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#1e40af\">RNAi against Nematode <em>Meloidogyne incognita</em>:</text>\n    <text x=\"465\" y=\"96\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; Vector: <em>Agrobacterium tumefaciens</em> T-DNA</text>\n    <text x=\"465\" y=\"112\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; Introduces nematode-specific genes (Sense + Antisense)</text>\n    <text x=\"465\" y=\"128\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; Forms <strong>double-stranded RNA (dsRNA)</strong> in host tobacco plant</text>\n    <text x=\"465\" y=\"144\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#dc2626\">&bull; Dicer & RISC silence target nematode mRNA &rarr; Pest dies!</text>\n\n    <text x=\"465\" y=\"172\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#059669\">Gene Therapy for ADA Deficiency (SCID):</text>\n    <text x=\"465\" y=\"190\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; First clinical trial: 1990 on a 4-year-old girl</text>\n    <text x=\"465\" y=\"206\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; Lymphocytes cultured in vitro + Retroviral vector</text>\n    <text x=\"465\" y=\"222\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; Functional <strong>ADA cDNA</strong> introduced & returned to patient</text>\n    <text x=\"465\" y=\"238\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; Periodic infusion required (lymphocytes not immortal)</text>\n    <text x=\"465\" y=\"258\" font-family=\"sans-serif\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#047857\">Permanent cure: Introducing gene into bone marrow at early embryonic stages</text>\n  </svg>\n</div>\n\n  <div class=\"ex-div\" style=\"font-size:0.88rem; font-weight:700; color:#334155; margin-bottom:16px; padding:8px 14px; background:#ecfdf5; border-radius:8px; border-left:4px solid #059669;\">NCERT Exercises (13 Verbatim Questions)</div>\n\n  <div class=\"questions-container\">\n    \n  <!-- c12b-ch10-q1 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch10-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch10-q1')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Crystals of Bt toxin produced by some bacteria do not kill the bacteria themselves because &mdash;\n  <br>(a) bacteria are resistant to the toxin\n  <br>(b) toxin is immature;\n  <br>(c) toxin is inactive;\n  <br>(d) bacteria enclose toxin in a special sac.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (c) toxin is inactive</strong></p>\n  <p><strong>Detailed Scientific Explanation:</strong></p>\n  <ul>\n    <li>The bacterium <em>Bacillus thuringiensis</em> produces insecticidal crystalline proteins during sporulation known as <strong>Bt toxin crystals</strong>.</li>\n    <li>Inside the bacterial cell, this toxin exists harmlessly as an <strong>inactive protoxin (prototoxin)</strong>. It requires an alkaline environment and specific endoproteases to undergo activation.</li>\n    <li>Because the bacterial intracellular cytoplasm has a neutral pH, the toxin remains completely inert and crystalline, causing zero harm to the bacterium.</li>\n    <li>When a susceptible insect (e.g., lepidopteran bollworm) ingests the crop tissue, the <strong>alkaline pH of the insect midgut</strong> solubilises the crystals, and gut proteases cleave the protoxin into its active, lethal toxic conformation. The active toxin binds to surface receptors of midgut epithelial cells, creating pores that cause cell swelling, lysis, and death of the insect pest.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct choice: (c) toxin is inactive</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation: Exists as inactive protoxin requiring alkaline gut pH to solubilise and activate</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch10-q2 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch10-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch10-q2')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What are transgenic bacteria? Illustrate using any one example.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition:</strong></p>\n  <p><strong>Transgenic bacteria</strong> (genetically modified bacteria) are bacterial cells whose genome has been stably altered by the introduction and functional integration of a foreign gene (transgene) using recombinant DNA technology, enabling them to synthesize a specific heterologous protein.</p>\n\n  <p><strong>Classic Example: Transgenic <em>Escherichia coli</em> for Human Insulin (Humulin) Production:</strong></p>\n  <ol>\n    <li>In 1983, the American pharmaceutical company <strong>Eli Lilly</strong> prepared two synthetic DNA oligonucleotide sequences corresponding to the <strong>A chain (21 amino acids)</strong> and <strong>B chain (30 amino acids)</strong> of human insulin.</li>\n    <li>These synthetic DNA sequences were linked to the &beta;-galactosidase gene and separately introduced into plasmid vectors of <em>Escherichia coli</em>.</li>\n    <li>The transgenic <em>E. coli</em> bacteria were cultured in large bioreactors to express individual insulin chains A and B.</li>\n    <li>The chains were extracted, purified, and joined together chemically by creating synthetic <strong>disulphide (-S-S-) bonds</strong> to produce active human insulin (Humulin).</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition of transgenic bacteria (bacterial cells harboring foreign recombinant gene)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Detailed illustration: Eli Lilly transgenic E. coli synthesizing human insulin A and B chains</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Extraction and covalent disulphide bonding to yield functional Humulin</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch10-q3 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch10-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch10-q3')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Compare and contrast the advantages and disadvantages of production of genetically modified crops.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Genetically Modified (GM) crops carry beneficial foreign genes to confer targeted agronomic traits, but also pose potential ecological and health concerns:</p>\n  \n  <div style=\"display:flex; flex-direction:column; gap:16px; margin-top:10px;\">\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">1. Major Advantages of GM Crops</h5>\n      <ul style=\"margin:0; padding-left:20px;\">\n        <li><strong>Enhanced Tolerance to Abiotic Stresses:</strong> Engineered to withstand harsh environmental extremes (drought, cold, frost, heat, and soil salinity).</li>\n        <li><strong>Built-In Pest Resistance:</strong> Transgenic crops like <strong>Bt Cotton</strong> produce their own insecticidal Cry proteins, dramatically reducing reliance on harmful chemical pesticides.</li>\n        <li><strong>Reduction in Post-Harvest Losses:</strong> Delayed fruit softening (e.g., Flavr Savr tomato via polygalacturonase antisense inhibition) extends shelf-life and reduces transport wastage.</li>\n        <li><strong>Enhanced Nutritional Value:</strong> Biofortified crops, such as <strong>Golden Rice</strong> enriched with provitamin A (&beta;-carotene), directly combat nutritional blindness in developing countries.</li>\n        <li><strong>Increased Mineral Usage Efficiency:</strong> Prevents early exhaustion of soil fertility by enabling crops to utilize micronutrients more efficiently.</li>\n      </ul>\n    </div>\n\n    <div>\n      <h5 style=\"color:#dc2626; margin:0 0 6px 0;\">2. Potential Disadvantages & Concerns of GM Crops</h5>\n      <ul style=\"margin:0; padding-left:20px;\">\n        <li><strong>Emergence of \"Superweeds\":</strong> Risk of transgene escape via accidental cross-pollination between herbicide-resistant GM crops and wild relatives.</li>\n        <li><strong>Threat to Non-Target Biodiversity:</strong> Secretion of insecticidal proteins into soil or nectar could potentially harm beneficial pollinators (honeybees) or soil organisms.</li>\n        <li><strong>Risk of Allergenicity in Humans:</strong> Introducing novel viral or bacterial genes may express uncharacterised proteins that provoke food allergies.</li>\n        <li><strong>Corporate Monopolisation & Terminator Seeds:</strong> Multinationals patenting seed technologies and using Genetic Use Restriction Technology (terminator genes) forces farmers to repurchase seeds every season.</li>\n      </ul>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Key advantages: Pest resistance (Bt), abiotic stress tolerance, reduced post-harvest losses, biofortification (Golden rice)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Key disadvantages: Emergence of superweeds, harm to non-target pollinators, potential allergenicity, corporate seed monopoly</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch10-q4 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch10-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch10-q4')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What are Cry proteins? Name an organism that produce it. How has man exploited this protein to his benefit?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>1. Definition & Producing Organism:</strong></p>\n  <ul>\n    <li><strong>Cry proteins</strong> (Crystal endotoxins) are toxic crystalline proteinaceous parasporal inclusions encoded by <em>cry</em> genes.</li>\n    <li>They are naturally produced by the soil bacterium <strong><em>Bacillus thuringiensis</em> (Bt)</strong> during its sporulation phase.</li>\n  </ul>\n\n  <p><strong>2. Exploitation in Agricultural Biotechnology:</strong></p>\n  <ol>\n    <li>Specific <em>cry</em> genes were isolated from <em>Bacillus thuringiensis</em> and cloned into crop plants (e.g., cotton, corn, brinjal, potato) using <em>Agrobacterium tumefaciens</em> plasmid vectors:\n      <ul>\n        <li><strong><em>cryIAc</em> and <em>cryIIAb</em>:</strong> Effectively control <strong>cotton bollworms</strong>.</li>\n        <li><strong><em>cryIAb</em>:</strong> Specifically controls <strong>corn borers</strong>.</li>\n      </ul>\n    </li>\n    <li><strong>Transgenic Resistance Mechanism:</strong>\n      <ul>\n        <li>When insects chew on the transgenic crop tissues, they ingest the protoxin crystals.</li>\n        <li>The protoxin is solubilised in the <strong>alkaline insect midgut</strong>, where gut proteases cleave it into its active toxic form.</li>\n        <li>The activated toxin binds to receptors on midgut epithelial cells, forms lytic trans-membrane pores, causing osmotic swelling, cell lysis, and starvation-induced death of the pest.</li>\n      </ul>\n    </li>\n    <li><strong>Human Benefit:</strong> Created high-yielding, pest-resistant crops (e.g., <strong>Bt Cotton</strong>), saving billions of dollars in crop losses, eliminating toxic synthetic pesticide spraying, and protecting farmworkers.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of Cry proteins and naming Bacillus thuringiensis (Bt)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Specific cry genes listed: cryIAc & cryIIAb (cotton bollworms) and cryIAb (corn borer)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mechanism of pest control in alkaline gut creating Bt crops and reducing chemical sprays</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch10-q5 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch10-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch10-q5')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What is gene therapy? Illustrate using the example of adenosine deaminase (ADA) deficiency.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition:</strong></p>\n  <p><strong>Gene therapy</strong> is a revolutionary collection of clinical methods that allows the correction of a hereditary genetic defect by inserting a normal, functional copy of a gene into the cells and tissues of an individual to take over the function of and compensate for the non-functional mutant gene.</p>\n\n  <p><strong>Illustration: Adenosine Deaminase (ADA) Deficiency (SCID):</strong></p>\n  <ol>\n    <li><strong>Etiology:</strong> ADA deficiency is caused by the deletion or mutation of the gene coding for the enzyme adenosine deaminase. The lack of ADA leads to accumulation of toxic deoxyadenosine, destroying mature T and B lymphocytes and causing <strong>Severe Combined Immunodeficiency (SCID)</strong> (\"bubble boy\" disease).</li>\n    <li><strong>Historic Gene Therapy Procedure (1990):</strong>\n      <ul>\n        <li>In 1990, the first clinical gene therapy was performed by French Anderson and colleagues on a <strong>4-year-old girl</strong> suffering from ADA deficiency.</li>\n        <li>Lymphocytes were harvested from the peripheral blood of the patient and cultured in vitro in the laboratory.</li>\n        <li>A functional human <strong>ADA cDNA</strong> was introduced into these cultured lymphocytes using a disarmed <strong>retroviral vector</strong>.</li>\n        <li>The genetically engineered lymphocytes expressing functional ADA were re-infused into the young patient's bloodstream.</li>\n      </ul>\n    </li>\n    <li><strong>Limitation & Permanent Cure:</strong>\n      <ul>\n        <li>Because mature lymphocytes have a finite lifespan and are not immortal, the patient requires periodic, lifelong re-infusions of genetically engineered cells.</li>\n        <li><strong>Permanent Cure:</strong> If the functional ADA gene isolated from healthy bone marrow is introduced into recipient cells at <strong>early embryonic stages</strong>, it provides a complete, lifelong permanent cure.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear definition of gene therapy (introducing functional gene to correct genetic defect)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clinical basis of ADA deficiency causing SCID (destruction of immune lymphocytes)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clinical protocol: Culturing lymphocytes, inserting ADA cDNA via retroviral vector, and reinfusion</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Need for periodic re-infusions vs permanent embryonic gene correction</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch10-q6 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch10-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch10-q6')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Diagrammatically represent the experimental steps in cloning and expressing an human gene (say for growth hormone) into a bacterium like E. coli?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Step-by-Step Experimental Protocol for Expressing Human Growth Hormone (hGH) in <em>E. coli</em>:</strong></p>\n  \n  <div style=\"background:#f8fafc; padding:14px; border-radius:8px; border:1px solid #cbd5e1; margin:10px 0; font-size:0.92rem;\">\n    <ol style=\"margin:0; padding-left:20px; display:flex; flex-direction:column; gap:8px;\">\n      <li><strong>1. Isolation of Human Gene (cDNA):</strong> Human pituitary mRNA is reverse-transcribed to yield pure hGH cDNA (devoid of eukaryotic non-coding introns).</li>\n      <li><strong>2. Cleavage of Plasmid Vector & Gene:</strong> The cloning vector (plasmid pBR322 / pUC) and the human hGH cDNA are digested with the <strong>same restriction endonuclease</strong> (e.g., <em>EcoRI</em>) to generate matching cohesive sticky ends.</li>\n      <li><strong>3. Formation of Recombinant DNA:</strong> The cleaved vector and human cDNA fragment are incubated together in the presence of <strong>DNA ligase</strong> to covalently seal the phosphodiester bonds, yielding the <strong>recombinant plasmid</strong>.</li>\n      <li><strong>4. Transformation into Host:</strong> Recombinant plasmids are introduced into competent <em>E. coli</em> bacterial cells made permeable by ice-cold CaCl<sub>2</sub> treatment followed by a brief heat-shock at 42&deg;C.</li>\n      <li><strong>5. Selection of Transformants:</strong> Transformed bacterial colonies are selected using selectable antibiotic markers (e.g., ampicillin/tetracycline resistance or blue-white screening).</li>\n      <li><strong>6. Mass Expression in Bioreactor:</strong> Selected recombinant <em>E. coli</em> clones are cultured in large-scale stirred-tank bioreactors under controlled induction, expressing high yields of recombinant Human Growth Hormone.</li>\n      <li><strong>7. Downstream Processing:</strong> Lysis of bacterial cells, chromatographic purification, and formulation into injectable clinical somatotropin.</li>\n    </ol>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Isolation of human gene (cDNA) and cutting vector with same restriction enzyme</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ligation with DNA ligase producing recombinant plasmid</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Transformation of competent E. coli host cells (CaCl2 / heat shock) and selectable marker screening</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Bioreactor cultivation, expression of recombinant hGH, and downstream purification</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch10-q7 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch10-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch10-q7')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Can you suggest a method to remove oil (hydrocarbon) from seeds based on your understanding of rDNA technology and chemistry of oil?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Biochemical & Genetic Engineering Strategy:</strong></p>\n  <ol>\n    <li><strong>Chemistry of Seed Oil:</strong>\n      <ul>\n        <li>Seed oils are triacylglycerols (triglycerides) synthesized through the glycerol-3-phosphate / Kennedy pathway.</li>\n        <li>Glycerol is esterified with three fatty acid chains, catalyzed sequentially by key rate-limiting enzymes such as <strong>Glycerol-3-phosphate acyltransferase (GPAT)</strong> and <strong>Diacylglycerol acyltransferase (DGAT)</strong>.</li>\n      </ul>\n    </li>\n    <li><strong>Targeted Gene Silencing via RNA Interference (RNAi):</strong>\n      <ul>\n        <li>Isolate the cDNA sequence coding for the critical rate-limiting enzyme <strong>Diacylglycerol acyltransferase (DGAT)</strong>.</li>\n        <li>Clone both the sense and antisense fragments of this gene into a plant expression vector under the control of a <strong>seed-specific promoter</strong> (such as the napin or phaseolin promoter).</li>\n        <li>Transform oil-seed plants (e.g., soybean, canola, or sunflower) using <em>Agrobacterium tumefaciens</em>.</li>\n        <li>During seed maturation, transcription of both strands forms a <strong>hairpin double-stranded RNA (dsRNA)</strong> in the developing embryonic cotyledons.</li>\n        <li>Dicer cleaves dsRNA into small interfering RNAs (siRNAs), which program the RISC complex to cleave and degrade the endogenous mRNA of DGAT.</li>\n      </ul>\n    </li>\n    <li><strong>Result:</strong> Silencing DGAT eliminates triglyceride assembly specifically within the seed tissues without affecting vegetative plant growth. The carbon flux is redirected towards starch or protein accumulation, yielding oil-free / low-fat seeds.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of biochemical target: Triacylglycerol synthesis pathway enzymes (DGAT/GPAT)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Application of RNA interference (RNAi) with seed-specific promoter</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formation of dsRNA silencing DGAT mRNA, producing oil-free/low-fat seeds</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch10-q8 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch10-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch10-q8')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Find out on the internet what is golden rice.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Golden Rice</strong> is a genetically biofortified variety of rice (<em>Oryza sativa</em>) engineered to synthesize and accumulate <strong>&beta;-carotene (provitamin A)</strong> in the edible starchy endosperm of the grain, giving the milled grain a characteristic golden-yellow colour.</p>\n\n  <p><strong>Key Scientific Highlights:</strong></p>\n  <ol>\n    <li><strong>Inventors & Genetic Architecture:</strong>\n      <ul>\n        <li>Developed by <strong>Ingo Potrykus and Peter Beyer</strong> in 1999.</li>\n        <li>Wild rice naturally synthesizes &beta;-carotene in its green photosynthetic leaves, but the biosynthetic pathway is switched off in the endosperm.</li>\n        <li>Two exogenous genes encoding the enzymes of the carotenoid biosynthetic pathway were introduced into the rice genome:\n          <ul>\n            <li><strong><em>psy</em> (Phytoene Synthase):</strong> Sourced from daffodil (<em>Narcissus pseudonarcissus</em>) or maize.</li>\n            <li><strong><em>crtI</em> (Phytoene Desaturase):</strong> Sourced from the soil bacterium <em>Pantoea ananatis</em> (formerly <em>Erwinia uredovora</em>).</li>\n          </ul>\n        </li>\n      </ul>\n    </li>\n    <li><strong>Humanitarian Mission:</strong>\n      <ul>\n        <li>Developed to combat <strong>Vitamin A Deficiency (VAD)</strong> in poverty-stricken populations across Southeast Asia and Africa where rice is the primary staple food.</li>\n        <li>VAD is the leading cause of preventable childhood blindness (xerophthalmia) and increases mortality from childhood diarrhoeal infections.</li>\n        <li>Inside the human body, consumed &beta;-carotene is cleaved by intestinal mucosal enzymes into active <strong>Vitamin A (retinol)</strong>.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of Golden Rice as biofortified rice engineered to accumulate provitamin A (beta-carotene)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of cloned genes: Phytoene synthase (psy) and Phytoene desaturase (crtI)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clinical goal: Combating Vitamin A deficiency (VAD) and preventing childhood blindness/xerophthalmia</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch10-q9 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch10-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch10-q9')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Does our blood have proteases and nucleases? If yes, why don't they digest our proteins and nucleic acids?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Yes, human blood contains proteases and nucleases.</strong></p>\n  \n  <p><strong>1. Presence of Enzymes in Blood:</strong></p>\n  <ul>\n    <li><strong>Proteases in Blood:</strong> The blood plasma contains numerous serine proteases that drive the blood coagulation cascade (e.g., <em>Prothrombin, Factor X, Factor IX, Factor VII</em>), fibrinolytic enzymes (<em>Plasmin</em>), and the complement system cascade (<em>C1r, C1s</em>).</li>\n    <li><strong>Nucleases in Blood:</strong> Circulating blood contains trace amounts of secretory deoxyribonucleases (e.g., <strong>Serum DNase I</strong>) and ribonucleases (<strong>RNase 1</strong>) responsible for clearing extracellular cell-free DNA and RNA fragments released from apoptotic cells.</li>\n  </ul>\n\n  <p><strong>2. Why They Do Not Digest Our Own Body Proteins and Nucleic Acids:</strong></p>\n  <ol>\n    <li><strong>Synthesis as Inactive Zymogens (Pro-enzymes):</strong> Coagulation and complement proteases circulate in the bloodstream strictly as inactive pro-enzymes (zymogens). They are activated exclusively at localized sites of vascular injury through a highly regulated cascade of cofactor triggers.</li>\n    <li><strong>High Concentration of Endogenous Protease Inhibitors:</strong> Normal blood plasma contains massive concentrations of circulating antiproteases (such as <strong>&alpha;<sub>1</sub>-antitrypsin, &alpha;<sub>2</sub>-macroglobulin, Antithrombin III</strong>) that instantly bind and neutralize any free active proteases.</li>\n    <li><strong>Membrane Compartmentalisation & Protection of Nucleic Acids:</strong> Cellular DNA and RNA are strictly sequestered inside intact lipid bilayer plasma membranes and nuclear envelopes, physically shielded from extracellular nucleases. Extracellular serum nucleases only degrade foreign viral nucleic acids and debris from ruptured apoptotic cells.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmation: Yes, blood contains proteases (coagulation factors) and nucleases (serum DNase/RNase)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Inactive zymogen form and presence of powerful plasma antiproteases (alpha-1-antitrypsin, antithrombin III)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Compartmentalisation: Host nucleic acids protected inside intact cell/nuclear membranes</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch10-q10 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch10-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch10-q10')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Consult internet and find out how to make orally active protein pharmaceutical. What is the major problem to be encountered?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>The Major Problem Encountered with Oral Protein Pharmaceuticals:</strong></p>\n  <ol>\n    <li><strong>Enzymatic Gastrointestinal Proteolysis:</strong> Proteins are biological polymers of amino acids. When ingested orally, powerful gastric proteases (pepsin in stomach at pH 1.5–2) and pancreatic proteases (trypsin, chymotrypsin, carboxypeptidases at alkaline pH in small intestine) rapidly hydrolyse peptide bonds, completely denaturing and degrading the therapeutic protein into inactive fragments.</li>\n    <li><strong>Poor Epithelial Permeability & Bioavailability:</strong> Proteins are large, hydrophilic macromolecules unable to cross the lipophilic intestinal epithelial cell membrane or mucosal tight junctions to reach the bloodstream intact.</li>\n    <li><strong>Hepatic First-Pass Metabolism:</strong> Any minor amount absorbed into mesenteric capillaries is routed via portal circulation directly to the liver, where it undergoes extensive degradation.</li>\n  </ol>\n\n  <p><strong>Modern Biotechnology Approaches to Engineer Orally Active Proteins:</strong></p>\n  <ul>\n    <li><strong>Enteric Polymer Coating:</strong> Encapsulating the protein inside pH-sensitive acid-resistant polymers (e.g., methacrylic acid co-polymers) that remain insoluble in acidic gastric juice (pH &lt; 3) but dissolve selectively in the neutral/alkaline small intestine (pH &gt; 6.5).</li>\n    <li><strong>Liposomal & Nanoparticle Encapsulation:</strong> Packaging the therapeutic protein inside biocompatible lipid nanocarriers (liposomes, solid lipid nanoparticles) or biodegradable polymer matrices (PLGA) that shield the protein from digestive enzymes and enhance mucosal endocytosis.</li>\n    <li><strong>Co-administration with Protease Inhibitors & Permeation Enhancers:</strong> Formulating the drug alongside transient intestinal permeability enhancers (e.g., sodium caprate, bile salts) and safe enzyme inhibitors that reversibly loosen tight junctions for systemic absorption.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Major problems: Enzymatic degradation by stomach/pancreatic proteases and poor intestinal epithelial permeability</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Modern solutions: Enteric acid-resistant polymer coating, liposome/PLGA nanoparticle encapsulation, and permeation enhancers</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch10-q11 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch10-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch10-q11')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Re-combinant DNA technology has simplified the process of finding out the structure of a gene and its function. How?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Recombinant DNA (rDNA) technology has revolutionized molecular genetics by providing powerful analytical tools to dissect gene structure and assign cellular functions:</p>\n  <ol>\n    <li><strong>Molecular Cloning and Gene Amplification:</strong>\n      <ul>\n        <li>Before rDNA technology, isolating a single gene from a eukaryotic genome containing billions of base pairs was practically impossible.</li>\n        <li>rDNA technology allows a target DNA segment to be cleaved with restriction enzymes, ligated into a plasmid vector, and cloned in bacteria, or exponentially amplified using <strong>Polymerase Chain Reaction (PCR)</strong>, yielding milligram quantities of ultra-pure gene fragments.</li>\n      </ul>\n    </li>\n    <li><strong>High-Speed Sanger & Next-Generation DNA Sequencing:</strong>\n      <ul>\n        <li>Pure cloned gene fragments can be readily sequenced using dideoxy chain termination methods, directly revealing the complete primary nucleotide sequence (exons, introns, promoter TATA boxes, and termination signals).</li>\n      </ul>\n    </li>\n    <li><strong>Site-Directed Mutagenesis:</strong>\n      <ul>\n        <li>Geneticists can introduce precise, premeditated point mutations into specific base pairs of the cloned gene in vitro and express it in host cells to observe functional alterations in the translated protein (e.g., identifying catalytic active-site amino acids).</li>\n      </ul>\n    </li>\n    <li><strong>Gene Knockout & RNA Interference (RNAi):</strong>\n      <ul>\n        <li>Specific genes can be selectively disrupted (\"knocked out\") in model transgenic organisms (e.g., knockout mice) or silenced post-transcriptionally via <strong>RNAi</strong>. The resulting phenotypic deficiencies directly reveal the natural physiological role and function of the gene.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Gene isolation, cloning into vectors, and PCR amplification yielding pure copies</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Nucleotide sequencing revealing exact gene anatomy (exons, introns, regulatory promoters)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Functional characterisation via site-directed mutagenesis, gene knockouts, and RNAi silencing</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch10-q12 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch10-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch10-q12')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Why are transgenic animals produced? Mention any four areas where they are used.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Transgenic animals</strong> are animals that have had their DNA manipulated to carry and stably express a foreign gene (transgene) across successive generations. Over 95% of all existing transgenic animals are mice.</p>\n\n  <p><strong>Four Major Areas of Production & Utilisation:</strong></p>\n  <ol>\n    <li><strong>Normal Physiology and Development:</strong>\n      <ul>\n        <li>Engineered to study how specific genes are regulated and how they affect normal bodily development and growth factors (e.g., studying the biological role of Insulin-like Growth Factor - IGF).</li>\n      </ul>\n    </li>\n    <li><strong>Study of Human Disease Pathology:</strong>\n      <ul>\n        <li>Transgenic models serve as living animal models for investigating the onset and progression of incurable human diseases and testing new gene therapies (e.g., transgenic animal models for <strong>cancer, cystic fibrosis, rheumatoid arthritis, and Alzheimer's disease</strong>).</li>\n      </ul>\n    </li>\n    <li><strong>Production of Biological Products (Molecular Pharming):</strong>\n      <ul>\n        <li>Transgenic animals are engineered to produce valuable human therapeutic proteins in their milk:\n          <ul>\n            <li>Transgenic sheep producing <strong>&alpha;-1-antitrypsin</strong> used for treating emphysema.</li>\n            <li>In 1997, the first transgenic cow, <strong>Rosie</strong>, produced human protein-enriched milk (2.4 grams per litre) containing <strong>human &alpha;-lactalbumin</strong>, providing a more nutritionally balanced milk for human infants than natural cow milk.</li>\n          </ul>\n        </li>\n      </ul>\n    </li>\n    <li><strong>Vaccine Safety & Chemical Toxicity Testing:</strong>\n      <ul>\n        <li>Transgenic mice are developed for testing the safety of vaccines (e.g., Polio vaccine) before human trials. Transgenic animals carrying genes making them more sensitive to toxins are used for rapid toxicity safety testing.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of transgenic animals (manipulated genome expressing foreign transgene)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Four areas: 1. Normal physiology/development, 2. Human disease models (cancer/Alzheimer's)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">3. Biological products (Rosie cow producing alpha-lactalbumin / alpha-1-antitrypsin for emphysema)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">4. Vaccine safety (polio testing in mice) and chemical toxicity testing</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch10-q13 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch10-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch10-q13')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What are the ethical issues associated with biotechnology?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Genetic engineering manipulates living organisms and ecosystems across species boundaries, raising significant bioethical, safety, and socioeconomic challenges:</p>\n  <ol>\n    <li><strong>Disruption of Natural Order & Animal Welfare:</strong>\n      <ul>\n        <li>Altering the genetic makeup of animals and creating chimera models crosses natural species barriers. Subjecting animals to genetic deformities, painful chronic diseases, or commercial exploitation raises serious ethical concerns regarding animal suffering and intrinsic rights.</li>\n      </ul>\n    </li>\n    <li><strong>Unforeseen Ecological Consequences:</strong>\n      <ul>\n        <li>The environmental release of genetically modified organisms (GMOs) may trigger unpredictable ecological consequences (e.g., gene flow to wild weeds creating uncontrollable \"superweeds\", toxicity to non-target pollinators, and loss of indigenous landrace biodiversity).</li>\n      </ul>\n    </li>\n    <li><strong>Biopiracy & Corporate Monopolisation:</strong>\n      <ul>\n        <li><strong>Biopiracy</strong> is the unauthorized commercial exploitation and patenting of bioresources, indigenous crops, and traditional ethnic knowledge of developing nations by wealthy multinational corporations without authentic consent or fair benefit sharing (e.g., foreign patents attempted on <strong>Basmati rice (Texas company RiceTec), Neem, and Turmeric</strong>).</li>\n      </ul>\n    </li>\n    <li><strong>Regulatory Governance (Role of GEAC):</strong>\n      <ul>\n        <li>To address these concerns, the Government of India established the <strong>Genetic Engineering Appraisal Committee (GEAC)</strong> under the Ministry of Environment and Forests, responsible for evaluating the ethical validity of GMO research and deciding the biosafety clearance of introducing GM organisms into the public domain.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Ethical concerns regarding animal suffering, rights, and crossing natural species boundaries</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ecological hazards of GMO release (superweeds, harm to non-target biodiversity)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Biopiracy (patenting Basmati rice/neem/turmeric) and regulatory role of GEAC in India</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"display:flex; justify-content:space-between; align-items:center; margin-top:36px; padding-top:20px; border-top:1px solid #e2e8f0;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(9)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 9</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(11)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#059669; color:white; font-weight:700; cursor:pointer;\">Next: Ch 11 (Organisms and Populations) →</button>\n  </div>\n</section>";
window.CHAPTER_DATA[11] = "<section class=\"chapter-section\" id=\"c12b-ch11\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#059669;\">11</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#059669;\">CBSE Class 12 Biology &bull; Chapter 11</div>\n      <h2>Organisms and Populations</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 18 Verbatim Questions with Official CBSE Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n<div class=\"chem-card\" style=\"margin-bottom:24px; padding:20px; background:#f0fdf4; border:1px solid #bbf7d0; border-radius:12px;\">\n  <h4 style=\"margin:0 0 12px 0; color:#059669; font-size:1.05rem;\">🧬 Population Ecology Map: Growth Curves, Age Pyramids & Interspecific Interactions</h4>\n  <svg viewBox=\"0 0 880 300\" style=\"width:100%; max-width:880px; height:auto; display:block; margin:0 auto; background:white; border-radius:8px; border:1px solid #d1fae5;\">\n    <!-- Growth Curves -->\n    <rect x=\"20\" y=\"20\" width=\"280\" height=\"260\" rx=\"10\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"160\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Population Growth Models</text>\n    <line x1=\"35\" y1=\"56\" x2=\"285\" y2=\"56\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n\n    <!-- Graph axes -->\n    <line x1=\"50\" y1=\"210\" x2=\"260\" y2=\"210\" stroke=\"#334155\" stroke-width=\"2\"/>\n    <line x1=\"50\" y1=\"210\" x2=\"50\" y2=\"70\" stroke=\"#334155\" stroke-width=\"2\"/>\n    <text x=\"250\" y=\"225\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#334155\">Time (t)</text>\n    <text x=\"35\" y=\"80\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#334155\" transform=\"rotate(-90 35,80)\">Density (N)</text>\n\n    <!-- Carrying Capacity K -->\n    <line x1=\"50\" y1=\"120\" x2=\"260\" y2=\"120\" stroke=\"#dc2626\" stroke-width=\"1.5\" stroke-dasharray=\"4,4\"/>\n    <text x=\"265\" y=\"124\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#dc2626\">K</text>\n\n    <!-- Exponential curve (J-shaped) -->\n    <path d=\"M 50 205 Q 150 200, 190 75\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"2.5\"/>\n    <text x=\"195\" y=\"85\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#2563eb\">dN/dt = rN</text>\n\n    <!-- Logistic curve (Sigmoid / S-shaped) -->\n    <path d=\"M 50 205 Q 110 200, 140 160 Q 170 125, 250 122\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2.5\"/>\n    <text x=\"150\" y=\"150\" font-family=\"sans-serif\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#166534\">dN/dt = rN(K-N)/K</text>\n\n    <text x=\"50\" y=\"245\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#2563eb\">&bull; J-shape: Unlimited resources</text>\n    <text x=\"50\" y=\"262\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#16a34a\">&bull; S-shape: Realistic carrying capacity (K)</text>\n\n    <!-- Age Pyramids Card -->\n    <rect x=\"320\" y=\"20\" width=\"260\" height=\"260\" rx=\"10\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <text x=\"450\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Human Age Pyramids</text>\n    <line x1=\"335\" y1=\"56\" x2=\"565\" y2=\"56\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n\n    <!-- Triangular / Expanding -->\n    <polygon points=\"340,160 380,75 420,160\" fill=\"#bbf7d0\" stroke=\"#16a34a\" stroke-width=\"1.5\"/>\n    <text x=\"380\" y=\"180\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#166534\" text-anchor=\"middle\">Expanding</text>\n    <text x=\"380\" y=\"195\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#334155\" text-anchor=\"middle\">Pre-rep &gt; Rep</text>\n\n    <!-- Bell-shaped / Stable -->\n    <path d=\"M 440 160 L 455 100 Q 475 75, 495 100 L 510 160 Z\" fill=\"#fed7aa\" stroke=\"#ea580c\" stroke-width=\"1.5\"/>\n    <text x=\"475\" y=\"180\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#c2410c\" text-anchor=\"middle\">Stable</text>\n    <text x=\"475\" y=\"195\" font-family=\"sans-serif\" font-size=\"9\" fill=\"#334155\" text-anchor=\"middle\">Pre-rep = Rep</text>\n\n    <text x=\"335\" y=\"230\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Pre-reproductive:</strong> 0&ndash;14 years</text>\n    <text x=\"335\" y=\"246\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Reproductive:</strong> 15&ndash;44 years</text>\n    <text x=\"335\" y=\"262\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Post-reproductive:</strong> 45+ years</text>\n\n    <!-- Interspecific Interactions Card -->\n    <rect x=\"600\" y=\"20\" width=\"260\" height=\"260\" rx=\"10\" fill=\"#fef2f2\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n    <text x=\"730\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">Interspecific Interactions</text>\n    <line x1=\"615\" y1=\"56\" x2=\"845\" y2=\"56\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n\n    <text x=\"615\" y=\"80\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\"><strong>Mutualism:</strong> (+ , +) &bull; Lichen, Mycorrhiza</text>\n    <text x=\"615\" y=\"105\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\"><strong>Competition:</strong> (- , -) &bull; Gause's Principle</text>\n    <text x=\"615\" y=\"130\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\"><strong>Predation:</strong> (+ , -) &bull; Tiger & Deer</text>\n    <text x=\"615\" y=\"155\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\"><strong>Parasitism:</strong> (+ , -) &bull; Cuscuta, Liver fluke</text>\n    <text x=\"615\" y=\"180\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\"><strong>Commensalism:</strong> (+ , 0) &bull; Orchid on Mango</text>\n    <text x=\"615\" y=\"205\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\"><strong>Amensalism:</strong> (- , 0) &bull; <em>Penicillium</em> & Bacteria</text>\n\n    <text x=\"615\" y=\"240\" font-family=\"sans-serif\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#991b1b\">Allen's Rule: Shorter ears/limbs in cold</text>\n    <text x=\"615\" y=\"258\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#047857\">Resource Partitioning: MacArthur's warblers</text>\n  </svg>\n</div>\n\n  <div class=\"ex-div\" style=\"font-size:0.88rem; font-weight:700; color:#334155; margin-bottom:16px; padding:8px 14px; background:#ecfdf5; border-radius:8px; border-left:4px solid #059669;\">NCERT Exercises (18 Verbatim Questions)</div>\n\n  <div class=\"questions-container\">\n    \n  <!-- c12b-ch11-q1 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q1')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        How is diapause different from hibernation?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Both diapause and hibernation represent physiological adaptations of organisms to avoid stressful environmental conditions by escaping through time, but they differ fundamentally in developmental arrest and taxonomic occurrence:</p>\n  \n  <table style=\"width:100%; border-collapse:collapse; margin-top:10px; font-size:0.9rem;\">\n    <thead>\n      <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n        <th style=\"padding:6px 10px; color:#065f46; width:50%;\">Diapause</th>\n        <th style=\"padding:6px 10px; color:#065f46; width:50%;\">Hibernation (Winter Sleep)</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr style=\"border-bottom:1px solid #e2e8f0;\">\n        <td style=\"padding:6px 10px;\">A state of <strong>suspended development</strong> characterized by complete cessation of cellular growth and differentiation.</td>\n        <td style=\"padding:6px 10px;\">A state of <strong>metabolic dormancy</strong> where metabolic rate, heart rate, and body temperature drop to near-dormancy to conserve energy.</td>\n      </tr>\n      <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n        <td style=\"padding:6px 10px;\">Commonly observed in developmental life stages (eggs, pupae, larvae) of <strong>zooplankton and insects</strong> in response to adverse seasonal changes.</td>\n        <td style=\"padding:6px 10px;\">Observed in adult ectothermic and endothermic vertebrates (e.g., <strong>bears, frogs, lizards, rodents</strong>) strictly during extreme winter cold.</td>\n      </tr>\n      <tr>\n        <td style=\"padding:6px 10px;\">Can occur at any season (summer or winter) triggered by photoperiod or food scarcity.</td>\n        <td style=\"padding:6px 10px;\">Strictly seasonal winter dormancy (contrasted with aestivation, which is summer sleep).</td>\n      </tr>\n    </tbody>\n  </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Diapause: Suspended development in zooplankton/insects during adverse conditions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Hibernation: Metabolic winter dormancy in vertebrates (bears, frogs) escaping cold</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q2 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q2')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        If a marine fish is placed in a fresh water aquarium, will the fish be able to survive? Why or why not?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>No, the marine fish will NOT be able to survive.</strong></p>\n  <p><strong>Scientific Explanation (Osmoregulatory Failure):</strong></p>\n  <ol>\n    <li><strong>Hypotonic Stress & Severe Endosmosis:</strong>\n      <ul>\n        <li>Fresh water is <strong>hypotonic</strong> (very low salinity, &lt; 5 ppt) compared to the hypertonic internal body fluids and tissues of the marine fish.</li>\n        <li>Consequently, water will continuously rush into the fish's body across its semi-permeable membranes (gills, oral mucosa) through <strong>endosmosis</strong>.</li>\n      </ul>\n    </li>\n    <li><strong>Inability to Cope with Osmotic Swelling:</strong>\n      <ul>\n        <li>Marine fish are biologically adapted to live in a hypertonic environment: they constantly drink seawater, excrete concentrated salt ions via specialized chloride secretory cells in their gills, and produce minimal, concentrated urine.</li>\n        <li>In a freshwater aquarium, the fish's kidneys cannot pump out such massive volumes of incoming water. Its cells and blood vessels swell, tissues suffer severe oedema, erythrocytes burst (haemolysis), and the fish dies of osmoregulatory shock.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear negative answer: No, the fish will not survive</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Osmotic explanation: Freshwater is hypotonic causing continuous endosmosis of water into body</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Cell swelling, bursting (haemolysis), and osmoregulatory failure</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q3 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q3')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Most living organisms cannot survive at temperatures above 45&deg;C. How are some microbes able to live in habitats with temperatures exceeding 100&deg;C?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Thermophilic and hyperthermophilic archaebacteria (e.g., <strong><em>Thermus aquaticus, Methanopyrus, Pyrococcus</em></strong>) survive in superheated hydrothermal vents and hot sulfur springs (&gt; 100&deg;C) due to unique macromolecular and membrane adaptations:</p>\n  <ol>\n    <li><strong>Thermostable Enzymes & Proteins:</strong>\n      <ul>\n        <li>Their catalytic enzymes (such as <strong><em>Taq</em> DNA polymerase</strong>) have highly stabilized tertiary and quaternary conformations.</li>\n        <li>They possess an unusually high density of <strong>disulphide (-S-S-) covalent bridges, extensive salt bridges (ionic bonds), hydrophobic core packing, and elevated proline residues</strong> that prevent thermal unfolding and denaturation even at boiling temperatures.</li>\n      </ul>\n    </li>\n    <li><strong>Unique Ether-Linked Branched Lipid Membranes:</strong>\n      <ul>\n        <li>Unlike the ester-linked unbranched fatty acids found in eubacteria and eukaryotes, archaebacterial cell membranes are made of <strong>ether-linked, branched phytanyl lipid chains</strong>.</li>\n        <li>In extreme hyperthermophiles, these form a rigid, continuous <strong>lipid monolayer</strong> (instead of a bilayer) that prevents heat-induced membrane fluidization, disintegration, and lethal cellular leakage.</li>\n      </ul>\n    </li>\n    <li><strong>DNA Stabilization (Reverse DNA Gyrase):</strong>\n      <ul>\n        <li>They express specialized enzymes like <strong>reverse DNA gyrase</strong> that introduce positive supercoils into DNA, preventing thermal denaturation of the double helix.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Thermostable enzymes (Taq polymerase) with dense disulfide/ionic bonds preventing thermal denaturation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Unique ether-linked branched lipid monolayer membranes maintaining membrane integrity</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reverse DNA gyrase maintaining double-stranded DNA stability at >100°C</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q4 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q4')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        List the attributes that populations possess but not individuals.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>An individual organism is born, reproduces, and dies; however, a <strong>biological population</strong> (a group of individuals of the same species occupying a defined geographical area) exhibits collective emergent ecological attributes that an individual organism cannot have:</p>\n  <ol>\n    <li><strong>Birth Rate (Natality):</strong> Expressed as the number of new individuals added per unit population per unit time (e.g., if 20 lotus plants in a pond increase to 28 in a year, birth rate is 8/20 = 0.4 offspring per lotus per year). An individual has a birth, but not a birth rate.</li>\n    <li><strong>Death Rate (Mortality):</strong> Expressed as the number of individuals dying per unit population per unit time. An individual dies, but only a population has a mortality rate.</li>\n    <li><strong>Sex Ratio:</strong> An individual is either male or female, but a population possesses a <strong>sex ratio</strong> (e.g., 60% of the population are females and 40% are males).</li>\n    <li><strong>Age Distribution & Age Pyramids:</strong> A population is composed of individuals of diverse age groups grouped into <em>pre-reproductive, reproductive, and post-reproductive cohorts</em>, forming distinct age pyramids (expanding, stable, or declining).</li>\n    <li><strong>Population Density / Size:</strong> The total number or biomass of individuals inhabiting a unit area or volume (N) at a given point in time.</li>\n    <li><strong>Gene Pool & Allele Frequencies:</strong> The sum total of all genes and alleles in a population obeying Hardy-Weinberg equilibrium.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Birth rate (Natality) and Death rate (Mortality) per capita rates vs individual birth/death</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sex ratio and Population density/size</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Age distribution/pyramids and population gene pool</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q5 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q5')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Differentiate between the following:\n  <br>(a) Exponential growth and Logistic growth\n  <br>(b) Birth rate and Death rate\n  <br>(c) Emigration and Immigration\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:16px;\">\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(a) Exponential Growth vs Logistic Growth</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.9rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:6px 10px; width:50%;\">Exponential Growth (J-shaped)</th>\n          <th style=\"padding:6px 10px; width:50%;\">Logistic Growth (S-shaped / Sigmoid)</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Occurs when environmental resources (food and space) are <strong>unlimited</strong>.</td>\n          <td style=\"padding:6px 10px;\">Occurs when resources are <strong>finite and limiting</strong>, defining a carrying capacity (K).</td>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Equation: <strong>dN/dt = rN</strong>. Population increases indefinitely until sudden crash.</td>\n          <td style=\"padding:6px 10px;\">Equation: <strong>dN/dt = rN [(K - N) / K]</strong>. Exhibits lag, acceleration, deceleration, and asymptote phases.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:6px 10px;\">Unrealistic in nature.</td>\n          <td style=\"padding:6px 10px;\">Most realistic model of natural population dynamics.</td>\n        </tr>\n      </table>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(b) Birth Rate vs Death Rate</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.9rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:6px 10px; width:50%;\">Birth Rate (Natality)</th>\n          <th style=\"padding:6px 10px; width:50%;\">Death Rate (Mortality)</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">Number of new individuals added into the population per capita per unit time through reproduction.</td>\n          <td style=\"padding:6px 10px;\">Number of individuals lost from the population per capita per unit time due to death.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:6px 10px;\">Increases overall population size and density.</td>\n          <td style=\"padding:6px 10px;\">Decreases overall population size and density.</td>\n        </tr>\n      </table>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(c) Emigration vs Immigration</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.9rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:6px 10px; width:50%;\">Emigration (E)</th>\n          <th style=\"padding:6px 10px; width:50%;\">Immigration (I)</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:6px 10px;\">The number of individuals of the population who left the habitat and moved elsewhere during a given time period.</td>\n          <td style=\"padding:6px 10px;\">The number of individuals of the same species that have come into the habitat from elsewhere during a given time period.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:6px 10px;\">Contributes negatively to population density (-E).</td>\n          <td style=\"padding:6px 10px;\">Contributes positively to population density (+I).</td>\n        </tr>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Exponential (unlimited resources, dN/dt=rN, J-shape) vs Logistic (limited resources, carrying capacity K, S-shape)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Birth rate (per capita additions) vs Death rate (per capita losses)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Emigration (individuals leaving habitat) vs Immigration (individuals entering habitat)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q6 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q6')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        If in a population of 50 water hyacinth plants, 10 new plants were added through reproduction in a month, calculate the birth rate of the population.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Calculation of Per Capita Birth Rate:</strong></p>\n  <ul>\n    <li>Initial population size (<em>N</em>) = <strong>50 water hyacinth plants</strong></li>\n    <li>Number of new plants added through reproduction (&Delta;<em>N</em>) = <strong>10 plants</strong></li>\n    <li>Time interval (&Delta;<em>t</em>) = <strong>1 month</strong></li>\n  </ul>\n\n  <div style=\"background:#f8fafc; padding:12px 14px; border-left:4px solid #059669; margin:8px 0; font-family:monospace; font-size:1rem;\">\n    Birth Rate = &Delta;N / (N &times; &Delta;t)<br>\n    Birth Rate = 10 / 50 = <strong>0.2 offspring per water hyacinth plant per month</strong>.\n  </div>\n\n  <p><strong>Conclusion:</strong> The birth rate of the water hyacinth population is <strong>0.2 plants per water hyacinth per month</strong> (or 20% increase per month).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Formula for per capita birth rate = Number of new additions / Initial population size</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution leading to correct answer: 10 / 50 = 0.2 offspring per water hyacinth per month</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q7 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q7')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Define phenotypic adaptation. Give one example.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition:</strong></p>\n  <p>A <strong>phenotypic adaptation</strong> is any non-genetic, physiological, morphological, or behavioural change that develops in an organism during its lifetime in response to an environmental stress, allowing it to survive and reproduce in that altered habitat without changing its genotype.</p>\n\n  <p><strong>Classic Example: Altitude Sickness Acclimatisation in Humans:</strong></p>\n  <ul>\n    <li>When a person moves from sea level to high altitude (&gt; 3,500 metres, e.g., Rohtang Pass or Leh), they experience <strong>altitude sickness</strong> due to low atmospheric pressure and resultant hypoxia (nausea, fatigue, heart palpitations).</li>\n    <li>Over several days, the human body exhibits a phenotypic physiological adaptation:\n      <ol>\n        <li>Kidneys secrete increased <strong>erythropoietin</strong>, stimulating bone marrow to <strong>increase total RBC production</strong>.</li>\n        <li>The binding affinity of haemoglobin for oxygen decreases, facilitating easier oxygen unloading in tissues.</li>\n        <li>Breathing rate increases substantially.</li>\n      </ol>\n    </li>\n    <li>Within 1–2 weeks, the symptoms disappear, demonstrating full phenotypic acclimatisation.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of phenotypic adaptation: Non-genetic physiological/behavioural acclimatisation to stress</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Detailed example: Altitude sickness acclimatisation (increasing RBC count and breathing rate)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q8 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q8')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Most living organisms tolerate a narrow range of temperature (such animals are called stenothermal). How do organisms manage if environmental temperatures get beyond tolerance limits?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>When ambient temperatures exceed an organism's narrow stenothermal tolerance limits, they employ one or more of the following survival strategies:</p>\n  <ol>\n    <li><strong>Migration (Escape in Space):</strong>\n      <ul>\n        <li>Organisms move away temporarily from the stressful habitat to a hospitable area and return when the stressful period is over.</li>\n        <li><em>Example:</em> Every winter, thousands of migratory birds (e.g., Siberian cranes) fly thousands of kilometres from freezing Siberia to Keoladeo National Park (Bharatpur, Rajasthan).</li>\n      </ul>\n    </li>\n    <li><strong>Suspension (Escape in Time):</strong>\n      <ul>\n        <li><strong>Hibernation (Winter Sleep):</strong> Ectotherms (bears, frogs, lizards) retreat into caves/mud during extreme winter, lowering their metabolism.</li>\n        <li><strong>Aestivation (Summer Sleep):</strong> Snails and lungfishes burrow into damp mud during hot, dry summer months to avoid desiccation and heat stress.</li>\n        <li><strong>Diapause:</strong> Many species of zooplankton in lakes enter suspended developmental arrest during unfavorable seasonal temperatures.</li>\n      </ul>\n    </li>\n    <li><strong>Behavioural Thermoregulation:</strong>\n      <ul>\n        <li>Desert lizards lack internal physiological thermoregulation. When body temperature drops below comfort zone, they bask in the sun to absorb heat; when ambient temperature gets dangerously high, they move into cool subterranean burrows.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Migration: Moving to hospitable zones (Siberian cranes to Bharatpur)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Suspension in time: Hibernation (bears in winter), Aestivation (snails in summer), and Diapause</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Behavioural adaptations: Basking and burrowing in desert lizards</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q9 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q9')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Define the following terms and give one example for each:\n  <br>(a) Commensalism\n  <br>(b) Parasitism\n  <br>(c) Camouflage\n  <br>(d) Mutualism\n  <br>(e) Interspecific competition\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:12px;\">\n    <div style=\"background:#f8fafc; padding:10px 14px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(a) Commensalism (+, 0):</strong> An interaction between two species where one species is benefited while the other species is neither benefited nor harmed.\n      <br><em>Example:</em> An epiphytic <strong>orchid</strong> growing on the branch of a mango tree, or <strong>barnacles</strong> growing on the back of a whale.\n    </div>\n    <div style=\"background:#f8fafc; padding:10px 14px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(b) Parasitism (+, -):</strong> An interaction where one organism (the parasite) lives on or inside another organism (the host), deriving nourishment and shelter while causing physiological harm.\n      <br><em>Example:</em> <strong><em>Cuscuta</em></strong> (dodder) parasitising hedge plants, or <strong>liver fluke</strong> parasitising sheep and snail hosts.\n    </div>\n    <div style=\"background:#f8fafc; padding:10px 14px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(c) Camouflage:</strong> A cryptic morphological coloration or pattern evolved by prey species that blends seamlessly with the background to avoid detection by visual predators.\n      <br><em>Example:</em> <strong>Stick insects</strong> resembling dry twigs, or cryptically coloured tree frogs and leaf-mimicking insects.\n    </div>\n    <div style=\"background:#f8fafc; padding:10px 14px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(d) Mutualism (+, +):</strong> An obligate interaction between two species that confers mutual survival benefits to both interacting partners.\n      <br><em>Example:</em> <strong>Lichens</strong> (symbiotic association between an alga/cyanobacterium and a fungus), or <strong>mycorrhiza</strong>, or the mutualism between <strong>fig tree and wasp</strong>.\n    </div>\n    <div style=\"background:#f8fafc; padding:10px 14px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(e) Interspecific Competition (-, -):</strong> An interaction occurring between individuals of two distinct species competing for the same limited ecological resources (food, space, light).\n      <br><em>Example:</em> Visiting <strong>flamingos and resident fishes</strong> competing for common zooplankton in shallow South American lakes.\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Commensalism definition (+, 0) and example (orchid on mango/barnacle on whale)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Parasitism definition (+, -) and example (Cuscuta / Liver fluke)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Camouflage definition and example (cryptic frogs / stick insect)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Mutualism definition (+, +) and example (Lichen / Fig-wasp)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) Interspecific competition (-, -) and example (Flamingos and fish for zooplankton)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q10 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q10')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        With the help of suitable diagram describe the logistic population growth curve.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Logistic Population Growth (Verhulst-Pearl Logistic Growth):</strong></p>\n  <p>In nature, environmental resources (food and space) are finite. A population growing in a limited environment exhibits a characteristic <strong>sigmoid (S-shaped) curve</strong> governed by the carrying capacity (<em>K</em>).</p>\n\n  <p><strong>The Four Distinct Phases:</strong></p>\n  <ol>\n    <li><strong>Lag Phase:</strong> Initial period of slow population growth as individuals adapt to their environment.</li>\n    <li><strong>Phase of Acceleration (Log / Exponential Phase):</strong> Rapid population expansion where birth rate substantially exceeds death rate.</li>\n    <li><strong>Phase of Deceleration:</strong> Growth slows down as increasing population density causes intense competition for shrinking resources.</li>\n    <li><strong>Asymptote:</strong> Population density reaches the habitat's maximum sustainable limit, known as the <strong>Carrying Capacity (<em>K</em>)</strong>. Birth rate equals death rate, stabilizing the population.</li>\n  </ol>\n\n  <p><strong>Differential Mathematical Equation:</strong></p>\n  <div style=\"background:#f0fdf4; padding:12px 16px; border:1px solid #86efac; border-radius:8px; margin:10px 0; font-family:monospace; font-size:1.1rem; color:#065f46; text-align:center;\">\n    dN / dt = rN &times; [ (K - N) / K ]\n  </div>\n  <ul>\n    <li><strong>N:</strong> Population density at time <em>t</em></li>\n    <li><strong>r:</strong> Intrinsic rate of natural increase</li>\n    <li><strong>K:</strong> Carrying capacity of the habitat</li>\n    <li><strong>(K - N) / K:</strong> Environmental resistance factor</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Description of Sigmoid (S-shaped) curve and 4 phases (Lag, Acceleration, Deceleration, Asymptote)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate differential equation: dN/dt = rN[(K - N)/K] with notation definitions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Concept of Carrying Capacity (K) representing environmental resistance limit</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q11 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q11')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Select the statement which best explains parasitism.\n  <br>(a) One organism is benefited.\n  <br>(b) Both the organisms are benefited.\n  <br>(c) One organism is benefited, other is not affected.\n  <br>(d) One organism is benefited, other is affected.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (d) One organism is benefited, other is affected.</strong></p>\n  <p><strong>Explanation:</strong></p>\n  <ul>\n    <li>In a parasitic ecological relationship, one interacting partner (the <strong>parasite</strong>) derives nutritional sustenance and shelter, and is thus <strong>benefited (+)</strong>.</li>\n    <li>The other partner (the <strong>host</strong>) is deprived of vital nutrients, sustains physiological damage, impaired growth, reduced reproductive fitness, and vulnerability to predators, and is thus <strong>harmed / negatively affected (-)</strong>.</li>\n    <li>Hence, parasitism is formally designated as a <strong>(+ , -) interspecific interaction</strong>.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct choice: (d) One organism is benefited, other is affected</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Designation as (+, -) interaction where parasite benefits and host is harmed</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q12 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q12')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        List any three important characteristics of a population and explain them.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Three core demographic characteristics that define a biological population are:</p>\n  <ol>\n    <li><strong>1. Population Density (N):</strong>\n      <br>The size of a population relative to a unit of space (area or volume) at a given point in time. It can be measured as total numerical count (e.g., number of trees per hectare), percent cover/biomass (useful for giant banyan trees), relative density (e.g., number of fish caught per trap), or indirect indices (e.g., tiger census based on pug marks and fecal pellets).</li>\n    <li><strong>2. Natality (Birth Rate) and Mortality (Death Rate):</strong>\n      <br>Expressed as per capita rates:\n      <ul>\n        <li><strong>Natality:</strong> The rate at which new individuals are added to the population by reproduction per unit time.</li>\n        <li><strong>Mortality:</strong> The rate at which individuals are lost from the population by death per unit time.</li>\n      </ul>\n    </li>\n    <li><strong>3. Age Distribution (Age Pyramids):</strong>\n      <br>The proportion of individuals belonging to different age groups (pre-reproductive, reproductive, and post-reproductive) plotted graphically as an <strong>age pyramid</strong>. The geometry of the pyramid indicates whether the population is <em>expanding</em> (triangular), <em>stable</em> (bell-shaped), or <em>declining</em> (urn-shaped).</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Population density (N): Definition and methods of measurement (biomass, relative density, pug marks)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Natality and Mortality: Per capita additions and losses per unit time</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Age distribution: Proportion of age cohorts forming expanding, stable, or declining age pyramids</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q13 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q13')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What is age-structure? What are its categories in human population?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition of Age-Structure:</strong></p>\n  <p><strong>Age-structure</strong> refers to the percentage composition or proportional distribution of individuals belonging to different chronological age categories within a given population at a specific point in time.</p>\n\n  <p><strong>Three Ecological Age Categories in Human Populations:</strong></p>\n  <ol>\n    <li><strong>Pre-Reproductive Age Group:</strong> Includes young infants, children, and early adolescents (typically <strong>0 to 14 years</strong>) who are sexually immature and not yet capable of bearing offspring.</li>\n    <li><strong>Reproductive Age Group:</strong> Sexually mature, biologically active individuals (typically <strong>15 to 44 years</strong>) who are actively bearing children and driving population growth.</li>\n    <li><strong>Post-Reproductive Age Group:</strong> Elderly individuals (typically <strong>45 years and above</strong>) who have passed reproductive senescence (menopause) and are no longer contributing offspring.</li>\n  </ol>\n  <p><strong>Significance:</strong> A large pre-reproductive base yields an <strong>expanding population</strong>, equal pre-reproductive and reproductive cohorts yield a <strong>stable population</strong>, and a smaller pre-reproductive base yields a <strong>declining population</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of age-structure as proportional distribution of age groups</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Three human categories: Pre-reproductive (0-14), Reproductive (15-44), Post-reproductive (45+)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correlation to population growth trajectory (expanding, stable, declining)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q14 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q14')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Explain the difference between Gause's Competitive Exclusion Principle and Resource Partitioning with examples.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:16px;\">\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">1. Gause's Competitive Exclusion Principle (Complete Elimination)</h5>\n      <p><strong>Statement:</strong> Formulated by G.F. Gause (1934), it states that two closely related species competing for the exact same limiting resources cannot coexist indefinitely; the competitively inferior species will eventually be eliminated.</p>\n      <p><strong>Classic Example: Abingdon Tortoises in Galapagos:</strong></p>\n      <ul>\n        <li>The giant Abingdon tortoises on the Galapagos Islands became extinct within a decade after goats were introduced on the island, because the goats possessed vastly greater browsing efficiency.</li>\n      </ul>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">2. Resource Partitioning (Coexistence Mechanism)</h5>\n      <p><strong>Statement:</strong> If two species compete for the same resource, they can avoid exclusion and achieve stable coexistence by partitioning resources—choosing different feeding times, foraging zones, or different micro-habitats.</p>\n      <p><strong>Classic Example: MacArthur's Warblers (1958):</strong></p>\n      <ul>\n        <li>Robert MacArthur demonstrated that five closely related species of warblers coexisted peacefully on the same spruce tree because they partitioned the tree: each species hunted insects in different vertical zones of the tree canopy and developed behavioral foraging differences.</li>\n      </ul>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Gause's Principle: Competing species cannot coexist indefinitely; inferior eliminated (Tortoises vs Goats)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Resource Partitioning: Coexistence via differing feeding times/foraging zones (MacArthur's 5 warbler species)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q15 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q15')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        How do organisms adapt to cold climate / sub-zero temperatures (e.g. Allen's rule, blubber)?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Endothermic mammals and aquatic vertebrates inhabiting polar regions and cold climates display specialized morphological and physiological adaptations:</p>\n  <ol>\n    <li><strong>Allen's Rule (Morphological Adaptation):</strong>\n      <ul>\n        <li>Mammals living in colder climates generally possess <strong>shorter ears, snouts, and shorter limbs</strong> compared to their warm-climate counterparts.</li>\n        <li><em>Thermodynamic Principle:</em> Shorter extremities minimize surface area-to-volume ratio, thereby substantially reducing heat loss from the body to the freezing environment (e.g., Arctic fox vs desert fennec fox).</li>\n      </ul>\n    </li>\n    <li><strong>Thick Subcutaneous Fat Layer (Blubber):</strong>\n      <ul>\n        <li>Polar marine mammals (e.g., <strong>Seals, Sea lions, and Whales</strong>) possess an extremely thick subcutaneous adipose layer beneath their dermis called <strong>Blubber</strong>.</li>\n        <li>Blubber acts as a thermal insulator, preventing body core heat from dissipating into freezing ocean waters and serving as an energy reserve.</li>\n      </ul>\n    </li>\n    <li><strong>Antifreeze Compounds (Physiological):</strong>\n      <ul>\n        <li>Antarctic icefishes and arctic beetles synthesize specialized <strong>antifreeze glycoproteins (AFGPs)</strong> and glycerol in their blood, depressing the freezing point and preventing ice crystal nucleation.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Allen's Rule: Shorter ears and limbs minimizing surface area to reduce heat loss</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Blubber in seals and whales acting as insulating adipose blanket against sub-zero water</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Antifreeze glycoproteins and physiological mechanisms in polar fishes/insects</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q16 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q16\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q16')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q16</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        How do desert plants and animals adapt to water scarcity?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Organisms living in arid desert environments possess evolutionary xerophytic and behavioural adaptations to conserve scarce water:</p>\n\n  <p><strong>1. Adaptations in Desert Plants (Xerophytes):</strong></p>\n  <ul>\n    <li><strong>Sunken Stomata & Thick Waxy Cuticle:</strong> Possess a heavy waxy cuticle on leaf surfaces and stomata arranged in deep pits (sunken stomata) to minimize transpirational water loss.</li>\n    <li><strong>CAM Pathway (Crassulacean Acid Metabolism):</strong> Desert succulents keep their stomata tightly closed during the scorching day and open them only at night to take in CO<sub>2</sub>, virtually eliminating daytime transpiration.</li>\n    <li><strong>Foliar Reduction into Spines:</strong> Leaves are modified into sharp spines (e.g., <em>Opuntia</em>), while the green flattened stem (phylloclade) takes over photosynthesis.</li>\n  </ul>\n\n  <p><strong>2. Adaptations in Desert Animals:</strong></p>\n  <ul>\n    <li><strong>Kangaroo Rat (<em>Dipodomys</em>) of North American Deserts:</strong>\n      <ul>\n        <li>Never drinks water throughout its entire life. Meets 100% of its internal water requirements through <strong>internal fat oxidation</strong> (metabolic water released as a byproduct).</li>\n        <li>Possesses extremely long Loops of Henle, concentrating its urine to an almost solid state to excrete minimal water.</li>\n      </ul>\n    </li>\n    <li><strong>Behavioural Burrowing:</strong> Desert reptiles and rodents stay inside deep, cool, humid subterranean burrows during the daytime heat and emerge only at night (nocturnal habit).</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Desert plants: Thick cuticle, sunken stomata, CAM photosynthesis, leaves modified to spines (Opuntia)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Desert animals: Kangaroo rat using metabolic water, concentrated urine, and nocturnal burrowing</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q17 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q17\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q17')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q17</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What are mycorrhizae? How do they benefit the plants?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition:</strong></p>\n  <p><strong>Mycorrhiza</strong> is a mutualistic symbiotic association between a fungus (most commonly belonging to the genus <strong><em>Glomus</em></strong>) and the roots of higher vascular plants (e.g., Pinus, forest trees, and agricultural crops).</p>\n\n  <p><strong>Multi-Faceted Benefits Conferred to Host Plants:</strong></p>\n  <ol>\n    <li><strong>Enhanced Phosphorus Absorption:</strong> Fungal hyphae extend far beyond root hair depletion zones in the soil, effectively absorbing <strong>phosphorus</strong> (and other minerals) and transferring it to the plant roots.</li>\n    <li><strong>Resistance to Root-Borne Pathogens:</strong> The dense fungal mantle acts as a physical and chemical antimicrobial shield, protecting host roots from soil fungi and pathogenic nematodes.</li>\n    <li><strong>Tolerance to Drought and Soil Salinity:</strong> Greatly expands the effective absorptive surface area of the root system, enhancing water uptake during drought.</li>\n    <li><strong>Obligate Dependency in Some Lineages:</strong> Certain plants (e.g., <em>Pinus</em> seeds) have obligate mycorrhizal associations; their seeds cannot germinate or establish seedlings in the absence of mycorrhiza.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of mycorrhiza (mutualistic fungus-root symbiosis, e.g. Glomus)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Key benefits: Phosphorus absorption, drought/salinity tolerance, and root pathogen defense</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch11-q18 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch11-q18\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch11-q18')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q18</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What is sexual deceit? Explain with the example of Mediterranean orchid Ophrys.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition of Sexual Deceit:</strong></p>\n  <p><strong>Sexual deceit</strong> is a specialised co-evolutionary floral adaptation wherein a flower mimics the visual appearance, texture, and sex pheromones of a female insect to trick male insects into pseudocopulation, successfully achieving pollination without providing any nectar reward.</p>\n\n  <p><strong>Classic Example: Mediterranean Orchid <em>Ophrys</em> and Solitary Bee (<em>Colletes</em>):</strong></p>\n  <ol>\n    <li>The Mediterranean orchid <strong><em>Ophrys</em></strong> employs sexual deceit to accomplish cross-pollination.</li>\n    <li><strong>Visual & Olfactory Mimicry:</strong> One petal of the orchid flower bears an uncanny resemblance in size, color, markings, and velvety texture to the female solitary bee. Furthermore, the orchid produces chemical volatiles identical to the female bee's sex pheromone.</li>\n    <li><strong>Pseudocopulation:</strong> The male bee is attracted by the scent and appearance, mistaking the flower petal for a receptive female bee. It lands and attempts to copulate with the petal (\"pseudocopulation\").</li>\n    <li><strong>Pollen Transfer:</strong> During this act, sticky pollinia (pollen packets) from the flower adhere to the male bee's head or thorax. When the same frustrated bee visits another <em>Ophrys</em> flower, it pseudocopulates again, transferring the pollen and achieving cross-pollination.</li>\n    <li><strong>Co-evolutionary Dependency:</strong> If the female bee's color patterns change during evolution, the orchid must co-evolve to maintain resemblance, or it faces extinction.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of sexual deceit (mimicking female insect appearance/pheromone for pseudocopulation)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Detailed Ophrys example: Petal mimicking female solitary bee in color, markings, and scent</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pseudocopulation leading to pollinia transfer and co-evolutionary mutual dependency</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"display:flex; justify-content:space-between; align-items:center; margin-top:36px; padding-top:20px; border-top:1px solid #e2e8f0;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(10)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 10</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(12)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#059669; color:white; font-weight:700; cursor:pointer;\">Next: Ch 12 (Ecosystem) →</button>\n  </div>\n</section>";
window.CHAPTER_DATA[12] = "<section class=\"chapter-section\" id=\"c12b-ch12\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#059669;\">12</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#059669;\">CBSE Class 12 Biology &bull; Chapter 12</div>\n      <h2>Ecosystem</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 14 Verbatim Questions with Official CBSE Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n<div class=\"chem-card\" style=\"margin-bottom:24px; padding:20px; background:#f0fdf4; border:1px solid #bbf7d0; border-radius:12px;\">\n  <h4 style=\"margin:0 0 12px 0; color:#059669; font-size:1.05rem;\">🧬 Ecosystem Dynamics Map: Lindeman's 10% Energy Flow & Ecological Pyramids</h4>\n  <svg viewBox=\"0 0 880 300\" style=\"width:100%; max-width:880px; height:auto; display:block; margin:0 auto; background:white; border-radius:8px; border:1px solid #d1fae5;\">\n    <!-- 10% Energy Pyramid -->\n    <rect x=\"20\" y=\"20\" width=\"380\" height=\"260\" rx=\"10\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"210\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Lindeman's 10% Energy Law (Always Upright)</text>\n    <line x1=\"35\" y1=\"56\" x2=\"385\" y2=\"56\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n\n    <!-- Apex: Tertiary Consumer -->\n    <polygon points=\"180,95 240,95 210,65\" fill=\"#fecaca\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n    <text x=\"210\" y=\"85\" font-family=\"sans-serif\" font-size=\"9\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">Top Carnivore (10 J)</text>\n\n    <!-- Secondary Consumer -->\n    <polygon points=\"150,135 270,135 240,95 180,95\" fill=\"#fed7aa\" stroke=\"#f97316\" stroke-width=\"1.5\"/>\n    <text x=\"210\" y=\"120\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#9a3412\" text-anchor=\"middle\">Secondary Consumer (100 J)</text>\n\n    <!-- Primary Consumer -->\n    <polygon points=\"110,180 310,180 270,135 150,135\" fill=\"#fef08a\" stroke=\"#eab308\" stroke-width=\"1.5\"/>\n    <text x=\"210\" y=\"162\" font-family=\"sans-serif\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#854d0e\" text-anchor=\"middle\">Herbivore / Primary Consumer (1,000 J)</text>\n\n    <!-- Producer -->\n    <polygon points=\"60,230 360,230 310,180 110,180\" fill=\"#bbf7d0\" stroke=\"#16a34a\" stroke-width=\"1.5\"/>\n    <text x=\"210\" y=\"210\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#166534\" text-anchor=\"middle\">Primary Producers / Plants (10,000 J)</text>\n\n    <text x=\"210\" y=\"250\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#334155\" text-anchor=\"middle\">Incident Solar Energy: 1,000,000 J (Plants capture ~1% of sunlight)</text>\n    <text x=\"210\" y=\"268\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#047857\" text-anchor=\"middle\">Energy pyramid is NEVER inverted!</text>\n\n    <!-- Ecological Pyramids Card -->\n    <rect x=\"420\" y=\"20\" width=\"440\" height=\"260\" rx=\"10\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <text x=\"640\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Upright vs Inverted Ecological Pyramids</text>\n    <line x1=\"435\" y1=\"56\" x2=\"845\" y2=\"56\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n\n    <text x=\"435\" y=\"78\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#1e40af\">1. Pyramid of Numbers:</text>\n    <text x=\"435\" y=\"96\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Grassland:</strong> Upright (Millions of grasses &gt; Herbivores &gt; Wolves &gt; Lions)</text>\n    <text x=\"435\" y=\"112\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Single Tree Ecosystem:</strong> Inverted (1 Big Oak Tree &rarr; Hundreds of</text>\n    <text x=\"445\" y=\"126\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#475569\">birds &rarr; Thousands of hyperparasitic lice & ticks)</text>\n\n    <text x=\"435\" y=\"150\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#1e40af\">2. Pyramid of Biomass:</text>\n    <text x=\"435\" y=\"168\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>Forest / Terrestrial:</strong> Upright (Large standing crop of trees)</text>\n    <text x=\"435\" y=\"184\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#dc2626\">&bull; <strong>Sea / Ocean (Aquatic):</strong> <strong>INVERTED</strong> (Phytoplankton standing crop is</text>\n    <text x=\"445\" y=\"198\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#dc2626\">tiny due to short lifespans; supported by large biomass of fishes)</text>\n\n    <text x=\"435\" y=\"222\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#059669\">3. Productivity & Decomposition Steps:</text>\n    <text x=\"435\" y=\"238\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <strong>NPP = GPP - R</strong> (Net Primary Productivity = Gross - Respiration loss)</text>\n    <text x=\"435\" y=\"254\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; 5 Steps: Fragmentation &rarr; Leaching &rarr; Catabolism &rarr; Humification &rarr; Mineralisation</text>\n  </svg>\n</div>\n\n  <div class=\"ex-div\" style=\"font-size:0.88rem; font-weight:700; color:#334155; margin-bottom:16px; padding:8px 14px; background:#ecfdf5; border-radius:8px; border-left:4px solid #059669;\">NCERT Exercises (14 Verbatim Questions)</div>\n\n  <div class=\"questions-container\">\n    \n  <!-- c12b-ch12-q1 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch12-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch12-q1')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Fill in the blanks:\n  <br>(a) Plants are called as_________because they fix carbon dioxide.\n  <br>(b) In an ecosystem dominated by trees, the pyramid (of numbers) is_________type.\n  <br>(c) In aquatic ecosystems, the limiting factor for the productivity is_________.\n  <br>(d) Common detritivores in our ecosystem are_________.\n  <br>(e) The major reservoir of carbon on earth is_________.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:10px;\">\n    <div style=\"background:#f8fafc; padding:8px 12px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(a)</strong> Plants are called as <strong><u>autotrophs (producers)</u></strong> because they fix carbon dioxide through photosynthesis.\n    </div>\n    <div style=\"background:#f8fafc; padding:8px 12px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(b)</strong> In an ecosystem dominated by trees, the pyramid (of numbers) is <strong><u>inverted</u></strong> type (a single tree supports hundreds of frugivorous birds and thousands of parasites).\n    </div>\n    <div style=\"background:#f8fafc; padding:8px 12px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(c)</strong> In aquatic ecosystems, the limiting factor for the productivity is <strong><u>light (and nutrients like nitrogen/phosphorus)</u></strong>.\n    </div>\n    <div style=\"background:#f8fafc; padding:8px 12px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(d)</strong> Common detritivores in our ecosystem are <strong><u>earthworms (and termites, woodlice)</u></strong>.\n    </div>\n    <div style=\"background:#f8fafc; padding:8px 12px; border-radius:6px; border-left:4px solid #059669;\">\n      <strong>(e)</strong> The major reservoir of carbon on earth is the <strong><u>oceans</u></strong> (holding roughly 71% of all global dissolved carbon).\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Autotrophs / Producers</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Inverted (spindle-shaped/inverted)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Light / Sunlight (or nutrients)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Earthworm</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) Oceans</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch12-q2 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch12-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch12-q2')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Which one of the following has the largest population in a food chain?\n  <br>(a) Producers\n  <br>(b) Primary consumers\n  <br>(c) Secondary consumers\n  <br>(d) Decomposers\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (d) Decomposers</strong></p>\n  <p><strong>Detailed Scientific Explanation:</strong></p>\n  <ul>\n    <li>In any natural ecological food web, <strong>decomposers</strong> (saprotrophic bacteria, actinomycetes, and microscopic fungi) inhabit the soil and sediment litter in trillions of individuals per square meter.</li>\n    <li>While producers (phytoplankton or grass blades) occupy the base of grazing pyramids, the sheer numerical density of microscopic decomposers breaking down organic matter vastly outstrips all macroscopic autotrophs and consumers combined.</li>\n    <li><em>Note on NCERT alternative:</em> If restricted strictly to a classical <strong>Grazing Food Chain (GFC)</strong> excluding saprotrophs, <strong>(a) Producers</strong> have the largest population. However, ecologically across the entire ecosystem, <strong>(d) Decomposers</strong> represent the largest population.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct choice: (d) Decomposers (or (a) Producers in strict GFC context)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ecological justification: Microscopic saprophytic bacteria/fungi exist in trillions per unit area</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch12-q3 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch12-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch12-q3')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        The second trophic level in a lake is &mdash;\n  <br>(a) Phytoplankton\n  <br>(b) Zooplankton\n  <br>(c) Benthos\n  <br>(d) Fishes\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (b) Zooplankton</strong></p>\n  <p><strong>Explanation:</strong></p>\n  <ul>\n    <li><strong>First Trophic Level (T1 - Primary Producers):</strong> Microscopic photosynthetic floating autotrophs, i.e., <strong>Phytoplankton</strong> (diatoms, green algae, cyanobacteria).</li>\n    <li><strong>Second Trophic Level (T2 - Primary Consumers / Herbivores):</strong> Microscopic floating herbivores that feed directly upon phytoplankton, i.e., <strong>Zooplankton</strong> (rotifers, copepods, cladocerans).</li>\n    <li><strong>Third Trophic Level (T3 - Secondary Consumers):</strong> Small planktivorous fishes.</li>\n    <li><strong>Fourth Trophic Level (T4 - Tertiary Consumers):</strong> Large predatory fishes.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct choice: (b) Zooplankton</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Trophic position: Zooplankton are primary consumers (T2) grazing on phytoplankton (T1)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch12-q4 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch12-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch12-q4')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Secondary producers are &mdash;\n  <br>(a) Herbivores\n  <br>(b) Producers\n  <br>(c) Carnivores\n  <br>(d) None of the above\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (a) Herbivores</strong></p>\n  <p><strong>Explanation:</strong></p>\n  <ul>\n    <li>Green plants and photosynthetic autotrophs synthesize organic matter from inorganic CO<sub>2</sub> and sunlight, and are termed <strong>Primary Producers</strong>.</li>\n    <li><strong>Herbivores (Primary Consumers)</strong> consume plant biomass and assimilate it into new animal biomass (flesh, muscle tissue). This newly produced organic animal matter is then made available as food for the next higher trophic level (carnivores).</li>\n    <li>Therefore, herbivores are formally designated as <strong>Secondary Producers</strong>.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct choice: (a) Herbivores</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Rationale: Herbivores assimilate plant food into animal biomass available for higher trophic levels</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch12-q5 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch12-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch12-q5')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What is the percentage of photosynthetically active radiation (PAR) in the incident solar radiation?\n  <br>(a) 100%\n  <br>(b) 50%\n  <br>(c) 1-5%\n  <br>(d) 2-10%\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (b) 50% (less than 50%)</strong></p>\n  <p><strong>Scientific Explanation:</strong></p>\n  <ul>\n    <li>Of the total incident solar radiation reaching the earth's atmosphere, <strong>less than 50%</strong> constitutes <strong>Photosynthetically Active Radiation (PAR)</strong> (wavelength range between 400 nm to 700 nm). The rest consists of ultraviolet (UV) and infrared (heat) radiation.</li>\n    <li>Plants and photosynthetic autotrophs capture only <strong>2–10% of this PAR</strong> (equivalent to 1–5% of total incident solar radiation) to sustain the entire biosphere.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct choice: (b) 50% (or less than 50%)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clarification: PAR constitutes <50% of incident sunlight, of which plants capture 2-10%</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch12-q6 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch12-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch12-q6')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Distinguish between:\n  <br>(a) Grazing food chain and detritus food chain\n  <br>(b) Production and decomposition\n  <br>(c) Upright and inverted pyramid\n  <br>(d) Food chain and Food web\n  <br>(e) Top consumer and Primary consumer\n  <br>(f) Primary and secondary productivity\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[6 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <div style=\"display:flex; flex-direction:column; gap:16px;\">\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(a) Grazing Food Chain (GFC) vs Detritus Food Chain (DFC)</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.88rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:4px 8px; width:50%;\">Grazing Food Chain (GFC)</th>\n          <th style=\"padding:4px 8px; width:50%;\">Detritus Food Chain (DFC)</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:4px 8px;\">Starts with living green photosynthetic plants (primary producers) as the primary energy source.</td>\n          <td style=\"padding:4px 8px;\">Starts with dead organic matter (detritus / leaf litter) as the primary energy source.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:4px 8px;\">Major conduit of energy flow in aquatic ecosystems.</td>\n          <td style=\"padding:4px 8px;\">Much larger fraction of energy flows through DFC in terrestrial forest ecosystems.</td>\n        </tr>\n      </table>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(b) Production vs Decomposition</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.88rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:4px 8px; width:50%;\">Production</th>\n          <th style=\"padding:4px 8px; width:50%;\">Decomposition</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:4px 8px;\">Anabolic process where organic biomass is synthesised by autotrophs using solar energy and CO<sub>2</sub>.</td>\n          <td style=\"padding:4px 8px;\">Catabolic process where complex dead organic matter is broken down into simple inorganic nutrients.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:4px 8px;\">Requires solar energy input; increases standing biomass.</td>\n          <td style=\"padding:4px 8px;\">Releases energy and recycles essential mineral nutrients back to soil/water.</td>\n        </tr>\n      </table>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(c) Upright Pyramid vs Inverted Pyramid</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.88rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:4px 8px; width:50%;\">Upright Pyramid</th>\n          <th style=\"padding:4px 8px; width:50%;\">Inverted Pyramid</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:4px 8px;\">Base (producers) is broad; apex (carnivores) narrows progressively (e.g., Grassland number/biomass).</td>\n          <td style=\"padding:4px 8px;\">Base (producers) is narrow and small; apex (consumers) is broad and heavy.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:4px 8px;\">Energy pyramid is always upright.</td>\n          <td style=\"padding:4px 8px;\">Biomass pyramid in sea/oceans is inverted (tiny phytoplankton standing crop supports large fishes).</td>\n        </tr>\n      </table>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(d) Food Chain vs Food Web</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.88rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:4px 8px; width:50%;\">Food Chain</th>\n          <th style=\"padding:4px 8px; width:50%;\">Food Web</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:4px 8px;\">A single, linear, unbranched pathway of feeding relationships and energy transfer.</td>\n          <td style=\"padding:4px 8px;\">A complex, interconnected, multidirectional network of multiple intersecting food chains.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:4px 8px;\">Vulnerable to collapse if one species is eliminated.</td>\n          <td style=\"padding:4px 8px;\">Provides alternative food pathways, ensuring high ecosystem stability and resilience.</td>\n        </tr>\n      </table>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(e) Top Consumer vs Primary Consumer</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.88rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:4px 8px; width:50%;\">Top Consumer (Apex Carnivore)</th>\n          <th style=\"padding:4px 8px; width:50%;\">Primary Consumer (Herbivore)</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:4px 8px;\">Occupies the highest trophic level (T4 or T5); is not preyed upon by any other animal in that ecosystem (e.g., Lion, Eagle, Shark).</td>\n          <td style=\"padding:4px 8px;\">Occupies the second trophic level (T2); feeds directly on living plant matter (e.g., Deer, Cow, Zooplankton).</td>\n        </tr>\n        <tr>\n          <td style=\"padding:4px 8px;\">Receives the lowest fraction of original energy (Lindeman's law).</td>\n          <td style=\"padding:4px 8px;\">Receives the highest fraction of energy directly from primary producers.</td>\n        </tr>\n      </table>\n    </div>\n\n    <div>\n      <h5 style=\"color:#059669; margin:0 0 6px 0;\">(f) Primary Productivity vs Secondary Productivity</h5>\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.88rem;\">\n        <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n          <th style=\"padding:4px 8px; width:50%;\">Primary Productivity</th>\n          <th style=\"padding:4px 8px; width:50%;\">Secondary Productivity</th>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:4px 8px;\">Rate at which biomass or organic matter is produced per unit area by green photosynthetic autotrophs (producers).</td>\n          <td style=\"padding:4px 8px;\">Rate of formation of new organic matter by heterotrophic consumers (herbivores/carnivores).</td>\n        </tr>\n        <tr>\n          <td style=\"padding:4px 8px;\">Divided into Gross Primary (GPP) and Net Primary (NPP).</td>\n          <td style=\"padding:4px 8px;\">Depends entirely upon the available net primary productivity of the preceding trophic level.</td>\n        </tr>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) GFC vs DFC: Living producer base vs dead organic detritus base</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Production vs Decomposition: Anabolic synthesis vs catabolic mineral breakdown</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Upright vs Inverted: Broad base vs broad apex (aquatic biomass)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Food chain vs Food web: Linear pathway vs interconnected network</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) Top consumer vs Primary consumer: Apex carnivore vs herbivore</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(f) Primary vs Secondary productivity: Rate of synthesis by autotrophs vs consumers</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch12-q7 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch12-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch12-q7')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Describe the components of an ecosystem.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>An <strong>ecosystem</strong> is a functional, self-sustaining biological unit of nature where living organisms interact among themselves and with the surrounding physical environment. It consists of two major structural components:</p>\n\n  <p><strong>1. Abiotic Components (Physical & Chemical Factors):</strong></p>\n  <ul>\n    <li><strong>Climatic Factors:</strong> Sunlight (solar radiation drives photosynthesis), Temperature, Humidity, Precipitation, and Wind.</li>\n    <li><strong>Edaphic & Topographic Factors:</strong> Soil mineral composition, soil pH, moisture, topography, and organic humus content.</li>\n    <li><strong>Inorganic & Organic Substances:</strong> Essential biogeochemical elements (C, N, P, S, Ca) and macromolecules (proteins, carbohydrates, lipids) cycling through the system.</li>\n  </ul>\n\n  <p><strong>2. Biotic Components (Living Organisms):</strong></p>\n  <ul>\n    <li><strong>Producers (Autotrophs):</strong> Photosynthetic plants, phytoplankton, and photosynthetic bacteria that convert solar energy into chemical energy (biomass) via photosynthesis.</li>\n    <li><strong>Consumers (Heterotrophs / Phagotrophs):</strong> Animals that depend on producers for food:\n      <ul>\n        <li><em>Primary Consumers (Herbivores):</em> Feed directly on plants (e.g., deer, cattle, zooplankton).</li>\n        <li><em>Secondary Consumers (Primary Carnivores):</em> Feed on herbivores (e.g., frogs, small fishes).</li>\n        <li><em>Tertiary Consumers (Top Carnivores):</em> Apex predators (e.g., lions, tigers, eagles).</li>\n      </ul>\n    </li>\n    <li><strong>Decomposers (Saprotrophs / Microconsumers):</strong> Heterotrophic bacteria and fungi that secrete extracellular digestive enzymes to break down complex dead organic detritus, releasing mineral nutrients back into the abiotic reservoir.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Abiotic components: Climatic (light, temperature) and edaphic/chemical factors (soil, nutrients)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Biotic producers: Autotrophs fixing solar energy into organic matter</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Biotic consumers (herbivores, carnivores) and saprotrophic decomposers (bacteria/fungi)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch12-q8 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch12-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch12-q8')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Define ecological pyramids and describe with examples, pyramids of number and biomass.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition:</strong></p>\n  <p>An <strong>ecological pyramid</strong> is a graphic representation of the trophic structure and function of an ecosystem, where successive trophic levels are plotted in steps starting with producers at the base and apex carnivores at the top.</p>\n\n  <p><strong>1. Pyramid of Numbers:</strong></p>\n  <ul>\n    <li>Represents the total number of individual organisms inhabiting each trophic level per unit area.</li>\n    <li><strong>Upright in Grassland:</strong> Millions of grass plants support thousands of grasshoppers, which support hundreds of frogs, which support a few snakes and top birds of prey.</li>\n    <li><strong>Inverted in Tree Ecosystem:</strong> A single large oak/banyan tree (1 producer) supports hundreds of herbivorous birds, which in turn support thousands of parasitic lice, ticks, and fleas (hyperparasites).</li>\n  </ul>\n\n  <p><strong>2. Pyramid of Biomass:</strong></p>\n  <ul>\n    <li>Represents the total dry weight / organic biomass of standing crop present at each trophic level.</li>\n    <li><strong>Upright in Terrestrial Forest:</strong> Massive biomass of trees and shrubs &gt; biomass of herbivores &gt; biomass of carnivores.</li>\n    <li><strong>Inverted in Aquatic (Sea / Lake) Ecosystem:</strong> Phytoplankton have a very small standing biomass at any given moment because of their microscopic size and rapid turnover (lifespan of hours/days). This small biomass supports a significantly larger standing biomass of zooplankton and predatory fishes.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of ecological pyramid as graphical representation of trophic parameters</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pyramid of number with grassland (upright) and single tree (inverted) examples</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pyramid of biomass with terrestrial forest (upright) and ocean/sea (inverted) examples</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch12-q9 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch12-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch12-q9')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What is primary productivity? Give brief description of factors that affect primary productivity.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition of Primary Productivity:</strong></p>\n  <p><strong>Primary productivity</strong> is defined as the rate at which organic biomass is synthesized per unit area over a specified time period by photosynthetic autotrophs (plants and phytoplankton) through photosynthesis, expressed in units of <strong>g m<sup>-2</sup> yr<sup>-1</sup> or kcal m<sup>-2</sup> yr<sup>-1</sup></strong>.</p>\n  <ul>\n    <li><strong>Gross Primary Productivity (GPP):</strong> The total rate of production of organic matter during photosynthesis.</li>\n    <li><strong>Net Primary Productivity (NPP):</strong> The biomass remaining after meeting the plant's own respiratory losses (R):\n      <div style=\"background:#f8fafc; padding:8px 12px; border-left:4px solid #059669; font-weight:700; margin:6px 0;\">\n        NPP = GPP - R\n      </div>\n    </li>\n  </ul>\n\n  <p><strong>Key Factors Regulating Primary Productivity:</strong></p>\n  <ol>\n    <li><strong>Plant Species & Photosynthetic Capacity:</strong> The genetic architecture and physiological efficiency of plant species inhabiting a particular area (e.g., C4 plants like sugarcane and maize have higher productivity than C3 plants).</li>\n    <li><strong>Availability of Solar Radiation (Light):</strong> Intensity, quality, and photoperiod of sunlight; light is a critical limiting factor in aquatic deep zones and dense forest understories.</li>\n    <li><strong>Temperature:</strong> Governs the enzymatic kinetics of photosynthetic enzymes (e.g., RuBisCO). Tropical ecosystems exhibit peak productivity due to optimal warm temperatures year-round.</li>\n    <li><strong>Soil Moisture & Water Availability:</strong> Water is an essential electron donor in photolysis and prevents stomatal closure. Deserts have exceptionally low productivity due to severe drought.</li>\n    <li><strong>Nutrient Availability:</strong> Availability of essential minerals (nitrogen, phosphorus, potassium). Marine open oceans have low productivity due to nitrogen/phosphorus limitation.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of primary productivity and equation NPP = GPP - R</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Measurement units: g m^-2 yr^-1 or kcal m^-2 yr^-1</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Factors: Plant species capacity, solar radiation, temperature, water availability, and nutrients</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch12-q10 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch12-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch12-q10')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Define decomposition and describe the processes and products of decomposition.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition:</strong></p>\n  <p><strong>Decomposition</strong> is the oxygen-requiring physical and biochemical breakdown of complex, insoluble dead organic matter (detritus such as fallen leaves, dead plant debris, animal carcasses, and fecal matter) into simple, soluble inorganic substances (carbon dioxide, water, and mineral nutrients).</p>\n\n  <p><strong>Five Sequential Biological Processes of Decomposition:</strong></p>\n  <ol>\n    <li><strong>1. Fragmentation:</strong> Detritivores (such as <strong>earthworms</strong>) break down large pieces of detritus into fine particulate matter, greatly increasing the surface area for microbial enzyme action.</li>\n    <li><strong>2. Leaching:</strong> Water-soluble inorganic nutrients percolate downward through the soil profile along with gravitational water and become precipitated as unavailable subterranean salts.</li>\n    <li><strong>3. Catabolism:</strong> Bacterial and fungal extracellular saprotrophic enzymes degrade detritus into simple inorganic compounds.</li>\n    <li><strong>4. Humification:</strong> Leads to the accumulation of <strong>humus</strong>, a dark-coloured, amorphous colloidal organic substance that is highly resistant to microbial decomposition, undergoes extremely slow degradation, acts as a reservoir of nutrients, and improves soil water retention.</li>\n    <li><strong>5. Mineralisation:</strong> The slow, continuous degradation of humus by specialized microbes, releasing inorganic mineral ions (NH<sub>4</sub><sup>+</sup>, PO<sub>4</sub><sup>3-</sup>, K<sup>+</sup>) back into the soil solution for root absorption.</li>\n  </ol>\n  <p><strong>Final Products:</strong> Humus, CO<sub>2</sub>, H<sub>2</sub>O, and plant-available mineral ions.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of decomposition (oxygen-requiring breakdown of detritus into minerals)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Five steps: Fragmentation, Leaching, Catabolism, Humification, and Mineralisation</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Properties of humus (dark, amorphous, colloidal, resistant to microbes) and final products</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch12-q11 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch12-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch12-q11')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Give an account of energy flow in an ecosystem.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Energy flow through an ecosystem obeys the fundamental laws of thermodynamics and is strictly <strong>unidirectional (one-way)</strong>:</p>\n  <ol>\n    <li><strong>Incident Solar Radiation & Capture:</strong>\n      <ul>\n        <li>The Sun is the ultimate source of energy for all terrestrial and aquatic ecosystems on Earth (except deep-sea hydrothermal ecosystems).</li>\n        <li>Less than 50% of incident sunlight is Photosynthetically Active Radiation (PAR). Plants and photosynthetic autotrophs capture only <strong>2–10% of this PAR</strong> to convert it into chemical bond energy (organic biomass).</li>\n      </ul>\n    </li>\n    <li><strong>Obedience to Laws of Thermodynamics:</strong>\n      <ul>\n        <li><em>First Law:</em> Energy is neither created nor destroyed; radiant solar energy is transformed into chemical bond energy in glucose.</li>\n        <li><em>Second Law:</em> Ecosystems require a constant influx of energy to counteract entropy and maintain structural order; at each trophic transfer, substantial energy is dissipated as non-recoverable metabolic heat.</li>\n      </ul>\n    </li>\n    <li><strong>Lindeman's 10% Law of Energy Transfer:</strong>\n      <ul>\n        <li>Formulated by Raymond Lindeman (1942). Only about <strong>10% of the energy</strong> stored as biomass at one trophic level is transferred to and assimilated into biomass by the next higher trophic level.</li>\n        <li>The remaining 90% is expended during cellular respiration (maintenance metabolism) or lost as heat and unassimilated waste.</li>\n        <li><em>Example:</em> 10,000 J in Plants &rarr; 1,000 J in Herbivores &rarr; 100 J in Carnivores &rarr; 10 J in Top Carnivores.</li>\n      </ul>\n    </li>\n    <li><strong>Limitation on Food Chain Length:</strong> Because of this steep 90% energy loss at each step, food chains rarely exceed <strong>4 to 5 trophic levels</strong>, beyond which the remaining energy is insufficient to support another viable predator population.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Solar energy capture (Sun as ultimate source, <50% PAR, 2-10% captured by plants)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Thermodynamic laws and unidirectional energy flow without recycling</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Lindeman's 10% law: Only 10% energy transferred, 90% lost to respiration/heat</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Consequence: Short food chains limited to 4-5 trophic levels</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch12-q12 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch12-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch12-q12')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Write important features of a sedimentary cycle in an ecosystem.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Biogeochemical nutrient cycles are broadly divided into gaseous and sedimentary cycles. Phosphorus and sulphur cycles exemplify <strong>sedimentary cycles</strong>:</p>\n  <ol>\n    <li><strong>Lithospheric Reservoir:</strong>\n      <ul>\n        <li>Unlike gaseous cycles (where the main reservoir is the atmosphere or ocean), the primary reservoir of a sedimentary cycle is located in the <strong>Earth's crust (lithosphere / sedimentary rocks)</strong> in the form of mineral deposits.</li>\n      </ul>\n    </li>\n    <li><strong>Slow Weathering Input:</strong>\n      <ul>\n        <li>Nutrients enter the biological cycle through the extremely slow mechanical, chemical, and biological <strong>weathering and erosion of phosphate-containing rocks</strong>, dissolving minute quantities into the soil solution.</li>\n      </ul>\n    </li>\n    <li><strong>Biological Assimilation & Food Chain Circulation:</strong>\n      <ul>\n        <li>Plant roots absorb dissolved inorganic phosphates (PO<sub>4</sub><sup>3-</sup>) from soil moisture. The nutrient is incorporated into nucleic acids (DNA, RNA), ATP, GTP, and cellular phospholipids.</li>\n        <li>Herbivores and carnivores obtain phosphorus sequentially by consuming lower trophic biomass.</li>\n      </ul>\n    </li>\n    <li><strong>Return via Decomposition:</strong>\n      <ul>\n        <li>Excreta and dead organic detritus are decomposed by phosphate-solubilising bacteria, returning inorganic phosphate back to the soil.</li>\n      </ul>\n    </li>\n    <li><strong>Absence of Significant Respiratory/Atmospheric Gaseous Phase:</strong>\n      <ul>\n        <li>In contrast to the carbon cycle, sedimentary cycles have <strong>no gaseous atmospheric exchange or respiratory release</strong> into the air. Phosphorus inputs from rainfall are negligible.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Primary reservoir in Earth's crust (sedimentary rocks)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Entry via slow rock weathering into soil solution and uptake by roots</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Contrast with gaseous cycles: Negligible atmospheric/rainfall component and no respiratory release</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch12-q13 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch12-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch12-q13')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Outline salient features of carbon cycling in an ecosystem.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Carbon constitutes <strong>49% of the dry weight</strong> of living organisms (second only to water) and cycles continuously through a global gaseous biogeochemical cycle:</p>\n  <ol>\n    <li><strong>Global Carbon Reservoirs:</strong>\n      <ul>\n        <li><strong>Oceanic Reservoir (71%):</strong> Oceans hold the massive majority of the biosphere's dissolved carbon (~71%), acting as the planetary carbon buffer and regulating atmospheric carbon dioxide levels.</li>\n        <li><strong>Fossil Fuel Reservoir:</strong> Immense quantities of carbon remain locked in underground sedimentary strata as coal, petroleum, and natural gas.</li>\n        <li><strong>Atmospheric Reservoir:</strong> The atmosphere holds only about <strong>1% of total global carbon</strong> (approx 0.04% CO<sub>2</sub> by volume).</li>\n      </ul>\n    </li>\n    <li><strong>Assimilation via Photosynthesis:</strong>\n      <ul>\n        <li>An astounding <strong>4 &times; 10<sup>13</sup> kg (40 billion tonnes) of carbon</strong> is fixed annually in the biosphere through terrestrial and marine photosynthesis.</li>\n      </ul>\n    </li>\n    <li><strong>Return Pathways of Carbon into Atmosphere:</strong>\n      <ul>\n        <li><strong>Cellular Respiration:</strong> Living organisms (plants, animals, decomposers) continuously oxidize glucose, releasing CO<sub>2</sub> gas back into the air.</li>\n        <li><strong>Decomposition:</strong> Saprophytes catabolize detritus, releasing immobilized carbon as CO<sub>2</sub>.</li>\n        <li><strong>Combustion of Fossil Fuels & Biomass:</strong> Forest fires, burning of firewood, and combustion of fossil fuels (coal, diesel, petrol) in transport and power plants rapidly inject CO<sub>2</sub> into the atmosphere.</li>\n        <li><strong>Volcanic Degassing:</strong> Volcanic eruptions emit juvenile carbon dioxide.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Carbon reservoirs: Oceans (71% dissolved carbon), fossil fuels, and atmosphere (1%)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Biological fixation: 4 x 10^13 kg carbon fixed annually via photosynthesis</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Return mechanisms: Cellular respiration, microbial decomposition, and anthropogenic fossil combustion</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch12-q14 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch12-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch12-q14')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Explain the 10 percent law of energy transfer with an example.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Statement of Lindeman's 10% Law (1942):</strong></p>\n  <div style=\"background:#f0fdf4; padding:12px 16px; border:1px solid #86efac; border-radius:8px; margin:10px 0; font-size:1.02rem; color:#065f46;\">\n    During the transfer of organic energy from one trophic level to the next higher trophic level, <strong>only about 10% of the energy is conserved and stored as new biomass</strong>; the remaining 90% is consumed in cellular respiration (metabolic maintenance) or dissipated into the environment as unrecoverable heat.\n  </div>\n\n  <p><strong>Demonstrative Example in a 4-Tier Terrestrial Food Chain:</strong></p>\n  <p>Assume an incident solar radiation yields <strong>10,000 Joules</strong> of Net Primary Productivity at the plant producer level:</p>\n  <ul>\n    <li><strong>Trophic Level 1 (T1 - Primary Producers / Grass):</strong>\n      <br>Stored Chemical Energy = <strong>10,000 J</strong>\n    </li>\n    <li><strong>Trophic Level 2 (T2 - Primary Consumers / Deer):</strong>\n      <br>Herbivores consume the grass, but 90% is lost to maintenance, movement, and heat.\n      <br>Energy transferred = 10% of 10,000 J = <strong>1,000 J</strong>\n    </li>\n    <li><strong>Trophic Level 3 (T3 - Secondary Consumers / Wolves):</strong>\n      <br>Carnivores hunt and consume herbivores.\n      <br>Energy transferred = 10% of 1,000 J = <strong>100 J</strong>\n    </li>\n    <li><strong>Trophic Level 4 (T4 - Tertiary Consumers / Lions):</strong>\n      <br>Top predators consume secondary consumers.\n      <br>Energy transferred = 10% of 100 J = <strong>10 J</strong>\n    </li>\n  </ul>\n  <p><strong>Ecological Implication:</strong> Because energy diminishes exponentially by a factor of 10 at each successive tier, higher carnivores require expansive hunting ranges to harvest sufficient calories, and food chains are strictly constrained to 4 or 5 trophic levels.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear statement of 10% law: Only 10% energy transferred to next level, 90% lost to respiration/heat</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stepwise numerical calculation across 4 trophic levels (10,000 J -> 1,000 J -> 100 J -> 10 J)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Biological consequence explaining why food chains rarely exceed 4-5 links</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"display:flex; justify-content:space-between; align-items:center; margin-top:36px; padding-top:20px; border-top:1px solid #e2e8f0;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(11)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 11</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(13)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#059669; color:white; font-weight:700; cursor:pointer;\">Next: Ch 13 (Biodiversity and Conservation) →</button>\n  </div>\n</section>";
window.CHAPTER_DATA[13] = "<section class=\"chapter-section\" id=\"c12b-ch13\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#059669;\">13</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#059669;\">CBSE Class 12 Biology &bull; Chapter 13</div>\n      <h2>Biodiversity and Conservation</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 10 Verbatim Questions with Official CBSE Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n<div class=\"chem-card\" style=\"margin-bottom:24px; padding:20px; background:#f0fdf4; border:1px solid #bbf7d0; border-radius:12px;\">\n  <h4 style=\"margin:0 0 12px 0; color:#059669; font-size:1.05rem;\">🧬 Conservation Biology Map: Species-Area Relationship & The Evil Quartet</h4>\n  <svg viewBox=\"0 0 880 300\" style=\"width:100%; max-width:880px; height:auto; display:block; margin:0 auto; background:white; border-radius:8px; border:1px solid #d1fae5;\">\n    <!-- Species-Area Curve (Humboldt) -->\n    <rect x=\"20\" y=\"20\" width=\"280\" height=\"260\" rx=\"10\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"160\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Species-Area Relationship (Humboldt)</text>\n    <line x1=\"35\" y1=\"56\" x2=\"285\" y2=\"56\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n\n    <!-- Graph axes -->\n    <line x1=\"50\" y1=\"210\" x2=\"260\" y2=\"210\" stroke=\"#334155\" stroke-width=\"2\"/>\n    <line x1=\"50\" y1=\"210\" x2=\"50\" y2=\"70\" stroke=\"#334155\" stroke-width=\"2\"/>\n    <text x=\"240\" y=\"225\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#334155\">Area (A)</text>\n    <text x=\"35\" y=\"80\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#334155\" transform=\"rotate(-90 35,80)\">Species Richness (S)</text>\n\n    <!-- Rectangular hyperbola: S = C A^Z -->\n    <path d=\"M 55 205 Q 85 110, 250 85\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"2.5\"/>\n    <text x=\"175\" y=\"95\" font-family=\"sans-serif\" font-size=\"10\" font-weight=\"bold\" fill=\"#2563eb\">S = C A<sup>Z</sup></text>\n\n    <!-- Straight line on log scale: log S = log C + Z log A -->\n    <line x1=\"55\" y1=\"205\" x2=\"250\" y2=\"135\" stroke=\"#dc2626\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n    <text x=\"150\" y=\"160\" font-family=\"sans-serif\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#dc2626\">log S = log C + Z log A</text>\n\n    <text x=\"50\" y=\"245\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#334155\">&bull; Z = 0.1 to 0.2 (regional taxa)</text>\n    <text x=\"50\" y=\"262\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#047857\">&bull; Z = 0.6 to 1.2 (entire continents)</text>\n\n    <!-- The Evil Quartet Card -->\n    <rect x=\"320\" y=\"20\" width=\"260\" height=\"260\" rx=\"10\" fill=\"#fef2f2\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n    <text x=\"450\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">The Evil Quartet (Species Loss)</text>\n    <line x1=\"335\" y1=\"56\" x2=\"565\" y2=\"56\" stroke=\"#ef4444\" stroke-width=\"1.5\"/>\n\n    <text x=\"335\" y=\"80\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#b91c1c\">1. Habitat Loss & Fragmentation:</text>\n    <text x=\"335\" y=\"96\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; Most major cause (Amazon rainforest</text>\n    <text x=\"345\" y=\"110\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#475569\">cleared for soybean / cattle ranching)</text>\n\n    <text x=\"335\" y=\"130\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#b91c1c\">2. Over-Exploitation:</text>\n    <text x=\"335\" y=\"146\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; Need turns to greed (Dodo, Steller's</text>\n    <text x=\"345\" y=\"160\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#475569\">sea cow, Passenger pigeon extinct)</text>\n\n    <text x=\"335\" y=\"180\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#b91c1c\">3. Alien Species Invasions:</text>\n    <text x=\"335\" y=\"196\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; Nile Perch in L. Victoria killed 200 cichlids</text>\n    <text x=\"335\" y=\"210\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; <em>Parthenium, Lantana, Eichhornia</em></text>\n\n    <text x=\"335\" y=\"232\" font-family=\"sans-serif\" font-size=\"11\" font-weight=\"bold\" fill=\"#b91c1c\">4. Co-Extinctions:</text>\n    <text x=\"335\" y=\"248\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#334155\">&bull; Obligate host-parasite / plant-pollinator</text>\n    <text x=\"345\" y=\"262\" font-family=\"sans-serif\" font-size=\"10\" fill=\"#475569\">extinction (Fig & Wasp)</text>\n\n    <!-- In-situ vs Ex-situ Card -->\n    <rect x=\"600\" y=\"20\" width=\"260\" height=\"260\" rx=\"10\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <text x=\"730\" y=\"46\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Biodiversity Conservation</text>\n    <line x1=\"615\" y1=\"56\" x2=\"845\" y2=\"56\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n\n    <text x=\"615\" y=\"80\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#1d4ed8\">In-Situ (On-Site Preservation):</text>\n    <text x=\"615\" y=\"98\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; 14 Biosphere Reserves (in India)</text>\n    <text x=\"615\" y=\"114\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; 90+ National Parks & 448+ Sanctuaries</text>\n    <text x=\"615\" y=\"130\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; <strong>Sacred Groves:</strong> Khasi/Jaintia hills,</text>\n    <text x=\"625\" y=\"146\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#475569\">Aravalli hills, Western Ghats</text>\n    <text x=\"615\" y=\"164\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; <strong>Biodiversity Hotspots:</strong> 34 globally</text>\n    <text x=\"625\" y=\"180\" font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#475569\">(Western Ghats-Sri Lanka, Indo-Burma, Himalaya)</text>\n\n    <text x=\"615\" y=\"206\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"bold\" fill=\"#1d4ed8\">Ex-Situ (Off-Site Preservation):</text>\n    <text x=\"615\" y=\"224\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Zoological Parks & Botanical Gardens</text>\n    <text x=\"615\" y=\"240\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; Cryopreservation of gametes (-196 &deg;C)</text>\n    <text x=\"615\" y=\"258\" font-family=\"sans-serif\" font-size=\"11\" fill=\"#334155\">&bull; In vitro tissue culture & Seed banks</text>\n  </svg>\n</div>\n\n  <div class=\"ex-div\" style=\"font-size:0.88rem; font-weight:700; color:#334155; margin-bottom:16px; padding:8px 14px; background:#ecfdf5; border-radius:8px; border-left:4px solid #059669;\">NCERT Exercises (10 Verbatim Questions)</div>\n\n  <div class=\"questions-container\">\n    \n  <!-- c12b-ch13-q1 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch13-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch13-q1')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Name the three important components of biodiversity.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>The sociobiologist <strong>Edward Wilson</strong> popularized the term <strong>biodiversity</strong> to describe the combined diversity at all levels of biological organisation. The three interrelated components are:</p>\n  <ol>\n    <li><strong>Genetic Diversity:</strong>\n      <br>The diversity of genes and alleles within a single biological species over its geographical distributional range.\n      <ul>\n        <li><em>Example 1:</em> The medicinal plant <strong><em>Rauwolfia vomitoria</em></strong> growing in different Himalayan ranges shows substantial genetic variation in the potency and concentration of the active chemical alkaloid <strong>reserpine</strong>.</li>\n        <li><em>Example 2:</em> India has more than <strong>50,000 genetically different strains of rice</strong> and more than <strong>1,000 distinct varieties of mango</strong>.</li>\n      </ul>\n    </li>\n    <li><strong>Species Diversity:</strong>\n      <br>The variety and richness of different biological species within a specific region or community.\n      <ul>\n        <li><em>Example:</em> The <strong>Western Ghats have a greater amphibian species diversity</strong> than the Eastern Ghats.</li>\n      </ul>\n    </li>\n    <li><strong>Ecological (Ecosystem) Diversity:</strong>\n      <br>The diversity of habitats, biological communities, and ecological processes at the ecosystem level across biomes.\n      <ul>\n        <li><em>Example:</em> India, with its deserts, rainforests, mangroves, coral reefs, wetlands, estuaries, and alpine meadows, possesses a vastly greater ecosystem diversity than a Scandinavian country like Norway.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">1. Genetic diversity with valid example (Rauwolfia vomitoria / 50,000 strains of rice)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">2. Species diversity with valid example (Western Ghats amphibians > Eastern Ghats)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">3. Ecological / Ecosystem diversity with valid example (India vs Norway)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch13-q2 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch13-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch13-q2')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        How do ecologists estimate the total number of species present in the world?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Because comprehensive planetary species inventories are complete only in a few temperate regions and grossly incomplete in the hyper-diverse tropics, ecologists employ statistical extrapolation:</p>\n  <ol>\n    <li><strong>Taxonomic Group Extrapolation (Temperate-to-Tropical Ratio):</strong>\n      <ul>\n        <li>Taxonomists have carried out exhaustive inventories of specific, well-studied taxonomic groups (especially insects) in temperate regions.</li>\n        <li>They compare the ratio of temperate species to tropical species within these well-studied insect groups.</li>\n        <li>Assuming this temperate-to-tropical species ratio remains roughly consistent across other animal and plant groups, they statistically extrapolate this ratio to the entire planet to calculate global estimates.</li>\n      </ul>\n    </li>\n    <li><strong>Robert May's Conservative Global Estimate:</strong>\n      <ul>\n        <li>While some extreme hypotheses range from 20 to 50 million species, a widely accepted, scientifically sound, and conservative estimate was formulated by <strong>Robert May</strong>:</li>\n        <li>He placed the global species diversity at approximately <strong>7 million species (70 lakhs)</strong>.</li>\n      </ul>\n    </li>\n    <li><strong>Current Recorded Fraction:</strong>\n      <ul>\n        <li>According to the International Union for Conservation of Nature (IUCN, 2004), the total number of documented plant and animal species is slightly more than <strong>1.5 million</strong>.</li>\n        <li>This implies that over <strong>70–78% of planetary species</strong> remain undiscovered and unrecorded by modern science, facing the threat of extinction before they are even discovered.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Statistical comparison of temperate vs tropical species richness in well-studied insect taxa</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Extrapolating ratio across all taxonomic groups to estimate global diversity</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Robert May's scientifically grounded estimate of ~7 million species (vs ~1.5 million currently recorded)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch13-q3 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch13-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch13-q3')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Give three hypotheses for explaining why tropics show greatest levels of species richness.\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Species diversity decreases as we move away from the equator towards the poles. Ecologists and evolutionary biologists propose three major hypotheses for the unparalleled species richness of the tropics:</p>\n  <ol>\n    <li><strong>1. Speciation is a Function of Time (Long Undisturbed Evolutionary History):</strong>\n      <br>Temperate latitudes were subjected to frequent, catastrophic glaciations in the geological past that wiped out flora and fauna repeatedly. In contrast, <strong>tropical latitudes have remained relatively undisturbed and stable for millions of years</strong>, providing an uninterrupted evolutionary time span for speciation, niche specialization, and diversification.</li>\n    <li><strong>2. Constant, Predictable, and Less Seasonal Environment:</strong>\n      <br>Unlike temperate regions with severe seasonal winters, tropical environments are <strong>less seasonal, relatively more constant, and predictable</strong>. Such predictable environmental conditions promote fine niche specialization and biological adaptations, allowing a vastly greater number of species to coexist in the same habitat.</li>\n    <li><strong>3. Abundance of Solar Energy & High Productivity:</strong>\n      <br>Tropical regions receive maximum, direct incident solar radiation year-round. High solar energy influx drives <strong>higher net primary productivity (NPP)</strong>, which translates into abundant food resources and metabolic energy directly and indirectly supporting a complex, multi-tiered biodiversity web.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">1. Evolutionary time hypothesis: Tropical stability without frequent glaciations allowing prolonged speciation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">2. Less seasonal/constant environment fostering fine niche specialisation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">3. Greater solar energy input driving higher primary productivity and energy availability</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch13-q4 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch13-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch13-q4')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What is the significance of the slope of regression in a species-area relationship?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>The pioneering German naturalist and geographer <strong>Alexander von Humboldt</strong> observed that within a region, species richness increases with increasing explored area, but only up to a limit.</p>\n  <p>On a logarithmic scale, the relationship is a straight line described by the equation:</p>\n  <div style=\"background:#f8fafc; padding:10px 14px; border-left:4px solid #059669; font-family:monospace; margin:8px 0; font-size:1.05rem;\">\n    log S = log C + Z log A\n  </div>\n  <p>Where <em>S</em> = Species richness, <em>A</em> = Area, <em>C</em> = Y-intercept, and <strong><em>Z</em> = Slope of the regression line (regression coefficient)</strong>.</p>\n\n  <p><strong>Ecological Significance of the Slope of Regression (<em>Z</em>):</strong></p>\n  <ol>\n    <li><strong>Standard Regional Value (Z = 0.1 to 0.2):</strong>\n      <br>Ecologists have discovered that regardless of the taxonomic group or geographic region (e.g., plants in Britain, birds in California, or molluscs in New York state), the slope of the regression line remarkably falls strictly within the narrow range of <strong>0.1 to 0.2</strong> when analyzing small or regional areas.</li>\n    <li><strong>Steeper Slope for Enormous Continental Areas (Z = 0.6 to 1.2):</strong>\n      <br>If the species-area relationship is analysed across very large spatial scales, such as an entire continent, the slope of the regression line becomes <strong>significantly steeper</strong>, with <em>Z</em> values ranging between <strong>0.6 and 1.2</strong>.</li>\n    <li><strong>Significance:</strong> A steeper regression slope (higher <em>Z</em> value) signifies that as explored area expands across massive continental landscapes, <strong>species richness accumulates at a vastly higher rate</strong> because diverse new geographical habitats, biomes, and isolated mountain/river barriers are integrated into the survey.\n      <br><em>Example:</em> For frugivorous (fruit-eating) birds and mammals in the tropical forests of different continents, the slope <em>Z</em> is an extremely steep <strong>1.15</strong>.</li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Mathematical equation: log S = log C + Z log A and defining Z as slope of regression line</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Standard value of Z (0.1 to 0.2) in regional areas regardless of taxonomic group</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Steeper slope (0.6 to 1.2, e.g. 1.15 for frugivorous birds/mammals) across entire continents indicating rapid species accumulation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch13-q5 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch13-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch13-q5')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What are the major causes of species losses in a geographical region?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>The accelerated rate of anthropogenic species extinction currently occurring worldwide (the Sixth Mass Extinction) is driven by four primary causes, famously termed by ecologists as <strong>\"The Evil Quartet\"</strong>:</p>\n  <ol>\n    <li><strong>1. Habitat Loss and Fragmentation (Most Important Cause):</strong>\n      <ul>\n        <li>Clearing of pristine natural ecosystems for agriculture, urbanisation, and mining.</li>\n        <li>The Amazon rainforest (the \"lungs of the planet\"), harbouring millions of species, is being cleared and burned for soybean cultivation and beef cattle ranching.</li>\n        <li>Breaking large contiguous forest tracts into small fragmented patches severely threatens large mammals requiring extensive home ranges (elephants, tigers) and migratory animals.</li>\n      </ul>\n    </li>\n    <li><strong>2. Over-Exploitation:</strong>\n      <ul>\n        <li>When human biological \"need\" turns into commercial \"greed\", overharvesting drives vulnerable species to extinction.</li>\n        <li>Overexploitation by humans led to the complete extinction of <strong>Steller's sea cow, the Passenger pigeon, and Dodo</strong>, and current overfishing threatens marine commercial fish populations.</li>\n      </ul>\n    </li>\n    <li><strong>3. Alien (Invasive) Species Invasions:</strong>\n      <ul>\n        <li>Introduction of non-native exotic species unintentionally or deliberately disrupts native ecosystems:\n          <ul>\n            <li>Introduction of <strong>Nile Perch</strong> into Lake Victoria (East Africa) led to the total extinction of an ecologically unique assemblage of over 200 endemic species of cichlid fish.</li>\n            <li>Invasive weed species like <strong><em>Parthenium</em> (carrot grass), <em>Lantana</em>, and <em>Eichhornia</em> (water hyacinth)</strong> choke native vegetation.</li>\n            <li>Illegal introduction of the African catfish <strong><em>Clarias gariepinus</em></strong> threatens indigenous river catfishes.</li>\n          </ul>\n        </li>\n      </ul>\n    </li>\n    <li><strong>4. Co-Extinctions:</strong>\n      <ul>\n        <li>When a host species becomes extinct, all its obligate parasitic and mutualistic partner species that depend exclusively on it also face mandatory extinction (e.g., an obligate plant-pollinator mutualism like Fig tree and wasp).</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">1. Habitat loss and fragmentation (Amazon destruction / edge effects)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">2. Over-exploitation (Passenger pigeon, Steller's sea cow, Dodo)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">3. Alien species invasions (Nile perch in Lake Victoria, Parthenium, Eichhornia, Clarias)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">4. Co-extinctions (extinction of host causing loss of obligate parasites/mutualist pollinators)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch13-q6 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch13-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch13-q6')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        How is biodiversity important for ecosystem functioning?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Biodiversity is the foundational cornerstone that maintains ecological stability, biogeochemical cycling, and resilience:</p>\n  <ol>\n    <li><strong>David Tilman's Long-Term Ecosystem Experiments:</strong>\n      <ul>\n        <li>Tilman's outdoor experimental grassland plots demonstrated that plots with <strong>greater species richness showed less year-to-year variation in total biomass</strong>.</li>\n        <li>Increased species diversity directly caused <strong>higher net community productivity</strong>, proving that species-rich ecosystems are functionally more productive and stable than monocultures.</li>\n      </ul>\n    </li>\n    <li><strong>Ecosystem Stability & Resistance to Invasions:</strong>\n      <ul>\n        <li>Diverse communities are resilient: they rebound quickly from occasional environmental disturbances (droughts, fires) and exhibit strong resistance to biological invasions by alien exotic pests.</li>\n      </ul>\n    </li>\n    <li><strong>Paul Ehrlich's \"Rivet Popper Hypothesis\":</strong>\n      <ul>\n        <li>Stanford ecologist Paul Ehrlich used an analogy comparing an ecosystem to an airplane, where thousands of rivets hold the airplane frame together (representing thousands of species in an ecosystem).</li>\n        <li>If every passenger pops out a rivet (species extinction), a few missing rivets on seats may not jeopardize flight safety initially.</li>\n        <li>However, as more and more rivets are removed, the airplane becomes dangerously weak. Furthermore, popping a critical rivet located on a vital structure (like the wing, representing a <strong>keystone species</strong> like top predators or fig trees) will cause an immediate catastrophic crash of the plane (ecosystem collapse).</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">David Tilman's experiments: High species richness delivers lower biomass variation and higher productivity</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ecosystem stability, resilience to disturbances, and resistance to alien invasions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Paul Ehrlich's Rivet Popper hypothesis explaining the disproportionate peril of losing keystone species</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch13-q7 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch13-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch13-q7')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        What are sacred groves? What is their role in conservation?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition of Sacred Groves:</strong></p>\n  <p><strong>Sacred groves</strong> are pristine forest patches or woodland tracts that are communally protected, preserved, and venerated by indigenous tribal and local communities due to deep-rooted spiritual beliefs, religious sanctity, and cultural taboos against felling any tree or killing any animal within the boundary.</p>\n\n  <p><strong>Prominent Examples in India:</strong></p>\n  <ul>\n    <li><strong>Khasi and Jaintia Hills</strong> in Meghalaya</li>\n    <li><strong>Aravalli Hills</strong> of Rajasthan</li>\n    <li><strong>Western Ghat regions</strong> of Maharashtra and Karnataka</li>\n    <li><strong>Sarguja, Chanda, and Bastar</strong> areas of Chhattisgarh and Madhya Pradesh</li>\n  </ul>\n\n  <p><strong>Crucial Role in Biodiversity Conservation:</strong></p>\n  <ol>\n    <li><strong>Refugia for Rare, Threatened, and Endemic Taxa:</strong>\n      <ul>\n        <li>Sacred groves act as the <strong>last surviving biological refuges</strong> for numerous endangered plant and animal species that have been completely extirpated from surrounding degraded landscapes.</li>\n        <li>In Meghalaya, the Khasi sacred groves serve as the only remaining sanctuary for several critically endangered orchid species, medicinal ferns, and ancient angiosperm trees.</li>\n      </ul>\n    </li>\n    <li><strong>Gene Pool Preservation & Ethnobotanical Repository:</strong>\n      <ul>\n        <li>They preserve wild crop ancestors, rare medicinal herbs, and primitive plant germplasms outside modern statutory national park regimes.</li>\n      </ul>\n    </li>\n    <li><strong>Model of Community-Driven In-Situ Conservation:</strong>\n      <ul>\n        <li>They demonstrate that indigenous cultural traditions, religious reverence for nature, and local self-governance can conserve biodiversity without expensive enforcement.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of sacred groves as culturally and religiously protected pristine forest tracts</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Prominent Indian examples: Khasi and Jaintia hills (Meghalaya), Aravalli hills (Rajasthan), Western Ghats</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conservation role as last refugia for rare/endangered endemic flora and preserving ancient gene pools</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch13-q8 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch13-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch13-q8')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Among the ecosystem services are control of floods and soil erosion. How is this achieved by the biotic components of the ecosystem?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>The living biotic components of terrestrial ecosystems (primarily forest trees, shrubs, grasslands, and soil microorganisms) perform vital regulating ecosystem services:</p>\n\n  <p><strong>1. Biological Control of Soil Erosion:</strong></p>\n  <ul>\n    <li><strong>Root Anchoring:</strong> The extensive, fibrous root networks of trees, shrubs, and grasses penetrate deep into the subterranean soil profile, binding loose mineral particles tightly into an aggregate crumb structure, preventing topsoil from being dislodged by wind or water.</li>\n    <li><strong>Canopy Interception:</strong> The dense multi-layered forest foliage intercepts the kinetic impact of falling raindrops, breaking their velocity and preventing splash erosion.</li>\n    <li><strong>Humus & Soil Cover:</strong> Leaf litter and organic humus formed by microbial decomposition act as a porous sponge on the forest floor that shields topsoil from surface run-off.</li>\n  </ul>\n\n  <p><strong>2. Biological Control of Floods:</strong></p>\n  <ul>\n    <li><strong>Enhanced Percolation & Infiltration:</strong> Humus-rich soil has superior porosity and percolation rates. Precipitation is rapidly absorbed into the ground to recharge deep subterranean aquifers rather than washing away as torrential flash surface runoff.</li>\n    <li><strong>Slowing Water Discharge:</strong> Vegetation buffers, riverbank riparian woodlands, and wetland roots create natural physical friction that retards surface floodwater velocity, allowing water to disperse gradually into river channels.</li>\n    <li><strong>Transpirational Evacuation:</strong> Dense vegetation continuously absorbs vast quantities of groundwater and transpires it into the atmosphere, creating significant hydraulic buffer capacity in the soil to absorb subsequent heavy monsoon downpours.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Soil erosion control: Root network binding soil particles, canopy intercepting rain velocity, humus cover</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Flood control: High soil percolation recharging groundwater, riparian vegetation retarding runoff velocity, transpirational pumping</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch13-q9 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch13-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch13-q9')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        The species diversity of plants (22 per cent) is much less than that of animals (72 per cent). What could be the explanations to how animals achieved greater diversification?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p>Of all recorded species on Earth, <strong>animals comprise over 70–72%</strong> (with insects alone accounting for more than 70% of all animals), whereas <strong>plants comprise only about 22%</strong>. Evolutionary and biological reasons for this massive discrepancy include:</p>\n  <ol>\n    <li><strong>Locomotion & Active Motility:</strong>\n      <ul>\n        <li>Plants are sessile (rooted to one spot) and must passively tolerate fluctuating environmental stresses, herbivory, and climate extremes.</li>\n        <li>In contrast, animals possess active locomotion, neuromuscular coordination, and sensory organs. They can actively escape hostile environmental conditions, seek hospitable microhabitats, migrate across barriers, search for diverse food sources, and avoid predators, enabling occupation of specialized ecological niches.</li>\n      </ul>\n    </li>\n    <li><strong>Complex Nervous System & Behavioural Plasticity:</strong>\n      <ul>\n        <li>Animals possess complex sensory receptors and nervous systems that allow behavioral learning, courtship rituals, territorial defense, and social communication. Behavioral isolation rapidly accelerates reproductive isolation and <strong>sympatric speciation</strong>.</li>\n      </ul>\n    </li>\n    <li><strong>Co-evolution with Angiosperms (The Insect Explosion):</strong>\n      <ul>\n        <li>Insects underwent massive co-evolutionary radiation alongside flowering plants. Specialized morphological mouthparts (chewing, siphoning, piercing-sucking) and intricate plant-pollinator mutualisms drove explosive insect speciation.</li>\n      </ul>\n    </li>\n    <li><strong>Structural Adaptations in Arthropods:</strong>\n      <ul>\n        <li>Chitinous waterproof exoskeletons, jointed appendages, and flight (wings) allowed insects to conquer every terrestrial, subterranean, and aerial niche.</li>\n      </ul>\n    </li>\n  </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Locomotion enabling active escape from predators/stress and migration to novel niches</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Complex nervous/sensory systems leading to behavioral adaptations and rapid speciation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Insect co-evolution with flowering plants and protective chitinous exoskeleton/flight</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c12b-ch13-q10 (Exercises (NCERT Verbatim)) -->\n  <div class=\"q-card\" id=\"c12b-ch13-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c12b-ch13-q10')\">\n      <div class=\"q-num\" style=\"background:#059669;\">Q10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Exercises (NCERT Verbatim)</span><br>\n        Can you think of a situation where we deliberately want to make a species extinct? How would you justify it?\n      </div>\n      <div class=\"q-marks\" style=\"color:#059669; background:#ecfdf5; border-color:#a7f3d0;\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\" style=\"border-left-color:#059669;\">\n        <div class=\"answer-label\" style=\"color:#059669;\">✅ CBSE Step-by-Step Biological Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Biological & Ethical Dilemma:</strong></p>\n  <p>While conservation biology advocates the preservation of all planetary biodiversity, there are exceptional, highly debated clinical scenarios where human society has deliberately sought to achieve the total eradication (extinction) of specific lethal human pathogenic microbes:</p>\n\n  <p><strong>1. Primary Candidate Species Targeted for Deliberate Eradication:</strong></p>\n  <ul>\n    <li><strong>Variola Virus (Smallpox):</strong> Successfully eradicated globally in 1980 through universal WHO vaccination campaigns (only surviving stocks kept in ultra-secure bio-safety level 4 laboratories).</li>\n    <li><strong>Poliovirus (Poliomyelitis):</strong> Targeted globally for complete biological eradication through intensive pulse polio immunization.</li>\n    <li><strong>Dracunculus medinensis (Guinea Worm):</strong> A crippling human parasitic nematode on the verge of complete worldwide eradication.</li>\n    <li><strong>Vector Elimination (Debated):</strong> Genetic extinction technologies (CRISPR gene drives) targeting <strong><em>Anopheles gambiae</em></strong> (malaria vector mosquito) to collapse local populations.</li>\n  </ul>\n\n  <p><strong>2. Scientific & Humanitarian Justification:</strong></p>\n  <ol>\n    <li><strong>Obligate Lethal Human Pathogens:</strong> Viruses like Variola or Polio are obligate parasites with <em>no other animal reservoir or ecological niche</em>. They cause agonizing mortality, permanent paralysis, and suffering to millions of humans without serving any beneficial ecological food-chain role or ecosystem service.</li>\n    <li><strong>Preservation of Human Life:</strong> Human survival and public health justify the eradication of specific lethal microbial agents that threaten civilization.</li>\n  </ol>\n\n  <p><strong>3. Ecological Counter-Warning:</strong></p>\n  <ul>\n    <li>Deliberately making any macroscopic wild species extinct (e.g., mosquito vectors or apex predators) is biologically hazardous, as their elimination could trigger unpredictable ecological cascading effects, food web collapse, or secondary pest outbreaks.</li>\n  </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\" style=\"color:#059669;\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of target species: Human-specific obligate pathogens (Variola smallpox virus, Poliovirus, Guinea worm)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification: Obligate pathogens causing mass human mortality/suffering without providing ecological services</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ecological counter-warning against targeting macroscopic species (risk of cascading food web collapse)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"display:flex; justify-content:space-between; align-items:center; margin-top:36px; padding-top:20px; border-top:1px solid #e2e8f0;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(12)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 12</button>\n    <a href=\"../ncert-solutions-class-12.html\" class=\"ch-nav-btn next\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#059669; color:white; font-weight:700; text-decoration:none;\">Class 12 All Subjects Hub →</a>\n  </div>\n</section>";
